                    </div>
                </div>

                <div className="flex-1 relative">
                    <JacquardCanvas 
                        data={jacquardData}
                        onUpdate={handleStructureUpdate}
                        tool={currentTool}
                        viewMode={viewMode}
                        faceMode={faceMode}
                        warpColors={warpColorArray}
                        weftColors={weftColorArray}
                        gridDivision={settings.gridDivision}
                    />
                </div>
            </div>

            <RightPanel 
