import React, { useRef, useEffect, useState, useMemo } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode } from '../types';

interface JacquardCanvasProps {
    data: JacquardData;
    onUpdate: (newData: Uint8Array) => void;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    gridDivision: number;
}

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, onUpdate, tool, viewMode, faceMode, warpColors, weftColors, gridDivision
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [view, setView] = useState({ x: 0, y: 0, zoom: 10 });
    const [isDrawing, setIsDrawing] = useState(false);
    const lastPos = useRef({ x: 0, y: 0 });

    const width = data.width;
    const height = data.height;

    // Viewport-based rendering for high performance
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        canvas.width = w;
        canvas.height = h;

        ctx.fillStyle = '#111827';
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        const startX = Math.floor(-view.x / zoom);
        const startY = Math.floor(-view.y / zoom);
        const endX = Math.min(width, startX + Math.ceil(w / zoom) + 1);
        const endY = Math.min(height, startY + Math.ceil(h / zoom) + 1);

        const isStructure = viewMode === 'structure';
        const isReverse = faceMode === 'reverse';

        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * width + x;
                let val = data.structure[idx] === 1;
                if (isReverse) val = !val;

                if (isStructure) {
                    ctx.fillStyle = val ? '#ffffff' : '#000000';
                } else {
                    ctx.fillStyle = val ? warpColors[x % warpColors.length] : weftColors[y % weftColors.length];
                }

                ctx.fillRect(
                    Math.floor(view.x + x * zoom),
                    Math.floor(view.y + y * zoom),
                    Math.ceil(zoom),
                    Math.ceil(zoom)
                );
            }
        }

        // Draw grid lines if zoomed in enough
        if (zoom > 4) {
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            for (let x = Math.max(0, startX); x <= endX; x++) {
                if (x % gridDivision === 0) {
                    ctx.moveTo(view.x + x * zoom, 0);
                    ctx.lineTo(view.x + x * zoom, h);
                }
            }
            for (let y = Math.max(0, startY); y <= endY; y++) {
                if (y % gridDivision === 0) {
                    ctx.moveTo(0, view.y + y * zoom);
                    ctx.lineTo(w, view.y + y * zoom);
                }
            }
            ctx.stroke();
        }

    }, [data, view, viewMode, faceMode, warpColors, weftColors, gridDivision]);

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;

        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const delta = wheelEv.deltaY;
            const zoomFactor = delta > 0 ? 0.9 : 1.1;
            const newZoom = Math.min(100, Math.max(0.1, view.zoom * zoomFactor));

            // Zoom centered on mouse
            const worldX = (mouseX - view.x) / view.zoom;
            const worldY = (mouseY - view.y) / view.zoom;

            setView(prev => ({
                x: mouseX - worldX * newZoom,
                y: mouseY - worldY * newZoom,
                zoom: newZoom
            }));
            return;
        }

        if (tool === 'pan') {
            if (e.type === 'mousedown') {
                setIsDrawing(true);
                lastPos.current = { x: mouseX, y: mouseY };
            } else if (e.type === 'mousemove' && isDrawing) {
                const dx = mouseX - lastPos.current.x;
                const dy = mouseY - lastPos.current.y;
                setView(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
                lastPos.current = { x: mouseX, y: mouseY };
            } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
                setIsDrawing(false);
            }
            return;
        }

        // Drawing Tools
        const gridX = Math.floor((mouseX - view.x) / view.zoom);
        const gridY = Math.floor((mouseY - view.y) / view.zoom);

        if (gridX < 0 || gridX >= width || gridY < 0 || gridY >= height) return;

        if (e.type === 'mousedown') {
            setIsDrawing(true);
            const newData = new Uint8Array(data.structure);
            const current = newData[gridY * width + gridX];
            newData[gridY * width + gridX] = current === 1 ? 0 : 1;
            onUpdate(newData);
        } else if (e.type === 'mousemove' && isDrawing) {
            const newData = new Uint8Array(data.structure);
            newData[gridY * width + gridX] = 1; // Always paint 1 for drag?
            onUpdate(newData);
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            setIsDrawing(false);
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden">
            <canvas 
                ref={canvasRef}
                onMouseDown={handleInteraction}
                onMouseMove={handleInteraction}
                onMouseUp={handleInteraction}
                onMouseLeave={handleInteraction}
                onWheel={handleInteraction}
                className="block"
            />
            <div className="absolute bottom-4 left-4 bg-black/60 px-3 py-1 rounded text-[10px] font-mono text-gray-400">
                {tool === 'pan' ? 'CLICK & DRAG TO PAN' : 'CLICK TO TOGGLE WEAVE INTERSECTION'} | ZOOM: {Math.round(view.zoom * 10)}%
            </div>
        </div>
    );
};

import React from 'react';
