export const generateWeave = (input: { structure: boolean[][], warpPattern: string[], weftPattern: string[] }): { pattern: string[][], structure: boolean[][] } => {
  const { structure, warpPattern, weftPattern } = input;
  const rows = structure.length;
  const cols = rows > 0 ? structure[0].length : 0;

  const pattern: string[][] = Array.from({ length: rows }, () => Array(cols).fill('transparent'));

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const isWarpUp = structure[y][x];
      pattern[y][x] = isWarpUp ? warpPattern[x % warpPattern.length] : weftPattern[y % weftPattern.length];
    }
  }

  return { pattern, structure };
};

