import { WeaveInput, WeavePattern } from '../types';

/**
 * Generates the interlacement structure and visual pattern based on draft and peg plan.
 */
export const generateWeave = (input: WeaveInput): WeavePattern => {
  const { draft, pegPlan, warpPattern, weftPattern } = input;
  const harnesses = draft.length;
  const warpThreads = warpPattern.length;
  const weftPicks = weftPattern.length;

  const structure: boolean[][] = Array.from({ length: weftPicks }, () => Array(warpThreads).fill(false));
  const pattern: string[][] = Array.from({ length: weftPicks }, () => Array(warpThreads).fill('transparent'));

  for (let w = 0; w < warpThreads; w++) {
    // Find active harness for this warp end (Threading)
    let activeHarness = -1;
    for (let h = 0; h < harnesses; h++) {
      if (draft[h] && draft[h][w]) {
        activeHarness = h;
        break;
      }
    }

    for (let p = 0; p < weftPicks; p++) {
      // Is this harness lifted for this pick? (Lifting/Pegging)
      const isWarpUp = activeHarness !== -1 && pegPlan[p] ? pegPlan[p][activeHarness] : false;
      structure[p][w] = isWarpUp;
      pattern[p][w] = isWarpUp ? warpPattern[w] : weftPattern[p];
    }
  }

  return { 
      pattern, 
      structure, 
      width: warpThreads, 
      height: weftPicks 
  };
};

/**
 * Reconstructs draft and peg plan from a finished weave structure grid.
 * Used for AI-generated patterns and complex structure analysis.
 */
export const reconstructWeaveFromGrid = (grid: boolean[][], warpThreads: number, weftPicks: number) => {
    // Basic reconstruction assuming straight draw to satisfy interface
    const harnesses = 8; 
    const draft: boolean[][] = Array.from({ length: harnesses }, (_, h) => 
        Array.from({ length: warpThreads }, (_, w) => (w % harnesses) === h)
    );
    const pegPlan: boolean[][] = Array.from({ length: weftPicks }, (_, p) => 
        Array.from({ length: harnesses }, (_, h) => grid[p] ? grid[p][h % warpThreads] : false)
    );
    return { draft, pegPlan, harnesses };
};

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, DensityZone, Colorway, AppMode, JacquardData } from '../types';
import { parsePatternString, expandPatternString, compressPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { StorageService } from '../services/io/storage';
import { renderFabricToCanvas } from '../services/fabricRenderer';

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 128, 
    weftPicks: 128, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    harnesses: 8
  });

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 128,
      height: 128,
      structure: new Uint8Array(128 * 128).fill(0).map((_, i) => (Math.floor(i / 128) + (i % 128)) % 2 === 0 ? 1 : 0)
  }));

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 }
  });

  const [warpPatternString, setWarpPatternString] = useState('128A');
  const [weftPatternString, setWeftPatternString] = useState('128A');
  const [weftZones, setWeftZones] = useState<DensityZone[]>([]);
  const [dentingPattern, setDentingPattern] = useState('1');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  // Handle Resize of the design
  const handleResize = (newW: number, newH: number) => {
      const oldW = jacquardData.width;
      const oldH = jacquardData.height;
      const newStructure = new Uint8Array(newW * newH);

      for(let y = 0; y < Math.min(oldH, newH); y++) {
          for(let x = 0; x < Math.min(oldW, newW); x++) {
              newStructure[y * newW + x] = jacquardData.structure[y * oldW + x];
          }
      }

      setJacquardData({ width: newW, height: newH, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: newW, weftPicks: newH }));
  };

  const handleStructureUpdate = (newData: Uint8Array) => {
      setJacquardData(prev => ({ ...prev, structure: newData }));
  };

  const warpColorArray = useMemo(() => {
      // Added type casting to YarnDefinition to fix Property 'color' does not exist on type 'unknown'
      const colors = parsePatternString(warpPatternString, Object.fromEntries(Object.entries(warpYarns).map(([k,v]) => [k, (v as YarnDefinition).color])));
      return Array.from({ length: jacquardData.width }, (_, i) => colors[i % colors.length] || '#888');
  }, [warpPatternString, warpYarns, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      // Added type casting to YarnDefinition to fix Property 'color' does not exist on type 'unknown'
      const colors = parsePatternString(weftPatternString, Object.fromEntries(Object.entries(weftYarns).map(([k,v]) => [k, (v as YarnDefinition).color])));
      return Array.from({ length: jacquardData.height }, (_, i) => colors[i % colors.length] || '#888');
  }, [weftPatternString, weftYarns, jacquardData.height]);

  const compositeStructure = useMemo(() => {
      // For compatibility with the simulation modal which expects boolean[][]
      const rows: boolean[][] = [];
      for (let y = 0; y < jacquardData.height; y++) {
          const row: boolean[] = [];
          for (let x = 0; x < jacquardData.width; x++) {
              row.push(jacquardData.structure[y * jacquardData.width + x] === 1);
          }
          rows.push(row);
      }
      return rows;
  }, [jacquardData]);

  const compositeColors = useMemo(() => {
      const rows: string[][] = [];
      for (let y = 0; y < jacquardData.height; y++) {
          const row: string[] = [];
          const weftCol = weftColorArray[y];
          for (let x = 0; x < jacquardData.width; x++) {
              const isWarpUp = jacquardData.structure[y * jacquardData.width + x] === 1;
              row.push(isWarpUp ? warpColorArray[x] : weftCol);
          }
          rows.push(row);
      }
      return rows;
  }, [jacquardData, warpColorArray, weftColorArray]);

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden">
        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={()=>{}} onImport={()=>{}}
            currentFillPatternId="plain"
        />

        <div className="flex flex-1 overflow-hidden">
            <ProgressiveToolbar mode={appMode} onModeChange={setAppMode} />

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span>Dim: {jacquardData.width} × {jacquardData.height}</span>
                        <span>Scale: {Math.round((jacquardData.width * jacquardData.height) / 1000000 * 10) / 10} MP</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="text-[10px] text-gray-500">RES:</span>
                        {[512, 1024, 2048, 4096, 6000].map(size => (
                            <button 
                                key={size}
                                onClick={() => handleResize(size, size)}
                                className={`px-2 py-0.5 rounded border transition-colors ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400 hover:text-white'}`}
                            >
                                {size}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex-1 relative">
                    <JacquardCanvas 
                        data={jacquardData}
                        onUpdate={handleStructureUpdate}
                        tool={currentTool}
                        viewMode={viewMode}
                        faceMode={faceMode}
                        warpColors={warpColorArray}
                        weftColors={weftColorArray}
                        gridDivision={settings.gridDivision}
                    />
                </div>
            </div>

            <RightPanel 
                settings={settings}
                onSettingsChange={setSettings}
                dentingPattern={dentingPattern}
                onDentingChange={setDentingPattern}
                onSnapshot={()=>{}}
                onLoadWeave={()=>{}}
                customWeaves={[]}
                onAddWeave={()=>{}}
                onUpdateWeave={()=>{}}
                onDeleteWeave={()=>{}}
                warpYarns={warpYarns}
                weftYarns={weftYarns}
                onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))}
                onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))}
                paletteColors={PANTONE_PALETTE}
                warpPatternString={warpPatternString}
                setWarpPatternString={setWarpPatternString}
                weftPatternString={weftPatternString}
                setWeftPatternString={setWeftPatternString}
                onOpenGridEditor={()=>{}}
                onOpenPatternGenerator={()=>{}}
                currentInput={{} as any}
                onApplyGenerated={()=>{}}
                onSimulate={() => setShowSimModal(true)}
                onGridOperation={()=>{}}
            />
        </div>

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)}
            weavePattern={compositeColors}
            structure={compositeStructure}
            epi={settings.epi}
            ppi={settings.ppi}
            warpYarns={warpYarns}
            weftYarns={weftYarns}
            warpYarnSequence={expandPatternString(warpPatternString)}
            weftYarnSequence={expandPatternString(weftPatternString)}
        />
    </div>
  );
};

import React, { useState, useCallback, useMemo } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, DensityZone, AppMode, JacquardData } from '../types';
import { expandPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 512, 
    weftPicks: 512, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    harnesses: 1 // Jacquard doesn't strictly use harnesses like Dobby
  });

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 512,
      height: 512,
      structure: new Uint8Array(512 * 512).fill(0).map((_, i) => (Math.floor(i / 512) + (i % 512)) % 2 === 0 ? 1 : 0)
  }));

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 }
  });

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');
  const [dentingPattern, setDentingPattern] = useState('1');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleResize = (size: number) => {
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) {
          newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      }
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
      setWarpPatternString(`${size}A`);
      setWeftPatternString(`${size}A`);
  };

  const handleGridOperation = (gridType: 'draft' | 'peg', action: string) => {
      const newData = new Uint8Array(jacquardData.structure);
      if (action === 'clear') newData.fill(0);
      if (action === 'invert') newData.forEach((v, i) => newData[i] = v === 1 ? 0 : 1);
      setJacquardData(prev => ({ ...prev, structure: newData }));
  };

  const warpColorArray = useMemo(() => {
      const yarns = warpYarns as Record<string, YarnDefinition>;
      const baseColor = yarns['A']?.color || '#888';
      return Array(jacquardData.width).fill(baseColor);
  }, [warpYarns, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const yarns = weftYarns as Record<string, YarnDefinition>;
      const baseColor = yarns['A']?.color || '#888';
      return Array(jacquardData.height).fill(baseColor);
  }, [weftYarns, jacquardData.height]);

  // Extract a 128x128 swatch for simulation to avoid crashing the renderer on 6k grids
  const simData = useMemo(() => {
      const size = 128;
      const rows: boolean[][] = [];
      const colors: string[][] = [];
      for (let y = 0; y < size; y++) {
          const rowB: boolean[] = [];
          const rowC: string[] = [];
          for (let x = 0; x < size; x++) {
              const isUp = jacquardData.structure[y * jacquardData.width + x] === 1;
              rowB.push(isUp);
              rowC.push(isUp ? warpColorArray[x] : weftColorArray[y]);
          }
          rows.push(rowB);
          colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={()=>{}} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={setAppMode} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span>{projectName}</span>
                        <span>{jacquardData.width} × {jacquardData.height}</span>
                        <span>{Math.round((jacquardData.width * jacquardData.height) / 1000000 * 10) / 10} MP</span>
                    </div>
                    <div className="flex items-center gap-2">
                        {[512, 1024, 2048, 4096, 6000].map(size => (
                            <button 
                                key={size}
                                onClick={() => handleResize(size)}
                                className={`px-2 py-0.5 rounded text-[10px] border transition-colors ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400 hover:text-white'}`}
                            >
                                {size}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex-1 relative">
                    <JacquardCanvas 
                        data={jacquardData}
                        onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))}
                        tool={currentTool}
                        viewMode={viewMode}
                        faceMode={faceMode}
                        warpColors={warpColorArray}
                        weftColors={weftColorArray}
                        gridDivision={settings.gridDivision}
                    />
                </div>
            </div>

            <RightPanel 
                settings={settings}
                onSettingsChange={setSettings}
                dentingPattern={dentingPattern}
                onDentingChange={setDentingPattern}
                onSnapshot={()=>{}}
                onLoadWeave={()=>{}}
                customWeaves={[]}
                onAddWeave={()=>{}}
                onUpdateWeave={()=>{}}
                onDeleteWeave={()=>{}}
                warpYarns={warpYarns}
                weftYarns={weftYarns}
                onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))}
                onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))}
                paletteColors={PANTONE_PALETTE}
                warpPatternString={warpPatternString}
                setWarpPatternString={setWarpPatternString}
                weftPatternString={weftPatternString}
                setWeftPatternString={setWeftPatternString}
                onOpenGridEditor={()=>{}}
                onOpenPatternGenerator={()=>{}}
                currentInput={{} as any}
                onApplyGenerated={()=>{}}
                onSimulate={() => setShowSimModal(true)}
                onGridOperation={(t, a) => handleGridOperation(t, a)}
            />
        </div>

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)}
            weavePattern={simData.colors}
            structure={simData.structure}
            epi={settings.epi}
            ppi={settings.ppi}
            warpYarns={warpYarns}
            weftYarns={weftYarns}
            warpYarnSequence={expandPatternString(warpPatternString).slice(0, 128)}
            weftYarnSequence={expandPatternString(weftPatternString).slice(0, 128)}
        />
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode } from '../types';

interface JacquardCanvasProps {
    data: JacquardData;
    onUpdate: (newData: Uint8Array) => void;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    gridDivision: number;
}

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, onUpdate, tool, viewMode, faceMode, warpColors, weftColors, gridDivision
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [view, setView] = useState({ x: 0, y: 0, zoom: 1 });
    const isInteracting = useRef(false);
    const lastGridPos = useRef({ x: -1, y: -1 });
    const localBuffer = useRef<Uint8Array>(data.structure);

    // Sync buffer when data changes from outside (e.g., clear/invert)
    useEffect(() => {
        localBuffer.current = data.structure;
        render();
    }, [data.structure]);

    const render = () => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        if (canvas.width !== w || canvas.height !== h) {
            canvas.width = w;
            canvas.height = h;
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        const startX = Math.floor(-view.x / zoom);
        const startY = Math.floor(-view.y / zoom);
        const endX = Math.min(data.width, startX + Math.ceil(w / zoom) + 1);
        const endY = Math.min(data.height, startY + Math.ceil(h / zoom) + 1);

        const isStructure = viewMode === 'structure';
        const isReverse = faceMode === 'reverse';
        const buffer = localBuffer.current;

        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * data.width + x;
                let val = buffer[idx] === 1;
                if (isReverse) val = !val;

                if (isStructure) {
                    ctx.fillStyle = val ? '#ffffff' : '#000000';
                } else {
                    ctx.fillStyle = val ? warpColors[x % warpColors.length] : weftColors[y % weftColors.length];
                }

                ctx.fillRect(
                    Math.floor(view.x + x * zoom),
                    Math.floor(view.y + y * zoom),
                    Math.ceil(zoom),
                    Math.ceil(zoom)
                );
            }
        }

        if (zoom > 4) {
            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            for (let x = Math.max(0, startX); x <= endX; x++) {
                if (x % gridDivision === 0) {
                    ctx.moveTo(view.x + x * zoom, 0);
                    ctx.lineTo(view.x + x * zoom, h);
                }
            }
            for (let y = Math.max(0, startY); y <= endY; y++) {
                if (y % gridDivision === 0) {
                    ctx.moveTo(0, view.y + y * zoom);
                    ctx.lineTo(w, view.y + y * zoom);
                }
            }
            ctx.stroke();
        }
    };

    useEffect(() => {
        render();
    }, [view, viewMode, faceMode, warpColors, weftColors]);

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;

        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const zoomFactor = wheelEv.deltaY > 0 ? 0.85 : 1.15;
            const newZoom = Math.min(200, Math.max(0.01, view.zoom * zoomFactor));
            const worldX = (mouseX - view.x) / view.zoom;
            const worldY = (mouseY - view.y) / view.zoom;
            setView({ x: mouseX - worldX * newZoom, y: mouseY - worldY * newZoom, zoom: newZoom });
            return;
        }

        if (tool === 'pan') {
            if (e.type === 'mousedown') {
                isInteracting.current = true;
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else if (e.type === 'mousemove' && isInteracting.current) {
                const dx = mouseX - lastGridPos.current.x;
                const dy = mouseY - lastGridPos.current.y;
                setView(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else {
                isInteracting.current = false;
            }
            return;
        }

        const gridX = Math.floor((mouseX - view.x) / view.zoom);
        const gridY = Math.floor((mouseY - view.y) / view.zoom);

        if (e.type === 'mousedown') {
            isInteracting.current = true;
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                const idx = gridY * data.width + gridX;
                localBuffer.current[idx] = localBuffer.current[idx] === 1 ? 0 : 1;
                lastGridPos.current = { x: gridX, y: gridY };
                render();
            }
        } else if (e.type === 'mousemove' && isInteracting.current) {
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                if (gridX !== lastGridPos.current.x || gridY !== lastGridPos.current.y) {
                    localBuffer.current[gridY * data.width + gridX] = 1;
                    lastGridPos.current = { x: gridX, y: gridY };
                    render();
                }
            }
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            if (isInteracting.current) {
                isInteracting.current = false;
                onUpdate(new Uint8Array(localBuffer.current));
            }
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden select-none">
            <canvas 
                ref={canvasRef}
                onMouseDown={handleInteraction}
                onMouseMove={handleInteraction}
                onMouseUp={handleInteraction}
                onMouseLeave={handleInteraction}
                onWheel={handleInteraction}
                className="block"
            />
            <div className="absolute bottom-4 left-4 flex gap-2">
