export interface QuantizationResult {
  pixels: number[]; // Array of palette indices
  palette: string[]; // Array of hex colors
  width: number;
  height: number;
}

const rgbToHex = (r: number, g: number, b: number) => {
    return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase();
};

const hexToRgb = (hex: string) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return [r, g, b];
};

const colorDistanceSq = (r1: number, g1: number, b1: number, r2: number, g2: number, b2: number) => {
    return (r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2;
};

export const loadImage = (file: File): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => {
            URL.revokeObjectURL(url);
            resolve(img);
        };
        img.onerror = () => {
            URL.revokeObjectURL(url);
            reject(new Error(`Failed to load image: ${file.name}. Ensure it is a valid image file.`));
        };
        img.src = url;
    });
};

/**
 * Process image with optimized inherent color detection and centroid merging.
 */
export const processImage = (
    img: HTMLImageElement, 
    maxColors: number = 12, 
    maxWidth: number = 1024
): QuantizationResult => {
    let w = img.width;
    let h = img.height;

    if (w > maxWidth) {
        const ratio = maxWidth / w;
        w = maxWidth;
        h = Math.floor(h * ratio);
    }

    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error("Could not initialize 2D context.");

    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(img, 0, 0, w, h);

    const imgData = ctx.getImageData(0, 0, w, h);
    const data = imgData.data;
    const pixelCount = w * h;

    // 1. Detect Inherent Unique Colors
    const uniqueColorsMap = new Map<string, number>();
    for (let i = 0; i < pixelCount; i++) {
        const offset = i * 4;
        if (data[offset + 3] < 128) continue; // Skip transparent
        const hex = rgbToHex(data[offset], data[offset+1], data[offset+2]);
        uniqueColorsMap.set(hex, (uniqueColorsMap.get(hex) || 0) + 1);
    }

    // Optimization: If image already has a limited palette, use it exactly
    if (uniqueColorsMap.size <= maxColors) {
        const palette = Array.from(uniqueColorsMap.keys());
        const pixels = new Array(pixelCount);
        for (let i = 0; i < pixelCount; i++) {
            const offset = i * 4;
            const hex = rgbToHex(data[offset], data[offset+1], data[offset+2]);
            pixels[i] = palette.indexOf(hex);
        }
        return { pixels, palette, width: w, height: h };
    }

    // 2. K-Means Clustering for rich bitmaps
    let centroids: number[][] = [];
    const sortedColors = Array.from(uniqueColorsMap.entries()).sort((a, b) => b[1] - a[1]);
    for (let i = 0; i < Math.min(maxColors * 2, sortedColors.length); i++) {
        if (centroids.length >= maxColors) break;
        centroids.push(hexToRgb(sortedColors[i][0]));
    }

    const assignments = new Uint8Array(pixelCount);
    let iterations = 0;
    const maxIters = 10;
    let changed = true;

    while (changed && iterations < maxIters) {
        changed = false;
        const sums = Array.from({ length: centroids.length }, () => [0, 0, 0]);
        const counts = new Uint32Array(centroids.length);

        for (let i = 0; i < pixelCount; i++) {
            const offset = i * 4;
            const r = data[offset], g = data[offset+1], b = data[offset+2];

            let minDist = Infinity;
            let bestIdx = 0;

            for (let c = 0; c < centroids.length; c++) {
                const d = colorDistanceSq(r, g, b, centroids[c][0], centroids[c][1], centroids[c][2]);
                if (d < minDist) {
                    minDist = d;
                    bestIdx = c;
                }
            }

            if (assignments[i] !== bestIdx) {
                assignments[i] = bestIdx;
                changed = true;
            }

            sums[bestIdx][0] += r; sums[bestIdx][1] += g; sums[bestIdx][2] += b;
            counts[bestIdx]++;
        }

        for (let c = 0; c < centroids.length; c++) {
            if (counts[c] > 0) {
                centroids[c] = [Math.round(sums[c][0] / counts[c]), Math.round(sums[c][1] / counts[c]), Math.round(sums[c][2] / counts[c])];
            }
        }
        iterations++;
    }

    // 3. Merge Identical Colors (Post-Clustering Optimization)
    const MERGE_THRESHOLD = 15 * 15; // Euclidean distance squared
    const finalPalette: string[] = [];
    const paletteMap = new Map<number, number>(); // Old Index -> New Merged Index

    centroids.forEach((c, i) => {
        const hex = rgbToHex(c[0], c[1], c[2]);
        let foundIdx = -1;

        // Look for similar color already in final palette
        for (let j = 0; j < finalPalette.length; j++) {
            const existingRgb = hexToRgb(finalPalette[j]);
            if (colorDistanceSq(c[0], c[1], c[2], existingRgb[0], existingRgb[1], existingRgb[2]) < MERGE_THRESHOLD) {
                foundIdx = j;
                break;
            }
        }

        if (foundIdx === -1) {
            finalPalette.push(hex);
            paletteMap.set(i, finalPalette.length - 1);
        } else {
            paletteMap.set(i, foundIdx);
        }
    });

    // Remap assignments to merged palette
    const remappedPixels = Array.from(assignments).map(idx => paletteMap.get(idx) || 0);

    return {
        pixels: remappedPixels,
        palette: finalPalette,
        width: w,
        height: h
    };
};

