                            >STRUCTURE</button>
                            <button 
                                onClick={() => setViewMode('structure')} 
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-gray-600 text-white' : 'text-gray-400'}`}
                            >ARTWORK</button>
                        </div>
                        <div className="flex items-center gap-1 border-l border-gray-800 pl-4">
                            {[1024, 2048, 4096].map(size => (
                                <button key={size} onClick={() => handleResize(size)} className={`px-2 py-0.5 rounded text-[10px] border transition-colors ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400 hover:text-white'}`}>{size}</button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="flex-1 relative">
                    <JacquardCanvas 
                        data={jacquardData}
                        artwork={artwork || undefined}
                        onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))}
