import React, { useState, useCallback, useMemo, useRef } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, AppMode, JacquardData } from '../types';
import { expandPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { loadImage, processImage } from '../services/imageProcessor';
import { LibraryWeave } from '../services/weaveLibrary';

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');
  const [loadingStatus, setLoadingStatus] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragOverColorIdx, setDragOverColorIdx] = useState<number | null>(null);

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 512, 
    weftPicks: 512, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    harnesses: 1
  });

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 512,
      height: 512,
      structure: new Uint8Array(512 * 512).fill(0).map((_, i) => (Math.floor(i / 512) + (i % 512)) % 2 === 0 ? 1 : 0)
  }));

  const [artwork, setArtwork] = useState<{
      data: Uint8Array;
      palette: string[];
      width: number;
      height: number;
  } | null>(null);

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 }
  });

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');
  const [dentingPattern, setDentingPattern] = useState('1');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleResize = (size: number) => {
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) {
          newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      }
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 

          setArtwork({
              data: new Uint8Array(result.pixels),
              palette: result.palette,
              width: result.width,
              height: result.height
          });

          setJacquardData({
              width: result.width,
              height: result.height,
              structure: new Uint8Array(result.width * result.height).fill(0)
          });

          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`);
          setWeftPatternString(`${result.height}A`);

          setProjectName(file.name.split('.')[0]);
          setViewMode('structure'); 
          setLoadingStatus(null);
      } catch (err: any) {
          console.error("Bitmap Process Error:", err);
          alert(err.message || "Failed to process bitmap.");
          setLoadingStatus(null);
      }
  };

  const handleApplyWeaveToColor = (weave: LibraryWeave, colorIdx: number) => {
    if (!artwork) return;
    setLoadingStatus(`Applying ${weave.name}...`);

    setTimeout(() => {
        const newStructure = new Uint8Array(jacquardData.structure);
        const { width, height } = jacquardData;
        const weaveDraft = weave.draft;
        const weavePeg = weave.pegPlan;
        const weaveW = weaveDraft[0].length;
        const weaveH = weavePeg.length;

        // Pre-calculate weave lookup for better performance
        const weaveLookup = new Uint8Array(weaveW * weaveH);
        const warpToHarness = new Int16Array(weaveW).fill(-1);
        for(let w=0; w<weaveW; w++) {
            for(let h=0; h<weave.harnesses; h++) {
                if(weaveDraft[h][w] === 1) { warpToHarness[w] = h; break; }
            }
        }
        for(let y=0; y<weaveH; y++) {
            for(let x=0; x<weaveW; x++) {
                const harness = warpToHarness[x];
                if(harness !== -1 && weavePeg[y][harness] === 1) {
                    weaveLookup[y * weaveW + x] = 1;
                }
            }
        }

        // Apply weave to mask
        for(let i=0; i<artwork.data.length; i++) {
            if(artwork.data[i] === colorIdx) {
                const x = i % width;
                const y = Math.floor(i / width);
                newStructure[i] = weaveLookup[(y % weaveH) * weaveW + (x % weaveW)];
            }
        }

        setJacquardData(prev => ({ ...prev, structure: newStructure }));
        setLoadingStatus(null);
        setViewMode('interlace');
    }, 50);
  };

  const warpColorArray = useMemo(() => {
      const yarns = warpYarns as Record<string, YarnDefinition>;
      const baseColor = yarns['A']?.color || '#888';
      return Array(jacquardData.width).fill(baseColor);
  }, [warpYarns, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const yarns = weftYarns as Record<string, YarnDefinition>;
      const baseColor = yarns['A']?.color || '#888';
      return Array(jacquardData.height).fill(baseColor);
  }, [weftYarns, jacquardData.height]);

  const simData = useMemo(() => {
      const size = 128;
      const rows: boolean[][] = [];
      const colors: string[][] = [];
      for (let y = 0; y < size; y++) {
          const rowB: boolean[] = [];
          const rowC: string[] = [];
          for (let x = 0; x < size; x++) {
              const idx = (y % jacquardData.height) * jacquardData.width + (x % jacquardData.width);
              const isUp = jacquardData.structure[idx] === 1;
              rowB.push(isUp);
              rowC.push(isUp ? warpColorArray[x % warpColorArray.length] : weftColorArray[y % weftColorArray.length]);
          }
          rows.push(rowB);
          colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  const handleGridOperation = (type: 'draft' | 'peg', action: string) => {
      const newData = new Uint8Array(jacquardData.structure);
      if (action === 'clear') newData.fill(0);
      else if (action === 'invert') {
          for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1;
      }
      setJacquardData(prev => ({ ...prev, structure: newData }));
  };

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />

        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={setAppMode} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{jacquardData.width} × {jacquardData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                         <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                            <button 
                                onClick={() => setViewMode('interlace')}
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-gray-600 text-white' : 'text-gray-400'}`}
                            >STRUCTURE</button>
                            <button 
                                onClick={() => setViewMode('structure')} 
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-gray-600 text-white' : 'text-gray-400'}`}
                            >ARTWORK</button>
                        </div>
                        <div className="flex items-center gap-1 border-l border-gray-800 pl-4">
                            {[1024, 2048, 4096].map(size => (
                                <button key={size} onClick={() => handleResize(size)} className={`px-2 py-0.5 rounded text-[10px] border transition-colors ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400 hover:text-white'}`}>{size}</button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="flex-1 relative">
                    <JacquardCanvas 
                        data={jacquardData}
                        artwork={artwork || undefined}
                        onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))}
                        tool={currentTool}
                        viewMode={viewMode}
                        faceMode={faceMode}
                        warpColors={warpColorArray}
                        weftColors={weftColorArray}
                        gridDivision={settings.gridDivision}
                    />
                </div>

                {artwork && (
                    <div className="h-20 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl">
                        <div className="flex flex-col">
                            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest mb-1">Optimized Palette</span>
                            <span className="text-[10px] text-gray-400 font-mono">{artwork.palette.length} Inherent Colors</span>
                        </div>
                        <div className="flex-1 flex items-center gap-3 overflow-x-auto no-scrollbar py-2">
                            {artwork.palette.map((color, idx) => (
                                <div 
                                    key={`${color}-${idx}`}
                                    onDragOver={(e) => { e.preventDefault(); setDragOverColorIdx(idx); }}
                                    onDragLeave={() => setDragOverColorIdx(null)}
                                    onDrop={(e) => {
                                        e.preventDefault();
                                        setDragOverColorIdx(null);
                                        const weaveData = e.dataTransfer.getData('weave-obj');
                                        if (weaveData) {
                                            handleApplyWeaveToColor(JSON.parse(weaveData), idx);
                                        }
                                    }}
                                    className={`group flex flex-col items-center gap-1 shrink-0 bg-gray-800/40 p-2 rounded-lg border transition-all ${dragOverColorIdx === idx ? 'bg-blue-900/40 border-blue-500 scale-105 shadow-lg shadow-blue-500/20' : 'border-gray-700/50 hover:bg-gray-800'}`}
                                >
                                    <div 
                                        className="w-8 h-8 rounded-md border border-white/10 shadow-md transition-transform" 
                                        style={{ backgroundColor: color }}
                                    />
                                    <span className="text-[8px] font-mono text-gray-500 uppercase">{idx + 1}: {color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end">
                            <span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drag weave to color</span>
                            <button 
                                onClick={() => setArtwork(null)}
                                className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded hover:bg-red-900/50 transition-colors font-bold uppercase tracking-tighter"
                            >
                                Clear Artwork
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <RightPanel 
                settings={settings}
                onSettingsChange={setSettings}
                dentingPattern={dentingPattern}
                onDentingChange={setDentingPattern}
                onSnapshot={()=>{}}
                onLoadWeave={()=>{}}
                customWeaves={[]}
                onAddWeave={()=>{}}
                onUpdateWeave={()=>{}}
                onDeleteWeave={()=>{}}
                warpYarns={warpYarns}
                weftYarns={weftYarns}
                onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))}
                onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))}
                paletteColors={PANTONE_PALETTE}
                warpPatternString={warpPatternString}
                setWarpPatternString={setWarpPatternString}
                weftPatternString={weftPatternString}
                setWeftPatternString={setWeftPatternString}
                onOpenGridEditor={()=>{}}
                onOpenPatternGenerator={()=>{}}
                currentInput={{} as any}
                onApplyGenerated={()=>{}}
                onSimulate={() => setShowSimModal(true)}
                onGridOperation={(t, a) => handleGridOperation(t, a)}
            />
        </div>

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)}
            weavePattern={simData.colors}
            structure={simData.structure}
            epi={settings.epi}
            ppi={settings.ppi}
            warpYarns={warpYarns}
            weftYarns={weftYarns}
            warpYarnSequence={expandPatternString(warpPatternString).slice(0, 128)}
            weftYarnSequence={expandPatternString(weftPatternString).slice(0, 128)}
        />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { WeaveSettings, WeaveInput, YarnDefinition } from '../types';
import { LayersIcon, ListIcon, PaletteIcon, GridFillIcon, GridIcon, PencilIcon, TrashIcon, PlusIcon, FlipIcon, CopyIcon, ArrowDownIcon, ArrowDownIcon as ArrowUpIcon } from './icons';
import { WEAVE_LIBRARY, LibraryWeave } from '../services/weaveLibrary';
import { TextPatternEditor } from './TextPatternEditor';
import { AiControl } from './AiControl';
import { WeaveThumbnail } from './WeaveThumbnail';
import { YarnDesignerModal } from './YarnDesignerModal';
import { WeaveEditorModal } from './WeaveEditorModal';
import { GridToolbar } from './GridToolbar';
import { getTotalThreads } from '../utils/patternParser';

interface RightPanelProps {
    settings: WeaveSettings;
    onSettingsChange: (newSettings: WeaveSettings) => void;
    dentingPattern: string;
    onDentingChange: (val: string) => void;
    onSnapshot: () => void;
    onLoadWeave: (weave: LibraryWeave) => void;

    // Custom Weaves
    customWeaves: LibraryWeave[];
    onAddWeave: (weave: LibraryWeave) => void;
    onUpdateWeave: (weave: LibraryWeave) => void;
    onDeleteWeave: (id: string) => void;

    // Yarns
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    onUpdateWarpYarn: (char: string, def: YarnDefinition) => void;
    onUpdateWeftYarn: (char: string, def: YarnDefinition) => void;
    onUpdateAllYarns?: (type: 'warp' | 'weft', yarns: { [key: string]: YarnDefinition }) => void;

    // Palette (Library)
    paletteColors: string[];

    warpPatternString: string;
    setWarpPatternString: (val: string) => void;
    weftPatternString: string;
    setWeftPatternString: (val: string) => void;
    onOpenGridEditor: (type: 'warp' | 'weft') => void;
    onOpenPatternGenerator: (type: 'warp' | 'weft') => void;

    currentInput: WeaveInput;
    onApplyGenerated: (data: any) => void;
    onSimulate: () => void;

    selectedColorIndex?: number;
    onSelectColor?: (index: number) => void;

    // Grid Ops
    onGridOperation: (gridType: 'draft' | 'peg', action: 'clear' | 'invert' | 'shiftUp' | 'shiftDown' | 'shiftLeft' | 'shiftRight' | 'double') => void;

    activeYarnId?: string;
    selectedYarnType?: 'warp' | 'weft'; 
    onSelectYarn?: (id: string, type: 'warp' | 'weft') => void; 
    onActiveYarnChange?: (char: string) => void; 

    forcedTab?: TabType; 
    onSyncGridDimensions?: (warpLen: number, weftLen: number) => void; 
}

type TabType = 'construction' | 'pattern' | 'weave' | 'yarns' | 'colors';

// Helper Components Defined Outside to prevent Remounting
const TabButton: React.FC<{ id: TabType, activeTab: TabType, icon: React.ReactNode, label: string, onClick: (id: TabType) => void }> = ({ id, activeTab, icon, label, onClick }) => (
    <button
        onClick={() => onClick(id)}
        className={`flex-1 flex flex-col items-center justify-center py-3 gap-1 border-b-2 transition-colors ${activeTab === id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
    >
        {icon}
        <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
    </button>
);

const SliderInput: React.FC<{
    label: string; value: number; onChange?: (value: number) => void; min?: number; max?: number; step?: number; subLabel?: string; disabled?: boolean; onPointerDown?: () => void;
}> = ({ label, value, onChange, min, max, step, subLabel, disabled, onPointerDown }) => (
    <div className="mb-5">
        <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex justify-between">
            <span>{label} {subLabel && <span className="text-gray-400 normal-case ml-1">({subLabel})</span>}</span>
            <span className={`${disabled ? 'text-gray-500' : 'text-blue-600'} font-mono`}>{value}</span>
        </label>
        {disabled ? (
            <div className="w-full h-1 bg-gray-200 rounded-lg opacity-50"></div>
        ) : (
            <input
                type="range" min={min} max={max} step={step} value={value}
                onChange={(e) => onChange && onChange(parseInt(e.target.value, 10))}
                onPointerDown={onPointerDown}
                className="w-full h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600 hover:accent-blue-500"
            />
        )}
    </div>
);

const YarnList: React.FC<{ 
    yarns: {[key: string]: YarnDefinition}, 
    type: 'warp' | 'weft',
    activeId?: string,
    isSelectedType?: boolean,
    onSelect?: (id: string, type: 'warp' | 'weft') => void,
    onEdit: (char: string, def: YarnDefinition) => void,
    onAssignColor: (char: string) => void, 
    onDropYarn: (sourceId: string, sourceType: 'warp' | 'weft', targetId: string) => void,
    label: string 
}> = ({ yarns, type, activeId, isSelectedType, onSelect, onEdit, onAssignColor, onDropYarn, label }) => {
    const letters = ['A','B','C','D','E','F','G','H'];
    const [dragOverId, setDragOverId] = useState<string | null>(null);

    return (
        <div className="mb-4">
            <h2 className="text-sm font-bold text-gray-900 mb-2">{label}</h2>
            <div className="flex flex-col gap-2">
                {letters.map((char) => {
                    const yarn = yarns[char];
                    const isSelected = isSelectedType && activeId === char;
                    const isDragOver = dragOverId === char;

                    if (!yarn) {
                        return (
                            <div 
                                key={char} 
                                className={`flex items-center gap-3 p-2 rounded-md border border-dashed hover:bg-blue-50 transition-all cursor-pointer opacity-60 hover:opacity-100 ${isSelected ? 'border-blue-500 bg-blue-50' : (isDragOver ? 'border-blue-400 bg-blue-50 ring-2 ring-blue-100' : 'border-gray-300 hover:border-blue-400')}`}
                                onClick={() => {
                                    const defaultDef: YarnDefinition = { 
                                        color: '#CCCCCC', 
                                        model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 28, ply: 1, thickness: 1.0, twist: 'Z', tpi: 15, sheen: 0.5, roughness: 0.5, price: 0,
                                        bindingDepth: 0.05
                                    };
                                    onEdit(char, defaultDef);
                                    onSelect && onSelect(char, type);
                                }}
                                onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                                onDragLeave={() => setDragOverId(null)}
                                onDrop={(e) => {
                                    e.preventDefault();
                                    setDragOverId(null);
                                    const data = e.dataTransfer.getData('yarn-id');
                                    const sType = e.dataTransfer.getData('yarn-type') as 'warp' | 'weft';
                                    if (data) onDropYarn(data, sType, char);
                                }}
                                title={`Initialize Yarn ${char}`}
                            >
                                <div className="font-mono font-bold text-gray-400 w-4">{char}</div>
                                <div className="text-[10px] text-gray-400 font-medium">Empty Slot</div>
                                <PlusIcon className="w-4 h-4 text-gray-400 ml-auto" />
                            </div>
                        );
                    }

                    const code = yarn.code || (yarn.count ? `${yarn.ply||1}/${yarn.count} ${yarn.countSystem||'Nm'}` : `Type ${char}`);

                    return (
                        <div 
                            key={char} 
                            draggable
                            onDragStart={(e) => {
                                e.dataTransfer.setData('yarn-id', char);
                                e.dataTransfer.setData('yarn-type', type);
                                e.dataTransfer.effectAllowed = 'copy';
                            }}
                            onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                            onDragLeave={() => setDragOverId(null)}
                            onDrop={(e) => {
                                e.preventDefault();
                                setDragOverId(null);
                                const data = e.dataTransfer.getData('yarn-id');
                                const sType = e.dataTransfer.getData('yarn-type') as 'warp' | 'weft';
                                if (data) onDropYarn(data, sType, char);
                            }}
                            onClick={() => onSelect && onSelect(char, type)}
                            className={`flex items-center gap-3 p-2 rounded-md border transition-all group cursor-pointer ${isSelected ? 'bg-gray-200 border-gray-400 ring-1 ring-gray-300' : (isDragOver ? 'border-blue-400 bg-blue-50 ring-2 ring-blue-100' : 'border-gray-200 hover:bg-gray-50')}`}
                        >
                            <div className={`font-mono font-bold w-4 ${isSelected ? 'text-gray-900' : 'text-gray-500'}`}>{char}</div>

                            <div className="flex-1 min-w-0">
                                <div 
                                    className="h-3 rounded-full relative overflow-hidden shadow-inner flex items-center hover:ring-2 hover:ring-blue-400 hover:ring-offset-1 transition-all mb-1" 
                                    style={{ background: yarn.color }}
                                    onClick={(e) => { e.stopPropagation(); onAssignColor(char); }}
                                    title="Click to apply selected palette color"
                                >
                                    <div className="absolute inset-0 bg-gradient-to-b from-black/10 via-transparent to-black/20"></div>
                                </div>
                                <div className="flex justify-between items-center px-1">
                                     <span className="text-[10px] text-gray-500 font-medium truncate">{code}</span>
                                     <span className="text-[9px] text-gray-400">{yarn.fiberType || 'Cotton'}</span>
                                </div>
                            </div>

                            <button 
                                onClick={(e) => { e.stopPropagation(); onEdit(char, yarn); }}
                                className={`w-7 h-7 flex items-center justify-center rounded-full border hover:border-blue-500 hover:bg-blue-50 hover:text-blue-600 transition-all shrink-0 ${isSelected ? 'border-gray-300 bg-white text-gray-500' : 'border-gray-200 text-gray-400'}`}
                                title="Edit Yarn Properties"
                            >
                                <PencilIcon className="w-3 h-3" />
                            </button>
                        </div>
                    )
                })}
            </div>
        </div>
    );
}

export const RightPanel: React.FC<RightPanelProps> = ({
    settings, onSettingsChange, dentingPattern, onDentingChange, onSnapshot, onLoadWeave,
    customWeaves, onAddWeave, onUpdateWeave, onDeleteWeave,
    warpYarns, weftYarns, onUpdateWarpYarn, onUpdateWeftYarn, onUpdateAllYarns,
    paletteColors,
    warpPatternString, setWarpPatternString, weftPatternString, setWeftPatternString, onOpenGridEditor, onOpenPatternGenerator,
    currentInput, onApplyGenerated, onSimulate,
    selectedColorIndex, onSelectColor,
    onGridOperation,
    activeYarnId = 'A', selectedYarnType, onSelectYarn, onActiveYarnChange,
    forcedTab, onSyncGridDimensions
}) => {
    const [activeTab, setActiveTab] = useState<TabType>('construction');
    const [editingYarn, setEditingYarn] = useState<{ id: string, type: 'warp' | 'weft', def: YarnDefinition } | null>(null);
    const [weaveEditorState, setWeaveEditorState] = useState<{ isOpen: boolean, weave?: LibraryWeave }>({ isOpen: false });

    useEffect(() => {
        if (forcedTab) {
            setActiveTab(forcedTab);
        }
    }, [forcedTab]);

    const warpColors = Object.fromEntries(Object.entries(warpYarns).map(([k,v]) => [k, (v as YarnDefinition).color]));
    const weftColors = Object.fromEntries(Object.entries(weftYarns).map(([k,v]) => [k, (v as YarnDefinition).color]));

    const allWeaves = [...WEAVE_LIBRARY, ...customWeaves];
    const activePaletteColor = paletteColors[selectedColorIndex || 0];
    const letters = ['A','B','C','D','E','F','G','H'];

    const handleMirror = () => {
        onSnapshot();
        setWeftPatternString(warpPatternString);
    };

    const handleShuffleColors = () => {
        if (!onUpdateAllYarns) return;
        onSnapshot();

        const shuffle = (yarns: { [key: string]: YarnDefinition }) => {
            const newYarns = { ...yarns };
            const colors = letters.filter(l => yarns[l]).map(l => yarns[l].color);
            if (colors.length === 0) return newYarns;
            colors.unshift(colors.pop()!);
            letters.forEach((l, i) => {
                if (newYarns[l] && colors[i]) {
                    newYarns[l] = { ...newYarns[l], color: colors[i] };
                }
            });
            return newYarns;
        };

        onUpdateAllYarns('warp', shuffle(warpYarns));
        onUpdateAllYarns('weft', shuffle(weftYarns));
    };

    const handleCopyWarpToWeft = () => {
        if (window.confirm("Copy all Warp yarn definitions to Weft? Current weft yarns will be overwritten.")) {
            onSnapshot();
            const newWeft = { ...weftYarns };
            letters.forEach(l => {
                if (warpYarns[l]) newWeft[l] = { ...warpYarns[l] };
            });
            if (onUpdateAllYarns) onUpdateAllYarns('weft', newWeft);
        }
    };

    const handleCopyWeftToWarp = () => {
        if (window.confirm("Copy all Weft yarn definitions to Warp? Current warp yarns will be overwritten.")) {
            onSnapshot();
            const newWarp = { ...warpYarns };
            letters.forEach(l => {
                if (weftYarns[l]) newWarp[l] = { ...weftYarns[l] };
            });
            if (onUpdateAllYarns) onUpdateAllYarns('warp', newWarp);
        }
    };

    const handleDropYarn = (sourceId: string, sourceType: 'warp' | 'weft', targetId: string, targetType: 'warp' | 'weft') => {
        onSnapshot();
        const sourceBank = sourceType === 'warp' ? warpYarns : weftYarns;
        const sourceDef = sourceBank[sourceId];
        if (!sourceDef) return;

        if (targetType === 'warp') {
            onUpdateWarpYarn(targetId, { ...sourceDef });
        } else {
            onUpdateWeftYarn(targetId, { ...sourceDef });
        }
    };

    const patternWarpRepeat = getTotalThreads(warpPatternString);
    const patternWeftRepeat = getTotalThreads(weftPatternString);

    return (
        <>
            <div className="w-80 flex-shrink-0 bg-white border-l border-gray-200 flex flex-col z-20 shadow-xl">
                <div className="flex border-b border-gray-200 bg-gray-50 overflow-x-auto no-scrollbar">
                    <TabButton id="construction" activeTab={activeTab} onClick={setActiveTab} icon={<LayersIcon className="w-5 h-5" />} label="Specs" />
                    <TabButton id="weave" activeTab={activeTab} onClick={setActiveTab} icon={<GridFillIcon className="w-5 h-5" />} label="Weave" />
                    <TabButton id="pattern" activeTab={activeTab} onClick={setActiveTab} icon={<GridIcon className="w-5 h-5" />} label="Pattern" />
                    <TabButton id="yarns" activeTab={activeTab} onClick={setActiveTab} icon={<ListIcon className="w-5 h-5" />} label="Yarns" />
                    <TabButton id="colors" activeTab={activeTab} onClick={setActiveTab} icon={<PaletteIcon className="w-5 h-5" />} label="Colors" />
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar p-5">

                    {activeTab === 'construction' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <h2 className="text-sm font-bold text-gray-900 mb-4">Fabric Specifications</h2>

                            <div className="bg-blue-50 border border-blue-100 p-3 rounded-lg mb-6">
                                <div className="flex justify-between items-center mb-1 text-xs">
                                    <span className="text-gray-500 uppercase tracking-wide">Pattern Repeat</span>
                                    <span className="font-bold text-gray-700">{patternWarpRepeat} x {patternWeftRepeat}</span>
                                </div>
                                <div className="flex justify-between items-center mb-3 text-xs">
                                    <span className="text-gray-500 uppercase tracking-wide">Grid Dimensions</span>
                                    <span className="font-bold text-gray-700">{settings.warpThreads} x {settings.weftPicks}</span>
                                </div>
                                {onSyncGridDimensions && (
                                    <button 
                                        onClick={() => onSyncGridDimensions(patternWarpRepeat, patternWeftRepeat)}
                                        className="w-full py-2 bg-blue-600 hover:bg-blue-500 text-white rounded font-bold text-xs shadow-sm transition-colors"
                                    >
                                        Sync Grid to Pattern
                                    </button>
                                )}
                            </div>

                            <SliderInput label="Draft Repeat (Threads)" value={settings.warpThreads} onChange={(v) => onSettingsChange({ ...settings, warpThreads: v })} onPointerDown={onSnapshot} min={4} max={128} step={4} />
                            <SliderInput label="Peg Plan Repeat (Picks)" value={settings.weftPicks} onChange={(v) => onSettingsChange({ ...settings, weftPicks: v })} onPointerDown={onSnapshot} min={4} max={128} step={4} />
                            <SliderInput label="Harnesses" value={settings.harnesses} onChange={(v) => onSettingsChange({ ...settings, harnesses: v })} onPointerDown={onSnapshot} min={2} max={120} step={1} />

                            <div className="h-px bg-gray-100 my-6" />

                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Set & Reed</h3>
                            <SliderInput label="Ends Per Inch" value={settings.epi} onChange={(v) => onSettingsChange({ ...settings, epi: v })} onPointerDown={onSnapshot} min={8} max={120} step={1} />
                            <SliderInput label="Picks Per Inch" value={settings.ppi} onChange={(v) => onSettingsChange({ ...settings, ppi: v })} onPointerDown={onSnapshot} min={8} max={120} step={1} />

                            <div className="mb-4">
                                <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 block">Denting Pattern</label>
                                <input type="text" value={dentingPattern} onChange={(e) => { onSnapshot(); onDentingChange(e.target.value); }}
                                    className="w-full bg-white border border-gray-300 rounded p-2 text-sm font-mono focus:border-blue-500 focus:outline-none"
                                />
                            </div>

                            <div className="mt-8 pt-4 border-t border-gray-100">
                                <button onClick={onSimulate} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-bold shadow-sm transition-colors flex items-center justify-center gap-2">
                                    Simulate Fabric
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === 'weave' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <div className="mb-6">
                                <h2 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Draft Operations</h2>
                                <GridToolbar 
                                    onClear={() => onGridOperation('draft', 'clear')}
                                    onInvert={() => onGridOperation('draft', 'invert')}
                                    onShiftUp={() => onGridOperation('draft', 'shiftUp')}
                                    onShiftDown={() => onGridOperation('draft', 'shiftDown')}
                                    onShiftLeft={() => onGridOperation('draft', 'shiftLeft')}
                                    onShiftRight={() => onGridOperation('draft', 'shiftRight')}
                                    onDouble={() => onGridOperation('draft', 'double')}
                                />
                                <h2 className="text-xs font-bold text-gray-400 uppercase tracking-widest mt-4 mb-2">Peg Plan Operations</h2>
                                <GridToolbar 
                                    onClear={() => onGridOperation('peg', 'clear')}
                                    onInvert={() => onGridOperation('peg', 'invert')}
                                    onShiftUp={() => onGridOperation('peg', 'shiftUp')}
                                    onShiftDown={() => onGridOperation('peg', 'shiftDown')}
                                    onShiftLeft={() => onGridOperation('peg', 'shiftLeft')}
                                    onShiftRight={() => onGridOperation('peg', 'shiftRight')}
                                    onDouble={() => onGridOperation('peg', 'double')}
                                />
                            </div>

                            <div className="h-px bg-gray-100 mb-4" />

                            <div className="flex justify-between items-center mb-4">
                                <h2 className="text-sm font-bold text-gray-900">Weave Library</h2>
                                <button 
                                    onClick={() => setWeaveEditorState({ isOpen: true })}
                                    className="p-1 text-blue-600 hover:bg-blue-50 rounded"
                                    title="Add Custom Weave"
                                >
                                    <PlusIcon className="w-5 h-5" />
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                {allWeaves.map(weave => {
                                    const isCustom = weave.id.startsWith('custom-');
                                    return (
                                        <div key={weave.id} className="relative group">
                                            <button
                                                draggable
                                                onDragStart={(e) => {
                                                    e.dataTransfer.setData('weave-obj', JSON.stringify(weave));
                                                    e.dataTransfer.effectAllowed = 'copy';
                                                }}
                                                onClick={() => { onSnapshot(); onLoadWeave(weave); }}
                                                className="flex flex-col items-start p-2 bg-gray-50 border border-gray-200 hover:border-blue-500 hover:bg-blue-50 rounded-lg transition-all text-left w-full cursor-grab active:cursor-grabbing"
                                            >
                                                <WeaveThumbnail weave={weave} className="w-full aspect-square mb-2 pointer-events-none" />
                                                <span className="text-xs font-semibold text-gray-700 group-hover:text-blue-700 leading-tight">{weave.name}</span>
                                                <span className="text-[10px] text-gray-400 mt-1">{weave.harnesses}H</span>
                                            </button>

                                            {isCustom && (
                                                <div className="absolute top-1 right-1 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); setWeaveEditorState({ isOpen: true, weave }); }}
                                                        className="p-1 bg-white border border-gray-200 rounded shadow-sm hover:text-blue-600"
                                                    >
                                                        <PencilIcon className="w-3 h-3" />
                                                    </button>
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); onDeleteWeave(weave.id); }}
                                                        className="p-1 bg-white border border-gray-200 rounded shadow-sm hover:text-red-600"
                                                    >
                                                        <TrashIcon className="w-3 h-3" />
                                                    </button>
                                                </div>
                                            )}
                                        </div>
                                    )
                                })}
                            </div>
                        </div>
                    )}

                    {activeTab === 'pattern' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200 flex flex-col gap-6">
                            <div className="flex gap-2 p-2 bg-gray-50 rounded-lg border border-gray-200 mb-2">
                                <button onClick={handleMirror} className="flex-1 flex flex-col items-center gap-1 p-2 rounded hover:bg-gray-200 text-gray-500 hover:text-blue-600 transition-colors" title="Copy Warp Pattern to Weft">
                                    <CopyIcon className="w-4 h-4" />
                                    <span className="text-[10px] font-bold">Mirror</span>
                                </button>
                                <button onClick={handleShuffleColors} className="flex-1 flex flex-col items-center gap-1 p-2 rounded hover:bg-gray-200 text-gray-500 hover:text-blue-600 transition-colors" title="Rotate Yarn Colors">
                                    <FlipIcon className="w-4 h-4" />
                                    <span className="text-[10px] font-bold">Shuffle</span>
                                </button>
                            </div>

                            <div className="bg-blue-50/50 p-3 rounded-lg border border-blue-100">
                                <h3 className="text-xs font-bold text-blue-500 uppercase mb-2">Active Yarn Brush</h3>
                                <div className="flex flex-wrap gap-2">
                                    {letters.map((char) => (
                                        <button 
                                            key={char} 
                                            onClick={() => onActiveYarnChange?.(char)}
                                            className={`
                                                w-8 h-8 rounded flex items-center justify-center font-mono font-bold text-sm transition-all
                                                ${activeYarnId === char 
                                                    ? 'bg-blue-600 text-white shadow-md ring-2 ring-blue-300 ring-offset-1' 
                                                    : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'}
                                            `}
                                            title={`Paint with Yarn ${char}`}
                                        >
                                            {char}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <h3 className="text-xs font-bold text-gray-500 uppercase mb-1">Warp Sequence</h3>
                                <TextPatternEditor 
                                    title="" 
                                    value={warpPatternString} 
                                    onValueChange={setWarpPatternString}
                                    colorMap={warpColors} 
                                    onOpenGridEditor={() => onOpenGridEditor('warp')}
                                    onFocus={onSnapshot}
                                />
                                <div className="h-4" />

                                <h3 className="text-xs font-bold text-gray-500 uppercase mb-1">Weft Sequence</h3>
                                <TextPatternEditor 
                                    title="" 
                                    value={weftPatternString} 
                                    onValueChange={setWeftPatternString}
                                    colorMap={weftColors} 
                                    onOpenGridEditor={() => onOpenGridEditor('weft')}
                                    onFocus={onSnapshot}
                                />
                            </div>

                            <div className="h-px bg-gray-100" />

                            <AiControl currentInput={currentInput} settings={settings} onApplyGenerated={onApplyGenerated} />
                        </div>
                    )}

                    {activeTab === 'yarns' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <YarnList 
                                yarns={warpYarns}
                                type="warp"
                                activeId={activeYarnId}
                                isSelectedType={selectedYarnType === 'warp'}
                                onSelect={onSelectYarn}
                                onEdit={(char, def) => setEditingYarn({ id: char, type: 'warp', def })}
                                onAssignColor={(char) => { onSnapshot(); onUpdateWarpYarn(char, { ...warpYarns[char], color: activePaletteColor }); }}
                                onDropYarn={(sId, sType, tId) => handleDropYarn(sId, sType, tId, 'warp')}
                                label="Warp Yarns" 
                            />

                            <div className="flex flex-col items-center gap-1 my-2">
                                <div className="flex gap-4">
                                    <button 
                                        onClick={handleCopyWarpToWeft}
                                        className="p-2 bg-gray-100 hover:bg-blue-100 text-gray-400 hover:text-blue-600 rounded-lg transition-all shadow-sm border border-gray-200 flex flex-col items-center gap-1"
                                        title="Copy all Warp yarns to Weft"
                                    >
                                        <ArrowDownIcon className="w-5 h-5" />
                                        <span className="text-[8px] font-bold uppercase">Warp to Weft</span>
                                    </button>
                                    <button 
                                        onClick={handleCopyWeftToWarp}
                                        className="p-2 bg-gray-100 hover:bg-blue-100 text-gray-400 hover:text-blue-600 rounded-lg transition-all shadow-sm border border-gray-200 flex flex-col items-center gap-1"
                                        title="Copy all Weft yarns to Warp"
                                    >
                                        <ArrowDownIcon className="w-5 h-5 rotate-180" />
                                        <span className="text-[8px] font-bold uppercase">Weft to Warp</span>
                                    </button>
                                </div>
                            </div>

                            <YarnList 
                                yarns={weftYarns}
                                type="weft"
                                activeId={activeYarnId}
                                isSelectedType={selectedYarnType === 'weft'}
                                onSelect={onSelectYarn}
                                onEdit={(char, def) => setEditingYarn({ id: char, type: 'weft', def })}
                                onAssignColor={(char) => { onSnapshot(); onUpdateWeftYarn(char, { ...weftYarns[char], color: activePaletteColor }); }}
                                onDropYarn={(sId, sType, tId) => handleDropYarn(sId, sType, tId, 'weft')}
                                label="Weft Yarns" 
                            />
                        </div>
                    )}

                    {activeTab === 'colors' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <h3 className="text-lg font-medium text-gray-900 mb-3">Color Library</h3>
                            <div className="grid grid-cols-6 gap-2">
                                {paletteColors.map((color, idx) => (
                                    <div 
                                        key={idx} 
                                        className={`relative group cursor-pointer transition-all p-0.5 rounded ${idx === selectedColorIndex ? 'ring-2 ring-blue-500 bg-blue-100' : ''}`}
                                        onClick={() => onSelectColor?.(idx)}
                                    >
                                        <div className="w-full aspect-square rounded shadow-sm border border-gray-200" style={{backgroundColor: color}} />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {editingYarn && (
                <YarnDesignerModal 
                    isOpen={!!editingYarn}
                    onClose={() => setEditingYarn(null)}
                    yarnId={editingYarn.id}
                    yarnType={editingYarn.type}
                    initialYarn={editingYarn.def}
                    onSave={(newYarn) => {
                        onSnapshot();
                        if (editingYarn.type === 'warp') {
                            onUpdateWarpYarn(editingYarn.id, newYarn);
                        } else {
                            onUpdateWeftYarn(editingYarn.id, newYarn);
                        }
                    }}
                />
            )}

            {weaveEditorState.isOpen && (
                <WeaveEditorModal
                    isOpen={weaveEditorState.isOpen}
                    initialWeave={weaveEditorState.weave}
                    onClose={() => setWeaveEditorState({ isOpen: false })}
                    onSave={(weave) => {
                        onSnapshot();
                        if (weaveEditorState.weave) {
                            onUpdateWeave(weave);
                        } else {
                            onAddWeave(weave);
                        }
                    }}
                />
            )}
        </>
    );
};

import React, { useState, useEffect } from 'react';
import { WeaveSettings, WeaveInput, YarnDefinition } from '../types';
import { LayersIcon, ListIcon, PaletteIcon, GridFillIcon, GridIcon, PencilIcon, TrashIcon, PlusIcon, FlipIcon, CopyIcon, ArrowDownIcon, ArrowDownIcon as ArrowUpIcon } from './icons';
import { WEAVE_LIBRARY, LibraryWeave } from '../services/weaveLibrary';
import { TextPatternEditor } from './TextPatternEditor';
import { AiControl } from './AiControl';
import { WeaveThumbnail } from './WeaveThumbnail';
import { YarnDesignerModal } from './YarnDesignerModal';
import { WeaveEditorModal } from './WeaveEditorModal';
import { GridToolbar } from './GridToolbar';
import { getTotalThreads } from '../utils/patternParser';

interface RightPanelProps {
    settings: WeaveSettings;
    onSettingsChange: (newSettings: WeaveSettings) => void;
    dentingPattern: string;
    onDentingChange: (val: string) => void;
    onSnapshot: () => void;
    onLoadWeave: (weave: LibraryWeave) => void;

    // Custom Weaves
    customWeaves: LibraryWeave[];
    onAddWeave: (weave: LibraryWeave) => void;
    onUpdateWeave: (weave: LibraryWeave) => void;
    onDeleteWeave: (id: string) => void;

    // Yarns
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    onUpdateWarpYarn: (char: string, def: YarnDefinition) => void;
    onUpdateWeftYarn: (char: string, def: YarnDefinition) => void;
    onUpdateAllYarns?: (type: 'warp' | 'weft', yarns: { [key: string]: YarnDefinition }) => void;

    // Palette (Library)
    paletteColors: string[];

    warpPatternString: string;
    setWarpPatternString: (val: string) => void;
    weftPatternString: string;
    setWeftPatternString: (val: string) => void;
    onOpenGridEditor: (type: 'warp' | 'weft') => void;
    onOpenPatternGenerator: (type: 'warp' | 'weft') => void;

    currentInput: WeaveInput;
    onApplyGenerated: (data: any) => void;
    onSimulate: () => void;

    selectedColorIndex?: number;
    onSelectColor?: (index: number) => void;

    // Grid Ops
    onGridOperation: (gridType: 'draft' | 'peg', action: 'clear' | 'invert' | 'shiftUp' | 'shiftDown' | 'shiftLeft' | 'shiftRight' | 'double') => void;

    activeYarnId?: string;
    selectedYarnType?: 'warp' | 'weft'; 
    onSelectYarn?: (id: string, type: 'warp' | 'weft') => void; 
    onActiveYarnChange?: (char: string) => void; 

    forcedTab?: TabType; 
    onSyncGridDimensions?: (warpLen: number, weftLen: number) => void; 
}

type TabType = 'construction' | 'pattern' | 'weave' | 'yarns' | 'colors';

// Helper Components Defined Outside to prevent Remounting
const TabButton: React.FC<{ id: TabType, activeTab: TabType, icon: React.ReactNode, label: string, onClick: (id: TabType) => void }> = ({ id, activeTab, icon, label, onClick }) => (
    <button
        onClick={() => onClick(id)}
        className={`flex-1 flex flex-col items-center justify-center py-3 gap-1 border-b-2 transition-colors ${activeTab === id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
    >
        {icon}
        <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
    </button>
);

const SliderInput: React.FC<{
    label: string; value: number; onChange?: (value: number) => void; min?: number; max?: number; step?: number; subLabel?: string; disabled?: boolean; onPointerDown?: () => void;
}> = ({ label, value, onChange, min, max, step, subLabel, disabled, onPointerDown }) => (
    <div className="mb-5">
        <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex justify-between">
            <span>{label} {subLabel && <span className="text-gray-400 normal-case ml-1">({subLabel})</span>}</span>
            <span className={`${disabled ? 'text-gray-500' : 'text-blue-600'} font-mono`}>{value}</span>
        </label>
        {disabled ? (
            <div className="w-full h-1 bg-gray-200 rounded-lg opacity-50"></div>
        ) : (
            <input
                type="range" min={min} max={max} step={step} value={value}
                onChange={(e) => onChange && onChange(parseInt(e.target.value, 10))}
                onPointerDown={onPointerDown}
                className="w-full h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600 hover:accent-blue-500"
            />
        )}
    </div>
);

const YarnList: React.FC<{ 
    yarns: {[key: string]: YarnDefinition}, 
    type: 'warp' | 'weft',
    activeId?: string,
    isSelectedType?: boolean,
    onSelect?: (id: string, type: 'warp' | 'weft') => void,
    onEdit: (char: string, def: YarnDefinition) => void,
    onAssignColor: (char: string) => void, 
    onDropYarn: (sourceId: string, sourceType: 'warp' | 'weft', targetId: string) => void,
    label: string 
}> = ({ yarns, type, activeId, isSelectedType, onSelect, onEdit, onAssignColor, onDropYarn, label }) => {
    const letters = ['A','B','C','D','E','F','G','H'];
    const [dragOverId, setDragOverId] = useState<string | null>(null);

    return (
        <div className="mb-4">
            <h2 className="text-sm font-bold text-gray-900 mb-2">{label}</h2>
            <div className="flex flex-col gap-2">
                {letters.map((char) => {
                    const yarn = yarns[char];
                    const isSelected = isSelectedType && activeId === char;
                    const isDragOver = dragOverId === char;

                    if (!yarn) {
                        return (
                            <div 
                                key={char} 
                                className={`flex items-center gap-3 p-2 rounded-md border border-dashed hover:bg-blue-50 transition-all cursor-pointer opacity-60 hover:opacity-100 ${isSelected ? 'border-blue-500 bg-blue-50' : (isDragOver ? 'border-blue-400 bg-blue-50 ring-2 ring-blue-100' : 'border-gray-300 hover:border-blue-400')}`}
                                onClick={() => {
                                    const defaultDef: YarnDefinition = { 
                                        color: '#CCCCCC', 
                                        model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 28, ply: 1, thickness: 1.0, twist: 'Z', tpi: 15, sheen: 0.5, roughness: 0.5, price: 0,
                                        bindingDepth: 0.05
                                    };
                                    onEdit(char, defaultDef);
                                    onSelect && onSelect(char, type);
                                }}
                                onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                                onDragLeave={() => setDragOverId(null)}
                                onDrop={(e) => {
                                    e.preventDefault();
                                    setDragOverId(null);
                                    const data = e.dataTransfer.getData('yarn-id');
                                    const sType = e.dataTransfer.getData('yarn-type') as 'warp' | 'weft';
                                    if (data) onDropYarn(data, sType, char);
                                }}
                                title={`Initialize Yarn ${char}`}
                            >
                                <div className="font-mono font-bold text-gray-400 w-4">{char}</div>
                                <div className="text-[10px] text-gray-400 font-medium">Empty Slot</div>
                                <PlusIcon className="w-4 h-4 text-gray-400 ml-auto" />
                            </div>
                        );
                    }

                    const code = yarn.code || (yarn.count ? `${yarn.ply||1}/${yarn.count} ${yarn.countSystem||'Nm'}` : `Type ${char}`);

                    return (
                        <div 
                            key={char} 
                            draggable
                            onDragStart={(e) => {
                                e.dataTransfer.setData('yarn-id', char);
                                e.dataTransfer.setData('yarn-type', type);
                                e.dataTransfer.effectAllowed = 'copy';
                            }}
                            onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                            onDragLeave={() => setDragOverId(null)}
                            onDrop={(e) => {
                                e.preventDefault();
                                setDragOverId(null);
                                const data = e.dataTransfer.getData('yarn-id');
                                const sType = e.dataTransfer.getData('yarn-type') as 'warp' | 'weft';
                                if (data) onDropYarn(data, sType, char);
                            }}
                            onClick={() => onSelect && onSelect(char, type)}
                            className={`flex items-center gap-3 p-2 rounded-md border transition-all group cursor-pointer ${isSelected ? 'bg-gray-200 border-gray-400 ring-1 ring-gray-300' : (isDragOver ? 'border-blue-400 bg-blue-50 ring-2 ring-blue-100' : 'border-gray-200 hover:bg-gray-50')}`}
                        >
                            <div className={`font-mono font-bold w-4 ${isSelected ? 'text-gray-900' : 'text-gray-500'}`}>{char}</div>

                            <div className="flex-1 min-w-0">
                                <div 
                                    className="h-3 rounded-full relative overflow-hidden shadow-inner flex items-center hover:ring-2 hover:ring-blue-400 hover:ring-offset-1 transition-all mb-1" 
                                    style={{ background: yarn.color }}
                                    onClick={(e) => { e.stopPropagation(); onAssignColor(char); }}
                                    title="Click to apply selected palette color"
                                >
                                    <div className="absolute inset-0 bg-gradient-to-b from-black/10 via-transparent to-black/20"></div>
                                </div>
                                <div className="flex justify-between items-center px-1">
                                     <span className="text-[10px] text-gray-500 font-medium truncate">{code}</span>
                                     <span className="text-[9px] text-gray-400">{yarn.fiberType || 'Cotton'}</span>
                                </div>
                            </div>

                            <button 
                                onClick={(e) => { e.stopPropagation(); onEdit(char, yarn); }}
                                className={`w-7 h-7 flex items-center justify-center rounded-full border hover:border-blue-500 hover:bg-blue-50 hover:text-blue-600 transition-all shrink-0 ${isSelected ? 'border-gray-300 bg-white text-gray-500' : 'border-gray-200 text-gray-400'}`}
                                title="Edit Yarn Properties"
                            >
                                <PencilIcon className="w-3 h-3" />
                            </button>
                        </div>
                    )
                })}
            </div>
        </div>
    );
}

export const RightPanel: React.FC<RightPanelProps> = ({
    settings, onSettingsChange, dentingPattern, onDentingChange, onSnapshot, onLoadWeave,
    customWeaves, onAddWeave, onUpdateWeave, onDeleteWeave,
    warpYarns, weftYarns, onUpdateWarpYarn, onUpdateWeftYarn, onUpdateAllYarns,
    paletteColors,
    warpPatternString, setWarpPatternString, weftPatternString, setWeftPatternString, onOpenGridEditor, onOpenPatternGenerator,
    currentInput, onApplyGenerated, onSimulate,
    selectedColorIndex, onSelectColor,
    onGridOperation,
    activeYarnId = 'A', selectedYarnType, onSelectYarn, onActiveYarnChange,
    forcedTab, onSyncGridDimensions
}) => {
    const [activeTab, setActiveTab] = useState<TabType>('construction');
    const [editingYarn, setEditingYarn] = useState<{ id: string, type: 'warp' | 'weft', def: YarnDefinition } | null>(null);
    const [weaveEditorState, setWeaveEditorState] = useState<{ isOpen: boolean, weave?: LibraryWeave }>({ isOpen: false });
    const [invertedWeaveIds, setInvertedWeaveIds] = useState<Set<string>>(new Set());

    useEffect(() => {
        if (forcedTab) {
            setActiveTab(forcedTab);
        }
    }, [forcedTab]);

    const warpColors = Object.fromEntries(Object.entries(warpYarns).map(([k,v]) => [k, (v as YarnDefinition).color]));
    const weftColors = Object.fromEntries(Object.entries(weftYarns).map(([k,v]) => [k, (v as YarnDefinition).color]));

    const allWeaves = [...WEAVE_LIBRARY, ...customWeaves];
    const activePaletteColor = paletteColors[selectedColorIndex || 0];
    const letters = ['A','B','C','D','E','F','G','H'];

    const handleMirror = () => {
        onSnapshot();
        setWeftPatternString(warpPatternString);
    };

    const toggleWeaveInversion = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        setInvertedWeaveIds(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    const handleShuffleColors = () => {
        if (!onUpdateAllYarns) return;
        onSnapshot();

        const shuffle = (yarns: { [key: string]: YarnDefinition }) => {
            const newYarns = { ...yarns };
            const colors = letters.filter(l => yarns[l]).map(l => yarns[l].color);
            if (colors.length === 0) return newYarns;
            colors.unshift(colors.pop()!);
            letters.forEach((l, i) => {
                if (newYarns[l] && colors[i]) {
                    newYarns[l] = { ...newYarns[l], color: colors[i] };
                }
            });
            return newYarns;
        };

        onUpdateAllYarns('warp', shuffle(warpYarns));
        onUpdateAllYarns('weft', shuffle(weftYarns));
    };

    const handleCopyWarpToWeft = () => {
        if (window.confirm("Copy all Warp yarn definitions to Weft? Current weft yarns will be overwritten.")) {
            onSnapshot();
            const newWeft = { ...weftYarns };
            letters.forEach(l => {
                if (warpYarns[l]) newWeft[l] = { ...warpYarns[l] };
            });
            if (onUpdateAllYarns) onUpdateAllYarns('weft', newWeft);
        }
    };

    const handleCopyWeftToWarp = () => {
        if (window.confirm("Copy all Weft yarn definitions to Warp? Current warp yarns will be overwritten.")) {
            onSnapshot();
            const newWarp = { ...warpYarns };
            letters.forEach(l => {
                if (weftYarns[l]) newWarp[l] = { ...weftYarns[l] };
            });
            if (onUpdateAllYarns) onUpdateAllYarns('warp', newWarp);
        }
    };

    const handleDropYarn = (sourceId: string, sourceType: 'warp' | 'weft', targetId: string, targetType: 'warp' | 'weft') => {
        onSnapshot();
        const sourceBank = sourceType === 'warp' ? warpYarns : weftYarns;
        const sourceDef = sourceBank[sourceId];
        if (!sourceDef) return;

        if (targetType === 'warp') {
            onUpdateWarpYarn(targetId, { ...sourceDef });
        } else {
            onUpdateWeftYarn(targetId, { ...sourceDef });
        }
    };

    const patternWarpRepeat = getTotalThreads(warpPatternString);
    const patternWeftRepeat = getTotalThreads(weftPatternString);

    return (
        <>
            <div className="w-80 flex-shrink-0 bg-white border-l border-gray-200 flex flex-col z-20 shadow-xl">
                <div className="flex border-b border-gray-200 bg-gray-50 overflow-x-auto no-scrollbar">
                    <TabButton id="construction" activeTab={activeTab} onClick={setActiveTab} icon={<LayersIcon className="w-5 h-5" />} label="Specs" />
                    <TabButton id="weave" activeTab={activeTab} onClick={setActiveTab} icon={<GridFillIcon className="w-5 h-5" />} label="Weave" />
                    <TabButton id="pattern" activeTab={activeTab} onClick={setActiveTab} icon={<GridIcon className="w-5 h-5" />} label="Pattern" />
                    <TabButton id="yarns" activeTab={activeTab} onClick={setActiveTab} icon={<ListIcon className="w-5 h-5" />} label="Yarns" />
                    <TabButton id="colors" activeTab={activeTab} onClick={setActiveTab} icon={<PaletteIcon className="w-5 h-5" />} label="Colors" />
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar p-5">

                    {activeTab === 'construction' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <h2 className="text-sm font-bold text-gray-900 mb-4">Fabric Specifications</h2>

                            <div className="bg-blue-50 border border-blue-100 p-3 rounded-lg mb-6">
                                <div className="flex justify-between items-center mb-1 text-xs">
                                    <span className="text-gray-500 uppercase tracking-wide">Pattern Repeat</span>
                                    <span className="font-bold text-gray-700">{patternWarpRepeat} x {patternWeftRepeat}</span>
                                </div>
                                <div className="flex justify-between items-center mb-3 text-xs">
                                    <span className="text-gray-500 uppercase tracking-wide">Grid Dimensions</span>
                                    <span className="font-bold text-gray-700">{settings.warpThreads} x {settings.weftPicks}</span>
                                </div>
                                {onSyncGridDimensions && (
                                    <button 
                                        onClick={() => onSyncGridDimensions(patternWarpRepeat, patternWeftRepeat)}
                                        className="w-full py-2 bg-blue-600 hover:bg-blue-500 text-white rounded font-bold text-xs shadow-sm transition-colors"
                                    >
                                        Sync Grid to Pattern
                                    </button>
                                )}
                            </div>

                            <SliderInput label="Draft Repeat (Threads)" value={settings.warpThreads} onChange={(v) => onSettingsChange({ ...settings, warpThreads: v })} onPointerDown={onSnapshot} min={4} max={128} step={4} />
                            <SliderInput label="Peg Plan Repeat (Picks)" value={settings.weftPicks} onChange={(v) => onSettingsChange({ ...settings, weftPicks: v })} onPointerDown={onSnapshot} min={4} max={128} step={4} />
                            <SliderInput label="Harnesses" value={settings.harnesses} onChange={(v) => onSettingsChange({ ...settings, harnesses: v })} onPointerDown={onSnapshot} min={2} max={120} step={1} />

                            <div className="h-px bg-gray-100 my-6" />

                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Set & Reed</h3>
                            <SliderInput label="Ends Per Inch" value={settings.epi} onChange={(v) => onSettingsChange({ ...settings, epi: v })} onPointerDown={onSnapshot} min={8} max={120} step={1} />
                            <SliderInput label="Picks Per Inch" value={settings.ppi} onChange={(v) => onSettingsChange({ ...settings, ppi: v })} onPointerDown={onSnapshot} min={8} max={120} step={1} />

                            <div className="mb-4">
                                <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 block">Denting Pattern</label>
                                <input type="text" value={dentingPattern} onChange={(e) => { onSnapshot(); onDentingChange(e.target.value); }}
                                    className="w-full bg-white border border-gray-300 rounded p-2 text-sm font-mono focus:border-blue-500 focus:outline-none"
                                />
                            </div>

                            <div className="mt-8 pt-4 border-t border-gray-100">
                                <button onClick={onSimulate} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-bold shadow-sm transition-colors flex items-center justify-center gap-2">
                                    Simulate Fabric
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === 'weave' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <div className="mb-6">
                                <h2 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Draft Operations</h2>
                                <GridToolbar 
                                    onClear={() => onGridOperation('draft', 'clear')}
                                    onInvert={() => onGridOperation('draft', 'invert')}
                                    onShiftUp={() => onGridOperation('draft', 'shiftUp')}
                                    onShiftDown={() => onGridOperation('draft', 'shiftDown')}
                                    onShiftLeft={() => onGridOperation('draft', 'shiftLeft')}
                                    onShiftRight={() => onGridOperation('draft', 'shiftRight')}
                                    onDouble={() => onGridOperation('draft', 'double')}
                                />
                                <h2 className="text-xs font-bold text-gray-400 uppercase tracking-widest mt-4 mb-2">Peg Plan Operations</h2>
                                <GridToolbar 
                                    onClear={() => onGridOperation('peg', 'clear')}
                                    onInvert={() => onGridOperation('peg', 'invert')}
                                    onShiftUp={() => onGridOperation('peg', 'shiftUp')}
                                    onShiftDown={() => onGridOperation('peg', 'shiftDown')}
                                    onShiftLeft={() => onGridOperation('peg', 'shiftLeft')}
                                    onShiftRight={() => onGridOperation('peg', 'shiftRight')}
                                    onDouble={() => onGridOperation('peg', 'double')}
                                />
                            </div>

                            <div className="h-px bg-gray-100 mb-4" />

                            <div className="flex justify-between items-center mb-4">
                                <div className="flex flex-col">
                                    <h2 className="text-sm font-bold text-gray-900">Weave Library</h2>
                                    <span className="text-[10px] text-gray-400 uppercase tracking-tighter">Flip icons toggle Face/Back</span>
                                </div>
                                <button 
                                    onClick={() => setWeaveEditorState({ isOpen: true })}
                                    className="p-1 text-blue-600 hover:bg-blue-50 rounded"
                                    title="Add Custom Weave"
                                >
                                    <PlusIcon className="w-5 h-5" />
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                {allWeaves.map(weave => {
                                    const isCustom = weave.id.startsWith('custom-');
                                    const isInverted = invertedWeaveIds.has(weave.id);

                                    // Prepare the display weave (potentially inverted)
                                    const displayWeave = isInverted ? {
                                        ...weave,
                                        pegPlan: weave.pegPlan.map(row => row.map(v => v === 1 ? 0 : 1))
                                    } : weave;

                                    return (
                                        <div key={weave.id} className="relative group">
                                            <button
                                                draggable
                                                onDragStart={(e) => {
                                                    e.dataTransfer.setData('weave-obj', JSON.stringify(displayWeave));
                                                    e.dataTransfer.effectAllowed = 'copy';
                                                }}
                                                onClick={() => { onSnapshot(); onLoadWeave(displayWeave); }}
                                                className={`flex flex-col items-start p-2 bg-gray-50 border hover:border-blue-500 hover:bg-blue-50 rounded-lg transition-all text-left w-full cursor-grab active:cursor-grabbing ${isInverted ? 'border-orange-300 bg-orange-50/30' : 'border-gray-200'}`}
                                            >
                                                <WeaveThumbnail weave={displayWeave} className="w-full aspect-square mb-2 pointer-events-none" />
                                                <div className="flex items-center justify-between w-full min-w-0 gap-1">
                                                    <span className="text-xs font-semibold text-gray-700 group-hover:text-blue-700 leading-tight truncate">{weave.name}</span>
                                                    <button 
                                                        onClick={(e) => toggleWeaveInversion(weave.id, e)}
                                                        className={`shrink-0 p-1 rounded transition-colors ${isInverted ? 'text-orange-600 bg-orange-100' : 'text-gray-400 hover:text-blue-600 hover:bg-white'}`}
                                                        title={isInverted ? "Switch to Face" : "Switch to Back"}
                                                    >
                                                        <FlipIcon className="w-3 h-3" />
                                                    </button>
                                                </div>
                                                <span className="text-[10px] text-gray-400 mt-0.5">{weave.harnesses}H {isInverted ? '(BACK)' : '(FACE)'}</span>
                                            </button>

                                            {isCustom && (
                                                <div className="absolute top-1 right-1 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); setWeaveEditorState({ isOpen: true, weave }); }}
                                                        className="p-1 bg-white border border-gray-200 rounded shadow-sm hover:text-blue-600"
                                                    >
                                                        <PencilIcon className="w-3 h-3" />
                                                    </button>
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); onDeleteWeave(weave.id); }}
                                                        className="p-1 bg-white border border-gray-200 rounded shadow-sm hover:text-red-600"
                                                    >
                                                        <TrashIcon className="w-3 h-3" />
                                                    </button>
                                                </div>
                                            )}
                                        </div>
                                    )
                                })}
                            </div>
                        </div>
                    )}

                    {activeTab === 'pattern' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200 flex flex-col gap-6">
                            <div className="flex gap-2 p-2 bg-gray-50 rounded-lg border border-gray-200 mb-2">
                                <button onClick={handleMirror} className="flex-1 flex flex-col items-center gap-1 p-2 rounded hover:bg-gray-200 text-gray-500 hover:text-blue-600 transition-colors" title="Copy Warp Pattern to Weft">
                                    <CopyIcon className="w-4 h-4" />
                                    <span className="text-[10px] font-bold">Mirror</span>
                                </button>
                                <button onClick={handleShuffleColors} className="flex-1 flex flex-col items-center gap-1 p-2 rounded hover:bg-gray-200 text-gray-500 hover:text-blue-600 transition-colors" title="Rotate Yarn Colors">
                                    <FlipIcon className="w-4 h-4" />
                                    <span className="text-[10px] font-bold">Shuffle</span>
                                </button>
                            </div>

                            <div className="bg-blue-50/50 p-3 rounded-lg border border-blue-100">
                                <h3 className="text-xs font-bold text-blue-500 uppercase mb-2">Active Yarn Brush</h3>
                                <div className="flex flex-wrap gap-2">
                                    {letters.map((char) => (
                                        <button 
                                            key={char} 
                                            onClick={() => onActiveYarnChange?.(char)}
                                            className={`
                                                w-8 h-8 rounded flex items-center justify-center font-mono font-bold text-sm transition-all
                                                ${activeYarnId === char 
                                                    ? 'bg-blue-600 text-white shadow-md ring-2 ring-blue-300 ring-offset-1' 
                                                    : 'bg-white text-gray-500 border border-gray-200 hover:bg-gray-50'}
                                            `}
                                            title={`Paint with Yarn ${char}`}
                                        >
                                            {char}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <h3 className="text-xs font-bold text-gray-500 uppercase mb-1">Warp Sequence</h3>
                                <TextPatternEditor 
                                    title="" 
                                    value={warpPatternString} 
                                    onValueChange={setWarpPatternString}
                                    colorMap={warpColors} 
                                    onOpenGridEditor={() => onOpenGridEditor('warp')}
                                    onFocus={onSnapshot}
                                />
                                <div className="h-4" />

                                <h3 className="text-xs font-bold text-gray-500 uppercase mb-1">Weft Sequence</h3>
                                <TextPatternEditor 
                                    title="" 
                                    value={weftPatternString} 
                                    onValueChange={setWeftPatternString}
                                    colorMap={weftColors} 
                                    onOpenGridEditor={() => onOpenGridEditor('weft')}
                                    onFocus={onSnapshot}
                                />
                            </div>

                            <div className="h-px bg-gray-100" />

                            <AiControl currentInput={currentInput} settings={settings} onApplyGenerated={onApplyGenerated} />
                        </div>
                    )}

                    {activeTab === 'yarns' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <YarnList 
                                yarns={warpYarns}
                                type="warp"
                                activeId={activeYarnId}
                                isSelectedType={selectedYarnType === 'warp'}
                                onSelect={onSelectYarn}
                                onEdit={(char, def) => setEditingYarn({ id: char, type: 'warp', def })}
                                onAssignColor={(char) => { onSnapshot(); onUpdateWarpYarn(char, { ...warpYarns[char], color: activePaletteColor }); }}
                                onDropYarn={(sId, sType, tId) => handleDropYarn(sId, sType, tId, 'warp')}
                                label="Warp Yarns" 
                            />

                            <div className="flex flex-col items-center gap-1 my-2">
                                <div className="flex gap-4">
                                    <button 
                                        onClick={handleCopyWarpToWeft}
                                        className="p-2 bg-gray-100 hover:bg-blue-100 text-gray-400 hover:text-blue-600 rounded-lg transition-all shadow-sm border border-gray-200 flex flex-col items-center gap-1"
                                        title="Copy all Warp yarns to Weft"
                                    >
                                        <ArrowDownIcon className="w-5 h-5" />
                                        <span className="text-[8px] font-bold uppercase">Warp to Weft</span>
                                    </button>
                                    <button 
                                        onClick={handleCopyWeftToWarp}
                                        className="p-2 bg-gray-100 hover:bg-blue-100 text-gray-400 hover:text-blue-600 rounded-lg transition-all shadow-sm border border-gray-200 flex flex-col items-center gap-1"
                                        title="Copy all Weft yarns to Warp"
                                    >
                                        <ArrowDownIcon className="w-5 h-5 rotate-180" />
                                        <span className="text-[8px] font-bold uppercase">Weft to Warp</span>
                                    </button>
                                </div>
                            </div>

                            <YarnList 
                                yarns={weftYarns}
                                type="weft"
                                activeId={activeYarnId}
                                isSelectedType={selectedYarnType === 'weft'}
                                onSelect={onSelectYarn}
                                onEdit={(char, def) => setEditingYarn({ id: char, type: 'weft', def })}
                                onAssignColor={(char) => { onSnapshot(); onUpdateWeftYarn(char, { ...weftYarns[char], color: activePaletteColor }); }}
                                onDropYarn={(sId, sType, tId) => handleDropYarn(sId, sType, tId, 'weft')}
                                label="Weft Yarns" 
                            />
                        </div>
                    )}

                    {activeTab === 'colors' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <h3 className="text-lg font-medium text-gray-900 mb-3">Color Library</h3>
                            <div className="grid grid-cols-6 gap-2">
                                {paletteColors.map((color, idx) => (
                                    <div 
                                        key={idx} 
                                        className={`relative group cursor-pointer transition-all p-0.5 rounded ${idx === selectedColorIndex ? 'ring-2 ring-blue-500 bg-blue-100' : ''}`}
                                        onClick={() => onSelectColor?.(idx)}
                                    >
                                        <div className="w-full aspect-square rounded shadow-sm border border-gray-200" style={{backgroundColor: color}} />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {editingYarn && (
                <YarnDesignerModal 
                    isOpen={!!editingYarn}
                    onClose={() => setEditingYarn(null)}
                    yarnId={editingYarn.id}
                    yarnType={editingYarn.type}
                    initialYarn={editingYarn.def}
                    onSave={(newYarn) => {
                        onSnapshot();
                        if (editingYarn.type === 'warp') {
                            onUpdateWarpYarn(editingYarn.id, newYarn);
                        } else {
                            onUpdateWeftYarn(editingYarn.id, newYarn);
                        }
                    }}
                />
            )}

            {weaveEditorState.isOpen && (
                <WeaveEditorModal
                    isOpen={weaveEditorState.isOpen}
                    initialWeave={weaveEditorState.weave}
                    onClose={() => setWeaveEditorState({ isOpen: false })}
                    onSave={(weave) => {
                        onSnapshot();
                        if (weaveEditorState.weave) {
                            onUpdateWeave(weave);
                        } else {
                            onAddWeave(weave);
                        }
                    }}
                />
            )}
        </>
    );
};

import React, { useState, useCallback, useMemo, useRef } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, AppMode, JacquardData } from '../types';
import { expandPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { loadImage, processImage } from '../services/imageProcessor';
import { LibraryWeave } from '../services/weaveLibrary';

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');
  const [loadingStatus, setLoadingStatus] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragOverColorIdx, setDragOverColorIdx] = useState<number | null>(null);

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 512, 
    weftPicks: 512, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    harnesses: 1
  });

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 512,
      height: 512,
      structure: new Uint8Array(512 * 512).fill(0).map((_, i) => (Math.floor(i / 512) + (i % 512)) % 2 === 0 ? 1 : 0)
  }));

  const [artwork, setArtwork] = useState<{
      data: Uint8Array;
      palette: string[];
      width: number;
      height: number;
  } | null>(null);

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 },
      'B': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 },
      'B': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 }
  });

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');
  const [dentingPattern, setDentingPattern] = useState('1');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace'); // Default to Structure View
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleResize = (size: number) => {
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) {
          newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      }
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 

          setArtwork({
              data: new Uint8Array(result.pixels),
              palette: result.palette,
              width: result.width,
              height: result.height
          });

          setJacquardData({
              width: result.width,
              height: result.height,
              structure: new Uint8Array(result.width * result.height).fill(0)
          });

          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`);
          setWeftPatternString(`${result.height}A`);

          setProjectName(file.name.split('.')[0]);
          setViewMode('structure'); // Switch to Artwork view
          setLoadingStatus(null);
      } catch (err: any) {
          console.error("Bitmap Process Error:", err);
          alert(err.message || "Failed to process bitmap.");
          setLoadingStatus(null);
      }
  };

  const handleApplyWeaveToColor = (weave: LibraryWeave, colorIdx: number) => {
    if (!artwork) return;
    setLoadingStatus(`Applying ${weave.name}...`);

    setTimeout(() => {
        const newStructure = new Uint8Array(jacquardData.structure);
        const { width, height } = jacquardData;
        const weaveDraft = weave.draft;
        const weavePeg = weave.pegPlan;
        const weaveW = weaveDraft[0].length;
        const weaveH = weavePeg.length;

        const weaveLookup = new Uint8Array(weaveW * weaveH);
        const warpToHarness = new Int16Array(weaveW).fill(-1);
        for(let w=0; w<weaveW; w++) {
            for(let h=0; h<weave.harnesses; h++) {
                if(weaveDraft[h][w] === 1) { warpToHarness[w] = h; break; }
            }
        }
        for(let y=0; y<weaveH; y++) {
            for(let x=0; x<weaveW; x++) {
                const harness = warpToHarness[x];
                if(harness !== -1 && weavePeg[y][harness] === 1) {
                    weaveLookup[y * weaveW + x] = 1;
                }
            }
        }

        for(let i=0; i<artwork.data.length; i++) {
            if(artwork.data[i] === colorIdx) {
                const x = i % width;
                const y = Math.floor(i / width);
                newStructure[i] = weaveLookup[(y % weaveH) * weaveW + (x % weaveW)];
            }
        }

        setJacquardData(prev => ({ ...prev, structure: newStructure }));
        setLoadingStatus(null);
        setViewMode('interlace'); // Switch back to structure view to see changes
    }, 50);
  };

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      if (seq.length === 0) return Array(jacquardData.width).fill('#888');
      return Array.from({ length: jacquardData.width }, (_, i) => {
          const char = seq[i % seq.length];
          return warpYarns[char]?.color || '#888';
      });
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const seq = expandPatternString(weftPatternString);
      if (seq.length === 0) return Array(jacquardData.height).fill('#888');
      return Array.from({ length: jacquardData.height }, (_, i) => {
          const char = seq[i % seq.length];
          return weftYarns[char]?.color || '#888';
      });
  }, [weftYarns, weftPatternString, jacquardData.height]);

  const simData = useMemo(() => {
      const size = 128;
      const rows: boolean[][] = [];
      const colors: string[][] = [];
      for (let y = 0; y < size; y++) {
          const rowB: boolean[] = [];
          const rowC: string[] = [];
          for (let x = 0; x < size; x++) {
              const idx = (y % jacquardData.height) * jacquardData.width + (x % jacquardData.width);
              const isUp = jacquardData.structure[idx] === 1;
              rowB.push(isUp);
              rowC.push(isUp ? warpColorArray[x % warpColorArray.length] : weftColorArray[y % weftColorArray.length]);
          }
          rows.push(rowB);
          colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  const handleGridOperation = (type: 'draft' | 'peg', action: string) => {
      const newData = new Uint8Array(jacquardData.structure);
      if (action === 'clear') newData.fill(0);
      else if (action === 'invert') {
          for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1;
      }
      setJacquardData(prev => ({ ...prev, structure: newData }));
  };

  const activeYarnChar = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      return seq[0] || 'A';
  }, [warpPatternString]);

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />

        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={setAppMode} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{jacquardData.width} × {jacquardData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                         <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                            <button 
                                onClick={() => setViewMode('interlace')}
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400'}`}
                            >STRUCTURE</button>
                            <button 
                                onClick={() => setViewMode('structure')} 
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400'}`}
                            >ARTWORK</button>
                        </div>
                        <div className="flex items-center gap-1 border-l border-gray-800 pl-4">
                            {[1024, 2048, 4096].map(size => (
                                <button key={size} onClick={() => handleResize(size)} className={`px-2 py-0.5 rounded text-[10px] border transition-colors ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400 hover:text-white'}`}>{size}</button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="flex-1 relative">
                    <JacquardCanvas 
                        data={jacquardData}
                        artwork={artwork || undefined}
                        onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))}
                        tool={currentTool}
                        viewMode={viewMode}
                        faceMode={faceMode}
                        warpColors={warpColorArray}
                        weftColors={weftColorArray}
                        gridDivision={settings.gridDivision}
                    />
                </div>

                {artwork && (
                    <div className="h-20 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl">
                        <div className="flex flex-col">
                            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest mb-1">Optimized Palette</span>
                            <span className="text-[10px] text-gray-400 font-mono">{artwork.palette.length} Inherent Colors</span>
                        </div>
                        <div className="flex-1 flex items-center gap-3 overflow-x-auto no-scrollbar py-2">
                            {artwork.palette.map((color, idx) => (
                                <div 
                                    key={`${color}-${idx}`}
                                    onDragOver={(e) => { e.preventDefault(); setDragOverColorIdx(idx); }}
                                    onDragLeave={() => setDragOverColorIdx(null)}
                                    onDrop={(e) => {
                                        e.preventDefault();
                                        setDragOverColorIdx(null);
                                        const weaveData = e.dataTransfer.getData('weave-obj');
                                        if (weaveData) {
                                            handleApplyWeaveToColor(JSON.parse(weaveData), idx);
                                        }
                                    }}
                                    className={`group flex flex-col items-center gap-1 shrink-0 bg-gray-800/40 p-2 rounded-lg border transition-all ${dragOverColorIdx === idx ? 'bg-blue-900/40 border-blue-500 scale-105 shadow-lg shadow-blue-500/20' : 'border-gray-700/50 hover:bg-gray-800'}`}
                                >
                                    <div 
                                        className="w-8 h-8 rounded-md border border-white/10 shadow-md transition-transform" 
                                        style={{ backgroundColor: color }}
                                    />
                                    <span className="text-[8px] font-mono text-gray-500 uppercase">{idx + 1}: {color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end">
                            <span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drag weave to color</span>
                            <button 
                                onClick={() => setArtwork(null)}
                                className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded hover:bg-red-900/50 transition-colors font-bold uppercase tracking-tighter"
                            >
                                Clear Artwork
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <RightPanel 
                settings={settings}
                onSettingsChange={setSettings}
                dentingPattern={dentingPattern}
                onDentingChange={setDentingPattern}
                onSnapshot={()=>{}}
                onLoadWeave={()=>{}}
                customWeaves={[]}
                onAddWeave={()=>{}}
                onUpdateWeave={()=>{}}
                onDeleteWeave={()=>{}}
                warpYarns={warpYarns}
                weftYarns={weftYarns}
                onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))}
                onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))}
                paletteColors={PANTONE_PALETTE}
                warpPatternString={warpPatternString}
                setWarpPatternString={setWarpPatternString}
                weftPatternString={weftPatternString}
                setWeftPatternString={setWeftPatternString}
                onOpenGridEditor={()=>{}}
                onOpenPatternGenerator={()=>{}}
                currentInput={{} as any}
                onApplyGenerated={()=>{}}
                onSimulate={() => setShowSimModal(true)}
                onGridOperation={(t, a) => handleGridOperation(t, a)}
                activeYarnId={activeYarnChar}
                onActiveYarnChange={(char) => {
                    setWarpPatternString(`${settings.warpThreads}${char}`);
                    setWeftPatternString(`${settings.weftPicks}${char}`);
                }}
            />
        </div>

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)}
            weavePattern={simData.colors}
            structure={simData.structure}
            epi={settings.epi}
            ppi={settings.ppi}
            warpYarns={warpYarns}
            weftYarns={weftYarns}
            warpYarnSequence={expandPatternString(warpPatternString).slice(0, 128)}
            weftYarnSequence={expandPatternString(weftPatternString).slice(0, 128)}
        />
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode } from '../types';

interface JacquardCanvasProps {
    data: JacquardData;
    artwork?: {
        data: Uint8Array;
        palette: string[];
        width: number;
        height: number;
    };
    onUpdate: (newData: Uint8Array) => void;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    gridDivision: number;
}

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, artwork, onUpdate, tool, viewMode, faceMode, warpColors, weftColors, gridDivision
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [view, setView] = useState({ x: 40, y: 40, zoom: 1 }); // Start with padding for headers
    const isInteracting = useRef(false);
    const lastGridPos = useRef({ x: -1, y: -1 });
    const localBuffer = useRef<Uint8Array>(data.structure);

    useEffect(() => {
        localBuffer.current = data.structure;
        render();
    }, [data.structure]);

    const HEADER_SIZE = 24;

    const render = () => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        if (canvas.width !== w || canvas.height !== h) {
            canvas.width = w;
            canvas.height = h;
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        const startX = Math.floor((HEADER_SIZE - view.x) / zoom);
        const startY = Math.floor((HEADER_SIZE - view.y) / zoom);
        const endX = Math.min(data.width, startX + Math.ceil((w - HEADER_SIZE) / zoom) + 1);
        const endY = Math.min(data.height, startY + Math.ceil((h - HEADER_SIZE) / zoom) + 1);

        const isArtworkView = viewMode === 'structure';
        const isReverse = faceMode === 'reverse';
        const buffer = localBuffer.current;

        // 1. Render Main Grid
        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * data.width + x;

                if (isArtworkView && artwork) {
                    const colorIdx = artwork.data[idx];
                    ctx.fillStyle = artwork.palette[colorIdx] || '#000000';
                } else {
                    let val = buffer[idx] === 1;
                    if (isReverse) val = !val;

                    if (isArtworkView) {
                        ctx.fillStyle = val ? '#ffffff' : '#000000';
                    } else {
                        ctx.fillStyle = val ? warpColors[x % warpColors.length] : weftColors[y % weftColors.length];
                    }
                }

                ctx.fillRect(
                    Math.floor(view.x + x * zoom),
                    Math.floor(view.y + y * zoom),
                    Math.ceil(zoom),
                    Math.ceil(zoom)
                );
            }
        }

        // 2. Render Headers (Yarn Grids)
        // Static background for headers to prevent grid bleed
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, w, HEADER_SIZE); // Top
        ctx.fillRect(0, 0, HEADER_SIZE, h); // Left

        // Warp Yarn Bar (Top)
        for (let x = Math.max(0, startX); x < endX; x++) {
            ctx.fillStyle = warpColors[x % warpColors.length] || '#888';
            ctx.fillRect(
                Math.floor(view.x + x * zoom),
                0,
                Math.ceil(zoom),
                HEADER_SIZE
            );
        }

        // Weft Yarn Bar (Left)
        for (let y = Math.max(0, startY); y < endY; y++) {
            ctx.fillStyle = weftColors[y % weftColors.length] || '#888';
            ctx.fillRect(
                0,
                Math.floor(view.y + y * zoom),
                HEADER_SIZE,
                Math.ceil(zoom)
            );
        }

        // Intersection Corner
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, HEADER_SIZE, HEADER_SIZE);
        ctx.strokeStyle = '#334155';
        ctx.strokeRect(0, 0, HEADER_SIZE, HEADER_SIZE);

        // Visual Grid Divisions
        if (zoom > 4) {
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            for (let x = Math.max(0, startX); x <= endX; x++) {
                if (x % gridDivision === 0) {
                    ctx.moveTo(view.x + x * zoom, HEADER_SIZE);
                    ctx.lineTo(view.x + x * zoom, h);
                }
            }
            for (let y = Math.max(0, startY); y <= endY; y++) {
                if (y % gridDivision === 0) {
                    ctx.moveTo(HEADER_SIZE, view.y + y * zoom);
                    ctx.lineTo(w, view.y + y * zoom);
                }
            }
            ctx.stroke();
        }
    };

    useEffect(() => {
        render();
    }, [view, viewMode, faceMode, warpColors, weftColors, artwork]);

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;

        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const zoomFactor = wheelEv.deltaY > 0 ? 0.85 : 1.15;
            const newZoom = Math.min(200, Math.max(0.01, view.zoom * zoomFactor));
            const worldX = (mouseX - view.x) / view.zoom;
            const worldY = (mouseY - view.y) / view.zoom;
            setView({ x: mouseX - worldX * newZoom, y: mouseY - worldY * newZoom, zoom: newZoom });
            return;
        }

        if (tool === 'pan') {
            if (e.type === 'mousedown') {
                isInteracting.current = true;
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else if (e.type === 'mousemove' && isInteracting.current) {
                const dx = mouseX - lastGridPos.current.x;
                const dy = mouseY - lastGridPos.current.y;
                setView(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else {
                isInteracting.current = false;
            }
            return;
        }

        const gridX = Math.floor((mouseX - view.x) / view.zoom);
        const gridY = Math.floor((mouseY - view.y) / view.zoom);

        if (e.type === 'mousedown') {
            isInteracting.current = true;
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                const idx = gridY * data.width + gridX;
                localBuffer.current[idx] = localBuffer.current[idx] === 1 ? 0 : 1;
                lastGridPos.current = { x: gridX, y: gridY };
                render();
            }
        } else if (e.type === 'mousemove' && isInteracting.current) {
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                if (gridX !== lastGridPos.current.x || gridY !== lastGridPos.current.y) {
                    localBuffer.current[gridY * data.width + gridX] = 1;
                    lastGridPos.current = { x: gridX, y: gridY };
                    render();
                }
            }
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            if (isInteracting.current) {
                isInteracting.current = false;
                onUpdate(new Uint8Array(localBuffer.current));
            }
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden select-none relative">
            <canvas 
                ref={canvasRef}
                onMouseDown={handleInteraction}
                onMouseMove={handleInteraction}
                onMouseUp={handleInteraction}
                onMouseLeave={handleInteraction}
                onWheel={handleInteraction}
                className="block"
            />
            <div className="absolute bottom-4 left-4 flex gap-2 pointer-events-none">
                <div className="bg-black/80 px-3 py-1 rounded text-[10px] font-mono text-blue-400 border border-blue-900/50 uppercase tracking-tighter">
                    {tool.toUpperCase()} MODE | ZOOM {Math.round(view.zoom * 100)}%
                </div>
            </div>
            <div className="absolute top-8 left-4 text-[9px] font-bold text-gray-500 uppercase rotate-90 origin-left pointer-events-none">
                Weft Yarn Grid
            </div>
            <div className="absolute top-4 left-8 text-[9px] font-bold text-gray-500 uppercase pointer-events-none">
                Warp Yarn Grid
            </div>
        </div>
    );
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { YarnStudio } from './YarnStudio';
import { ProductionCalculator } from './ProductionCalculator';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, AppMode, JacquardData } from '../types';
import { expandPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { loadImage, processImage } from '../services/imageProcessor';
import { LibraryWeave } from '../services/weaveLibrary';

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');
  const [loadingStatus, setLoadingStatus] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragOverColorIdx, setDragOverColorIdx] = useState<number | null>(null);

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 512, 
    weftPicks: 512, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    harnesses: 1
  });

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 512,
      height: 512,
      structure: new Uint8Array(512 * 512).fill(0).map((_, i) => (Math.floor(i / 512) + (i % 512)) % 2 === 0 ? 1 : 0)
  }));

  const [artwork, setArtwork] = useState<{
      data: Uint8Array;
      palette: string[];
      width: number;
      height: number;
  } | null>(null);

  // Yarn Management
  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 },
      'B': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 },
      'B': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 }
  });

  const [activeYarnId, setActiveYarnId] = useState<string>('A');
  const [selectedYarnType, setSelectedYarnType] = useState<'warp' | 'weft'>('warp');
  const [studioYarnDef, setStudioYarnDef] = useState<YarnDefinition>(warpYarns['A']);

  useEffect(() => {
      const source = selectedYarnType === 'warp' ? warpYarns : weftYarns;
      if (source[activeYarnId]) {
          setStudioYarnDef(source[activeYarnId]);
      }
  }, [activeYarnId, selectedYarnType, warpYarns, weftYarns]);

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');
  const [dentingPattern, setDentingPattern] = useState('1');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleResize = (size: number) => {
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) {
          newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      }
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 

          setArtwork({
              data: new Uint8Array(result.pixels),
              palette: result.palette,
              width: result.width,
              height: result.height
          });

          setJacquardData({
              width: result.width,
              height: result.height,
              structure: new Uint8Array(result.width * result.height).fill(0)
          });

          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`);
          setWeftPatternString(`${result.height}A`);

          setProjectName(file.name.split('.')[0]);
          setViewMode('structure');
          setAppMode('art');
          setLoadingStatus(null);
      } catch (err: any) {
          console.error("Bitmap Process Error:", err);
          alert(err.message || "Failed to process bitmap.");
          setLoadingStatus(null);
      }
  };

  const handleApplyWeaveToColor = (weave: LibraryWeave, colorIdx: number) => {
    if (!artwork) return;
    setLoadingStatus(`Applying ${weave.name}...`);

    setTimeout(() => {
        const newStructure = new Uint8Array(jacquardData.structure);
        const { width, height } = jacquardData;
        const weaveDraft = weave.draft;
        const weavePeg = weave.pegPlan;
        const weaveW = weaveDraft[0].length;
        const weaveH = weavePeg.length;

        const weaveLookup = new Uint8Array(weaveW * weaveH);
        const warpToHarness = new Int16Array(weaveW).fill(-1);
        for(let w=0; w<weaveW; w++) {
            for(let h=0; h<weave.harnesses; h++) {
                if(weaveDraft[h][w] === 1) { warpToHarness[w] = h; break; }
            }
        }
        for(let y=0; y<weaveH; y++) {
            for(let x=0; x<weaveW; x++) {
                const harness = warpToHarness[x];
                if(harness !== -1 && weavePeg[y][harness] === 1) {
                    weaveLookup[y * weaveW + x] = 1;
                }
            }
        }

        for(let i=0; i<artwork.data.length; i++) {
            if(artwork.data[i] === colorIdx) {
                const x = i % width;
                const y = Math.floor(i / width);
                newStructure[i] = weaveLookup[(y % weaveH) * weaveW + (x % weaveW)];
            }
        }

        setJacquardData(prev => ({ ...prev, structure: newStructure }));
        setLoadingStatus(null);
        setViewMode('interlace');
    }, 50);
  };

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      if (seq.length === 0) return Array(jacquardData.width).fill('#888');
      return Array.from({ length: jacquardData.width }, (_, i) => {
          const char = seq[i % seq.length];
          return warpYarns[char]?.color || '#888';
      });
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const seq = expandPatternString(weftPatternString);
      if (seq.length === 0) return Array(jacquardData.height).fill('#888');
      return Array.from({ length: jacquardData.height }, (_, i) => {
          const char = seq[i % seq.length];
          return weftYarns[char]?.color || '#888';
      });
  }, [weftYarns, weftPatternString, jacquardData.height]);

  const simData = useMemo(() => {
      // Create a slice for simulation preview
      const size = 128;
      const rows: boolean[][] = [];
      const colors: string[][] = [];
      for (let y = 0; y < size; y++) {
          const rowB: boolean[] = [];
          const rowC: string[] = [];
          for (let x = 0; x < size; x++) {
              const idx = (y % jacquardData.height) * jacquardData.width + (x % jacquardData.width);
              const isUp = jacquardData.structure[idx] === 1;
              rowB.push(isUp);
              rowC.push(isUp ? warpColorArray[x % warpColorArray.length] : weftColorArray[y % weftColorArray.length]);
          }
          rows.push(rowB);
          colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  const handleGridOperation = (type: 'draft' | 'peg', action: string) => {
      const newData = new Uint8Array(jacquardData.structure);
      if (action === 'clear') newData.fill(0);
      else if (action === 'invert') {
          for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1;
      }
      setJacquardData(prev => ({ ...prev, structure: newData }));
  };

  const handleApplyStudioYarn = () => {
    if (selectedYarnType === 'warp') {
        setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    } else {
        setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    }
    setAppMode('art'); // Return to main designer
  };

  const handleModeChange = (mode: AppMode) => {
      if (mode === 'sim') {
          setShowSimModal(true);
      } else {
          setAppMode(mode);
      }
  };

  const isDesignerMode = appMode === 'art' || appMode === 'weave' || appMode === 'specs' || appMode === 'pattern';

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />

        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={handleModeChange} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{jacquardData.width} × {jacquardData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                         <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                            <button 
                                onClick={() => setViewMode('interlace')}
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400'}`}
                            >STRUCTURE</button>
                            <button 
                                onClick={() => setViewMode('structure')} 
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400'}`}
                            >ARTWORK</button>
                        </div>
                        <div className="flex items-center gap-1 border-l border-gray-800 pl-4">
                            {[1024, 2048, 4096].map(size => (
                                <button key={size} onClick={() => handleResize(size)} className={`px-2 py-0.5 rounded text-[10px] border transition-colors ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400 hover:text-white'}`}>{size}</button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="flex-1 relative">
                    {appMode === 'yarn' ? (
                        <YarnStudio 
                            yarn={studioYarnDef} 
                            onChange={setStudioYarnDef} 
                            onApply={handleApplyStudioYarn} 
                        />
                    ) : appMode === 'tech' ? (
                        <div className="bg-white text-gray-900 h-full overflow-hidden">
                            <ProductionCalculator 
                                settings={settings}
                                warpYarns={warpYarns}
                                weftYarns={weftYarns}
                                warpPatternString={warpPatternString}
                                weftPatternString={weftPatternString}
                                draft={[]} // Jacquard doesn't use standard dobby draft array in this view
                                pegPlan={[]}
                                generateThumbnail={() => simData.colors[0][0]} // Stub
                            />
                        </div>
                    ) : (
                        <JacquardCanvas 
                            data={jacquardData}
                            artwork={artwork || undefined}
                            onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))}
                            tool={currentTool}
                            viewMode={viewMode}
                            faceMode={faceMode}
                            warpColors={warpColorArray}
                            weftColors={weftColorArray}
                            gridDivision={settings.gridDivision}
                        />
                    )}
                </div>

                {artwork && isDesignerMode && (
                    <div className="h-20 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl">
                        <div className="flex flex-col">
                            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest mb-1">Optimized Palette</span>
                            <span className="text-[10px] text-gray-400 font-mono">{artwork.palette.length} Inherent Colors</span>
                        </div>
                        <div className="flex-1 flex items-center gap-3 overflow-x-auto no-scrollbar py-2">
                            {artwork.palette.map((color, idx) => (
                                <div 
                                    key={`${color}-${idx}`}
                                    onDragOver={(e) => { e.preventDefault(); setDragOverColorIdx(idx); }}
                                    onDragLeave={() => setDragOverColorIdx(null)}
                                    onDrop={(e) => {
                                        e.preventDefault();
                                        setDragOverColorIdx(null);
                                        const weaveData = e.dataTransfer.getData('weave-obj');
                                        if (weaveData) {
                                            handleApplyWeaveToColor(JSON.parse(weaveData), idx);
                                        }
                                    }}
                                    className={`group flex flex-col items-center gap-1 shrink-0 bg-gray-800/40 p-2 rounded-lg border transition-all ${dragOverColorIdx === idx ? 'bg-blue-900/40 border-blue-500 scale-105 shadow-lg shadow-blue-500/20' : 'border-gray-700/50 hover:bg-gray-800'}`}
                                >
                                    <div 
                                        className="w-8 h-8 rounded-md border border-white/10 shadow-md transition-transform" 
                                        style={{ backgroundColor: color }}
                                    />
                                    <span className="text-[8px] font-mono text-gray-500 uppercase">{idx + 1}: {color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end">
                            <span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drag weave to color</span>
                            <button 
                                onClick={() => setArtwork(null)}
                                className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded hover:bg-red-900/50 transition-colors font-bold uppercase tracking-tighter"
                            >
                                Clear Artwork
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <RightPanel 
                settings={settings}
                onSettingsChange={setSettings}
                dentingPattern={dentingPattern}
                onDentingChange={setDentingPattern}
                onSnapshot={()=>{}}
                onLoadWeave={()=>{}}
                customWeaves={[]}
                onAddWeave={()=>{}}
                onUpdateWeave={()=>{}}
                onDeleteWeave={()=>{}}
                warpYarns={warpYarns}
                weftYarns={weftYarns}
                onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))}
                onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))}
                paletteColors={PANTONE_PALETTE}
                warpPatternString={warpPatternString}
                setWarpPatternString={setWarpPatternString}
                weftPatternString={weftPatternString}
                setWeftPatternString={setWeftPatternString}
                onOpenGridEditor={()=>{}}
                onOpenPatternGenerator={()=>{}}
                currentInput={{} as any}
                onApplyGenerated={()=>{}}
                onSimulate={() => setShowSimModal(true)}
                onGridOperation={(t, a) => handleGridOperation(t, a)}
                activeYarnId={activeYarnId}
                selectedYarnType={selectedYarnType}
                onSelectYarn={(id, type) => {
                    setActiveYarnId(id);
                    setSelectedYarnType(type);
                    setAppMode('yarn');
                }}
            />
        </div>

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)}
            weavePattern={simData.colors}
            structure={simData.structure}
            epi={settings.epi}
            ppi={settings.ppi}
            warpYarns={warpYarns}
            weftYarns={weftYarns}
            warpYarnSequence={expandPatternString(warpPatternString).slice(0, 128)}
            weftYarnSequence={expandPatternString(weftPatternString).slice(0, 128)}
        />
    </div>
  );
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { YarnStudio } from './YarnStudio';
import { ProductionCalculator } from './ProductionCalculator';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, AppMode, JacquardData } from '../types';
import { expandPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { loadImage, processImage } from '../services/imageProcessor';
import { LibraryWeave } from '../services/weaveLibrary';

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');
  const [loadingStatus, setLoadingStatus] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragOverColorIdx, setDragOverColorIdx] = useState<number | null>(null);

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 512, 
    weftPicks: 512, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    harnesses: 1
  });

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 512,
      height: 512,
      structure: new Uint8Array(512 * 512).fill(0).map((_, i) => (Math.floor(i / 512) + (i % 512)) % 2 === 0 ? 1 : 0)
  }));

  const [artwork, setArtwork] = useState<{
      data: Uint8Array;
      palette: string[];
      width: number;
      height: number;
  } | null>(null);

  // Yarn Management
  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 },
      'B': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4 }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 },
      'B': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5 }
  });

  const [activeYarnId, setActiveYarnId] = useState<string>('A');
  const [selectedYarnType, setSelectedYarnType] = useState<'warp' | 'weft'>('warp');
  const [studioYarnDef, setStudioYarnDef] = useState<YarnDefinition>(warpYarns['A']);

  useEffect(() => {
      const source = selectedYarnType === 'warp' ? warpYarns : weftYarns;
      if (source[activeYarnId]) {
          setStudioYarnDef(source[activeYarnId]);
      }
  }, [activeYarnId, selectedYarnType, warpYarns, weftYarns]);

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');
  const [dentingPattern, setDentingPattern] = useState('1');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleResize = (size: number) => {
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) {
          newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      }
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 

          setArtwork({
              data: new Uint8Array(result.pixels),
              palette: result.palette,
              width: result.width,
              height: result.height
          });

          setJacquardData({
              width: result.width,
              height: result.height,
              structure: new Uint8Array(result.width * result.height).fill(0)
          });

          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`);
          setWeftPatternString(`${result.height}A`);

          setProjectName(file.name.split('.')[0]);
          setViewMode('structure');
          setAppMode('art');
          setLoadingStatus(null);
      } catch (err: any) {
          console.error("Bitmap Process Error:", err);
          alert(err.message || "Failed to process bitmap.");
          setLoadingStatus(null);
      }
  };

  const handleApplyWeaveToColor = (weave: LibraryWeave, colorIdx: number) => {
    if (!artwork) return;
    setLoadingStatus(`Applying ${weave.name}...`);

    setTimeout(() => {
        const newStructure = new Uint8Array(jacquardData.structure);
        const { width, height } = jacquardData;
        const weaveDraft = weave.draft;
        const weavePeg = weave.pegPlan;
        const weaveW = weaveDraft[0].length;
        const weaveH = weavePeg.length;

        const weaveLookup = new Uint8Array(weaveW * weaveH);
        const warpToHarness = new Int16Array(weaveW).fill(-1);
        for(let w=0; w<weaveW; w++) {
            for(let h=0; h<weave.harnesses; h++) {
                if(weaveDraft[h][w] === 1) { warpToHarness[w] = h; break; }
            }
        }
        for(let y=0; y<weaveH; y++) {
            for(let x=0; x<weaveW; x++) {
                const harness = warpToHarness[x];
                if(harness !== -1 && weavePeg[y][harness] === 1) {
                    weaveLookup[y * weaveW + x] = 1;
                }
            }
        }

        for(let i=0; i<artwork.data.length; i++) {
            if(artwork.data[i] === colorIdx) {
                const x = i % width;
                const y = Math.floor(i / width);
                newStructure[i] = weaveLookup[(y % weaveH) * weaveW + (x % weaveW)];
            }
        }

        setJacquardData(prev => ({ ...prev, structure: newStructure }));
        setLoadingStatus(null);
        setViewMode('interlace');
    }, 50);
  };

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      if (seq.length === 0) return Array(jacquardData.width).fill('#888');
      return Array.from({ length: jacquardData.width }, (_, i) => {
          const char = seq[i % seq.length];
          return warpYarns[char]?.color || '#888';
      });
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const seq = expandPatternString(weftPatternString);
      if (seq.length === 0) return Array(jacquardData.height).fill('#888');
      return Array.from({ length: jacquardData.height }, (_, i) => {
          const char = seq[i % seq.length];
          return weftYarns[char]?.color || '#888';
      });
  }, [weftYarns, weftPatternString, jacquardData.height]);

  const simData = useMemo(() => {
      const { width, height, structure } = jacquardData;
      // We pass the full structure to the simulation for accurate tiling and detail.
      // Convert flat Uint8Array structure to boolean[][] format expected by modal.
      const rows: boolean[][] = [];
      const colors: string[][] = [];

      for (let y = 0; y < height; y++) {
          const rowB: boolean[] = [];
          const rowC: string[] = [];
          for (let x = 0; x < width; x++) {
              const idx = y * width + x;
              const isUp = structure[idx] === 1;
              rowB.push(isUp);
              rowC.push(isUp ? warpColorArray[x % warpColorArray.length] : weftColorArray[y % weftColorArray.length]);
          }
          rows.push(rowB);
          colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  const handleGridOperation = (type: 'draft' | 'peg', action: string) => {
      const newData = new Uint8Array(jacquardData.structure);
      if (action === 'clear') newData.fill(0);
      else if (action === 'invert') {
          for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1;
      }
      setJacquardData(prev => ({ ...prev, structure: newData }));
  };

  const handleApplyStudioYarn = () => {
    if (selectedYarnType === 'warp') {
        setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    } else {
        setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    }
    setAppMode('art'); 
  };

  const handleModeChange = (mode: AppMode) => {
      if (mode === 'sim') {
          setShowSimModal(true);
      } else {
          setAppMode(mode);
      }
  };

  const isDesignerMode = appMode === 'art' || appMode === 'weave' || appMode === 'specs' || appMode === 'pattern';

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />

        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={handleModeChange} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{jacquardData.width} × {jacquardData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                         <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                            <button 
                                onClick={() => setViewMode('interlace')}
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400'}`}
                            >STRUCTURE</button>
                            <button 
                                onClick={() => setViewMode('structure')} 
                                className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400'}`}
                            >ARTWORK</button>
                        </div>
                        <div className="flex items-center gap-1 border-l border-gray-800 pl-4">
                            {[1024, 2048, 4096].map(size => (
                                <button key={size} onClick={() => handleResize(size)} className={`px-2 py-0.5 rounded text-[10px] border transition-colors ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400 hover:text-white'}`}>{size}</button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="flex-1 relative">
                    {appMode === 'yarn' ? (
                        <YarnStudio 
                            yarn={studioYarnDef} 
                            onChange={setStudioYarnDef} 
                            onApply={handleApplyStudioYarn} 
                        />
                    ) : appMode === 'tech' ? (
                        <div className="bg-white text-gray-900 h-full overflow-hidden">
                            <ProductionCalculator 
                                settings={settings}
                                warpYarns={warpYarns}
                                weftYarns={weftYarns}
                                warpPatternString={warpPatternString}
                                weftPatternString={weftPatternString}
                                draft={[]} 
                                pegPlan={[]}
                                generateThumbnail={() => simData.colors[0][0]} 
                            />
                        </div>
                    ) : (
                        <JacquardCanvas 
                            data={jacquardData}
                            artwork={artwork || undefined}
                            onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))}
                            tool={currentTool}
                            viewMode={viewMode}
                            faceMode={faceMode}
                            warpColors={warpColorArray}
                            weftColors={weftColorArray}
                            gridDivision={settings.gridDivision}
                        />
                    )}
                </div>

                {artwork && isDesignerMode && (
                    <div className="h-20 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl">
                        <div className="flex flex-col">
                            <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest mb-1">Optimized Palette</span>
                            <span className="text-[10px] text-gray-400 font-mono">{artwork.palette.length} Inherent Colors</span>
                        </div>
                        <div className="flex-1 flex items-center gap-3 overflow-x-auto no-scrollbar py-2">
                            {artwork.palette.map((color, idx) => (
                                <div 
                                    key={`${color}-${idx}`}
                                    onDragOver={(e) => { e.preventDefault(); setDragOverColorIdx(idx); }}
                                    onDragLeave={() => setDragOverColorIdx(null)}
                                    onDrop={(e) => {
                                        e.preventDefault();
                                        setDragOverColorIdx(null);
                                        const weaveData = e.dataTransfer.getData('weave-obj');
                                        if (weaveData) {
                                            handleApplyWeaveToColor(JSON.parse(weaveData), idx);
                                        }
                                    }}
                                    className={`group flex flex-col items-center gap-1 shrink-0 bg-gray-800/40 p-2 rounded-lg border transition-all ${dragOverColorIdx === idx ? 'bg-blue-900/40 border-blue-500 scale-105 shadow-lg shadow-blue-500/20' : 'border-gray-700/50 hover:bg-gray-800'}`}
                                >
                                    <div 
                                        className="w-8 h-8 rounded-md border border-white/10 shadow-md transition-transform" 
                                        style={{ backgroundColor: color }}
                                    />
                                    <span className="text-[8px] font-mono text-gray-500 uppercase">{idx + 1}: {color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end">
                            <span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drag weave to color</span>
                            <button 
                                onClick={() => setArtwork(null)}
                                className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded hover:bg-red-900/50 transition-colors font-bold uppercase tracking-tighter"
                            >
                                Clear Artwork
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <RightPanel 
                settings={settings}
                onSettingsChange={setSettings}
                dentingPattern={dentingPattern}
                onDentingChange={setDentingPattern}
                onSnapshot={()=>{}}
                onLoadWeave={()=>{}}
                customWeaves={[]}
                onAddWeave={()=>{}}
                onUpdateWeave={()=>{}}
                onDeleteWeave={()=>{}}
                warpYarns={warpYarns}
                weftYarns={weftYarns}
                onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))}
                onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))}
                paletteColors={PANTONE_PALETTE}
                warpPatternString={warpPatternString}
                setWarpPatternString={setWarpPatternString}
                weftPatternString={weftPatternString}
                setWeftPatternString={setWeftPatternString}
                onOpenGridEditor={()=>{}}
                onOpenPatternGenerator={()=>{}}
                currentInput={{} as any}
                onApplyGenerated={()=>{}}
                onSimulate={() => setShowSimModal(true)}
                onGridOperation={(t, a) => handleGridOperation(t, a)}
                activeYarnId={activeYarnId}
                selectedYarnType={selectedYarnType}
                onSelectYarn={(id, type) => {
                    setActiveYarnId(id);
                    setSelectedYarnType(type);
                    setAppMode('yarn');
                }}
            />
        </div>

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)}
            weavePattern={simData.colors}
            structure={simData.structure}
            epi={settings.epi}
            ppi={settings.ppi}
            warpYarns={warpYarns}
            weftYarns={weftYarns}
            warpYarnSequence={expandPatternString(warpPatternString).slice(0, jacquardData.width)}
            weftYarnSequence={expandPatternString(weftPatternString).slice(0, jacquardData.height)}
        />
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode } from '../types';

interface JacquardCanvasProps {
    data: JacquardData;
    artwork?: {
        data: Uint8Array;
        palette: string[];
        width: number;
        height: number;
    };
    onUpdate: (newData: Uint8Array) => void;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    gridDivision: number;
}

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, artwork, onUpdate, tool, viewMode, faceMode, warpColors, weftColors, gridDivision
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [view, setView] = useState({ x: 40, y: 40, zoom: 1 }); // Start with padding for headers
    const [hoverPos, setHoverPos] = useState({ x: 0, y: 0 });
    const isInteracting = useRef(false);
    const lastGridPos = useRef({ x: -1, y: -1 });
    const localBuffer = useRef<Uint8Array>(data.structure);

    useEffect(() => {
        localBuffer.current = data.structure;
        render();
    }, [data.structure]);

    const HEADER_SIZE = 24;

    const render = () => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        if (canvas.width !== w || canvas.height !== h) {
            canvas.width = w;
            canvas.height = h;
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        const startX = Math.floor((HEADER_SIZE - view.x) / zoom);
        const startY = Math.floor((HEADER_SIZE - view.y) / zoom);
        const endX = Math.min(data.width, startX + Math.ceil((w - HEADER_SIZE) / zoom) + 1);
        const endY = Math.min(data.height, startY + Math.ceil((h - HEADER_SIZE) / zoom) + 1);

        const isArtworkView = viewMode === 'structure';
        const isReverse = faceMode === 'reverse';
        const buffer = localBuffer.current;

        // 1. Render Main Grid
        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * data.width + x;

                if (isArtworkView && artwork) {
                    const colorIdx = artwork.data[idx];
                    ctx.fillStyle = artwork.palette[colorIdx] || '#000000';
                } else {
                    let val = buffer[idx] === 1;
                    if (isReverse) val = !val;

                    if (isArtworkView) {
                        ctx.fillStyle = val ? '#ffffff' : '#000000';
                    } else {
                        ctx.fillStyle = val ? warpColors[x % warpColors.length] : weftColors[y % weftColors.length];
                    }
                }

                ctx.fillRect(
                    Math.floor(view.x + x * zoom),
                    Math.floor(view.y + y * zoom),
                    Math.ceil(zoom),
                    Math.ceil(zoom)
                );
            }
        }

        // 2. Render Headers (Yarn Grids)
        // Static background for headers to prevent grid bleed
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, w, HEADER_SIZE); // Top
        ctx.fillRect(0, 0, HEADER_SIZE, h); // Left

        // Warp Yarn Bar (Top)
        for (let x = Math.max(0, startX); x < endX; x++) {
            ctx.fillStyle = warpColors[x % warpColors.length] || '#888';
            ctx.fillRect(
                Math.floor(view.x + x * zoom),
                0,
                Math.ceil(zoom),
                HEADER_SIZE
            );
        }

        // Weft Yarn Bar (Left)
        for (let y = Math.max(0, startY); y < endY; y++) {
            ctx.fillStyle = weftColors[y % weftColors.length] || '#888';
            ctx.fillRect(
                0,
                Math.floor(view.y + y * zoom),
                HEADER_SIZE,
                Math.ceil(zoom)
            );
        }

        // Intersection Corner
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, HEADER_SIZE, HEADER_SIZE);
        ctx.strokeStyle = '#334155';
        ctx.strokeRect(0, 0, HEADER_SIZE, HEADER_SIZE);

        // Visual Grid Divisions
        if (zoom > 4) {
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            for (let x = Math.max(0, startX); x <= endX; x++) {
                if (x % gridDivision === 0) {
                    ctx.moveTo(view.x + x * zoom, HEADER_SIZE);
                    ctx.lineTo(view.x + x * zoom, h);
                }
            }
            for (let y = Math.max(0, startY); y <= endY; y++) {
                if (y % gridDivision === 0) {
                    ctx.moveTo(HEADER_SIZE, view.y + y * zoom);
                    ctx.lineTo(w, view.y + y * zoom);
                }
            }
            ctx.stroke();
        }
    };

    useEffect(() => {
        render();
    }, [view, viewMode, faceMode, warpColors, weftColors, artwork]);

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;

        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const zoomFactor = wheelEv.deltaY > 0 ? 0.85 : 1.15;
            const newZoom = Math.min(200, Math.max(0.01, view.zoom * zoomFactor));
            const worldX = (mouseX - view.x) / view.zoom;
            const worldY = (mouseY - view.y) / view.zoom;
            setView({ x: mouseX - worldX * newZoom, y: mouseY - worldY * newZoom, zoom: newZoom });
            return;
        }

        if (tool === 'pan') {
            if (e.type === 'mousedown') {
                isInteracting.current = true;
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else if (e.type === 'mousemove' && isInteracting.current) {
                const dx = mouseX - lastGridPos.current.x;
                const dy = mouseY - lastGridPos.current.y;
                setView(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else {
                isInteracting.current = false;
            }
            return;
        }

        const gridX = Math.floor((mouseX - view.x) / view.zoom);
        const gridY = Math.floor((mouseY - view.y) / view.zoom);

        // Update hover pos for coordinate indicator
        if (e.type === 'mousemove') {
            setHoverPos({ x: Math.max(0, Math.min(data.width - 1, gridX)), y: Math.max(0, Math.min(data.height - 1, gridY)) });
        }

        if (e.type === 'mousedown') {
            isInteracting.current = true;
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                const idx = gridY * data.width + gridX;
                localBuffer.current[idx] = localBuffer.current[idx] === 1 ? 0 : 1;
                lastGridPos.current = { x: gridX, y: gridY };
                render();
            }
        } else if (e.type === 'mousemove' && isInteracting.current) {
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                if (gridX !== lastGridPos.current.x || gridY !== lastGridPos.current.y) {
                    localBuffer.current[gridY * data.width + gridX] = 1;
                    lastGridPos.current = { x: gridX, y: gridY };
                    render();
                }
            }
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            if (isInteracting.current) {
                isInteracting.current = false;
                onUpdate(new Uint8Array(localBuffer.current));
            }
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden select-none relative">
            <canvas 
                ref={canvasRef}
                onMouseDown={handleInteraction}
                onMouseMove={handleInteraction}
                onMouseUp={handleInteraction}
                onMouseLeave={handleInteraction}
                onWheel={handleInteraction}
                className="block"
            />
            <div className="absolute bottom-4 left-4 flex gap-2 pointer-events-none">
                <div className="bg-black/80 px-3 py-1 rounded text-[10px] font-mono text-blue-400 border border-blue-900/50 uppercase tracking-tighter flex items-center gap-4">
                    <span>{tool.toUpperCase()} MODE | ZOOM {Math.round(view.zoom * 100)}%</span>
                    <span className="text-gray-400 border-l border-gray-800 pl-4">
                        WARP: <span className="text-white font-bold">{hoverPos.x + 1}</span> | 
                        WEFT: <span className="text-white font-bold">{hoverPos.y + 1}</span>
                    </span>
                </div>
            </div>
            <div className="absolute top-8 left-4 text-[9px] font-bold text-gray-500 uppercase rotate-90 origin-left pointer-events-none">
                Weft Yarn Grid
            </div>
            <div className="absolute top-4 left-8 text-[9px] font-bold text-gray-500 uppercase pointer-events-none">
                Warp Yarn Grid
            </div>
        </div>
    );
};

