                </div>
                <div className="flex-1 overflow-y-auto custom-scrollbar p-5 space-y-6">
                    <section>
                        <h4 className="text-[10px] font-bold text-blue-600 uppercase mb-3">Material Definition</h4>
                        <div className="flex items-center gap-3 bg-gray-50 p-2 rounded border mb-4">
                            <input type="color" value={yarn.color} onChange={e => handleParamChange('color', e.target.value)} className="w-8 h-8 rounded cursor-pointer border border-gray-300 p-0" />
                            <div className="flex-1"><span className="text-[10px] font-bold text-gray-400 uppercase block">Main Color</span><span className="text-xs font-mono text-gray-700">{yarn.color}</span></div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div><label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Fiber</label><select value={yarn.fiberType} onChange={e => handleParamChange('fiberType', e.target.value)} className="w-full bg-white border border-gray-300 rounded p-1.5 text-xs"><option>Cotton</option><option>Wool</option><option>Silk</option><option>Synthetic</option></select></div>
                            <div><label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">System</label><select value={yarn.countSystem} onChange={e => handleParamChange('countSystem', e.target.value)} className="w-full bg-white border border-gray-300 rounded p-1.5 text-xs"><option>Nm</option><option>Ne</option><option>Tex</option><option>Denier</option></select></div>
