                        <Slider label="Sheen" value={yarn.sheen} min={0} max={1} step={0.1} onChange={(v:any)=>handleParamChange('sheen',v)}/>
                        <Slider label="Roughness" value={yarn.roughness} min={0} max={1} step={0.1} onChange={(v:any)=>handleParamChange('roughness',v)}/>
                        <Slider label="Hairiness" value={yarn.hairiness || 0} min={0} max={1} step={0.05} onChange={(v:any)=>handleParamChange('hairiness',v)}/>
                    </section>
                    <button onClick={handleSaveToLibrary} className="w-full py-3 bg-gray-900 text-white rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-gray-800 transition-all flex items-center justify-center gap-2"><PlusIcon className="w-4 h-4"/> Save to Presets</button>
                </div>
            </div>
        </div>
    );
