export interface QuantizationResult {
  pixels: number[]; // Array of palette indices
  palette: string[]; // Array of hex colors
  width: number;
  height: number;
}

const rgbToHex = (r: number, g: number, b: number) => {
    return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase();
};

const hexToRgb = (hex: string) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return [r, g, b];
};

const colorDistanceSq = (r1: number, g1: number, b1: number, r2: number, g2: number, b2: number) => {
    return (r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2;
};

export const loadImage = (file: File): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => {
            URL.revokeObjectURL(url);
            resolve(img);
        };
        img.onerror = () => {
            URL.revokeObjectURL(url);
            reject(new Error(`Failed to load image: ${file.name}. Ensure it is a valid image file.`));
        };
        img.src = url;
    });
};

export const processImage = (
    img: HTMLImageElement, 
    maxColors: number = 12, 
    maxWidth: number = 1024
): QuantizationResult => {
    let w = img.width;
    let h = img.height;

    if (w > maxWidth) {
        const ratio = maxWidth / w;
        w = maxWidth;
        h = Math.floor(h * ratio);
    }

    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error("Could not initialize 2D context.");

    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(img, 0, 0, w, h);

    const imgData = ctx.getImageData(0, 0, w, h);
    const data = imgData.data;
    const pixelCount = w * h;

    // 1. Detect Unique Colors
    const uniqueColorsMap = new Map<string, number>();
    for (let i = 0; i < pixelCount; i++) {
        const offset = i * 4;
        if (data[offset + 3] < 128) continue; 
        const hex = rgbToHex(data[offset], data[offset+1], data[offset+2]);
        uniqueColorsMap.set(hex, (uniqueColorsMap.get(hex) || 0) + 1);
    }

    let palette: string[] = [];
    let pixels: number[] = new Array(pixelCount).fill(0);

    if (uniqueColorsMap.size <= maxColors) {
        // Sort existing small palette by frequency
        palette = Array.from(uniqueColorsMap.entries())
            .sort((a, b) => b[1] - a[1])
            .map(entry => entry[0]);
        for (let i = 0; i < pixelCount; i++) {
            const hex = rgbToHex(data[i*4], data[i*4+1], data[i*4+2]);
            pixels[i] = palette.indexOf(hex);
        }
    } else {
        // K-Means
        let centroids = Array.from(uniqueColorsMap.entries())
            .sort((a, b) => b[1] - a[1])
            .slice(0, maxColors)
            .map(entry => hexToRgb(entry[0]));

        const assignments = new Uint8Array(pixelCount);
        for (let iter = 0; iter < 8; iter++) {
            const sums = centroids.map(() => [0, 0, 0, 0]); // r, g, b, count
            for (let i = 0; i < pixelCount; i++) {
                const r = data[i*4], g = data[i*4+1], b = data[i*4+2];
                let minDist = Infinity, best = 0;
                for (let c = 0; c < centroids.length; c++) {
                    const d = colorDistanceSq(r, g, b, centroids[c][0], centroids[c][1], centroids[c][2]);
                    if (d < minDist) { minDist = d; best = c; }
                }
                assignments[i] = best;
                sums[best][0] += r; sums[best][1] += g; sums[best][2] += b; sums[best][3]++;
            }
            centroids = sums.map((s, idx) => s[3] > 0 ? [s[0]/s[3], s[1]/s[3], s[2]/s[3]] : centroids[idx]);
        }

        // Sort centroids by assigned pixel count (frequency)
        const counts = new Array(centroids.length).fill(0);
        assignments.forEach(a => counts[a]++);

        const indexedCentroids = centroids.map((c, i) => ({ color: c, count: counts[i], oldIdx: i }));
        indexedCentroids.sort((a, b) => b.count - a.count);

        palette = indexedCentroids.map(ic => rgbToHex(Math.round(ic.color[0]), Math.round(ic.color[1]), Math.round(ic.color[2])));
        const remapping = new Int32Array(centroids.length);
        indexedCentroids.forEach((ic, newIdx) => remapping[ic.oldIdx] = newIdx);

        pixels = Array.from(assignments).map(oldIdx => remapping[oldIdx]);
    }

    return { pixels, palette, width: w, height: h };
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode } from '../types';

interface JacquardCanvasProps {
    data: JacquardData;
    artwork?: {
        data: Uint8Array;
        palette: string[];
        width: number;
        height: number;
    };
    onUpdate: (newData: Uint8Array) => void;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    gridDivision: number;
}

// Discrete zoom levels to prevent fractional pixel rendering artifacts
const ZOOM_LEVELS = [0.0625, 0.125, 0.25, 0.5, 1, 2, 4, 8, 16, 32, 64];

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, artwork, onUpdate, tool, viewMode, faceMode, warpColors, weftColors, gridDivision
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [view, setView] = useState({ x: 40, y: 40, zoom: 1 }); 
    const [hoverPos, setHoverPos] = useState({ x: 0, y: 0 });
    const [isSpacePressed, setIsSpacePressed] = useState(false);
    const isInteracting = useRef(false);
    const lastGridPos = useRef({ x: -1, y: -1 });
    const localBuffer = useRef<Uint8Array>(data.structure);

    useEffect(() => {
        localBuffer.current = data.structure;
        render();
    }, [data.structure]);

    const HEADER_SIZE = 24;

    const render = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        if (canvas.width !== w || canvas.height !== h) {
            canvas.width = w; canvas.height = h;
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        const startX = Math.floor((HEADER_SIZE - view.x) / zoom);
        const startY = Math.floor((HEADER_SIZE - view.y) / zoom);
        const endX = Math.min(data.width, startX + Math.ceil((w - HEADER_SIZE) / zoom) + 1);
        const endY = Math.min(data.height, startY + Math.ceil((h - HEADER_SIZE) / zoom) + 1);

        const isArtworkView = viewMode === 'structure';
        const isReverse = faceMode === 'reverse';
        const buffer = localBuffer.current;

        // 1. Render Design Grid
        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * data.width + x;
                if (isArtworkView && artwork) {
                    ctx.fillStyle = artwork.palette[artwork.data[idx]] || '#000';
                } else {
                    let val = buffer[idx] === 1;
                    if (isReverse) val = !val;
                    ctx.fillStyle = val ? warpColors[x % warpColors.length] : weftColors[y % weftColors.length];
                }
                ctx.fillRect(Math.floor(view.x + x * zoom), Math.floor(view.y + y * zoom), Math.ceil(zoom), Math.ceil(zoom));
            }
        }

        // 2. Render Headers & Hover Indicators
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, w, HEADER_SIZE); 
        ctx.fillRect(0, 0, HEADER_SIZE, h); 

        // Warp Bar
        for (let x = Math.max(0, startX); x < endX; x++) {
            ctx.fillStyle = warpColors[x % warpColors.length] || '#888';
            ctx.fillRect(Math.floor(view.x + x * zoom), 0, Math.ceil(zoom), HEADER_SIZE);
        }
        const wx = Math.floor(view.x + hoverPos.x * zoom);
        if (wx >= HEADER_SIZE && wx < w) {
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(wx, HEADER_SIZE - 4, Math.ceil(zoom), 4);
        }

        // Weft Bar
        for (let y = Math.max(0, startY); y < endY; y++) {
            ctx.fillStyle = weftColors[y % weftColors.length] || '#888';
            ctx.fillRect(0, Math.floor(view.y + y * zoom), HEADER_SIZE, Math.ceil(zoom));
        }
        const wy = Math.floor(view.y + hoverPos.y * zoom);
        if (wy >= HEADER_SIZE && wy < h) {
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(HEADER_SIZE - 4, wy, 4, Math.ceil(zoom));
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, HEADER_SIZE, HEADER_SIZE);
        ctx.strokeStyle = '#334155';
        ctx.strokeRect(0, 0, HEADER_SIZE, HEADER_SIZE);

        if (zoom > 4) {
            ctx.strokeStyle = 'rgba(255,255,255,0.05)'; ctx.lineWidth = 0.5; ctx.beginPath();
            for (let x = Math.max(0, startX); x <= endX; x++) { if (x % gridDivision === 0) { ctx.moveTo(view.x + x * zoom, HEADER_SIZE); ctx.lineTo(view.x + x * zoom, h); } }
            for (let y = Math.max(0, startY); y <= endY; y++) { if (y % gridDivision === 0) { ctx.moveTo(HEADER_SIZE, view.y + y * zoom); ctx.lineTo(w, view.y + y * zoom); } }
            ctx.stroke();
        }
    }, [view, viewMode, faceMode, warpColors, weftColors, artwork, hoverPos, data.width, data.height, gridDivision]);

    useEffect(() => { render(); }, [render]);

    // Handle Keyboard for Pan Shortcut (Spacebar)
    useEffect(() => {
        const onDown = (e: KeyboardEvent) => { if (e.code === 'Space') { setIsSpacePressed(true); if (e.target === document.body) e.preventDefault(); } };
        const onUp = (e: KeyboardEvent) => { if (e.code === 'Space') setIsSpacePressed(false); };
        window.addEventListener('keydown', onDown);
        window.addEventListener('keyup', onUp);
        return () => { window.removeEventListener('keydown', onDown); window.removeEventListener('keyup', onUp); };
    }, []);

    const effectiveTool = isSpacePressed ? 'pan' : tool;

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;
        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const direction = wheelEv.deltaY > 0 ? -1 : 1;
            const currentIndex = ZOOM_LEVELS.findIndex(z => z >= view.zoom);
            const nextIndex = Math.max(0, Math.min(ZOOM_LEVELS.length - 1, currentIndex + direction));
            const newZoom = ZOOM_LEVELS[nextIndex];

            if (newZoom !== view.zoom) {
                const worldX = (mouseX - view.x) / view.zoom, worldY = (mouseY - view.y) / view.zoom;
                setView({ x: mouseX - worldX * newZoom, y: mouseY - worldY * newZoom, zoom: newZoom });
            }
            return;
        }

        const gridX = Math.floor((mouseX - view.x) / view.zoom);
        const gridY = Math.floor((mouseY - view.y) / view.zoom);

        if (e.type === 'mousemove') {
            setHoverPos({ x: Math.max(0, Math.min(data.width - 1, gridX)), y: Math.max(0, Math.min(data.height - 1, gridY)) });
        }

        if (effectiveTool === 'pan') {
            if (e.type === 'mousedown') { isInteracting.current = true; lastGridPos.current = { x: mouseX, y: mouseY }; }
            else if (e.type === 'mousemove' && isInteracting.current) {
                setView(prev => ({ ...prev, x: prev.x + (mouseX - lastGridPos.current.x), y: prev.y + (mouseY - lastGridPos.current.y) }));
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else { isInteracting.current = false; }
            return;
        }

        if (e.type === 'mousedown') {
            isInteracting.current = true;
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                localBuffer.current[gridY * data.width + gridX] = localBuffer.current[gridY * data.width + gridX] === 1 ? 0 : 1;
                lastGridPos.current = { x: gridX, y: gridY }; render();
            }
        } else if (e.type === 'mousemove' && isInteracting.current) {
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height && (gridX !== lastGridPos.current.x || gridY !== lastGridPos.current.y)) {
                localBuffer.current[gridY * data.width + gridX] = 1; lastGridPos.current = { x: gridX, y: gridY }; render();
            }
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            if (isInteracting.current) { isInteracting.current = false; onUpdate(new Uint8Array(localBuffer.current)); }
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden select-none relative">
            <canvas ref={canvasRef} onMouseDown={handleInteraction} onMouseMove={handleInteraction} onMouseUp={handleInteraction} onMouseLeave={handleInteraction} onWheel={handleInteraction} className="block" />
            <div className="absolute bottom-4 left-4 flex gap-2 pointer-events-none">
                <div className="bg-black/80 px-3 py-1 rounded text-[10px] font-mono text-blue-400 border border-blue-900/50 uppercase tracking-tighter flex items-center gap-4">
                    <span>{effectiveTool.toUpperCase()} | {Math.round(view.zoom * 100)}%</span>
                    <span className="text-gray-400 border-l border-gray-800 pl-4">WARP: <span className="text-white font-bold">{hoverPos.x + 1}</span> | WEFT: <span className="text-white font-bold">{hoverPos.y + 1}</span></span>
                </div>
            </div>
            {isSpacePressed && <div className="absolute inset-0 bg-white/5 pointer-events-none flex items-center justify-center"><div className="bg-black/50 text-white px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest shadow-2xl border border-white/20">Pan Enabled</div></div>}
        </div>
    );
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { YarnStudio } from './YarnStudio';
import { ProductionCalculator } from './ProductionCalculator';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, AppMode, JacquardData } from '../types';
import { expandPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { loadImage, processImage } from '../services/imageProcessor';
import { LibraryWeave } from '../services/weaveLibrary';

const DEFAULT_PHYSICS = {
  floatTaper: 0.20,
  bindingDepth: 0.05,
  shadowAngle: 135,
  shadowThrow: 0.1
};

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');
  const [loadingStatus, setLoadingStatus] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragOverColorIdx, setDragOverColorIdx] = useState<number | null>(null);

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 512, 
    weftPicks: 512, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    harnesses: 1
  });

  const [dentingPattern, setDentingPattern] = useState('1');

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 512,
      height: 512,
      structure: new Uint8Array(512 * 512).fill(0).map((_, i) => (Math.floor(i / 512) + (i % 512)) % 2 === 0 ? 1 : 0)
  }));

  const [artwork, setArtwork] = useState<{
      data: Uint8Array;
      palette: string[];
      width: number;
      height: number;
  } | null>(null);

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4, ...DEFAULT_PHYSICS },
      'B': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4, ...DEFAULT_PHYSICS }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS },
      'B': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS }
  });

  const [activeYarnId, setActiveYarnId] = useState<string>('A');
  const [selectedYarnType, setSelectedYarnType] = useState<'warp' | 'weft'>('warp');
  const [studioYarnDef, setStudioYarnDef] = useState<YarnDefinition>(warpYarns['A']);

  useEffect(() => {
      const source = selectedYarnType === 'warp' ? warpYarns : weftYarns;
      if (source[activeYarnId]) setStudioYarnDef(source[activeYarnId]);
  }, [activeYarnId, selectedYarnType, warpYarns, weftYarns]);

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleResize = (size: number) => {
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 
          // Result is already sorted by frequency from update to imageProcessor.ts
          setArtwork({ data: new Uint8Array(result.pixels), palette: result.palette, width: result.width, height: result.height });
          setJacquardData({ width: result.width, height: result.height, structure: new Uint8Array(result.width * result.height).fill(0) });
          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`); setWeftPatternString(`${result.height}A`);
          setProjectName(file.name.split('.')[0]); setViewMode('structure'); setAppMode('art'); setLoadingStatus(null);
      } catch (err: any) { alert(err.message || "Error processing."); setLoadingStatus(null); }
  };

  const handleApplyWeaveToColor = (weave: LibraryWeave, colorIdx: number) => {
    if (!artwork) return;
    setLoadingStatus(`Applying ${weave.name}...`);
    setTimeout(() => {
        const newStructure = new Uint8Array(jacquardData.structure);
        const { width, height } = jacquardData, weaveDraft = weave.draft, weavePeg = weave.pegPlan, weaveW = weaveDraft[0].length, weaveH = weavePeg.length;
        const weaveLookup = new Uint8Array(weaveW * weaveH);
        const warpToHarness = new Int16Array(weaveW).fill(-1);
        for(let w=0; w<weaveW; w++) for(let h=0; h<weave.harnesses; h++) if(weaveDraft[h][w] === 1) { warpToHarness[w] = h; break; }
        for(let y=0; y<weaveH; y++) for(let x=0; x<weaveW; x++) if(warpToHarness[x] !== -1 && weavePeg[y][warpToHarness[x]] === 1) weaveLookup[y * weaveW + x] = 1;
        for(let i=0; i<artwork.data.length; i++) if(artwork.data[i] === colorIdx) { const x = i % width, y = Math.floor(i / width); newStructure[i] = weaveLookup[(y % weaveH) * weaveW + (x % weaveW)]; }
        setJacquardData(prev => ({ ...prev, structure: newStructure })); setLoadingStatus(null); setViewMode('interlace');
    }, 50);
  };

  const handleMergeColors = (sourceIdx: number, targetIdx: number) => {
    if (!artwork || sourceIdx === targetIdx) return;
    setLoadingStatus("Merging Colors...");
    setTimeout(() => {
        const newData = new Uint8Array(artwork.data);
        for(let i=0; i<newData.length; i++) {
            if(newData[i] === sourceIdx) newData[i] = targetIdx;
            else if(newData[i] > sourceIdx) newData[i]--; // Shift indices down to close gap
        }
        const newPalette = artwork.palette.filter((_, i) => i !== sourceIdx);
        setArtwork({ ...artwork, data: newData, palette: newPalette });
        setLoadingStatus(null);
    }, 50);
  };

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      return Array.from({ length: jacquardData.width }, (_, i) => warpYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const seq = expandPatternString(weftPatternString);
      return Array.from({ length: jacquardData.height }, (_, i) => weftYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [weftYarns, weftPatternString, jacquardData.height]);

  const simData = useMemo(() => {
      const { width, height, structure } = jacquardData;
      const rows: boolean[][] = []; const colors: string[][] = [];
      for (let y = 0; y < height; y++) {
          const rowB: boolean[] = []; const rowC: string[] = [];
          for (let x = 0; x < width; x++) {
              const isUp = structure[y * width + x] === 1;
              rowB.push(isUp); rowC.push(isUp ? warpColorArray[x] : weftColorArray[y]);
          }
          rows.push(rowB); colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  const dentingPlanParsed = useMemo(() => {
    return dentingPattern.split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n) && n > 0);
  }, [dentingPattern]);

  const handleApplyStudioYarn = () => {
    if (selectedYarnType === 'warp') setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    else setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    setAppMode('art'); 
  };

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />
        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={(m) => m === 'sim' ? setShowSimModal(true) : setAppMode(m)} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{jacquardData.width} × {jacquardData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                         <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
