            />
        </div>

        <FabricSimulationModal isOpen={showSimModal} onClose={() => setShowSimModal(false)} weavePattern={simData.colors} structure={simData.structure} epi={settings.epi} ppi={settings.ppi} dentingPlan={dentingPlanParsed} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { YarnDefinition, YarnModel, YarnConstruction, FiberType } from '../types';
import { generateYarnTexture } from '../services/yarnRenderer';
import { RulerIcon, ZoomInIcon, ZoomOutIcon, ResetZoomIcon, ShuffleIcon, PencilIcon, PlusIcon, TrashIcon } from './icons';

interface YarnStudioProps {
    yarn: YarnDefinition;
    onChange: (def: YarnDefinition) => void;
    onApply: () => void;
}

const GLOBAL_LIBRARY: { name: string, def: YarnDefinition }[] = [
    { name: "Cotton 2/30", def: { color: '#e5e7eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1.0, twist: 'Z', tpi: 15, sheen: 0.1, roughness: 0.4 } },
    { name: "Siro Grindle (Grey)", def: { color: '#333333', colorB: '#999999', model: 'grindle', construction: 'standard', fiberType: 'Poly-Cotton', countSystem: 'Ne', count: 20, ply: 2, thickness: 1.2, twist: 'Z', tpi: 22, sheen: 0.2, roughness: 0.3, strength: 18.5, elongation: 6.2, ipi: 45 } },
    { name: "Silk Crepe", def: { color: '#fca5a5', model: 'simple', construction: 'standard', fiberType: 'Silk', countSystem: 'Denier', count: 50, ply: 1, thickness: 0.6, twist: 'S', tpi: 35, sheen: 0.9, roughness: 0.1, shadowStrength: 0.6 } },
    { name: "Wool Roving", def: { color: '#d1d5db', model: 'simple', construction: 'standard', fiberType: 'Wool', countSystem: 'Nm', count: 4, ply: 1, thickness: 2.2, twist: 'Z', tpi: 1.5, sheen: 0.2, roughness: 0.8, hairiness: 0.5, hairLength: 0.4 } },
    { name: "Chenille Velvet", def: { color: '#9333ea', model: 'simple', construction: 'chenille', fiberType: 'Synthetic', countSystem: 'Nm', count: 6, ply: 1, thickness: 2.0, twist: 'Z', tpi: 4, sheen: 0.6, roughness: 0.5, hairiness: 0.8, hairLength: 0.1 } },
    { name: "Bouclé Loop", def: { color: '#3b82f6', model: 'simple', construction: 'boucle', fiberType: 'Wool', countSystem: 'Nm', count: 12, ply: 1, thickness: 1.5, twist: 'Z', tpi: 8, sheen: 0.3, roughness: 0.7, loopSize: 0.6, loopInterval: 0.4 } },
    { name: "Linen Slub", def: { color: '#d6d3d1', model: 'simple', construction: 'slub', fiberType: 'Linen', countSystem: 'Lea', count: 20, ply: 1, thickness: 1.1, twist: 'S', tpi: 12, sheen: 0.4, roughness: 0.6, slubLength: 2.5, slubDistance: 8.0, slubAmplitude: 150, slubMode: 'random' } },
];

const calculateTechSpecs = (yarn: YarnDefinition) => {
    let nm = 0;
    const safeCount = Math.max(0.1, yarn.count);
    const ply = Math.max(1, yarn.ply);
    switch (yarn.countSystem) {
        case 'Nm': nm = safeCount / ply; break;
        case 'Ne': nm = (safeCount * 1.6934) / ply; break;
        case 'Lea': nm = (safeCount * 0.6048) / ply; break;
        case 'Denier': nm = 9000 / (safeCount * ply); break;
        case 'Tex': nm = 1000 / (safeCount * ply); break;
        default: nm = safeCount / ply;
    }
    const tex = 1000 / nm;
    let diamCoeff = 0.037;
    if (['Silk', 'Synthetic', 'Lurex'].includes(yarn.fiberType)) diamCoeff = 0.032;
    const diameterMm = diamCoeff * Math.sqrt(tex);
    return { nm, tex, diameterMm };
};

export const YarnStudio: React.FC<YarnStudioProps> = ({ yarn, onChange, onApply }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [viewScale, setViewScale] = useState(1.5);
    const [searchTerm, setSearchTerm] = useState('');
    const [customLibrary, setCustomLibrary] = useState<{ name: string, def: YarnDefinition, id: number }[]>(() => {
        try { const saved = localStorage.getItem('wonderweaves_custom_yarns'); return saved ? JSON.parse(saved) : []; }
        catch (e) { return []; }
    });

    const displayLibrary = useMemo(() => {
        const allItems = [
            ...customLibrary.map(item => ({ ...item, isCustom: true, key: `custom-${item.id}` })),
            ...GLOBAL_LIBRARY.map((item, i) => ({ ...item, isCustom: false, id: -1, key: `global-${i}` }))
        ];
        if (!searchTerm.trim()) return allItems;
        const lowerTerm = searchTerm.toLowerCase();
        return allItems.filter(item => item.name.toLowerCase().includes(lowerTerm) || item.def.fiberType.toLowerCase().includes(lowerTerm));
    }, [customLibrary, searchTerm]);

    const specs = useMemo(() => calculateTechSpecs(yarn), [yarn]);

    const handleParamChange = (key: keyof YarnDefinition, value: any) => {
        onChange({ ...yarn, [key]: value });
    };

    const handleSaveToLibrary = () => {
        const name = prompt("Name your yarn preset:", yarn.code || `My ${yarn.fiberType} Yarn`);
        if (!name) return;
        const newItem = { name, def: { ...yarn }, id: Date.now() };
        setCustomLibrary(prev => {
            const updated = [newItem, ...prev];
            localStorage.setItem('wonderweaves_custom_yarns', JSON.stringify(updated));
            return updated;
        });
    };

    const handleDeleteFromLibrary = (id: number, e: React.MouseEvent) => {
        e.stopPropagation();
        if(window.confirm('Delete this preset?')) {
            setCustomLibrary(prev => {
                const updated = prev.filter(item => item.id !== id);
                localStorage.setItem('wonderweaves_custom_yarns', JSON.stringify(updated));
                return updated;
            });
        }
    };

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container || !yarn) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        const w = container.offsetWidth, h = container.offsetHeight;
        canvas.width = w; canvas.height = h;
        const texture = generateYarnTexture(yarn, 144);
        const targetCoreWidth = (w / 18) * yarn.thickness * viewScale;
        const drawWidth = targetCoreWidth * 4.0; 
        const threadStep = targetCoreWidth * (0.95 + (yarn.spacing || 0)); 
        const threadsNeeded = Math.ceil(w / threadStep) + 2;
        ctx.fillStyle = '#111827'; ctx.fillRect(0,0,w,h);
        for(let i=0; i<threadsNeeded; i++) {
            const cx = Math.round((i * threadStep) - (threadStep/2));
            const noise = (Math.sin(i * 12.9898 + 78.233) * 43758.5453) % 1; 
            const yOffset = Math.floor(Math.abs(noise) * texture.width);
            const lengthScale = drawWidth / texture.height;
            const tilesNeeded = Math.ceil(h / (texture.width * lengthScale)) + 1;
            for(let j=0; j<tilesNeeded; j++) {
                const dy = (j * texture.width * lengthScale) - (yOffset * lengthScale);
                ctx.save(); ctx.translate(cx, dy); ctx.rotate(Math.PI/2);
                ctx.drawImage(texture, 0, -drawWidth/2, texture.width * lengthScale, drawWidth);
                ctx.restore();
            }
        }
    }, [yarn, viewScale]);

    const Slider = ({label, value, min, max, step, onChange, subLabel=""}: any) => (
        <div className="mb-4">
            <div className="flex justify-between text-[10px] font-bold text-gray-500 uppercase mb-1">
                <span>{label}</span>
                <span className="text-gray-900">{typeof value === 'number' ? value.toFixed(2) : value} {subLabel}</span>
            </div>
            <input type="range" min={min} max={max} step={step} value={value || 0} onChange={e => onChange(parseFloat(e.target.value))} className="w-full h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600" />
        </div>
    );

    return (
        <div className="flex h-full w-full bg-white text-gray-900 font-sans overflow-hidden">
            {/* LEFT: LIBRARY */}
            <div className="w-64 border-r border-gray-200 flex flex-col bg-gray-50 flex-shrink-0 h-full">
                <div className="p-4 border-b border-gray-200 bg-white">
                    <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Library</h2>
                    <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Search..." className="w-full bg-gray-100 border border-gray-200 rounded p-1.5 text-xs focus:outline-none focus:bg-white transition-colors" />
                </div>
                <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
                    {displayLibrary.map((item) => (
                        <div key={item.key} onClick={() => onChange(item.def)} className="group p-2 rounded-md hover:bg-white hover:shadow-sm cursor-pointer border border-transparent hover:border-gray-200 transition-all flex items-center gap-3 relative">
                            <div className="w-8 h-8 rounded-full shadow-inner shrink-0 border border-gray-300" style={{backgroundColor: item.def.color}}></div>
                            <div className="min-w-0 flex-1">
                                <div className="text-xs font-bold text-gray-700 truncate">{item.name}</div>
                                <div className="text-[10px] text-gray-400">{item.def.fiberType}</div>
                            </div>
                            {item.isCustom && <button onClick={e => handleDeleteFromLibrary(item.id, e)} className="opacity-0 group-hover:opacity-100 p-1 text-gray-400 hover:text-red-500"><TrashIcon className="w-3 h-3"/></button>}
                        </div>
                    ))}
                </div>
            </div>

            {/* CENTER: CANVAS */}
            <div className="flex-1 relative bg-gray-900 flex flex-col min-w-0 h-full">
                <div className="absolute top-4 left-4 z-10 bg-white/90 backdrop-blur shadow rounded px-3 py-1.5 border border-gray-200">
                    <span className="text-[10px] font-bold text-gray-400 uppercase mr-2">Yarn Preview</span>
                    <span className="text-sm font-bold text-gray-800">{yarn.fiberType}</span>
                </div>
                <div className="absolute top-4 right-4 z-10">
                    <button onClick={onApply} className="bg-blue-600 hover:bg-blue-500 text-white shadow-lg rounded-full px-6 py-2 text-sm font-bold transition-all">Apply to Project</button>
                </div>
                <div className="flex-1 relative overflow-hidden" ref={containerRef}>
                    <canvas ref={canvasRef} className="w-full h-full block" />
                </div>
                <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-1 bg-white/90 backdrop-blur shadow rounded-full p-1.5 border border-gray-200">
                    <button onClick={() => setViewScale(s => Math.max(0.5, s - 0.2))} className="p-1.5 text-gray-500 hover:text-blue-600"><ZoomOutIcon className="w-4 h-4"/></button>
                    <span className="text-[10px] font-mono w-10 text-center font-bold text-gray-600">{Math.round(viewScale*100)}%</span>
                    <button onClick={() => setViewScale(s => Math.min(4.0, s + 0.2))} className="p-1.5 text-gray-500 hover:text-blue-600"><ZoomInIcon className="w-4 h-4"/></button>
                    <button onClick={() => setViewScale(1.5)} className="p-1.5 text-gray-500 hover:text-blue-600 ml-1 border-l border-gray-200 pl-2"><ResetZoomIcon className="w-4 h-4"/></button>
                </div>
            </div>

            {/* RIGHT: CONTROLS */}
            <div className="w-80 border-l border-gray-200 bg-white flex-shrink-0 h-full flex flex-col">
                <div className="p-5 bg-gray-50 border-b border-gray-200">
                    <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-4 flex items-center gap-2"><RulerIcon className="w-4 h-4"/> Engineering</h3>
                    <div className="grid grid-cols-2 gap-x-4 gap-y-3">
                        <div><label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Nm Eq.</label><span className="text-xs font-mono font-bold">{specs.nm.toFixed(1)}</span></div>
                        <div><label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Tex Eq.</label><span className="text-xs font-mono font-bold">{specs.tex.toFixed(1)}</span></div>
                        <div><label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Width</label><span className="text-xs font-mono font-bold">{specs.diameterMm.toFixed(3)}mm</span></div>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto custom-scrollbar p-5 space-y-6">
                    <section>
                        <h4 className="text-[10px] font-bold text-blue-600 uppercase mb-3">Material Definition</h4>
                        <div className="flex items-center gap-3 bg-gray-50 p-2 rounded border mb-4">
                            <input type="color" value={yarn.color} onChange={e => handleParamChange('color', e.target.value)} className="w-8 h-8 rounded cursor-pointer border border-gray-300 p-0" />
                            <div className="flex-1"><span className="text-[10px] font-bold text-gray-400 uppercase block">Color A</span><span className="text-xs font-mono text-gray-700">{yarn.color}</span></div>
                        </div>
                        {['mouline', 'grindle', 'melange', 'space-dyed'].includes(yarn.model) && (
                             <div className="flex items-center gap-3 bg-gray-50 p-2 rounded border mb-4">
                                <input type="color" value={yarn.colorB || '#ffffff'} onChange={e => handleParamChange('colorB', e.target.value)} className="w-8 h-8 rounded cursor-pointer border border-gray-300 p-0" />
                                <div className="flex-1"><span className="text-[10px] font-bold text-gray-400 uppercase block">Color B</span><span className="text-xs font-mono text-gray-700">{yarn.colorB || '#FFFFFF'}</span></div>
