                    </section>

                    <section>
                        <h4 className="text-[10px] font-bold text-emerald-600 uppercase mb-3">Spinning Props</h4>
                        <Slider label="Count" value={yarn.count} min={1} max={300} step={1} onChange={(v:any)=>handleParamChange('count',v)}/>
                        <Slider label="Ply" value={yarn.ply} min={1} max={12} step={1} onChange={(v:any)=>handleParamChange('ply',v)}/>
                        <div className="grid grid-cols-2 gap-4 mb-4">
                            <div><label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Twist Dir</label>
                                <select value={yarn.twist} onChange={e => handleParamChange('twist', e.target.value)} className="w-full bg-white border border-gray-300 rounded p-1.5 text-xs">
                                    <option value="Z">Z-Twist</option>
                                    <option value="S">S-Twist</option>
                                </select>
                            </div>
                            <div><Slider label="TPI" value={yarn.tpi} min={0} max={40} step={0.5} onChange={(v:any)=>handleParamChange('tpi',v)}/></div>
                        </div>
                    </section>

                    {yarn.construction === 'slub' && (
                        <section className="p-4 bg-orange-50 rounded-lg border border-orange-100">
                             <h4 className="text-[10px] font-bold text-orange-600 uppercase mb-3">Slub Architecture</h4>
                             <Slider label="Slub Length" value={yarn.slubLength || 5} min={1} max={50} step={0.5} onChange={(v:any)=>handleParamChange('slubLength',v)} subLabel="cm"/>
                             <Slider label="Slub Interval" value={yarn.slubDistance || 10} min={1} max={100} step={0.5} onChange={(v:any)=>handleParamChange('slubDistance',v)} subLabel="cm"/>
                             <Slider label="Slub Amp" value={yarn.slubAmplitude || 150} min={100} max={400} step={5} onChange={(v:any)=>handleParamChange('slubAmplitude',v)} subLabel="%"/>
                        </section>
                    )}

                    <section>
                        <h4 className="text-[10px] font-bold text-purple-600 uppercase mb-3">Surface Rendering</h4>
                        <Slider label="Visual Thickness" value={yarn.thickness} min={0.3} max={2.5} step={0.05} onChange={(v:any)=>handleParamChange('thickness',v)}/>
                        <Slider label="Sheen" value={yarn.sheen} min={0} max={1} step={0.1} onChange={(v:any)=>handleParamChange('sheen',v)}/>
                        <Slider label="Hairiness" value={yarn.hairiness || 0} min={0} max={1} step={0.05} onChange={(v:any)=>handleParamChange('hairiness',v)}/>
                        <Slider label="Roughness" value={yarn.roughness} min={0} max={1} step={0.1} onChange={(v:any)=>handleParamChange('roughness',v)}/>
                    </section>

                    <section className="bg-gray-50 p-4 rounded-lg border border-gray-100">
                        <h4 className="text-[10px] font-bold text-gray-500 uppercase mb-3">Universal Physics</h4>
                        <Slider label="Float Tapering" value={yarn.floatTaper ?? 0.2} min={0} max={0.5} step={0.01} onChange={(v:any)=>handleParamChange('floatTaper',v)}/>
                        <Slider label="Binding Shadow" value={yarn.bindingDepth ?? 0.05} min={0} max={0.2} step={0.01} onChange={(v:any)=>handleParamChange('bindingDepth',v)}/>
                        <Slider label="Shadow Throw" value={yarn.shadowThrow ?? 0.1} min={0} max={2.0} step={0.1} onChange={(v:any)=>handleParamChange('shadowThrow',v)}/>
                    </section>

                    <button onClick={handleSaveToLibrary} className="w-full py-3 bg-gray-900 text-white rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-gray-800 transition-all flex items-center justify-center gap-2"><PlusIcon className="w-4 h-4"/> Save to Presets</button>
                </div>
            </div>
        </div>
    );
};

