import React, { useRef, useEffect, useState, useCallback } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode } from '../types';

interface JacquardCanvasProps {
    data: JacquardData;
    artwork?: {
        data: Uint8Array;
        palette: string[];
        width: number;
        height: number;
    };
    onUpdate: (newData: Uint8Array) => void;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    epi: number;
    ppi: number;
    gridX: number;
    gridY: number;
}

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, artwork, onUpdate, tool, viewMode, faceMode, warpColors, weftColors, epi, ppi, gridX, gridY
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [view, setView] = useState({ x: 40, y: 40, zoom: 1.0 }); 
    const [hoverPos, setHoverPos] = useState({ x: 0, y: 0 });
    const [isSpacePressed, setIsSpacePressed] = useState(false);
    const isInteracting = useRef(false);
    const lastGridPos = useRef({ x: -1, y: -1 });
    const localBuffer = useRef<Uint8Array>(data.structure);

    useEffect(() => {
        localBuffer.current = data.structure;
        render();
    }, [data.structure]);

    const HEADER_SIZE = 24;

    const render = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        if (canvas.width !== w || canvas.height !== h) {
            canvas.width = w; canvas.height = h;
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        const aspect = epi / ppi;
        const cellW = zoom;
        const cellH = zoom * aspect;

        const startX = Math.floor((HEADER_SIZE - view.x) / cellW);
        const startY = Math.floor((HEADER_SIZE - view.y) / cellH);
        const endX = Math.min(data.width, startX + Math.ceil((w - HEADER_SIZE) / cellW) + 1);
        const endY = Math.min(data.height, startY + Math.ceil((h - HEADER_SIZE) / cellH) + 1);

        const isArtworkView = viewMode === 'structure';
        const isReverse = faceMode === 'reverse';
        const buffer = localBuffer.current;

        // 1. Render Design Grid
        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * data.width + x;
                if (isArtworkView && artwork) {
                    ctx.fillStyle = artwork.palette[artwork.data[idx]] || '#000';
                } else {
                    let val = buffer[idx] === 1;
                    if (isReverse) val = !val;
                    ctx.fillStyle = val ? warpColors[x % warpColors.length] : weftColors[y % weftColors.length];
                }
                ctx.fillRect(
                    Math.floor(view.x + x * cellW), 
                    Math.floor(view.y + y * cellH), 
                    Math.ceil(cellW), 
                    Math.ceil(cellH)
                );
            }
        }

        // 2. Render Headers & Hover Indicators
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, w, HEADER_SIZE); 
        ctx.fillRect(0, 0, HEADER_SIZE, h); 

        // Warp Bar
        for (let x = Math.max(0, startX); x < endX; x++) {
            ctx.fillStyle = warpColors[x % warpColors.length] || '#888';
            ctx.fillRect(Math.floor(view.x + x * cellW), 0, Math.ceil(cellW), HEADER_SIZE);
        }
        const wx = Math.floor(view.x + hoverPos.x * cellW);
        if (wx >= HEADER_SIZE && wx < w) {
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(wx, HEADER_SIZE - 4, Math.ceil(cellW), 4);
        }

        // Weft Bar
        for (let y = Math.max(0, startY); y < endY; y++) {
            ctx.fillStyle = weftColors[y % weftColors.length] || '#888';
            ctx.fillRect(0, Math.floor(view.y + y * cellH), HEADER_SIZE, Math.ceil(cellH));
        }
        const wy = Math.floor(view.y + hoverPos.y * cellH);
        if (wy >= HEADER_SIZE && wy < h) {
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(HEADER_SIZE - 4, wy, 4, Math.ceil(cellH));
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, HEADER_SIZE, HEADER_SIZE);
        ctx.strokeStyle = '#334155';
        ctx.strokeRect(0, 0, HEADER_SIZE, HEADER_SIZE);

        // 3. Technical Grid (Activate only at 400% zoom)
        if (zoom >= 4.0) {
            ctx.beginPath();
            // Vertical Lines (Ends)
            for (let x = Math.max(0, startX); x <= endX; x++) {
                const px = view.x + x * cellW;
                const isMajor = x % gridX === 0;
                ctx.strokeStyle = isMajor ? 'rgba(255,255,255,0.3)' : 'rgba(255,255,255,0.08)';
                ctx.lineWidth = isMajor ? 1.5 : 0.5;
                ctx.moveTo(px, HEADER_SIZE);
                ctx.lineTo(px, h);
                ctx.stroke();
                ctx.beginPath();
            }
            // Horizontal Lines (Picks)
            for (let y = Math.max(0, startY); y <= endY; y++) {
                const py = view.y + y * cellH;
                const isMajor = y % gridY === 0;
                ctx.strokeStyle = isMajor ? 'rgba(255,255,255,0.3)' : 'rgba(255,255,255,0.08)';
                ctx.lineWidth = isMajor ? 1.5 : 0.5;
                ctx.moveTo(HEADER_SIZE, py);
                ctx.lineTo(w, py);
                ctx.stroke();
                ctx.beginPath();
            }
        }
    }, [view, viewMode, faceMode, warpColors, weftColors, artwork, hoverPos, data.width, data.height, epi, ppi, gridX, gridY]);

    useEffect(() => { render(); }, [render]);

    useEffect(() => {
        const onDown = (e: KeyboardEvent) => { if (e.code === 'Space') { setIsSpacePressed(true); if (e.target === document.body) e.preventDefault(); } };
        const onUp = (e: KeyboardEvent) => { if (e.code === 'Space') setIsSpacePressed(false); };
        window.addEventListener('keydown', onDown);
        window.addEventListener('keyup', onUp);
        return () => { window.removeEventListener('keydown', onDown); window.removeEventListener('keyup', onUp); };
    }, []);

    const effectiveTool = isSpacePressed ? 'pan' : tool;

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;
        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const zoomStep = 0.25;
            const direction = wheelEv.deltaY > 0 ? -1 : 1;
            const newZoom = Math.min(128, Math.max(0.5, view.zoom + direction * zoomStep));

            if (newZoom !== view.zoom) {
                const aspect = epi / ppi;
                const worldX = (mouseX - view.x) / view.zoom;
                const worldY = (mouseY - view.y) / (view.zoom * aspect);
                setView({ x: mouseX - worldX * newZoom, y: mouseY - worldY * (newZoom * aspect), zoom: newZoom });
            }
            return;
        }

        const aspect = epi / ppi;
        const gridX = Math.floor((mouseX - view.x) / view.zoom);
        const gridY = Math.floor((mouseY - view.y) / (view.zoom * aspect));

        if (e.type === 'mousemove') {
            setHoverPos({ x: Math.max(0, Math.min(data.width - 1, gridX)), y: Math.max(0, Math.min(data.height - 1, gridY)) });
        }

        if (effectiveTool === 'pan') {
            if (e.type === 'mousedown') { isInteracting.current = true; lastGridPos.current = { x: mouseX, y: mouseY }; }
            else if (e.type === 'mousemove' && isInteracting.current) {
                setView(prev => ({ ...prev, x: prev.x + (mouseX - lastGridPos.current.x), y: prev.y + (mouseY - lastGridPos.current.y) }));
                lastGridPos.current = { x: mouseX, y: mouseY };
            } else { isInteracting.current = false; }
            return;
        }

        if (e.type === 'mousedown') {
            isInteracting.current = true;
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height) {
                localBuffer.current[gridY * data.width + gridX] = localBuffer.current[gridY * data.width + gridX] === 1 ? 0 : 1;
                lastGridPos.current = { x: gridX, y: gridY }; render();
            }
        } else if (e.type === 'mousemove' && isInteracting.current) {
            if (gridX >= 0 && gridX < data.width && gridY >= 0 && gridY < data.height && (gridX !== lastGridPos.current.x || gridY !== lastGridPos.current.y)) {
                localBuffer.current[gridY * data.width + gridX] = 1; lastGridPos.current = { x: gridX, y: gridY }; render();
            }
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            if (isInteracting.current) { isInteracting.current = false; onUpdate(new Uint8Array(localBuffer.current)); }
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden select-none relative">
            <canvas ref={canvasRef} onMouseDown={handleInteraction} onMouseMove={handleInteraction} onMouseUp={handleInteraction} onMouseLeave={handleInteraction} onWheel={handleInteraction} className="block" />
            <div className="absolute bottom-4 left-4 flex gap-2 pointer-events-none">
                <div className="bg-black/80 px-3 py-1 rounded text-[10px] font-mono text-blue-400 border border-blue-900/50 uppercase tracking-tighter flex items-center gap-4 shadow-xl">
                    <span>{effectiveTool.toUpperCase()} | {Math.round(view.zoom * 100)}%</span>
                    <span className="text-gray-400 border-l border-gray-800 pl-4">WARP (HOOKS): <span className="text-white font-bold">{hoverPos.x + 1}</span> | WEFT (PICKS): <span className="text-white font-bold">{hoverPos.y + 1}</span></span>
                </div>
            </div>
            {isSpacePressed && <div className="absolute inset-0 bg-white/5 pointer-events-none flex items-center justify-center"><div className="bg-black/50 text-white px-4 py-2 rounded-full font-bold text-xs uppercase tracking-widest shadow-2xl border border-white/20">Pan Enabled (Space)</div></div>}
        </div>
    );
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { TopToolbar } from './TopToolbar';
