                            <SliderInput label="Picks Repeat" value={settings.weftPicks} onChange={(v) => onSettingsChange({ ...settings, weftPicks: v })} onPointerDown={onSnapshot} min={4} max={1024} step={4} />

                            <div className="h-px bg-gray-100 my-6" />
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Loom Settings</h3>
                            <SliderInput label="EPI" value={settings.epi} onChange={(v) => onSettingsChange({ ...settings, epi: v })} onPointerDown={onSnapshot} min={8} max={160} step={1} />
                            <SliderInput label="PPI" value={settings.ppi} onChange={(v) => onSettingsChange({ ...settings, ppi: v })} onPointerDown={onSnapshot} min={8} max={160} step={1} />

                            <div className="h-px bg-gray-100 my-6" />
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Grid Specifications</h3>
                            <div className="grid grid-cols-2 gap-4">
                                <SliderInput label="Grid X" value={settings.gridX} onChange={(v) => onSettingsChange({ ...settings, gridX: v })} min={2} max={16} step={1} />
                                <SliderInput label="Grid Y" value={settings.gridY} onChange={(v) => onSettingsChange({ ...settings, gridY: v })} min={2} max={16} step={1} />
                            </div>

                            <button onClick={onSimulate} className="w-full py-3 mt-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-bold shadow-sm transition-colors">Simulate Fabric</button>
                        </div>
                    )}

                    {activeTab === 'weave' && (
