import React, { useEffect, useRef } from 'react';
import { LibraryWeave } from '../services/weaveLibrary';

interface WeaveThumbnailProps {
  weave: LibraryWeave;
  className?: string;
  faceMode?: 'face' | 'back';
}

export const WeaveThumbnail: React.FC<WeaveThumbnailProps> = ({ weave, className, faceMode = 'face' }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { draft, pegPlan } = weave;
    const harnesses = draft.length;
    const width = draft[0].length;
    const height = pegPlan.length;

    // Fixed scale for consistent library visuals
    const scale = Math.min(16, Math.floor(160 / Math.max(width, height)));

    canvas.width = width * scale;
    canvas.height = height * scale;

    // Use a deep background for high contrast
    ctx.fillStyle = '#0a0a0a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const warpToHarness = new Array(width).fill(-1);
    for(let w=0; w<width; w++) {
        for(let h=0; h<harnesses; h++) {
            if(draft[h][w] === 1) {
                warpToHarness[w] = h;
                break;
            }
        }
    }

    for(let y=0; y<height; y++) {
        for(let x=0; x<width; x++) {
            const harness = warpToHarness[x];
            let isWarpUp = false;
            if(harness !== -1 && pegPlan[y] && pegPlan[y][harness] === 1) {
                isWarpUp = true;
            }

            // Invert logic for back side
            if (faceMode === 'back') isWarpUp = !isWarpUp;

            if (isWarpUp) {
                ctx.fillStyle = '#f8fafc'; // Clean white for warp
                ctx.fillRect(x*scale, y*scale, scale, scale);
            }
        }
    }

    // Technical grid overlay for the thumbnail
    if (scale > 4) {
        ctx.strokeStyle = 'rgba(255,255,255,0.05)';
        ctx.lineWidth = 1;
        for(let i=0; i<=width; i++) {
            ctx.beginPath();
            ctx.moveTo(i*scale, 0); ctx.lineTo(i*scale, canvas.height);
            ctx.stroke();
        }
        for(let i=0; i<=height; i++) {
            ctx.beginPath();
            ctx.moveTo(0, i*scale); ctx.lineTo(canvas.width, i*scale);
            ctx.stroke();
        }
    }

  }, [weave, faceMode]);

  return (
    <div className={`bg-gray-950 rounded-lg border border-gray-800 flex items-center justify-center overflow-hidden group-hover:border-blue-500/50 transition-colors ${className}`}>
        <canvas ref={canvasRef} className="image-pixelated max-w-full max-h-full" />
    </div>
  );
};

