selectedYarnType} onSelectYarn={(id, type) => { handleYarnSelect(id, type); setCurrentTool('brush'); }} onActiveYarnChange={(id) => { setActiveYarnId(id); setCurrentTool('brush'); }} forcedTab={rightPanelTab as any} onSyncGridDimensions={handleSyncGrid} />
