type TabType = 'construction' | 'pattern' | 'weave' | 'yarns' | 'colors';

const TabButton: React.FC<{ id: TabType, activeTab: TabType, icon: React.ReactNode, label: string, onClick: (id: TabType) => void }> = ({ id, activeTab, icon, label, onClick }) => (
    <button
        onClick={() => onClick(id)}
        className={`flex-1 flex flex-col items-center justify-center py-3 gap-1 border-b-2 transition-colors ${activeTab === id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
    >
        {icon}
        <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
    </button>
);

const SliderInput: React.FC<{
    label: string; value: number; onChange?: (value: number) => void; min?: number; max?: number; step?: number; subLabel?: string; disabled?: boolean; onPointerDown?: () => void;
}> = ({ label, value, onChange, min, max, step, subLabel, disabled, onPointerDown }) => (
    <div className="mb-5">
        <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex justify-between">
            <span>{label} {subLabel && <span className="text-gray-400 normal-case ml-1">({subLabel})</span>}</span>
            <span className={`${disabled ? 'text-gray-500' : 'text-blue-600'} font-mono`}>{value}</span>
        </label>
        {!disabled && (
            <input
                type="range" min={min} max={max} step={step} value={value}
                onChange={(e) => onChange && onChange(parseInt(e.target.value, 10))}
                onPointerDown={onPointerDown}
                className="w-full h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600 hover:accent-blue-500"
            />
        )}
    </div>
);

const YarnList: React.FC<{ 
    yarns: {[key: string]: YarnDefinition}, 
    type: 'warp' | 'weft',
    activeId?: string,
    isSelectedType?: boolean,
    onSelect?: (id: string, type: 'warp' | 'weft') => void,
    onEdit: (char: string, def: YarnDefinition) => void,
    onAssignColor: (char: string) => void, 
    onDropYarn: (sourceId: string, sourceType: 'warp' | 'weft', targetId: string) => void,
    label: string 
}> = ({ yarns, type, activeId, isSelectedType, onSelect, onEdit, onAssignColor, onDropYarn, label }) => {
    const letters = ['A','B','C','D','E','F','G','H'];
    const [dragOverId, setDragOverId] = useState<string | null>(null);

    return (
        <div className="mb-4">
            <h2 className="text-sm font-bold text-gray-900 mb-2">{label}</h2>
            <div className="flex flex-col gap-2">
                {letters.map((char) => {
                    const yarn = yarns[char];
                    const isSelected = isSelectedType && activeId === char;
                    const isDragOver = dragOverId === char;

                    if (!yarn) {
                        return (
                            <div 
                                key={char} 
                                className={`flex items-center gap-3 p-2 rounded-md border border-dashed hover:bg-blue-50 transition-all cursor-pointer opacity-60 hover:opacity-100 ${isSelected ? 'border-blue-500 bg-blue-50' : (isDragOver ? 'border-blue-400 bg-blue-50 ring-2 ring-blue-100' : 'border-gray-300 hover:border-blue-400')}`}
                                onClick={() => {
                                    const defaultDef: YarnDefinition = { 
                                        color: '#CCCCCC', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 28, ply: 1, thickness: 1.0, twist: 'Z', tpi: 15, sheen: 0.5, roughness: 0.5, price: 0, bindingDepth: 0.05
                                    };
                                    onEdit(char, defaultDef);
                                    onSelect && onSelect(char, type);
                                }}
                                onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                                onDragLeave={() => setDragOverId(null)}
                                onDrop={(e) => { e.preventDefault(); setDragOverId(null); const d = e.dataTransfer.getData('yarn-id'), s = e.dataTransfer.getData('yarn-type') as any; if (d) onDropYarn(d, s, char); }}
                            >
                                <div className="font-mono font-bold text-gray-400 w-4">{char}</div>
                                <div className="text-[10px] text-gray-400 font-medium">Initialize Yarn</div>
                            </div>
                        );
                    }

                    return (
                        <div 
                            key={char} 
                            draggable
                            onDragStart={(e) => { e.dataTransfer.setData('yarn-id', char); e.dataTransfer.setData('yarn-type', type); }}
                            onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                            onDragLeave={() => setDragOverId(null)}
                            onDrop={(e) => { e.preventDefault(); setDragOverId(null); const d = e.dataTransfer.getData('yarn-id'), s = e.dataTransfer.getData('yarn-type') as any; if (d) onDropYarn(d, s, char); }}
                            onClick={() => onSelect && onSelect(char, type)}
                            className={`flex items-center gap-3 p-2 rounded-md border transition-all cursor-pointer ${isSelected ? 'bg-gray-100 border-gray-400' : (isDragOver ? 'border-blue-400 bg-blue-50' : 'border-gray-200 hover:bg-gray-50')}`}
                        >
                            <div className="font-mono font-bold w-4">{char}</div>
                            <div className="flex-1">
                                <div className="h-3 rounded-full mb-1" style={{ background: yarn.color }} />
                                <div className="flex justify-between items-center"><span className="text-[10px] text-gray-500 font-medium truncate">{yarn.fiberType}</span></div>
                            </div>
                            <button onClick={(e) => { e.stopPropagation(); onEdit(char, yarn); }} className="w-7 h-7 flex items-center justify-center rounded-full border border-gray-200 text-gray-400 hover:text-blue-500"><PencilIcon className="w-3 h-3" /></button>
                        </div>
                    )
                })}
            </div>
        </div>
    );
}

/**
 * Sub-component for individual weaves in the library list with Face/Back toggles
 */
const LibraryItem: React.FC<{ 
    weave: LibraryWeave; 
    onSnapshot: () => void; 
    onLoadWeave: (w: LibraryWeave) => void;
}> = ({ weave, onSnapshot, onLoadWeave }) => {
    const [faceMode, setFaceMode] = useState<'face' | 'back'>('face');

    const handleApply = () => {
        onSnapshot();
        if (faceMode === 'back') {
            const inverted = {
                ...weave,
                name: `${weave.name} (Back)`,
                pegPlan: weave.pegPlan.map(row => row.map(cell => cell === 1 ? 0 : 1))
            };
            onLoadWeave(inverted);
        } else {
            onLoadWeave(weave);
        }
    };

    const handleDragStart = (e: React.DragEvent) => {
        let dragObj = { ...weave };
        if (faceMode === 'back') {
            dragObj.pegPlan = weave.pegPlan.map(row => row.map(cell => cell === 1 ? 0 : 1));
            dragObj.name = `${weave.name} (Back)`;
        }
        e.dataTransfer.setData('weave-obj', JSON.stringify(dragObj));
    };

    return (
        <div className="relative group">
            <button 
                draggable 
                onDragStart={handleDragStart} 
                onClick={handleApply} 
                className="flex flex-col items-start p-2 bg-gray-50 border hover:border-blue-500 hover:bg-blue-50 rounded-lg transition-all text-left w-full cursor-grab overflow-hidden"
            >
                <div className="relative w-full aspect-square mb-2 pointer-events-none">
                    <WeaveThumbnail weave={weave} faceMode={faceMode} className="w-full h-full" />
                    {faceMode === 'back' && (
                        <div className="absolute top-1 right-1 bg-orange-600 text-[7px] font-bold px-1 py-0.5 rounded uppercase tracking-tighter text-white z-10 shadow-sm">
                            Back
                        </div>
                    )}
                </div>
                <span className="text-[10px] font-bold text-gray-700 truncate w-full uppercase leading-tight">{weave.name}</span>
            </button>

            {/* Floating Flip Toggle */}
            <button 
                onClick={(e) => { e.stopPropagation(); setFaceMode(faceMode === 'face' ? 'back' : 'face'); }}
                className={`absolute top-1 right-1 p-1 rounded shadow-md transition-all opacity-0 group-hover:opacity-100 z-20 ${faceMode === 'back' ? 'bg-orange-500 text-white' : 'bg-white/90 text-gray-400 hover:text-blue-500'}`}
                title={`Toggle to ${faceMode === 'face' ? 'Back' : 'Face'}`}
            >
                <FlipIcon className="w-3 h-3" />
            </button>
        </div>
    );
};

