                            <SliderInput label="Picks Repeat" value={settings.weftPicks} onChange={(v) => onSettingsChange({ ...settings, weftPicks: v })} onPointerDown={onSnapshot} min={4} max={1024} step={4} />

                            <div className="h-px bg-gray-100 my-6" />
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Loom Densities</h3>
                            <SliderInput label="EPI" value={settings.epi} onChange={(v) => onSettingsChange({ ...settings, epi: v })} onPointerDown={onSnapshot} min={8} max={160} step={1} />
                            <SliderInput label="PPI" value={settings.ppi} onChange={(v) => onSettingsChange({ ...settings, ppi: v })} onPointerDown={onSnapshot} min={8} max={160} step={1} />

                            <div className="h-px bg-gray-100 my-6" />
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Grid Setup</h3>
                            <div className="grid grid-cols-2 gap-4">
                                <SliderInput label="Grid X" value={settings.gridX} onChange={(v) => onSettingsChange({ ...settings, gridX: v })} min={2} max={32} step={1} />
                                <SliderInput label="Grid Y" value={settings.gridY} onChange={(v) => onSettingsChange({ ...settings, gridY: v })} min={2} max={32} step={1} />
                            </div>

                            <button onClick={onSimulate} className="w-full py-3 mt-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-bold shadow-sm transition-colors uppercase tracking-widest text-xs">Simulate Realistic</button>
                        </div>
                    )}

                    {activeTab === 'weave' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <h2 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Structure Library</h2>

                            <div className="grid grid-cols-2 gap-3">
                                {allWeaves.map(weave => (
                                    <LibraryItem 
                                        key={weave.id} 
                                        weave={weave} 
                                        onSnapshot={onSnapshot} 
                                        onLoadWeave={onLoadWeave} 
                                    />
                                ))}
                            </div>
                        </div>
                    )}

                    {activeTab === 'pattern' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200 flex flex-col gap-6">
                            <TextPatternEditor title="Warp Pattern" value={warpPatternString} onValueChange={setWarpPatternString} colorMap={warpColorMap} onFocus={onSnapshot} />
                            <TextPatternEditor title="Weft Pattern" value={weftPatternString} onValueChange={setWeftPatternString} colorMap={weftColorMap} onFocus={onSnapshot} />
                            <AiControl currentInput={currentInput} settings={settings} onApplyGenerated={onApplyGenerated} />
                        </div>
                    )}

                    {activeTab === 'yarns' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <YarnList yarns={warpYarns} type="warp" activeId={activeYarnId} isSelectedType={selectedYarnType === 'warp'} onSelect={onSelectYarn} onEdit={(id, def) => setEditingYarn({ id, type: 'warp', def })} onAssignColor={(id) => {}} onDropYarn={(s, st, t) => {}} label="Warp Registry" />
                            <YarnList yarns={weftYarns} type="weft" activeId={activeYarnId} isSelectedType={selectedYarnType === 'weft'} onSelect={onSelectYarn} onEdit={(id, def) => setEditingYarn({ id, type: 'weft', def })} onAssignColor={(id) => {}} onDropYarn={(s, st, t) => {}} label="Weft Registry" />
                        </div>
                    )}

                    {activeTab === 'colors' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <div className="grid grid-cols-6 gap-2">
                                {paletteColors.map((color, idx) => (
                                    <div key={idx} className={`relative cursor-pointer p-0.5 rounded ${idx === selectedColorIndex ? 'ring-2 ring-blue-500' : ''}`} onClick={() => onSelectColor?.(idx)}>
                                        <div className="w-full aspect-square rounded border border-gray-200" style={{backgroundColor: color}} />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {editingYarn && (
                <YarnDesignerModal 
                    isOpen={!!editingYarn} onClose={() => setEditingYarn(null)} yarnId={editingYarn.id} yarnType={editingYarn.type} initialYarn={editingYarn.def}
                    onSave={(newYarn) => { onSnapshot(); if (editingYarn.type === 'warp') onUpdateWarpYarn(editingYarn.id, newYarn); else onUpdateWeftYarn(editingYarn.id, newYarn); }}
                />
            )}
        </>
    );
};

import { YarnDefinition, DensityZone, WeaveSettings } from '../../types';

