    <button
        onClick={() => onClick(id)}
        className={`flex-1 flex flex-col items-center justify-center py-3 gap-1 border-b-2 transition-colors ${activeTab === id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
    >
        {icon}
        <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
    </button>
);

const SliderInput: React.FC<{
    label: string; value: number; onChange?: (value: number) => void; min?: number; max?: number; step?: number; subLabel?: string; disabled?: boolean; onPointerDown?: () => void;
}> = ({ label, value, onChange, min, max, step, subLabel, disabled, onPointerDown }) => (
    <div className="mb-5">
        <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex justify-between">
            <span>{label} {subLabel && <span className="text-gray-400 normal-case ml-1">({subLabel})</span>}</span>
            <span className={`${disabled ? 'text-gray-500' : 'text-blue-600'} font-mono`}>{value}</span>
        </label>
        {!disabled && (
            <input
                type="range" min={min} max={max} step={step} value={value}
                onChange={(e) => onChange && onChange(parseInt(e.target.value, 10))}
                onPointerDown={onPointerDown}
                className="w-full h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600 hover:accent-blue-500"
            />
        )}
    </div>
);

const YarnList: React.FC<{ 
    yarns: {[key: string]: YarnDefinition}, 
    type: 'warp' | 'weft',
    activeId?: string,
    isSelectedType?: boolean,
    onSelect?: (id: string, type: 'warp' | 'weft') => void,
    onEdit: (char: string, def: YarnDefinition) => void,
    onAssignColor: (char: string) => void, 
    onDropYarn: (sourceId: string, sourceType: 'warp' | 'weft', targetId: string) => void,
    label: string 
}> = ({ yarns, type, activeId, isSelectedType, onSelect, onEdit, onAssignColor, onDropYarn, label }) => {
    const letters = ['A','B','C','D','E','F','G','H'];
    const [dragOverId, setDragOverId] = useState<string | null>(null);

    return (
        <div className="mb-4">
            <h2 className="text-sm font-bold text-gray-900 mb-2">{label}</h2>
            <div className="flex flex-col gap-2">
                {letters.map((char) => {
                    const yarn = yarns[char];
                    const isSelected = isSelectedType && activeId === char;
                    const isDragOver = dragOverId === char;

                    if (!yarn) {
                        return (
                            <div 
                                key={char} 
                                className={`flex items-center gap-3 p-2 rounded-md border border-dashed hover:bg-blue-50 transition-all cursor-pointer opacity-60 hover:opacity-100 ${isSelected ? 'border-blue-500 bg-blue-50' : (isDragOver ? 'border-blue-400 bg-blue-50 ring-2 ring-blue-100' : 'border-gray-300 hover:border-blue-400')}`}
                                onClick={() => {
                                    const defaultDef: YarnDefinition = { 
                                        color: '#CCCCCC', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 28, ply: 1, thickness: 1.0, twist: 'Z', tpi: 15, sheen: 0.5, roughness: 0.5, price: 0, bindingDepth: 0.05
                                    };
                                    onEdit(char, defaultDef);
                                    onSelect && onSelect(char, type);
                                }}
                                onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                                onDragLeave={() => setDragOverId(null)}
                                onDrop={(e) => { e.preventDefault(); setDragOverId(null); const d = e.dataTransfer.getData('yarn-id'), s = e.dataTransfer.getData('yarn-type') as any; if (d) onDropYarn(d, s, char); }}
                            >
                                <div className="font-mono font-bold text-gray-400 w-4">{char}</div>
                                <div className="text-[10px] text-gray-400 font-medium">Initialize Yarn</div>
                            </div>
                        );
                    }

                    return (
                        <div 
                            key={char} 
                            draggable
                            onDragStart={(e) => { e.dataTransfer.setData('yarn-id', char); e.dataTransfer.setData('yarn-type', type); }}
                            onDragOver={(e) => { e.preventDefault(); setDragOverId(char); }}
                            onDragLeave={() => setDragOverId(null)}
                            onDrop={(e) => { e.preventDefault(); setDragOverId(null); const d = e.dataTransfer.getData('yarn-id'), s = e.dataTransfer.getData('yarn-type') as any; if (d) onDropYarn(d, s, char); }}
                            onClick={() => onSelect && onSelect(char, type)}
                            className={`flex items-center gap-3 p-2 rounded-md border transition-all cursor-pointer ${isSelected ? 'bg-gray-100 border-gray-400' : (isDragOver ? 'border-blue-400 bg-blue-50' : 'border-gray-200 hover:bg-gray-50')}`}
                        >
                            <div className="font-mono font-bold w-4">{char}</div>
                            <div className="flex-1">
                                <div className="h-3 rounded-full mb-1" style={{ background: yarn.color }} />
                                <div className="flex justify-between items-center"><span className="text-[10px] text-gray-500 font-medium truncate">{yarn.fiberType}</span></div>
                            </div>
                            <button onClick={(e) => { e.stopPropagation(); onEdit(char, yarn); }} className="w-7 h-7 flex items-center justify-center rounded-full border border-gray-200 text-gray-400 hover:text-blue-500"><PencilIcon className="w-3 h-3" /></button>
                        </div>
                    )
                })}
            </div>
        </div>
    );
}

/**
 * Sub-component for individual weaves in the library list with advanced controls
 */
const LibraryItem: React.FC<{ 
    weave: LibraryWeave; 
    onSnapshot: () => void; 
    onLoadWeave: (w: LibraryWeave) => void;
    layout: '1' | '2' | '3';
}> = ({ weave, onSnapshot, onLoadWeave, layout }) => {
    const [faceMode, setFaceMode] = useState<'face' | 'back'>('face');
    const [offsetX, setOffsetX] = useState(0);
    const [offsetY, setOffsetY] = useState(0);

    // Apply local transformations to the base library weave
    const getTransformedWeave = useCallback(() => {
        let transformed = { ...weave };

        // 1. Structural Shifts
        if (offsetX !== 0 || offsetY !== 0) {
            const h = transformed.pegPlan.length;
            const w = transformed.pegPlan[0].length;

            // Shift rows
            let nextPeg = transformed.pegPlan.map(r => [...r]);
            const shiftY = ((offsetY % h) + h) % h;
            if (shiftY > 0) {
                nextPeg = [...nextPeg.slice(h - shiftY), ...nextPeg.slice(0, h - shiftY)];
            }

            // Shift cols
            const shiftX = ((offsetX % w) + w) % w;
            if (shiftX > 0) {
                nextPeg = nextPeg.map(row => [...row.slice(w - shiftX), ...row.slice(0, w - shiftX)]);
            }

            transformed.pegPlan = nextPeg;

            // Shift Draft (only affects visual matching in full sim)
            const dH = transformed.draft.length;
            const dW = transformed.draft[0].length;
            const dShiftX = ((offsetX % dW) + dW) % dW;
            if (dShiftX > 0) {
                transformed.draft = transformed.draft.map(row => [...row.slice(dW - dShiftX), ...row.slice(0, dW - dShiftX)]);
            }
        }

        // 2. Face Inversion
        if (faceMode === 'back') {
            transformed.name = `${weave.name} (Back)`;
            transformed.pegPlan = transformed.pegPlan.map(row => row.map(cell => cell === 1 ? 0 : 1));
        }

        return transformed;
    }, [weave, offsetX, offsetY, faceMode]);

    const handleApply = () => {
        onSnapshot();
        onLoadWeave(getTransformedWeave());
    };

    const handleDragStart = (e: React.DragEvent) => {
        e.dataTransfer.setData('weave-obj', JSON.stringify(getTransformedWeave()));
    };

    const transformedWeave = getTransformedWeave();

    return (
        <div className={`relative group ${layout === '3' ? 'bg-white border rounded-xl shadow-sm hover:shadow-md transition-all overflow-hidden mb-2' : ''}`}>
            {layout === '3' ? (
                <div className="flex flex-col">
                    {/* Visual Area */}
                    <div className="relative aspect-video bg-gray-950 group/preview cursor-grab" draggable onDragStart={handleDragStart} onClick={handleApply}>
                        <WeaveThumbnail weave={transformedWeave} faceMode="face" className="w-full h-full border-none rounded-none" />
                        <div className="absolute inset-0 bg-black/0 group-hover/preview:bg-black/10 transition-colors flex items-center justify-center">
                            <span className="opacity-0 group-hover/preview:opacity-100 bg-white/90 text-gray-900 text-[10px] font-bold px-3 py-1 rounded-full shadow-lg uppercase tracking-widest pointer-events-none transition-all transform translate-y-2 group-hover/preview:translate-y-0">
                                Drag to Canvas
                            </span>
                        </div>
                        {faceMode === 'back' && (
                            <div className="absolute top-2 left-2 bg-orange-600 text-[7px] font-bold px-1.5 py-0.5 rounded uppercase tracking-tighter text-white z-10 shadow-sm">
                                Reverse View
                            </div>
                        )}
                    </div>

                    {/* Content & Metadata */}
                    <div className="p-3 border-t border-gray-100 bg-white">
                        <div className="flex justify-between items-start mb-2">
                            <div className="min-w-0">
                                <h3 className="font-bold text-gray-800 text-xs truncate uppercase tracking-tight">{weave.name}</h3>
                                <span className="text-[8px] text-gray-400 font-bold uppercase tracking-widest mt-0.5 block">{weave.category} • {weave.harnesses}H</span>
                            </div>
                            <div className="flex gap-1">
                                <button 
                                    onClick={() => setFaceMode(faceMode === 'face' ? 'back' : 'face')}
                                    className={`p-1.5 rounded-md transition-all border ${faceMode === 'back' ? 'bg-orange-50 border-orange-200 text-orange-600' : 'bg-gray-50 border-gray-200 text-gray-400 hover:text-blue-600'}`}
                                    title="Toggle Face/Back"
                                >
                                    <FlipIcon className="w-3.5 h-3.5" />
                                </button>
                            </div>
                        </div>

                        {/* Shift Controls Grid */}
                        <div className="flex items-center gap-3 pt-2 mt-2 border-t border-gray-50">
                            <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest mr-auto">Structural Alignment</span>

                            <div className="flex items-center gap-1 bg-gray-50 p-1 rounded-lg border border-gray-100">
                                <button onClick={() => setOffsetX(prev => prev - 1)} className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Left"><ShiftLeftIcon className="w-3 h-3"/></button>
                                <button onClick={() => setOffsetX(prev => prev + 1)} className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Right"><ShiftRightIcon className="w-3 h-3"/></button>
                                <div className="w-px h-3 bg-gray-200 mx-1"></div>
                                <button onClick={() => setOffsetY(prev => prev - 1)} className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Up"><ShiftUpIcon className="w-3 h-3"/></button>
                                <button onClick={() => setOffsetY(prev => prev + 1)} className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Down"><ShiftDownIcon className="w-3 h-3"/></button>
                            </div>

                            <button onClick={() => {setOffsetX(0); setOffsetY(0); setFaceMode('face');}} className="p-1.5 text-[8px] font-bold text-gray-400 hover:text-red-500 uppercase tracking-tighter" title="Reset Transforms">Reset</button>
                        </div>
                    </div>
                </div>
            ) : (
                <>
                    <button 
                        draggable 
                        onDragStart={handleDragStart} 
                        onClick={handleApply} 
                        className={`flex ${layout === '1' ? 'flex-row items-center' : 'flex-col items-start'} p-2 bg-gray-50 border hover:border-blue-500 hover:bg-blue-50 rounded-lg transition-all text-left w-full cursor-grab overflow-hidden gap-3`}
