                                <div className="flex justify-between items-center"><span className="text-[10px] text-gray-500 font-medium truncate">{yarn.fiberType}</span></div>
                            </div>
                            <button onClick={(e) => { e.stopPropagation(); onEdit(char, yarn); }} className="w-7 h-7 flex items-center justify-center rounded-full border border-gray-200 text-gray-400 hover:text-blue-500"><PencilIcon className="w-3 h-3" /></button>
                        </div>
                    )
                })}
            </div>
        </div>
    );
}

/**
 * Sub-component for individual weaves in the library list with advanced controls
 */
const LibraryItem: React.FC<{ 
    weave: LibraryWeave; 
    onSnapshot: () => void; 
    onLoadWeave: (w: LibraryWeave) => void;
    layout: '1' | '2' | '3';
}> = ({ weave, onSnapshot, onLoadWeave, layout }) => {
    const [faceMode, setFaceMode] = useState<'face' | 'back'>('face');
    const [offsetX, setOffsetX] = useState(0);
    const [offsetY, setOffsetY] = useState(0);

    // Apply local transformations to the base library weave
    const getTransformedWeave = useCallback(() => {
        let transformed = { ...weave };

        // Structural Shifts
        // FIXED: Horizontal shift (X) now only affects the harness lift map (pegPlan columns) 
        // to avoid "double jumping" by shifting both draft and peg.
        if (offsetX !== 0 || offsetY !== 0) {
            const h = transformed.pegPlan.length;
            const w = transformed.pegPlan[0].length;

            // Shift rows (Vertical)
            let nextPeg = transformed.pegPlan.map(r => [...r]);
            const shiftY = ((offsetY % h) + h) % h;
            if (shiftY > 0) {
                nextPeg = [...nextPeg.slice(h - shiftY), ...nextPeg.slice(0, h - shiftY)];
            }

            // Shift harness assignments in peg plan (Horizontal visual shift)
            const shiftX = ((offsetX % w) + w) % w;
            if (shiftX > 0) {
                nextPeg = nextPeg.map(row => [...row.slice(w - shiftX), ...row.slice(0, w - shiftX)]);
            }

            transformed.pegPlan = nextPeg;
        }

        // Face Inversion
        if (faceMode === 'back') {
            transformed.name = `${weave.name} (Back)`;
            transformed.pegPlan = transformed.pegPlan.map(row => row.map(cell => cell === 1 ? 0 : 1));
        }

        return transformed;
    }, [weave, offsetX, offsetY, faceMode]);

    const handleApply = () => {
        onSnapshot();
        onLoadWeave(getTransformedWeave());
    };

    const handleDragStart = (e: React.DragEvent) => {
        e.dataTransfer.setData('weave-obj', JSON.stringify(getTransformedWeave()));
    };

    const handleShift = (e: React.MouseEvent, type: 'x' | 'y', val: number) => {
        e.stopPropagation();
        e.preventDefault();
        if (type === 'x') setOffsetX(prev => prev + val);
        else setOffsetY(prev => prev + val);
    };

    const transformedWeave = getTransformedWeave();

    return (
        <div className={`relative group ${layout === '3' ? 'bg-white border rounded-xl shadow-sm hover:shadow-md transition-all overflow-hidden mb-2' : ''}`}>
            {layout === '3' ? (
                <div className="flex flex-col">
                    {/* Visual Area */}
                    <div className="relative aspect-video bg-gray-950 group/preview cursor-grab" draggable onDragStart={handleDragStart} onClick={handleApply}>
                        <WeaveThumbnail 
                            weave={transformedWeave} 
                            faceMode="face" 
                            showGrid={true} 
                            className="w-full h-full border-none rounded-none" 
                        />
                        <div className="absolute inset-0 bg-black/0 group-hover/preview:bg-black/10 transition-colors flex items-center justify-center">
                            <span className="opacity-0 group-hover/preview:opacity-100 bg-white/90 text-gray-900 text-[10px] font-bold px-3 py-1 rounded-full shadow-lg uppercase tracking-widest pointer-events-none transition-all transform translate-y-2 group-hover/preview:translate-y-0">
                                Drag to Canvas
                            </span>
                        </div>
                        {faceMode === 'back' && (
                            <div className="absolute top-2 left-2 bg-orange-600 text-[7px] font-bold px-1.5 py-0.5 rounded uppercase tracking-tighter text-white z-10 shadow-sm">
                                Reverse View
                            </div>
                        )}
                    </div>

                    {/* Content & Metadata */}
                    <div className="p-3 border-t border-gray-100 bg-white">
                        <div className="flex justify-between items-start mb-2">
                            <div className="min-w-0">
                                <h3 className="font-bold text-gray-800 text-xs truncate uppercase tracking-tight">{weave.name}</h3>
                                <span className="text-[8px] text-gray-400 font-bold uppercase tracking-widest mt-0.5 block">{weave.category} • {weave.harnesses}H</span>
                            </div>
                            <div className="flex gap-1">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); setFaceMode(faceMode === 'face' ? 'back' : 'face'); }}
                                    className={`p-1.5 rounded-md transition-all border ${faceMode === 'back' ? 'bg-orange-50 border-orange-200 text-orange-600' : 'bg-gray-50 border-gray-200 text-gray-400 hover:text-blue-600'}`}
                                    title="Toggle Face/Back"
                                >
                                    <FlipIcon className="w-4 h-4" />
                                </button>
                            </div>
                        </div>

                        {/* Shift Controls Grid */}
                        <div className="flex items-center justify-between pt-2 mt-2 border-t border-gray-50">
                            <div className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-lg border border-gray-100">
                                <button onClick={(e) => handleShift(e, 'x', -1)} className="p-2 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Left"><ShiftLeftIcon className="w-5 h-5"/></button>
                                <button onClick={(e) => handleShift(e, 'x', 1)} className="p-2 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Right"><ShiftRightIcon className="w-5 h-5"/></button>
                                <div className="w-px h-6 bg-gray-200 mx-1"></div>
                                <button onClick={(e) => handleShift(e, 'y', -1)} className="p-2 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Up"><ShiftUpIcon className="w-5 h-5"/></button>
                                <button onClick={(e) => handleShift(e, 'y', 1)} className="p-2 text-gray-400 hover:text-blue-600 hover:bg-white rounded transition-all" title="Shift Down"><ShiftDownIcon className="w-5 h-5"/></button>
                            </div>

                            <button onClick={(e) => { e.stopPropagation(); setOffsetX(0); setOffsetY(0); setFaceMode('face');}} className="p-2 text-[10px] font-bold text-gray-400 hover:text-red-500 uppercase tracking-tighter" title="Reset Transforms">Reset</button>
                        </div>
                    </div>
                </div>
            ) : (
                <>
                    <button 
                        draggable 
                        onDragStart={handleDragStart} 
                        onClick={handleApply} 
                        className={`flex ${layout === '1' ? 'flex-row items-center' : 'flex-col items-start'} p-2 bg-gray-50 border hover:border-blue-500 hover:bg-blue-50 rounded-lg transition-all text-left w-full cursor-grab overflow-hidden gap-3`}
                    >
                        <div className={`relative shrink-0 ${layout === '1' ? 'w-12 h-12' : 'w-full aspect-square'} pointer-events-none`}>
                            <WeaveThumbnail 
                                weave={transformedWeave} 
                                faceMode="face" 
                                showGrid={false}
                                tile={layout === '2'}
                                forceScale={layout === '2' ? 8 : undefined}
                                className="w-full h-full" 
                            />
                            {faceMode === 'back' && (
                                <div className={`absolute ${layout === '1' ? '-top-1 -right-1' : 'top-1 right-1'} bg-orange-600 text-[6px] font-bold px-1 py-0.5 rounded uppercase tracking-tighter text-white z-10 shadow-sm`}>
                                    Back
                                </div>
                            )}
                        </div>
                        <div className="flex-1 min-w-0">
                            <span className="text-[10px] font-bold text-gray-700 truncate w-full uppercase leading-tight block">{weave.name}</span>
                            {layout === '1' && <span className="text-[8px] text-gray-400 uppercase tracking-widest block mt-0.5">{weave.category} • {weave.harnesses}H</span>}
                        </div>
                    </button>

                    {/* Floating Flip Toggle */}
                    <button 
                        onClick={(e) => { e.stopPropagation(); setFaceMode(faceMode === 'face' ? 'back' : 'face'); }}
                        className={`absolute top-1 right-1 p-1 rounded shadow-md transition-all opacity-0 group-hover:opacity-100 z-20 ${faceMode === 'back' ? 'bg-orange-50 text-white' : 'bg-white/90 text-gray-400 hover:text-blue-500'}`}
                        title={`Toggle to ${faceMode === 'face' ? 'Back' : 'Face'}`}
                    >
                        <FlipIcon className="w-3 h-3" />
                    </button>
                </>
            )}
        </div>
    );
};

