import { RulerUnit, ViewMode, FaceMode, ToolType, DensityZone, YarnDefinition } from '../types';
import { CrossSection } from './CrossSection';
import { ZoomInIcon, ZoomOutIcon, ResetZoomIcon } from './icons';

interface WeaveAreaProps {
  draft: boolean[][];
  pegPlan: boolean[][];
  warpPattern: string[]; // Colors
  weftPattern: string[]; // Colors
  weavePattern: string[][];
  structure: boolean[][]; 
  dentingGrid?: string[][];
  handleDraftInteraction: (row: number, col: number, type: 'down' | 'enter' | 'up') => void;
  handlePegPlanInteraction: (row: number, col: number, type: 'down' | 'enter' | 'up') => void;
  handleDrawdownInteraction: (row: number, col: number, type: 'down' | 'enter' | 'up') => void;
  handleWarpColorInteraction?: (row: number, col: number, type: 'down' | 'enter' | 'up') => void;
  handleWeftColorInteraction?: (row: number, col: number, type: 'down' | 'enter' | 'up') => void;
  handleDentingInteraction?: (row: number, col: number, type: 'down' | 'enter' | 'up') => void;
  pegPlanActiveColor: string;
  draftActiveColor: string;
  currentTool: ToolType;
  gridDivision: number;
  viewMode: ViewMode;
  faceMode: FaceMode;
  epi: number;
  ppi: number;
  warpRepeat: number;
  weftRepeat: number;
  showHeaders?: boolean;
  showGrid?: boolean;
  weftZones?: DensityZone[]; 
  initialScale?: number;
  // NEW: Props for identifying extra yarns
  warpYarns?: { [key: string]: YarnDefinition };
  weftYarns?: { [key: string]: YarnDefinition };
  warpYarnSequence?: string[];
  weftYarnSequence?: string[];
}

const Ruler: React.FC<{
    orientation: 'horizontal' | 'vertical';
    lengthPixels: number; 
    offsetPixels: number; 
    unit: RulerUnit;
    ppi: number; 
    scale: number;
}> = ({ orientation, lengthPixels, offsetPixels, unit, ppi, scale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        const size = 24; 

        if (orientation === 'horizontal') {
            canvas.width = lengthPixels * dpr;
            canvas.height = size * dpr;
            canvas.style.width = `${lengthPixels}px`;
            canvas.style.height = `${size}px`;
        } else {
            canvas.width = size * dpr;
            canvas.height = lengthPixels * dpr;
            canvas.style.width = `${size}px`;
            canvas.style.height = `${lengthPixels}px`;
        }
        ctx.scale(dpr, dpr);
        ctx.fillStyle = '#f9fafb';
        ctx.fillRect(0,0, orientation === 'horizontal' ? lengthPixels : size, orientation === 'horizontal' ? size : lengthPixels);

        ctx.fillStyle = '#6b7280';
        ctx.font = '10px monospace';
        ctx.strokeStyle = '#d1d5db';
        ctx.lineWidth = 1;

        const pixelsPerThread = 20 * scale;
        let pixelsPerMajor = pixelsPerThread * 10; 
        let labelFactor = 10; 

        if (unit === 'inch') {
            pixelsPerMajor = pixelsPerThread * ppi; 
            labelFactor = 1;
        } else if (unit === 'cm') {
            pixelsPerMajor = (pixelsPerThread * ppi) / 2.54; 
            labelFactor = 1;
        }

        const scrollPos = -offsetPixels;

        const startUnit = Math.floor(scrollPos / pixelsPerMajor);
        const endUnit = Math.floor((scrollPos + lengthPixels) / pixelsPerMajor);

        for (let i = startUnit; i <= endUnit + 1; i++) {
            const worldPos = (i * pixelsPerMajor);
            const screenPos = worldPos - scrollPos;

            if (orientation === 'horizontal') {
                ctx.moveTo(screenPos, size);
                ctx.lineTo(screenPos, size - 10);
                if (i % 1 === 0) ctx.fillText(`${i*labelFactor}`, screenPos + 2, 10);
            } else {
                ctx.moveTo(size, screenPos);
                ctx.lineTo(size - 10, screenPos);
                if (i % 1 === 0) {
                     ctx.save();
                     ctx.translate(10, screenPos + 10);
                     ctx.rotate(-Math.PI/2);
                     ctx.fillText(`${i*labelFactor}`, 0, 0);
                     ctx.restore();
                }
            }
        }
        ctx.stroke();

    }, [orientation, lengthPixels, offsetPixels, unit, ppi, scale]);

    return <canvas ref={canvasRef} className="bg-gray-50 border-gray-200 pointer-events-none block" />;
}

const DensityTrack: React.FC<{
    zones: DensityZone[];
    height: number;
    rows: number;
    repeats: number;
}> = ({ zones, height, rows, repeats }) => {
    const totalRows = rows * repeats;
    if (totalRows === 0) return null;
    const rowHeight = height / totalRows;

    return (
        <div className="w-4 h-full bg-gray-100 border-r border-gray-200 relative">
            {zones.map((zone) => {
                const elements = [];
                for(let i=0; i<repeats; i++) {
                    const top = (i * rows + zone.startPick) * rowHeight;
                    const h = ((zone.endPick - zone.startPick + 1) * rowHeight);
                    elements.push(
                        <div 
                            key={`${zone.id}-${i}`}
                            className="absolute left-0 right-0 border-b border-white/20 flex items-center justify-center group"
                            style={{ top, height: h, backgroundColor: zone.color }}
                            title={`PPI: ${zone.ppi}`}
                        >
                            {h > 15 && <span className="text-[8px] font-bold text-white opacity-0 group-hover:opacity-100">{zone.ppi}</span>}
                        </div>
                    );
                }
                return elements;
            })}
        </div>
    );
};


export const WeaveArea: React.FC<WeaveAreaProps> = ({
  draft, pegPlan, warpPattern, weftPattern, weavePattern, structure, dentingGrid,
  handleDraftInteraction, handlePegPlanInteraction, handleDrawdownInteraction,
  handleWarpColorInteraction, handleWeftColorInteraction, handleDentingInteraction,
  pegPlanActiveColor, draftActiveColor, currentTool, gridDivision,
  viewMode, faceMode, epi, ppi,
  warpRepeat, weftRepeat,
  showHeaders = true,
  showGrid = true,
  weftZones = [],
  initialScale = 1,
  warpYarns, weftYarns, warpYarnSequence, weftYarnSequence
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const [scale, setScale] = useState(initialScale);
  const scaleRef = useRef(initialScale);

  const [scrollPos, setScrollPos] = useState({ x: 0, y: 0 });
  const [rulerUnit, setRulerUnit] = useState<RulerUnit>('thread');
  const [viewportSize, setViewportSize] = useState({ w: 0, h: 0 });
  const [isSpacePressed, setIsSpacePressed] = useState(false);

  const isPanning = useRef(false);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const zoomAnchor = useRef<{ worldX: number, worldY: number, screenX: number, screenY: number } | null>(null);

  const [activeCrossSectionRow, setActiveCrossSectionRow] = useState(0);
  const [activeCrossSectionCol, setActiveCrossSectionCol] = useState(0);

  useEffect(() => {
      const updateSize = () => {
          if (containerRef.current) {
              setViewportSize({ 
                  w: containerRef.current.clientWidth - 24, 
                  h: containerRef.current.clientHeight - 24 
              });
          }
      };
      updateSize();
      window.addEventListener('resize', updateSize);
      return () => window.removeEventListener('resize', updateSize);
  }, []);

  useEffect(() => { scaleRef.current = scale; }, [scale]);

  // Handle keyboard spacebar for panning
  useEffect(() => {
    const onDown = (e: KeyboardEvent) => {
        if (e.code === 'Space' && !e.repeat) {
            // Check if we are typing in an input
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
            setIsSpacePressed(true);
            if (e.target === document.body) e.preventDefault();
        }
    };
    const onUp = (e: KeyboardEvent) => {
        if (e.code === 'Space') {
            setIsSpacePressed(false);
        }
    };
    window.addEventListener('keydown', onDown);
    window.addEventListener('keyup', onUp);
    return () => {
        window.removeEventListener('keydown', onDown);
        window.removeEventListener('keyup', onUp);
    };
  }, []);

  useLayoutEffect(() => {
      if (zoomAnchor.current && scrollRef.current) {
          const { worldX, worldY, screenX, screenY } = zoomAnchor.current;
          const newScrollLeft = (worldX * scale) - screenX;
          const newScrollTop = (worldY * scale) - screenY;
          scrollRef.current.scrollLeft = newScrollLeft;
          scrollRef.current.scrollTop = newScrollTop;
          zoomAnchor.current = null;
      }
  }, [scale]);

  const handleScroll = () => {
      if (scrollRef.current) {
          setScrollPos({ x: scrollRef.current.scrollLeft, y: scrollRef.current.scrollTop });
      }
  };

  const displayWeave = useMemo(() => {
      const rows = weavePattern.length;
      if (rows === 0) return weavePattern;
      const cols = weavePattern[0] ? weavePattern[0].length : 0;
      const isStructure = viewMode === 'structure';
      const isReverse = faceMode === 'reverse';

      if (!isStructure && !isReverse) return weavePattern;

      const grid = new Array(rows).fill(null).map(() => new Array(cols).fill(''));
      for(let r=0; r<rows; r++) {
          const weftId = weftYarnSequence?.[r % weftYarnSequence.length] || 'A';
          const isExtraWeft = weftYarns?.[weftId]?.isExtraWeft || false;

          for(let c=0; c<cols; c++) {
              const warpId = warpYarnSequence?.[c % warpYarnSequence.length] || 'A';
              const isExtraWarp = warpYarns?.[warpId]?.isExtraWarp || false;
              const isExtra = isExtraWarp || isExtraWeft;

              let isWarpTop = (structure[r] && structure[r][c]) || false;
              if (isReverse) isWarpTop = !isWarpTop;

              if (isStructure) {
                  if (isExtra) {
                      grid[r][c] = isWarpTop ? '#6b7280' : '#e5e7eb'; // Medium gray / Light gray for extra structure
                  } else {
                      grid[r][c] = isWarpTop ? '#000000' : '#ffffff';
                  }
              } else {
                  if (isWarpTop) grid[r][c] = warpPattern[c % warpPattern.length] || '#888';
                  else grid[r][c] = weftPattern[r % weftPattern.length] || '#888';
              }
          }
      }
      return grid;
  }, [weavePattern, structure, warpPattern, weftPattern, viewMode, faceMode, warpYarns, weftYarns, warpYarnSequence, weftYarnSequence]);

  // Pre-calculate extra thread maps for grids
  const extraWarpMap = useMemo(() => {
      if (!warpYarnSequence || !warpYarns) return undefined;
      return warpYarnSequence.map(id => warpYarns[id]?.isExtraWarp || false);
  }, [warpYarnSequence, warpYarns]);

  const extraWeftMap = useMemo(() => {
      if (!weftYarnSequence || !weftYarns) return undefined;
      return weftYarnSequence.map(id => weftYarns[id]?.isExtraWeft || false);
  }, [weftYarnSequence, weftYarns]);

  const MAX_TILED_PIXELS = 12000;
  const BASE_CELL_SIZE = 20;
  const harnesses = draft.length;
  const warpThreads = warpPattern.length;
  const weftPicks = weftPattern.length;
  const repeatsX = Math.ceil(MAX_TILED_PIXELS / Math.max(1, warpThreads * BASE_CELL_SIZE));
  const repeatsY = Math.ceil(MAX_TILED_PIXELS / Math.max(1, weftPicks * BASE_CELL_SIZE));

  const draftHeight = harnesses * BASE_CELL_SIZE;
  const draftWidth = warpThreads * BASE_CELL_SIZE * repeatsX;
  const pegPlanHeight = weftPicks * BASE_CELL_SIZE * repeatsY;
  const pegPlanWidth = harnesses * BASE_CELL_SIZE;
  const colorBarSize = BASE_CELL_SIZE;
  const dentingHeight = dentingGrid ? (2 * BASE_CELL_SIZE) : 0;
  const crossSectionSize = 40; 
  const GAP = 20;
  const densityTrackWidth = 16; 

  const leftSidebarWidth = showHeaders ? (colorBarSize + densityTrackWidth + GAP + crossSectionSize + GAP + pegPlanWidth + GAP) : 0;
  const topHeaderHeight = showHeaders ? (colorBarSize + (dentingHeight > 0 ? GAP : 0) + dentingHeight + GAP + crossSectionSize + GAP + draftHeight + GAP) : 0;

  const scLeftW = leftSidebarWidth * scale;
  const scTopH = topHeaderHeight * scale;

  const performZoom = useCallback((factor: number, screenX: number, screenY: number) => {
      if (!scrollRef.current) return;
      const currentScale = scaleRef.current;
      const newScale = Math.min(Math.max(currentScale * factor, 0.05), 10);
      if (newScale === currentScale) return;

      const scrollLeft = scrollRef.current.scrollLeft;
      const scrollTop = scrollRef.current.scrollTop;

      // World position before scale
      const worldX = (scrollLeft + screenX) / currentScale;
      const worldY = (scrollTop + screenY) / currentScale;

      zoomAnchor.current = { worldX, worldY, screenX, screenY };
      scaleRef.current = newScale;
      setScale(newScale);
  }, []);

  useEffect(() => {
      const el = scrollRef.current;
      if (!el) return;
      const onWheel = (e: globalThis.WheelEvent) => {
        if (isPanning.current) return;

        // Ctrl+Wheel is for zooming
        if (e.ctrlKey) {
            e.preventDefault();
            const rect = el.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            const factor = e.deltaY > 0 ? 0.9 : 1.1;
            performZoom(factor, x, y);
            return;
        }

        // Standard Wheel scrolls natively unless we are in tool mode where we want wheel-zoom (like most design apps)
        // Let's implement design-app style: Alt+Wheel or Cmd+Wheel for zooming
        if (e.altKey || e.metaKey) {
            e.preventDefault();
            const rect = el.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            const factor = e.deltaY > 0 ? 0.92 : 1.08;
            performZoom(factor, x, y);
        }
      };
      el.addEventListener('wheel', onWheel, { passive: false });
      return () => el.removeEventListener('wheel', onWheel);
  }, [performZoom]);

  const handleZoomIn = () => performZoom(1.2, viewportSize.w / 2, viewportSize.h / 2);
  const handleZoomOut = () => performZoom(1/1.2, viewportSize.w / 2, viewportSize.h / 2);
  const handleResetZoom = () => { scaleRef.current = 1; setScale(1); };

  const handleMouseDown = (e: MouseEvent<HTMLDivElement>) => {
    // Space or Middle Click or Pan Tool or Shift+Drag activates panning
    if (isSpacePressed || currentTool === 'pan' || e.button === 1 || e.shiftKey) { 
        e.preventDefault();
        isPanning.current = true;
        lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (isPanning.current) {
        e.preventDefault();
        const dx = e.clientX - lastMousePos.current.x;
        const dy = e.clientY - lastMousePos.current.y;
        if (scrollRef.current) {
            scrollRef.current.scrollLeft -= dx;
            scrollRef.current.scrollTop -= dy;
        }
        lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleMouseUp = () => { isPanning.current = false; };

  const xsRenderCols = warpThreads * repeatsX;
  const xsRenderRows = weftPicks * repeatsY;

  const activeRowStructure = useMemo(() => {
      if (weftPicks === 0) return [];
      const row = activeCrossSectionRow % weftPicks;
      const singleRow = structure[row];
      if (!singleRow) return [];
      const tiled = [];
      for(let i=0; i<repeatsX; i++) tiled.push(...singleRow);
      return tiled;
  }, [activeCrossSectionRow, weftPicks, structure, repeatsX]);

  const activeWarpColors = useMemo(() => {
      const tiled = [];
      for(let i=0; i<repeatsX; i++) tiled.push(...warpPattern);
      return tiled;
  }, [warpPattern, repeatsX]);

  const activeWeftColor = weftPattern[activeCrossSectionRow % weftPattern.length] || '#000';

  const activeColStructure = useMemo(() => {
      if (warpThreads === 0 || weftPicks === 0) return [];
      const col = activeCrossSectionCol % warpThreads;
      const tiled = [];
      for(let r=0; r<repeatsY; r++) {
         for(let i=0; i<weftPicks; i++) {
             if (structure[i]) {
                tiled.push(structure[i][col]);
             } else {
                 tiled.push(false);
             }
         }
      }
      return tiled;
  }, [activeCrossSectionCol, warpThreads, structure, weftPicks, repeatsY]);

  const activeWeftColors = useMemo(() => {
      const tiled = [];
      for(let i=0; i<repeatsY; i++) tiled.push(...weftPattern);
      return tiled;
  }, [weftPattern, repeatsY]);

  const activeWarpColor = warpPattern[activeCrossSectionCol % warpPattern.length] || '#000';

  const handleDrawdownWithCrossSection = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      if (type === 'down' || type === 'enter') {
          setActiveCrossSectionRow(row);
          setActiveCrossSectionCol(col);
      }
      handleDrawdownInteraction(row, col, type);
  }

  const cycleUnit = () => {
      const units: RulerUnit[] = ['thread', 'inch', 'cm'];
      const next = units[(units.indexOf(rulerUnit) + 1) % units.length];
      setRulerUnit(next);
  };

  const cursorStyle = (() => {
      if (isPanning.current) return 'grabbing';
      if (isSpacePressed || currentTool === 'pan' || (window.event as any)?.shiftKey) return 'grab';
      if (currentTool === 'pencil') return 'default';
      return 'crosshair';
  })();

  const isInteractive = currentTool !== 'pan' && !isSpacePressed;

  return (
    <div ref={containerRef} className="w-full h-full relative group bg-gray-50 flex flex-col overflow-hidden">
       <div className="flex flex-none h-6 z-40 bg-gray-100 border-b border-gray-300">
           <div style={{ width: 24 }} className="flex-none bg-gray-100 border-r border-gray-300"></div>
           <div className="flex-1 overflow-hidden relative cursor-pointer" onClick={cycleUnit}>
                <Ruler orientation="horizontal" lengthPixels={viewportSize.w} offsetPixels={-scrollPos.x} unit={rulerUnit} ppi={epi} scale={scale} />
           </div>
       </div>

       <div className="flex flex-1 overflow-hidden relative">
           <div className="w-6 flex-none z-40 bg-gray-100 border-r border-gray-300 relative cursor-pointer" onClick={cycleUnit}>
                <Ruler orientation="vertical" lengthPixels={viewportSize.h} offsetPixels={-scrollPos.y} unit={rulerUnit} ppi={ppi} scale={scale} />
           </div>

           <div 
             ref={scrollRef}
             onScroll={handleScroll}
             onMouseDown={handleMouseDown}
             onMouseMove={handleMouseMove}
             onMouseUp={handleMouseUp}
             onMouseLeave={handleMouseUp}
             className="flex-1 overflow-auto bg-gray-50 relative custom-scrollbar"
             style={{ cursor: cursorStyle }}
           >
              <div 
                style={{ 
                    display: 'grid', 
                    gridTemplateColumns: showHeaders ? `${scLeftW}px max-content` : `max-content`, 
                    gridTemplateRows: showHeaders ? `${scTopH}px max-content` : `max-content`,
                    width: 'max-content',
                    height: 'max-content',
                    position: 'relative'
                }}
              >
                  {showHeaders && <div style={{ position: 'sticky', top: 0, left: 0, zIndex: 30, background: '#f3f4f6', borderRight: '1px solid #d1d5db', borderBottom: '1px solid #d1d5db' }}></div>}

                  {showHeaders && (
                      <div style={{ position: 'sticky', top: 0, zIndex: 20, background: '#f9fafb', borderBottom: '1px solid #e5e7eb', overflow: 'hidden' }}>
                          <div style={{ transform: `scale(${scale})`, transformOrigin: '0 0', position: 'absolute', top: 0, left: 0 }}>
                                <div style={{ position: 'absolute', left: 0, top: 0, width: draftWidth, height: colorBarSize }}>
                                    <InteractiveGrid data={[warpPattern]} renderRows={1} renderCols={warpThreads * repeatsX} width={draftWidth} height={colorBarSize} isColorGrid repeatCols={warpRepeat} gridDivision={gridDivision} onCellInteraction={handleWarpColorInteraction} allowInteraction={isInteractive} />
                                </div>
                                {dentingGrid && (
                                    <div style={{ position: 'absolute', left: 0, top: colorBarSize + GAP, width: draftWidth, height: dentingHeight }}>
                                        <InteractiveGrid data={dentingGrid} renderRows={2} renderCols={warpThreads * repeatsX} width={draftWidth} height={dentingHeight} isColorGrid repeatCols={warpRepeat} gridDivision={gridDivision} onCellInteraction={handleDentingInteraction} allowInteraction={isInteractive} />
                                    </div>
                                )}
                                <div style={{ position: 'absolute', left: 0, top: colorBarSize + GAP + (dentingHeight > 0 ? dentingHeight + GAP : 0), width: draftWidth, height: crossSectionSize }}>
                                    <CrossSection 
                                        orientation="horizontal" 
                                        structure={activeRowStructure} 
                                        yarnColors={activeWarpColors} 
                                        activeThreadColor={activeWeftColor} 
                                        width={draftWidth} height={crossSectionSize} 
                                        cellWidth={BASE_CELL_SIZE} cellHeight={BASE_CELL_SIZE} 
                                        renderCount={xsRenderCols}
                                    />
                                </div>
                                <div style={{ position: 'absolute', left: 0, top: colorBarSize + GAP + (dentingHeight > 0 ? dentingHeight + GAP : 0) + crossSectionSize + GAP, width: draftWidth, height: draftHeight }}>
                                    <InteractiveGrid data={draft} renderRows={harnesses} renderCols={warpThreads * repeatsX} width={draftWidth} height={draftHeight} onCellInteraction={handleDraftInteraction} activeColor={draftActiveColor} gridDivision={gridDivision} repeatCols={warpRepeat} repeatRows={harnesses} allowInteraction={isInteractive} extraCols={extraWarpMap} />
                                </div>
                          </div>
                      </div>
                  )}

                  {showHeaders && (
                      <div style={{ position: 'sticky', left: 0, zIndex: 20, background: '#f9fafb', borderRight: '1px solid #e5e7eb', overflow: 'hidden' }}>
                          <div style={{ transform: `scale(${scale})`, transformOrigin: '0 0', position: 'absolute', top: 0, left: 0 }}>
                                <div style={{ position: 'absolute', left: 0, top: 0, width: colorBarSize, height: pegPlanHeight }}>
                                    <InteractiveGrid data={weftPattern.map(c => [c])} renderRows={weftPicks * repeatsY} renderCols={1} width={colorBarSize} height={pegPlanHeight} isColorGrid repeatRows={weftRepeat} repeatCols={1} gridDivision={gridDivision} onCellInteraction={handleWeftColorInteraction} allowInteraction={isInteractive} />
                                </div>
                                <div style={{ position: 'absolute', left: colorBarSize, top: 0, width: densityTrackWidth, height: pegPlanHeight }}>
                                    <DensityTrack zones={weftZones} height={pegPlanHeight} rows={weftPicks} repeats={repeatsY} />
                                </div>
                                <div style={{ position: 'absolute', left: colorBarSize + densityTrackWidth + GAP, top: 0, width: crossSectionSize, height: pegPlanHeight }}>
                                    <CrossSection 
                                        orientation="vertical" 
                                        structure={activeColStructure} 
                                        yarnColors={activeWeftColors} 
                                        activeThreadColor={activeWarpColor} 
                                        width={crossSectionSize} height={pegPlanHeight} 
                                        cellWidth={BASE_CELL_SIZE} cellHeight={BASE_CELL_SIZE} 
                                        renderCount={xsRenderRows}
                                    />
                                </div>
                                <div style={{ position: 'absolute', left: colorBarSize + densityTrackWidth + GAP + crossSectionSize + GAP, top: 0, width: pegPlanWidth, height: pegPlanHeight }}>
                                    <InteractiveGrid data={pegPlan} renderRows={weftPicks * repeatsY} renderCols={harnesses} width={pegPlanWidth} height={pegPlanHeight} onCellInteraction={handlePegPlanInteraction} activeColor={pegPlanActiveColor} gridDivision={gridDivision} repeatRows={weftRepeat} repeatCols={harnesses} allowInteraction={isInteractive} extraRows={extraWeftMap} />
                                </div>
                          </div>
                      </div>
                  )}

                  <div style={{ position: 'relative', overflow: 'hidden' }}>
                      <div style={{ transform: `scale(${scale})`, transformOrigin: '0 0', width: draftWidth, height: pegPlanHeight }}>
                        <InteractiveGrid 
                            data={displayWeave} 
                            renderRows={weftPicks * repeatsY} renderCols={warpThreads * repeatsX}
                            width={draftWidth} height={pegPlanHeight}
                            isColorGrid 
                            onCellInteraction={handleDrawdownWithCrossSection}
                            gridDivision={gridDivision}
                            repeatRows={weftRepeat} repeatCols={warpRepeat}
                            allowInteraction={isInteractive}
                            showGrid={showGrid}
                            extraRows={extraWeftMap}
                            extraCols={extraWarpMap}
                        />
                      </div>
                  </div>
              </div>
           </div>

           <div className="absolute bottom-4 right-4 z-50 flex items-center gap-1 p-1.5 bg-white border border-gray-200 rounded-lg shadow-lg">
                <button onClick={handleZoomOut} className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded transition-colors"><ZoomOutIcon className="w-5 h-5" /></button>
                <div className="px-2 min-w-[3rem] text-center text-xs font-mono font-bold text-gray-700 select-none">{Math.round(scale * 100)}%</div>
                <button onClick={handleZoomIn} className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded transition-colors"><ZoomInIcon className="w-5 h-5" /></button>
                <div className="w-px h-5 bg-gray-200 mx-1"></div>
                <button onClick={handleResetZoom} className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded transition-colors"><ResetZoomIcon className="w-5 h-5" /></button>
           </div>

           {isSpacePressed && (
                <div className="absolute inset-0 z-[60] pointer-events-none flex items-center justify-center">
                    <div className="bg-black/70 text-white px-6 py-3 rounded-full font-bold text-sm uppercase tracking-widest shadow-2xl border border-white/20">
                        Space + Drag to Pan | Alt + Wheel to Zoom
                    </div>
                </div>
            )}
       </div>
    </div>
  );
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { JacquardCanvas } from './JacquardCanvas';
import { YarnStudio } from './YarnStudio';
import { ProductionCalculator } from './ProductionCalculator';
import { WeaveThumbnail } from './WeaveThumbnail';
import { WeaveSettings, ToolType, ViewMode, FaceMode, YarnDefinition, AppMode, JacquardData } from '../types';
import { expandPatternString } from '../utils/patternParser';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { loadImage, processImage } from '../services/imageProcessor';
import { LibraryWeave } from '../services/weaveLibrary';

const DEFAULT_PHYSICS = {
  floatTaper: 0.20,
  bindingDepth: 0.05,
  shadowAngle: 135,
  shadowThrow: 0.1
};

interface HistoryState {
    structure: Uint8Array;
    appliedWeaves: { [key: number]: LibraryWeave };
    artwork: {
        data: Uint8Array;
        palette: string[];
        width: number;
        height: number;
    } | null;
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpPatternString: string;
    weftPatternString: string;
    settings: WeaveSettings;
}

export const JacquardMaster: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>('art');
  const [showSimModal, setShowSimModal] = useState(false);
  const [projectName, setProjectName] = useState('New Jacquard Design');
  const [loadingStatus, setLoadingStatus] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragOverColorIdx, setDragOverColorIdx] = useState<number | null>(null);

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 512, 
    weftPicks: 512, 
    epi: 60, 
    ppi: 60, 
    gridDivision: 8,
    gridX: 8,
    gridY: 8,
    harnesses: 1
  });

  const [dentingPattern, setDentingPattern] = useState('1');

  const [jacquardData, setJacquardData] = useState<JacquardData>(() => ({
      width: 512,
      height: 512,
      structure: new Uint8Array(512 * 512).fill(0).map((_, i) => (Math.floor(i / 512) + (i % 512)) % 2 === 0 ? 1 : 0)
  }));

  const [artwork, setArtwork] = useState<{
      data: Uint8Array;
      palette: string[];
      width: number;
      height: number;
  } | null>(null);

  const [appliedWeaves, setAppliedWeaves] = useState<{ [key: number]: LibraryWeave }>({});

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4, ...DEFAULT_PHYSICS },
      'B': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.2, roughness: 0.4, ...DEFAULT_PHYSICS }
  });
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS },
      'B': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 20, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS }
  });

  const [activeYarnId, setActiveYarnId] = useState<string>('A');
  const [selectedYarnType, setSelectedYarnType] = useState<'warp' | 'weft'>('warp');
  const [studioYarnDef, setStudioYarnDef] = useState<YarnDefinition>(warpYarns['A']);

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  // --- HISTORY MANAGEMENT ---
  const [history, setHistory] = useState<{ past: HistoryState[], future: HistoryState[] }>({ past: [], future: [] });

  const saveHistory = useCallback(() => {
    setHistory(prev => {
        const snapshot: HistoryState = {
            structure: new Uint8Array(jacquardData.structure),
            appliedWeaves: { ...appliedWeaves },
            artwork: artwork ? { ...artwork, data: new Uint8Array(artwork.data) } : null,
            warpYarns: { ...warpYarns },
            weftYarns: { ...weftYarns },
            warpPatternString,
            weftPatternString,
            settings: { ...settings }
        };
        const newPast = [...prev.past, snapshot];
        if (newPast.length > 30) newPast.shift();
        return { past: newPast, future: [] };
    });
  }, [jacquardData, appliedWeaves, artwork, warpYarns, weftYarns, warpPatternString, weftPatternString, settings]);

  const undo = useCallback(() => {
    setHistory(prev => {
        if (prev.past.length === 0) return prev;

        const lastSnapshot = prev.past[prev.past.length - 1];
        const newPast = prev.past.slice(0, -1);

        // Current state to push to future
        const current: HistoryState = {
            structure: new Uint8Array(jacquardData.structure),
            appliedWeaves: { ...appliedWeaves },
            artwork: artwork ? { ...artwork, data: new Uint8Array(artwork.data) } : null,
            warpYarns: { ...warpYarns },
            weftYarns: { ...weftYarns },
            warpPatternString,
            weftPatternString,
            settings: { ...settings }
        };

        // Apply snapshot
        setJacquardData(prevData => ({ ...prevData, structure: lastSnapshot.structure, width: lastSnapshot.settings.warpThreads, height: lastSnapshot.settings.weftPicks }));
        setAppliedWeaves(lastSnapshot.appliedWeaves);
        setArtwork(lastSnapshot.artwork);
        setWarpYarns(lastSnapshot.warpYarns);
        setWeftYarns(lastSnapshot.weftYarns);
        setWarpPatternString(lastSnapshot.warpPatternString);
        setWeftPatternString(lastSnapshot.weftPatternString);
        setSettings(lastSnapshot.settings);

        return { past: newPast, future: [current, ...prev.future] };
    });
  }, [jacquardData, appliedWeaves, artwork, warpYarns, weftYarns, warpPatternString, weftPatternString, settings]);

  const redo = useCallback(() => {
    setHistory(prev => {
        if (prev.future.length === 0) return prev;

        const nextSnapshot = prev.future[0];
        const newFuture = prev.future.slice(1);

        const current: HistoryState = {
            structure: new Uint8Array(jacquardData.structure),
            appliedWeaves: { ...appliedWeaves },
            artwork: artwork ? { ...artwork, data: new Uint8Array(artwork.data) } : null,
            warpYarns: { ...warpYarns },
            weftYarns: { ...weftYarns },
            warpPatternString,
            weftPatternString,
            settings: { ...settings }
        };

        setJacquardData(prevData => ({ ...prevData, structure: nextSnapshot.structure, width: nextSnapshot.settings.warpThreads, height: nextSnapshot.settings.weftPicks }));
        setAppliedWeaves(nextSnapshot.appliedWeaves);
        setArtwork(nextSnapshot.artwork);
        setWarpYarns(nextSnapshot.warpYarns);
        setWeftYarns(nextSnapshot.weftYarns);
        setWarpPatternString(nextSnapshot.warpPatternString);
        setWeftPatternString(nextSnapshot.weftPatternString);
        setSettings(nextSnapshot.settings);

        return { past: [...prev.past, current], future: newFuture };
    });
  }, [jacquardData, appliedWeaves, artwork, warpYarns, weftYarns, warpPatternString, weftPatternString, settings]);

  useEffect(() => {
      const source = selectedYarnType === 'warp' ? warpYarns : weftYarns;
      if (source[activeYarnId]) setStudioYarnDef(source[activeYarnId]);
  }, [activeYarnId, selectedYarnType, warpYarns, weftYarns]);

  const handleResize = (size: number) => {
      saveHistory();
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      saveHistory();
      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 
          setArtwork({ data: new Uint8Array(result.pixels), palette: result.palette, width: result.width, height: result.height });
          setAppliedWeaves({});
          setJacquardData({ width: result.width, height: result.height, structure: new Uint8Array(result.width * result.height).fill(0) });
          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`); setWeftPatternString(`${result.height}A`);
          setProjectName(file.name.split('.')[0]); setViewMode('structure'); setAppMode('art'); setLoadingStatus(null);
      } catch (err: any) { alert(err.message || "Error processing."); setLoadingStatus(null); }
  };

  const handleApplyWeaveToColor = (weave: LibraryWeave, colorIdx: number) => {
    if (!artwork) return;
    saveHistory();
    setLoadingStatus(`Applying ${weave.name}...`);
    setTimeout(() => {
        const newStructure = new Uint8Array(jacquardData.structure);
        const { width, height } = jacquardData, weaveDraft = weave.draft, weavePeg = weave.pegPlan, weaveW = weaveDraft[0].length, weaveH = weavePeg.length;
        const weaveLookup = new Uint8Array(weaveW * weaveH);
        const warpToHarness = new Int16Array(weaveW).fill(-1);
        for(let w=0; w<weaveW; w++) for(let h=0; h<weave.harnesses; h++) if(weaveDraft[h][w] === 1) { warpToHarness[w] = h; break; }
        for(let y=0; y<weaveH; y++) for(let x=0; x<weaveW; x++) if(warpToHarness[x] !== -1 && weavePeg[y][warpToHarness[x]] === 1) weaveLookup[y * weaveW + x] = 1;
        for(let i=0; i<artwork.data.length; i++) if(artwork.data[i] === colorIdx) { const x = i % width, y = Math.floor(i / width); newStructure[i] = weaveLookup[(y % weaveH) * weaveW + (x % weaveW)]; }

        setAppliedWeaves(prev => ({ ...prev, [colorIdx]: weave }));
        setJacquardData(prev => ({ ...prev, structure: newStructure })); 
        setLoadingStatus(null); setViewMode('interlace');
    }, 50);
  };

  const handleMergeColors = (sourceIdx: number, targetIdx: number) => {
    if (!artwork || sourceIdx === targetIdx) return;
    saveHistory();
    setLoadingStatus("Merging Colors...");
    setTimeout(() => {
        const newData = new Uint8Array(artwork.data);
        for(let i=0; i<newData.length; i++) {
            if(newData[i] === sourceIdx) newData[i] = targetIdx;
            else if(newData[i] > sourceIdx) newData[i]--; 
        }
        const newPalette = artwork.palette.filter((_, i) => i !== sourceIdx);
        const newApplied: {[key: number]: LibraryWeave} = {};
        Object.keys(appliedWeaves).forEach(k => {
            const ki = parseInt(k);
            if (ki === sourceIdx) return;
            const nextK = ki > sourceIdx ? ki - 1 : ki;
            newApplied[nextK] = appliedWeaves[ki];
        });
        setAppliedWeaves(newApplied);
        setArtwork({ ...artwork, data: newData, palette: newPalette });
        setLoadingStatus(null);
    }, 50);
  };

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      return Array.from({ length: jacquardData.width }, (_, i) => warpYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const seq = expandPatternString(weftPatternString);
      return Array.from({ length: jacquardData.height }, (_, i) => weftYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [weftYarns, weftPatternString, jacquardData.height]);

  const simData = useMemo(() => {
      const { width, height, structure } = jacquardData;
      const rows: boolean[][] = []; const colors: string[][] = [];
      for (let y = 0; y < height; y++) {
          const rowB: boolean[] = []; const rowC: string[] = [];
          for (let x = 0; x < width; x++) {
              const isUp = structure[y * width + x] === 1;
              rowB.push(isUp); rowC.push(isUp ? warpColorArray[x] : weftColorArray[y]);
          }
          rows.push(rowB); colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  const handleApplyStudioYarn = () => {
    saveHistory();
    if (selectedYarnType === 'warp') setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    else setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    setAppMode('art'); 
  };

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />
        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={history.past.length > 0} canRedo={history.future.length > 0} 
            onUndo={undo} onRedo={redo}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={(m) => m === 'sim' ? setShowSimModal(true) : setAppMode(m)} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{jacquardData.width} × {jacquardData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                         <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                            <button onClick={() => setViewMode('interlace')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>INTERLACE</button>
                            <button onClick={() => setViewMode('structure')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>STRUCTURE (HOOKS)</button>
                        </div>
                        <div className="flex items-center gap-1 border-l border-gray-800 pl-4">
                            {[1024, 2048, 4096].map(size => (<button key={size} onClick={() => handleResize(size)} className={`px-2 py-0.5 rounded text-[10px] border ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400'}`}>{size}</button>))}
                        </div>
                    </div>
                </div>

                <div className="flex-1 relative">
                    {appMode === 'yarn' ? (
                        <div className="absolute inset-0 h-full"><YarnStudio yarn={studioYarnDef} onChange={setStudioYarnDef} onApply={handleApplyStudioYarn} /></div>
                    ) : appMode === 'tech' ? (
                        <div className="bg-white text-gray-900 h-full overflow-hidden absolute inset-0"><ProductionCalculator settings={settings} warpYarns={warpYarns} weftYarns={weftYarns} warpPatternString={warpPatternString} weftPatternString={weftPatternString} draft={[]} pegPlan={[]} generateThumbnail={() => ""} /></div>
                    ) : (
                        <JacquardCanvas 
                            data={jacquardData} artwork={artwork || undefined} 
                            onUpdate={(d) => { saveHistory(); setJacquardData(prev => ({ ...prev, structure: d })); }} 
                            tool={currentTool} viewMode={viewMode} faceMode={faceMode} 
                            warpColors={warpColorArray} weftColors={weftColorArray} 
                            epi={settings.epi} ppi={settings.ppi} gridX={settings.gridX} gridY={settings.gridY}
                        />
                    )}
                </div>

                {artwork && (appMode === 'art' || appMode === 'weave') && (
                    <div className="h-24 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl">
                        <div className="flex flex-col"><span className="text-[9px] font-bold text-gray-500 uppercase mb-1">Coverage Optimized Palette</span><span className="text-[10px] text-gray-400 font-mono italic">Drag color to merge</span></div>
                        <div className="flex-1 flex items-center gap-3 overflow-x-auto no-scrollbar py-2">
                            {artwork.palette.map((color, idx) => (
                                <div 
                                    key={idx} 
                                    draggable
                                    onDragStart={(e) => { e.dataTransfer.setData('color-idx', idx.toString()); }}
                                    onDragOver={e => { e.preventDefault(); setDragOverColorIdx(idx); }} 
                                    onDragLeave={() => setDragOverColorIdx(null)} 
                                    onDrop={e => { 
                                        e.preventDefault(); 
                                        setDragOverColorIdx(null); 
                                        const weaveD = e.dataTransfer.getData('weave-obj'); 
                                        const sourceC = e.dataTransfer.getData('color-idx');
                                        if (weaveD) handleApplyWeaveToColor(JSON.parse(weaveD), idx); 
                                        else if (sourceC !== "") handleMergeColors(parseInt(sourceC), idx);
                                    }} 
                                    className={`group flex flex-col items-center gap-1 shrink-0 bg-gray-800/40 p-2 rounded-lg border transition-all ${dragOverColorIdx === idx ? 'bg-blue-900/40 border-blue-500 scale-105 shadow-lg shadow-blue-500/20' : 'border-gray-700/50 hover:bg-gray-800'}`}
                                >
                                    <div className="relative w-10 h-10">
                                        <div className="w-full h-full rounded-md border border-white/10 shadow-md" style={{ backgroundColor: color }} />
                                        {appliedWeaves[idx] && (
                                            <div className="absolute inset-0 rounded-md overflow-hidden bg-black/40 flex items-center justify-center">
                                                <WeaveThumbnail weave={appliedWeaves[idx]} className="w-full h-full opacity-70" />
                                            </div>
                                        )}
                                    </div>
                                    <span className="text-[8px] font-mono text-gray-500 uppercase truncate max-w-[64px]">{appliedWeaves[idx] ? appliedWeaves[idx].name : color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end shrink-0"><span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drag weave to apply</span><button onClick={() => setArtwork(null)} className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded font-bold uppercase">Clear Art</button></div>
                    </div>
                )}
            </div>

            <RightPanel 
                settings={settings} onSettingsChange={(s) => { saveHistory(); setSettings(s); }} dentingPattern={dentingPattern} onDentingChange={setDentingPattern} onSnapshot={saveHistory} onLoadWeave={()=>{}} customWeaves={[]} onAddWeave={()=>{}} onUpdateWeave={()=>{}} onDeleteWeave={()=>{}} warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(id, d) => { saveHistory(); setWarpYarns(p => ({...p, [id]: d})); }} onUpdateWeftYarn={(id, d) => { saveHistory(); setWeftYarns(p => ({...p, [id]: d})); }} paletteColors={PANTONE_PALETTE} warpPatternString={warpPatternString} setWarpPatternString={(s) => { saveHistory(); setWarpPatternString(s); }} weftPatternString={weftPatternString} setWeftPatternString={(s) => { saveHistory(); setWeftPatternString(s); }} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{} as any} onApplyGenerated={()=>{}} onSimulate={() => setShowSimModal(true)} onGridOperation={(t, a) => { saveHistory(); const newData = new Uint8Array(jacquardData.structure); if (a === 'clear') newData.fill(0); else if (a === 'invert') for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1; setJacquardData(prev => ({ ...prev, structure: newData })); }} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { setActiveYarnId(id); setSelectedYarnType(type); setAppMode('yarn'); }}
            />
        </div>

        <FabricSimulationModal isOpen={showSimModal} onClose={() => setShowSimModal(false)} weavePattern={simData.colors} structure={simData.structure} epi={settings.epi} ppi={settings.ppi} dentingPlan={dentingPattern.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n))} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
    </div>
  );
};

import React, { useEffect, useState, useRef, MouseEvent, WheelEvent } from 'react';
import { ZoomInIcon, ZoomOutIcon, ResetZoomIcon, ChevronDownIcon, DownloadIcon, FlipIcon, RulerIcon, CubeIcon, EyeOffIcon, EyeIcon } from './icons';
import { YarnDefinition, DensityZone } from '../types';
import { renderFabricToCanvas } from '../services/fabricRenderer';
import { Fabric3DStudio } from './Fabric3DStudio';

interface FabricSimulationModalProps {
  isOpen: boolean;
  onClose: () => void;
  weavePattern: string[][];
  structure: boolean[][]; 
  epi: number;
  ppi: number;
  dentingPlan?: number[];
  weftZones?: DensityZone[];
  warpYarns: { [key: string]: YarnDefinition };
  weftYarns: { [key: string]: YarnDefinition };
  warpYarnSequence: string[];
  weftYarnSequence: string[];
  embedded?: boolean; 
}

const SVGRuler: React.FC<{
    orientation: 'horizontal' | 'vertical';
    viewportSize: number;
    zoom: number;
    pan: number;
    unit: 'inch' | 'cm';
}> = ({ orientation, viewportSize, zoom, pan, unit }) => {
    const pixelsPerUnit = unit === 'inch' ? 96 : (96 / 2.54);
    const scaledPixelsPerUnit = pixelsPerUnit * zoom;
    const divisions = unit === 'inch' ? 8 : 10;

    const ticks = [];
    const startIndex = Math.floor(-pan / scaledPixelsPerUnit);
    const numUnits = Math.ceil(viewportSize / scaledPixelsPerUnit) + 2;

    for (let i = 0; i < numUnits; i++) {
        const unitIndex = startIndex + i;
        const basePos = pan + (unitIndex * scaledPixelsPerUnit);

        if (basePos < -scaledPixelsPerUnit || basePos > viewportSize + scaledPixelsPerUnit) continue;

        // Major Tick
        ticks.push(
            <g key={`unit-${unitIndex}`} transform={orientation === 'horizontal' ? `translate(${basePos}, 0)` : `translate(0, ${basePos})`}>
                <line 
                    x1="0.5" y1="0.5" 
                    x2={orientation === 'horizontal' ? "0.5" : "15"} 
                    y2={orientation === 'horizontal' ? "15" : "0.5"} 
                    stroke="currentColor" strokeWidth="1.2" 
                />
                <text 
                    x={orientation === 'horizontal' ? "4" : "12"} 
                    y={orientation === 'horizontal' ? "12" : "3"} 
                    fontSize="9" fontWeight="bold" 
                    textAnchor={orientation === 'horizontal' ? "start" : "end"}
                    className="fill-gray-500 font-sans select-none"
                    transform={orientation === 'vertical' ? `rotate(-90 12 3)` : ''}
                >
                    {unitIndex}
                </text>

                {/* Sub-divisions */}
                {Array.from({ length: divisions - 1 }).map((_, j) => {
                    const subPos = (j + 1) * (scaledPixelsPerUnit / divisions);
                    const isHalf = (j + 1) === Math.floor(divisions / 2);
                    const h = isHalf ? 10 : 5;
                    return (
                        <line 
                            key={`sub-${unitIndex}-${j}`}
                            x1={orientation === 'horizontal' ? subPos : "0"} 
                            y1={orientation === 'horizontal' ? "0" : subPos}
                            x2={orientation === 'horizontal' ? subPos : h} 
                            y2={orientation === 'horizontal' ? h : subPos}
                            stroke="currentColor" strokeWidth="0.5"
                            className="text-gray-300"
                        />
                    );
                })}
            </g>
        );
    }

    return (
        <svg 
            className={`absolute z-30 pointer-events-none bg-white/95 backdrop-blur-sm border-gray-200 text-gray-400 ${orientation === 'horizontal' ? 'w-full h-6 border-b left-0 top-0' : 'h-full w-6 border-r left-0 top-0'}`}
        >
            {ticks}
        </svg>
    );
};

