export const WeaveStudio: React.FC<WeaveStudioProps> = ({ onSaveToLibrary }) => {
    const [state, setState] = useState<WeaveStudioState>({
        warpSystems: 2,
        weftSystems: 2,
        cells: [
            [ { ...DEFAULT_CELL }, { ...DEFAULT_CELL } ],
            [ { ...DEFAULT_CELL }, { ...DEFAULT_CELL } ]
        ],
        warpArrangement: [0, 1],
        weftArrangement: [0, 1]
    });

    const [complexName, setComplexName] = useState('New Complex Structure');
    const [viewRepeat, setViewRepeat] = useState(2);

    const updateGridSize = (warps: number, wefts: number) => {
        const newCells = Array.from({ length: wefts }, (_, r) => 
            Array.from({ length: warps }, (_, c) => {
                if (state.cells[r] && state.cells[r][c]) return state.cells[r][c];
                return { ...DEFAULT_CELL };
            })
        );
        setState(prev => ({
            ...prev,
            warpSystems: warps,
            weftSystems: wefts,
            cells: newCells,
            warpArrangement: Array.from({length: warps}, (_, i) => i),
            weftArrangement: Array.from({length: wefts}, (_, i) => i)
        }));
    };

    const updateCell = (r: number, c: number, updates: Partial<WeaveStudioCell>) => {
        const nextCells = state.cells.map(row => [...row]);
        nextCells[r][c] = { ...nextCells[r][c], ...updates };
        setState(prev => ({ ...prev, cells: nextCells }));
    };

    // --- COMPOSITION LOGIC ---
    const compositeWeave = useMemo(() => {
        // Calculate dimensions
        // For simplicity and stability, we use a fixed composite unit size that covers common repeats
        const COMP_W = 48;
        const COMP_H = 48;

        const grid = new Array(COMP_H).fill(null).map(() => new Array(COMP_W).fill(0));

        for (let y = 0; y < COMP_H; y++) {
            const weftSysIdx = state.weftArrangement[y % state.weftArrangement.length];
            for (let x = 0; x < COMP_W; x++) {
                const warpSysIdx = state.warpArrangement[x % state.warpArrangement.length];
                const cell = state.cells[weftSysIdx][warpSysIdx];

                if (cell.forceState === 'up') {
                    grid[y][x] = 1;
                } else if (cell.forceState === 'down') {
                    grid[y][x] = 0;
                } else if (cell.weave) {
                    const { draft, pegPlan } = cell.weave;
                    const w = draft[0].length;
                    const h = pegPlan.length;

                    // Lookup relative coordinate in the sub-weave
                    // We need to account for how many times this specific system has appeared
                    let localX = 0;
                    for (let k = 0; k < x; k++) if (state.warpArrangement[k % state.warpArrangement.length] === warpSysIdx) localX++;
                    let localY = 0;
                    for (let k = 0; k < y; k++) if (state.weftArrangement[k % state.weftArrangement.length] === weftSysIdx) localY++;

                    localX = (localX + cell.offsetX) % w;
                    localY = (localY + cell.offsetY) % h;
                    if (localX < 0) localX += w;
                    if (localY < 0) localY += h;

                    // Reconstruct interlacement from sub-weave
                    const warpToHarness = new Array(w).fill(-1);
                    for(let i=0; i<w; i++) for(let j=0; j<cell.weave.harnesses; j++) if(draft[j][i] === 1) { warpToHarness[i] = j; break; }

                    const hIdx = warpToHarness[localX];
                    let isUp = (hIdx !== -1 && pegPlan[localY][hIdx] === 1);
                    if (cell.faceMode === 'back') isUp = !isUp;
                    grid[y][x] = isUp ? 1 : 0;
                } else {
                    // Default to Checkerboard if box is empty
                    grid[y][x] = (x + y) % 2 === 0 ? 1 : 0;
                }
            }
        }

        // Return a virtual LibraryWeave object
        // Draft and Peg Plan are reconstructed as a straight draw for the large composite
        const harnesses = 24; // Composite uses standard large bank
        const compDraft = Array.from({length: harnesses}, (_, h) => Array.from({length: COMP_W}, (_, w) => (w % harnesses) === h ? 1 : 0));
        const compPeg = Array.from({length: COMP_H}, (_, p) => Array.from({length: harnesses}, (_, h) => grid[p][h % COMP_W] === 1 ? 1 : 0));

        return {
            id: `complex-${Date.now()}`,
            name: complexName,
            category: 'Compound',
            description: 'Generated in Weave Studio',
            harnesses: harnesses,
            draft: compDraft,
            pegPlan: compPeg
        } as LibraryWeave;

    }, [state, complexName]);

    const handleSave = () => {
        onSaveToLibrary(compositeWeave);
        alert(`"${complexName}" added to your local library!`);
    };

    return (
        <div className="flex h-full w-full bg-gray-950 text-white overflow-hidden font-sans">
            {/* LEFT: SOURCE LIBRARY */}
            <div className="w-72 border-r border-gray-800 flex flex-col bg-gray-900 overflow-hidden shrink-0">
                <div className="p-4 border-b border-gray-800">
                    <h2 className="text-sm font-black text-white uppercase tracking-[0.2em] mb-4">Structure Bank</h2>
                    <div className="relative">
                        <input type="text" placeholder="Search structures..." className="w-full bg-black/50 border border-gray-700 rounded-lg p-2 text-xs focus:border-blue-500 outline-none" />
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-4">
                    {WEAVE_LIBRARY.map(weave => (
                        <div 
                            key={weave.id} 
                            draggable 
                            onDragStart={e => e.dataTransfer.setData('weave-obj', JSON.stringify(weave))}
                            className="group flex flex-col bg-gray-800/40 border border-gray-700 rounded-lg p-3 hover:border-blue-500 hover:bg-gray-800 cursor-grab transition-all"
                        >
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-[10px] font-bold text-gray-400 uppercase truncate pr-2">{weave.name}</span>
                                <span className="text-[8px] bg-blue-900/50 text-blue-400 px-1.5 rounded font-bold">{weave.harnesses}H</span>
                            </div>
                            <WeaveThumbnail weave={weave} className="w-full aspect-video border-none shadow-lg opacity-80 group-hover:opacity-100" />
                        </div>
                    ))}
                </div>
            </div>

            {/* CENTER: COMPOSITOR */}
            <div className="flex-1 flex flex-col min-w-0 bg-gray-950">
                {/* TOOLBAR */}
                <div className="h-16 border-b border-gray-800 bg-gray-900/50 flex items-center px-6 justify-between shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2 bg-black/40 rounded-lg p-1 border border-gray-800">
                            <label className="text-[10px] font-bold text-gray-500 uppercase px-2">Systems</label>
                            <div className="flex items-center gap-1">
                                <input 
                                    type="number" min="1" max="4" value={state.warpSystems} 
                                    onChange={e => updateGridSize(parseInt(e.target.value) || 1, state.weftSystems)}
                                    className="w-10 bg-gray-800 border-none rounded text-center text-xs font-bold text-blue-400 py-1"
                                />
                                <span className="text-gray-600">×</span>
                                <input 
                                    type="number" min="1" max="4" value={state.weftSystems} 
                                    onChange={e => updateGridSize(state.warpSystems, parseInt(e.target.value) || 1)}
                                    className="w-10 bg-gray-800 border-none rounded text-center text-xs font-bold text-blue-400 py-1"
                                />
                            </div>
                        </div>
                        <div className="h-6 w-px bg-gray-800"></div>
                        <div className="flex items-center gap-2">
                            <label className="text-[10px] font-bold text-gray-500 uppercase">Project Name</label>
                            <input 
                                type="text" value={complexName} onChange={e => setComplexName(e.target.value)} 
                                className="bg-transparent border-b border-gray-800 focus:border-blue-500 outline-none text-sm font-bold text-white w-48 py-1"
                            />
                        </div>
                    </div>
                    <button onClick={handleSave} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-full font-bold text-xs shadow-lg transition-all flex items-center gap-2">
                        <PlusIcon className="w-4 h-4" /> Save Complex Weave
                    </button>
                </div>

                {/* COMPOSITOR GRID */}
                <div className="flex-1 overflow-auto p-12 custom-scrollbar flex items-start justify-center">
                    <div 
                        className="grid gap-6 p-6 bg-white/5 rounded-3xl border border-white/10 shadow-2xl backdrop-blur-md"
                        style={{ 
                            gridTemplateColumns: `repeat(${state.warpSystems}, 240px)`,
                            gridTemplateRows: `repeat(${state.weftSystems}, 240px)`
                        }}
                    >
                        {state.cells.map((row, r) => row.map((cell, c) => (
                            <WeaveBox 
                                key={`${r}-${c}`} 
                                cell={cell} 
                                onUpdate={(u) => updateCell(r, c, u)} 
                                warpLabel={`Warp Sys ${c+1}`} 
                                weftLabel={`Weft Sys ${r+1}`} 
                            />
                        )))}
                    </div>
                </div>
            </div>

            {/* RIGHT: LIVE PREVIEW & RECONSTRUCTION */}
            <div className="w-96 border-l border-gray-800 bg-gray-900 flex flex-col shrink-0 shadow-[-20px_0_40px_rgba(0,0,0,0.4)]">
                <div className="p-6 border-b border-gray-800 bg-black/20">
                    <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest mb-6">Composite Result</h3>
                    <div className="aspect-square bg-black rounded-2xl border border-gray-800 overflow-hidden shadow-inner p-4 relative group">
                        <WeaveThumbnail 
                            weave={compositeWeave} 
                            faceMode="face" 
                            tile 
                            forceScale={4}
                            className="w-full h-full border-none" 
                        />
                        <div className="absolute top-4 right-4 flex gap-1">
                            <button onClick={() => setViewRepeat(Math.max(1, viewRepeat - 1))} className="p-1.5 bg-gray-800 hover:bg-gray-700 rounded"><ZoomOutIcon className="w-4 h-4 text-gray-400"/></button>
                            <button onClick={() => setViewRepeat(viewRepeat + 1)} className="p-1.5 bg-gray-800 hover:bg-gray-700 rounded"><ZoomInIcon className="w-4 h-4 text-gray-400"/></button>
                        </div>
                    </div>
                </div>

                <div className="flex-1 p-6 overflow-y-auto custom-scrollbar">
                    <div className="space-y-6">
                        <div>
                            <h4 className="text-[10px] font-bold text-blue-400 uppercase mb-3">Construction Logic</h4>
                            <div className="bg-black/40 rounded-xl p-4 border border-gray-800 space-y-4">
                                <div>
                                    <div className="flex justify-between items-center mb-1">
                                        <span className="text-[10px] text-gray-500 font-bold uppercase">Warp Interleaving</span>
                                        <span className="text-[9px] font-mono text-gray-400">{state.warpArrangement.join(':')}</span>
                                    </div>
                                    <div className="flex h-1.5 bg-gray-800 rounded-full overflow-hidden">
                                        {state.warpArrangement.map((sys, i) => (
                                            <div key={i} className="h-full flex-1" style={{ backgroundColor: state.cells[0][sys]?.weave ? '#3b82f6' : '#1f2937' }}></div>
                                        ))}
                                    </div>
                                </div>
                                <div>
                                    <div className="flex justify-between items-center mb-1">
                                        <span className="text-[10px] text-gray-500 font-bold uppercase">Weft Interleaving</span>
                                        <span className="text-[9px] font-mono text-gray-400">{state.weftArrangement.join(':')}</span>
                                    </div>
                                    <div className="flex h-1.5 bg-gray-800 rounded-full overflow-hidden">
                                         {state.weftArrangement.map((sys, i) => (
                                            <div key={i} className="h-full flex-1" style={{ backgroundColor: state.cells[sys][0]?.weave ? '#3b82f6' : '#1f2937' }}></div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div>
                            <h4 className="text-[10px] font-bold text-emerald-400 uppercase mb-3">Double Cloth Helpers</h4>
                            <div className="grid grid-cols-1 gap-2">
                                <button 
                                    onClick={() => {
                                        // Standard Double Cloth Preset for 2x2
                                        if (state.warpSystems >= 2 && state.weftSystems >= 2) {
                                            updateCell(0, 1, { forceState: 'up' });   // Face Warp over Back Weft
                                            updateCell(1, 0, { forceState: 'down' }); // Back Warp under Face Weft
                                        }
                                    }}
                                    className="w-full py-3 px-4 bg-gray-800 border border-gray-700 hover:border-emerald-500 rounded-xl text-left transition-all group"
                                >
                                    <div className="text-xs font-bold text-gray-200 group-hover:text-emerald-400">Separation Preset</div>
                                    <div className="text-[9px] text-gray-500 font-medium">Auto-align layers for double-face fabrics</div>
                                </button>
                                <button 
                                    onClick={() => {
                                        // Reset offsets
                                        state.cells.forEach((row, r) => row.forEach((_, c) => updateCell(r, c, { offsetX: 0, offsetY: 0, faceMode: 'face' })));
                                    }}
                                    className="w-full py-2 px-4 bg-gray-800/50 border border-dashed border-gray-700 hover:border-red-500 rounded-xl text-center text-[10px] font-bold text-gray-500 uppercase transition-all"
                                >
                                    Reset All Transformations
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

