                                        <span className="text-[9px] font-mono text-gray-400">{state.weftArrangement.map(v => v+1).join(' : ')}</span>
                                    </div>
                                    <div className="flex h-1.5 bg-gray-800 rounded-full overflow-hidden">
                                         {state.weftArrangement.map((sys, i) => (
                                            <div key={i} className="h-full flex-1" style={{ backgroundColor: state.cells[sys][0]?.weave ? '#3b82f6' : '#1f2937' }}></div>
                                        ))}
                                    </div>
                                </div>
                                <div className="pt-2 border-t border-gray-800/50 flex justify-between items-center">
                                    <span className="text-[9px] text-gray-600 font-bold uppercase">Structural Repeat</span>
                                    <span className="text-[10px] text-blue-500 font-mono font-bold tracking-tight">{COMP_W}E x {COMP_H}P</span>
                                </div>
                            </div>
                        </div>

                        <div>
                            <h4 className="text-[10px] font-bold text-emerald-400 uppercase mb-3">Double Cloth Helpers</h4>
                            <div className="grid grid-cols-1 gap-2">
                                <button 
                                    onClick={() => {
                                        if (state.warpSystems >= 2 && state.weftSystems >= 2) {
                                            updateCell(0, 1, { forceState: 'up' });   
                                            updateCell(1, 0, { forceState: 'down' }); 
                                        }
                                    }}
                                    className="w-full py-3 px-4 bg-gray-800 border border-gray-700 hover:border-emerald-500 rounded-xl text-left transition-all group"
                                >
                                    <div className="text-xs font-bold text-gray-200 group-hover:text-emerald-400">Separation Preset</div>
                                    <div className="text-[9px] text-gray-500 font-medium">Auto-align layers for double-face fabrics</div>
                                </button>
                                <button 
                                    onClick={() => {
                                        state.cells.forEach((row, r) => row.forEach((_, c) => updateCell(r, c, { offsetX: 0, offsetY: 0, faceMode: 'face' })));
                                    }}
                                    className="w-full py-2 px-4 bg-gray-800/50 border border-dashed border-gray-700 hover:border-red-500 rounded-xl text-center text-[10px] font-bold text-gray-500 uppercase transition-all"
                                >
                                    Reset All Transformations
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

