const DEFAULT_CELL_COLORS = ['#3b82f6', '#f59e0b', '#10b981', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#14b8a6'];

const DEFAULT_CELL = (idx: number): WeaveStudioCell => ({
    weave: null,
    faceMode: 'face',
    offsetX: 0,
    offsetY: 0,
    forceState: 'none',
    color: DEFAULT_CELL_COLORS[idx % DEFAULT_CELL_COLORS.length]
});

const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));
const lcm = (a: number, b: number): number => (a * b) / (gcd(a, b) || 1);

const WeaveBox: React.FC<{
    cell: WeaveStudioCell;
    onUpdate: (updates: Partial<WeaveStudioCell>) => void;
    warpLabel: string;
    weftLabel: string;
    onDesign: () => void;
}> = ({ cell, onUpdate, warpLabel, weftLabel, onDesign }) => {
    const [isDragOver, setIsDragOver] = useState(false);

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
        const data = e.dataTransfer.getData('weave-obj');
        if (data) {
            onUpdate({ weave: JSON.parse(data), forceState: 'none' });
        }
    };

    // Calculate reflected weave with offsets for the internal thumbnail
    const reflectedWeave = useMemo(() => {
        if (!cell.weave) return null;
        if (cell.offsetX === 0 && cell.offsetY === 0) return cell.weave;

        const w = cell.weave.draft[0].length;
        const h = cell.weave.pegPlan.length;
        const nextPeg = cell.weave.pegPlan.map(row => [...row]);

        // Circular Shift Peg Plan
        const shiftY = ((cell.offsetY % h) + h) % h;
        const shiftedPeg = shiftY > 0 ? [...nextPeg.slice(h - shiftY), ...nextPeg.slice(0, h - shiftY)] : nextPeg;

        const shiftX = ((cell.offsetX % w) + w) % w;
        const finalPeg = shiftX > 0 
            ? shiftedPeg.map(row => {
                // In a Dobby structure, shifting X means remapping the peg plan's columns if they represent harnesses
                // For a "Technical Shift" of the repeat, we just shift the resulting interlacement.
                // However, the easiest way for thumbnail to show offset is to return a modified peg plan.
                return [...row.slice(w - shiftX), ...row.slice(0, w - shiftX)];
            }) 
            : shiftedPeg;

        return { ...cell.weave, pegPlan: finalPeg };
    }, [cell.weave, cell.offsetX, cell.offsetY]);

    return (
        <div 
            onDragOver={e => { e.preventDefault(); setIsDragOver(true); }}
            onDragLeave={() => setIsDragOver(false)}
            onDrop={handleDrop}
            className={`relative flex flex-col bg-gray-900 border-2 rounded-xl overflow-hidden transition-all h-64 ${isDragOver ? 'border-blue-500 bg-blue-900/20 scale-[1.02] shadow-2xl' : 'border-gray-800 hover:border-gray-700'}`}
        >
            <div className="flex justify-between items-center p-2 bg-gray-800/50 border-b border-gray-800">
                <div className="flex items-center gap-2">
                    <input 
                        type="color" value={cell.color} 
                        onChange={e => onUpdate({ color: e.target.value })} 
                        className="w-4 h-4 rounded-full border-none p-0 cursor-pointer overflow-hidden bg-transparent" 
                    />
                    <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{warpLabel} × {weftLabel}</span>
                </div>
                <div className="flex gap-1">
                    <button onClick={() => onUpdate({ forceState: cell.forceState === 'up' ? 'none' : 'up', weave: null })} className={`px-1.5 py-0.5 rounded text-[8px] font-bold border transition-colors ${cell.forceState === 'up' ? 'bg-white text-black border-white' : 'text-gray-500 border-gray-700 hover:border-gray-500'}`}>UP</button>
                    <button onClick={() => onUpdate({ forceState: cell.forceState === 'down' ? 'none' : 'down', weave: null })} className={`px-1.5 py-0.5 rounded text-[8px] font-bold border transition-colors ${cell.forceState === 'down' ? 'bg-black text-white border-white' : 'text-gray-500 border-gray-700 hover:border-gray-500'}`}>DN</button>
                </div>
            </div>

            <div className="flex-1 flex items-center justify-center p-4 relative group">
                {cell.weave ? (
                    <div className="relative w-full h-full">
                         <WeaveThumbnail weave={reflectedWeave!} faceMode={cell.faceMode} showGrid className="w-full h-full shadow-2xl rounded-lg" />
                         <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={onDesign} className="p-1.5 bg-blue-600 text-white rounded shadow-lg hover:bg-blue-500" title="Edit Structure"><PencilIcon className="w-3 h-3" /></button>
                            <button onClick={() => onUpdate({ weave: null, forceState: 'none' })} className="p-1.5 bg-red-600 text-white rounded shadow-lg hover:bg-red-500" title="Remove Weave"><TrashIcon className="w-3 h-3" /></button>
                         </div>
                    </div>
                ) : (
                    <div className="text-center flex flex-col items-center gap-3">
                        {cell.forceState === 'none' ? (
                            <>
                                <GridFillIcon className="w-8 h-8 text-gray-700" />
                                <button onClick={onDesign} className="px-3 py-1 bg-gray-800 border border-gray-700 rounded-full text-[9px] font-black text-gray-400 hover:text-white hover:border-blue-500 uppercase tracking-widest transition-all">Design Unit</button>
                            </>
                        ) : (
                            <span className={`text-xs font-black uppercase tracking-widest ${cell.forceState === 'up' ? 'text-white' : 'text-gray-700'}`}>
                                Forced {cell.forceState}
                            </span>
                        )}
                    </div>
                )}
            </div>

            {cell.weave && (
                <div className="p-2 bg-black/40 border-t border-gray-800 flex justify-between items-center">
                    <div className="flex gap-1">
                         <button onClick={() => onUpdate({ faceMode: cell.faceMode === 'face' ? 'back' : 'face' })} className={`p-1.5 rounded border ${cell.faceMode === 'back' ? 'bg-orange-600 border-orange-500 text-white' : 'bg-gray-800 border-gray-700 text-gray-400'}`} title="Flip Face/Back"><FlipIcon className="w-3.5 h-3.5" /></button>
                    </div>
                    <div className="flex gap-1 items-center bg-gray-800 rounded p-1">
                        <button onClick={() => onUpdate({ offsetX: cell.offsetX - 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftLeftIcon className="w-3 h-3"/></button>
                        <button onClick={() => onUpdate({ offsetY: cell.offsetY - 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftUpIcon className="w-3 h-3"/></button>
                        <div className="text-[8px] font-mono text-blue-400 w-8 text-center">{cell.offsetX},{cell.offsetY}</div>
                        <button onClick={() => onUpdate({ offsetY: cell.offsetY + 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftDownIcon className="w-3 h-3"/></button>
                        <button onClick={() => onUpdate({ offsetX: cell.offsetX + 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftRightIcon className="w-3 h-3"/></button>
                    </div>
                </div>
            )}
        </div>
    );
};

export const WeaveStudio: React.FC<WeaveStudioProps> = ({ onSaveToLibrary }) => {
    const [state, setState] = useState<WeaveStudioState>({
        warpSystems: 2,
        weftSystems: 2,
        cells: [
            [ DEFAULT_CELL(0), DEFAULT_CELL(1) ],
            [ DEFAULT_CELL(2), DEFAULT_CELL(3) ]
        ],
        warpArrangement: [0, 1],
        weftArrangement: [0, 1]
    });

    const [complexName, setComplexName] = useState('Compound Weave');
    const [isTiled, setIsTiled] = useState(false);
    const [isColorPreview, setIsColorPreview] = useState(false);
    const [pixelEditor, setPixelEditor] = useState<{r: number, c: number, weave: LibraryWeave | null} | null>(null);

    const updateGridSize = (warps: number, wefts: number) => {
        const newCells = Array.from({ length: wefts }, (_, r) => 
            Array.from({ length: warps }, (_, c) => {
                if (state.cells[r] && state.cells[r][c]) return state.cells[r][c];
                return DEFAULT_CELL(r * warps + c);
            })
        );
        setState(prev => ({
            ...prev,
            warpSystems: warps,
            weftSystems: wefts,
            cells: newCells,
            warpArrangement: Array.from({length: warps}, (_, i) => i),
            weftArrangement: Array.from({length: wefts}, (_, i) => i)
        }));
    };

    const updateCell = (r: number, c: number, updates: Partial<WeaveStudioCell>) => {
        const nextCells = state.cells.map(row => [...row]);
        nextCells[r][c] = { ...nextCells[r][c], ...updates };
        setState(prev => ({ ...prev, cells: nextCells }));
    };

    // --- DYNAMIC COMPOSITION ENGINE ---
    const { compositeWeave, compW, compH, colorGrid } = useMemo(() => {
        let finalW = state.warpArrangement.length;
        let finalH = state.weftArrangement.length;

        for(let s = 0; s < state.warpSystems; s++) {
            let systemW = 1;
            for(let r = 0; r < state.weftSystems; r++) {
                const w = state.cells[r][s].weave?.draft[0].length || 1;
                systemW = lcm(systemW, w);
            }
            const countInArr = state.warpArrangement.filter(idx => idx === s).length;
            if (countInArr > 0) {
                const neededCycles = lcm(systemW, countInArr) / countInArr;
                finalW = lcm(finalW, neededCycles * state.warpArrangement.length);
            }
        }

        for(let s = 0; s < state.weftSystems; s++) {
            let systemH = 1;
            for(let c = 0; c < state.warpSystems; c++) {
                const h = state.cells[s][c].weave?.pegPlan.length || 1;
                systemH = lcm(systemH, h);
            }
            const countInArr = state.weftArrangement.filter(idx => idx === s).length;
            if (countInArr > 0) {
                const neededCycles = lcm(systemH, countInArr) / countInArr;
                finalH = lcm(finalH, neededCycles * state.weftArrangement.length);
            }
        }

        finalW = Math.min(finalW, 256);
        finalH = Math.min(finalH, 256);

        const grid = Array.from({ length: finalH }, () => new Array(finalW).fill(0));
        const colorMatrix = Array.from({ length: finalH }, () => new Array(finalW).fill('#000'));

        for (let y = 0; y < finalH; y++) {
            const weftSysIdx = state.weftArrangement[y % state.weftArrangement.length];
            const seqH = state.weftArrangement.length;
            const fullCyclesY = Math.floor(y / seqH);
            let localYBase = fullCyclesY * state.weftArrangement.filter(i => i === weftSysIdx).length;
            for(let k = 0; k < (y % seqH); k++) if(state.weftArrangement[k] === weftSysIdx) localYBase++;

            for (let x = 0; x < finalW; x++) {
                const warpSysIdx = state.warpArrangement[x % state.warpArrangement.length];
                const seqW = state.warpArrangement.length;
                const fullCyclesX = Math.floor(x / seqW);
                let localXBase = fullCyclesX * state.warpArrangement.filter(i => i === warpSysIdx).length;
                for(let k = 0; k < (x % seqW); k++) if(state.warpArrangement[k] === warpSysIdx) localXBase++;

                const cell = state.cells[weftSysIdx][warpSysIdx];
                let isUp = false;

                if (cell.forceState === 'up') isUp = true;
                else if (cell.forceState === 'down') isUp = false;
                else if (cell.weave) {
                    const { draft, pegPlan, harnesses } = cell.weave;
                    const w = draft[0].length;
                    const h = pegPlan.length;
                    const lx = ((localXBase + cell.offsetX) % w + w) % w;
                    const ly = ((localYBase + cell.offsetY) % h + h) % h;
                    const wToH = new Array(w).fill(-1);
                    for(let i=0; i<w; i++) for(let j=0; j<harnesses; j++) if(draft[j][i] === 1) { wToH[i] = j; break; }
                    const hIdx = wToH[lx];
                    isUp = (hIdx !== -1 && pegPlan[ly][hIdx] === 1);
                    if (cell.faceMode === 'back') isUp = !isUp;
                } else {
                    isUp = (x + y) % 2 === 0;
                }

                grid[y][x] = isUp ? 1 : 0;
                colorMatrix[y][x] = isUp ? cell.color : '#111827';
            }
        }

        const harnesses = Math.min(finalW, 64); 
        const compDraft = Array.from({length: harnesses}, (_, h) => Array.from({length: finalW}, (_, w) => (w % harnesses) === h ? 1 : 0));
        const compPeg = Array.from({length: finalH}, (_, p) => Array.from({length: harnesses}, (_, h) => grid[p][h % finalW] === 1 ? 1 : 0));

        return {
            compositeWeave: {
                id: `complex-${Date.now()}`,
                name: complexName,
                category: 'Compound',
                harnesses,
                draft: compDraft,
                pegPlan: compPeg
            } as LibraryWeave,
            compW: finalW,
            compH: finalH,
            colorGrid: colorMatrix
        };

    }, [state, complexName]);

    const handleSave = () => {
        onSaveToLibrary(compositeWeave);
        alert(`"${complexName}" saved. Size: ${compW}x${compH}`);
    };

    return (
        <div className="flex h-full w-full bg-gray-950 text-white overflow-hidden font-sans">
            <div className="w-72 border-r border-gray-800 flex flex-col bg-gray-900 shrink-0">
