import React, { useState, useRef, useEffect } from 'react';
import { LibraryWeave } from '../types';
import { InteractiveGrid } from './InteractiveGrid';
import { CheckIcon, TrashIcon, InvertIcon } from './icons';

interface CustomWeaveModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (weave: LibraryWeave) => void;
    initialWeave?: LibraryWeave;
}

export const CustomWeaveModal: React.FC<CustomWeaveModalProps> = ({ isOpen, onClose, onSave, initialWeave }) => {
    const [size, setSize] = useState(8);
    const [name, setName] = useState('New Unit');
    const [grid, setGrid] = useState<boolean[][]>(() => 
        Array.from({ length: 8 }, () => Array(8).fill(false))
    );
    const isDrawing = useRef(false);
    const drawMode = useRef(true);

    useEffect(() => {
        if (isOpen) {
            if (initialWeave) {
                const s = initialWeave.draft[0].length;
                setSize(s);
                setName(initialWeave.name);

                const w = initialWeave.draft[0].length;
                const h = initialWeave.pegPlan.length;
                const harnesses = initialWeave.harnesses;
                const newGrid = Array.from({ length: h }, () => Array(w).fill(false));

                // Construct grid from pegPlan and draft
                const warpToHarness = new Array(w).fill(-1);
                for(let i=0; i<w; i++) for(let j=0; j<harnesses; j++) if(initialWeave.draft[j][i] === 1) { warpToHarness[i] = j; break; }

                for(let y=0; y<h; y++) {
                    for(let x=0; x<w; x++) {
                        const hIdx = warpToHarness[x];
                        newGrid[y][x] = hIdx !== -1 && initialWeave.pegPlan[y][hIdx] === 1;
                    }
                }
                setGrid(newGrid);
            } else {
                setGrid(Array.from({ length: size }, () => Array(size).fill(false)));
            }
        }
    }, [isOpen, initialWeave]);

    const handleInteraction = (r: number, c: number, type: 'down' | 'enter' | 'up') => {
        if (type === 'down') {
            isDrawing.current = true;
            drawMode.current = !grid[r][c];
            const next = grid.map(row => [...row]);
            next[r][c] = drawMode.current;
            setGrid(next);
        } else if (type === 'enter' && isDrawing.current) {
            const next = grid.map(row => [...row]);
            next[r][c] = drawMode.current;
            setGrid(next);
        } else if (type === 'up') {
            isDrawing.current = false;
        }
    };

    const handleSave = () => {
        const harnesses = size;
        const draft = Array.from({ length: harnesses }, (_, h) => Array.from({ length: size }, (_, w) => (w % harnesses) === h ? 1 : 0));
        const pegPlan = Array.from({ length: size }, (_, p) => Array.from({ length: harnesses }, (_, h) => grid[p][h] ? 1 : 0));

        onSave({
            id: initialWeave?.id || `custom-${Date.now()}`,
            name,
            category: 'Custom',
            description: 'Created in Pixel Editor',
            harnesses,
            draft,
            pegPlan
        });
        onClose();
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-gray-900 border border-gray-700 rounded-3xl shadow-[0_0_100px_rgba(0,0,0,0.5)] w-full max-w-xl flex flex-col overflow-hidden">
                <div className="p-6 border-b border-gray-800 bg-gray-900 flex justify-between items-center">
                    <div>
                        <h2 className="text-xl font-black text-white tracking-tight">PIXEL WEAVE EDITOR</h2>
                        <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">Design a structural unit</p>
                    </div>
                    <button onClick={onClose} className="p-2 text-gray-400 hover:text-white transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
                </div>

                <div className="p-8 bg-gray-950 flex flex-col items-center gap-8">
                    <div className="flex gap-4 items-center bg-gray-900 p-2 rounded-2xl border border-gray-800">
                         <div className="flex flex-col items-center px-4">
                            <span className="text-[9px] font-bold text-gray-500 uppercase mb-1">Unit Size</span>
                            <div className="flex items-center gap-3">
                                <button onClick={() => setSize(Math.max(2, size-1))} className="w-6 h-6 flex items-center justify-center bg-gray-800 rounded border border-gray-700 text-gray-400 hover:text-white">-</button>
                                <span className="font-mono font-black text-blue-400 w-6 text-center">{size}</span>
                                <button onClick={() => setSize(Math.min(24, size+1))} className="w-6 h-6 flex items-center justify-center bg-gray-800 rounded border border-gray-700 text-gray-400 hover:text-white">+</button>
                            </div>
                         </div>
                         <div className="w-px h-8 bg-gray-800"></div>
                         <div className="flex-1 px-4">
                             <span className="text-[9px] font-bold text-gray-500 uppercase mb-1">Unit Name</span>
                             <input value={name} onChange={e => setName(e.target.value)} className="bg-transparent text-sm font-bold text-white outline-none border-b border-gray-700 focus:border-blue-500 transition-colors w-full" />
                         </div>
                    </div>

                    <div className="bg-white/5 p-4 rounded-3xl border border-white/5 shadow-inner">
                        <InteractiveGrid 
                            data={grid} 
                            renderRows={size} 
                            renderCols={size} 
                            onCellInteraction={handleInteraction}
                            activeColor="#3b82f6"
                            width={320} 
                            height={320} 
                            gridDivision={4}
                        />
                    </div>

                    <div className="flex gap-3">
                        <button onClick={() => setGrid(grid.map(r => r.map(() => false)))} className="flex items-center gap-2 px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-xl text-[10px] font-bold text-gray-400 uppercase transition-all"><TrashIcon className="w-3.5 h-3.5"/> Clear</button>
                        <button onClick={() => setGrid(grid.map(r => r.map(c => !c)))} className="flex items-center gap-2 px-4 py-2 bg-gray-800 hover:bg-gray-700 rounded-xl text-[10px] font-bold text-gray-400 uppercase transition-all"><InvertIcon className="w-3.5 h-3.5"/> Invert</button>
                    </div>
                </div>

                <div className="p-6 bg-gray-900 border-t border-gray-800 flex justify-end">
                    <button onClick={handleSave} className="flex items-center gap-2 px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-full font-black text-xs uppercase tracking-widest shadow-2xl transition-all active:scale-95">
                        <CheckIcon className="w-4 h-4" /> Save to Library
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { LibraryWeave, WeaveStudioState, WeaveStudioCell } from '../types';
import { WEAVE_LIBRARY } from '../services/weaveLibrary';
import { WeaveThumbnail } from './WeaveThumbnail';
// Fix: Added PaletteIcon to the list of icons imported from icons.tsx
import { FlipIcon, ShiftUpIcon, ShiftDownIcon, ShiftLeftIcon, ShiftRightIcon, PlusIcon, TrashIcon, GridFillIcon, ListIcon, PencilIcon, PaletteIcon } from './icons';
import { CustomWeaveModal } from './CustomWeaveModal';
// Fix: Added missing import for InteractiveGrid
import { InteractiveGrid } from './InteractiveGrid';

interface WeaveStudioProps {
    onSaveToLibrary: (weave: LibraryWeave) => void;
}

const DEFAULT_CELL_COLORS = ['#3b82f6', '#f59e0b', '#10b981', '#ef4444', '#8b5cf6', '#06b6d4', '#f43f5e', '#14b8a6'];

const DEFAULT_CELL = (idx: number): WeaveStudioCell => ({
    weave: null,
    faceMode: 'face',
    offsetX: 0,
    offsetY: 0,
    forceState: 'none',
    color: DEFAULT_CELL_COLORS[idx % DEFAULT_CELL_COLORS.length]
});

const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));
const lcm = (a: number, b: number): number => (a * b) / (gcd(a, b) || 1);

const WeaveBox: React.FC<{
    cell: WeaveStudioCell;
    onUpdate: (updates: Partial<WeaveStudioCell>) => void;
    warpLabel: string;
    weftLabel: string;
    onDesign: () => void;
}> = ({ cell, onUpdate, warpLabel, weftLabel, onDesign }) => {
    const [isDragOver, setIsDragOver] = useState(false);

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
        const data = e.dataTransfer.getData('weave-obj');
        if (data) {
            onUpdate({ weave: JSON.parse(data), forceState: 'none' });
        }
    };

    // Calculate reflected weave with offsets for the internal thumbnail
    const reflectedWeave = useMemo(() => {
        if (!cell.weave) return null;
        if (cell.offsetX === 0 && cell.offsetY === 0) return cell.weave;

        const w = cell.weave.draft[0].length;
        const h = cell.weave.pegPlan.length;
        const nextPeg = cell.weave.pegPlan.map(row => [...row]);

        // Circular Shift Peg Plan
        const shiftY = ((cell.offsetY % h) + h) % h;
        const shiftedPeg = shiftY > 0 ? [...nextPeg.slice(h - shiftY), ...nextPeg.slice(0, h - shiftY)] : nextPeg;

        const shiftX = ((cell.offsetX % w) + w) % w;
        const finalPeg = shiftX > 0 
            ? shiftedPeg.map(row => {
                // In a Dobby structure, shifting X means remapping the peg plan's columns if they represent harnesses
                // For a "Technical Shift" of the repeat, we just shift the resulting interlacement.
                // However, the easiest way for thumbnail to show offset is to return a modified peg plan.
                return [...row.slice(w - shiftX), ...row.slice(0, w - shiftX)];
            }) 
            : shiftedPeg;

        return { ...cell.weave, pegPlan: finalPeg };
    }, [cell.weave, cell.offsetX, cell.offsetY]);

    return (
        <div 
            onDragOver={e => { e.preventDefault(); setIsDragOver(true); }}
            onDragLeave={() => setIsDragOver(false)}
            onDrop={handleDrop}
            className={`relative flex flex-col bg-gray-900 border-2 rounded-xl overflow-hidden transition-all h-64 ${isDragOver ? 'border-blue-500 bg-blue-900/20 scale-[1.02] shadow-2xl' : 'border-gray-800 hover:border-gray-700'}`}
        >
            <div className="flex justify-between items-center p-2 bg-gray-800/50 border-b border-gray-800">
                <div className="flex items-center gap-2">
                    <input 
                        type="color" value={cell.color} 
                        onChange={e => onUpdate({ color: e.target.value })} 
                        className="w-4 h-4 rounded-full border-none p-0 cursor-pointer overflow-hidden bg-transparent" 
                    />
                    <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{warpLabel} × {weftLabel}</span>
                </div>
                <div className="flex gap-1">
                    <button onClick={() => onUpdate({ forceState: cell.forceState === 'up' ? 'none' : 'up', weave: null })} className={`px-1.5 py-0.5 rounded text-[8px] font-bold border transition-colors ${cell.forceState === 'up' ? 'bg-white text-black border-white' : 'text-gray-500 border-gray-700 hover:border-gray-500'}`}>UP</button>
                    <button onClick={() => onUpdate({ forceState: cell.forceState === 'down' ? 'none' : 'down', weave: null })} className={`px-1.5 py-0.5 rounded text-[8px] font-bold border transition-colors ${cell.forceState === 'down' ? 'bg-black text-white border-white' : 'text-gray-500 border-gray-700 hover:border-gray-500'}`}>DN</button>
                </div>
            </div>

            <div className="flex-1 flex items-center justify-center p-4 relative group">
                {cell.weave ? (
                    <div className="relative w-full h-full">
                         <WeaveThumbnail weave={reflectedWeave!} faceMode={cell.faceMode} showGrid className="w-full h-full shadow-2xl rounded-lg" />
                         <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={onDesign} className="p-1.5 bg-blue-600 text-white rounded shadow-lg hover:bg-blue-500" title="Edit Structure"><PencilIcon className="w-3 h-3" /></button>
                            <button onClick={() => onUpdate({ weave: null, forceState: 'none' })} className="p-1.5 bg-red-600 text-white rounded shadow-lg hover:bg-red-500" title="Remove Weave"><TrashIcon className="w-3 h-3" /></button>
                         </div>
                    </div>
                ) : (
                    <div className="text-center flex flex-col items-center gap-3">
                        {cell.forceState === 'none' ? (
                            <>
                                <GridFillIcon className="w-8 h-8 text-gray-700" />
                                <button onClick={onDesign} className="px-3 py-1 bg-gray-800 border border-gray-700 rounded-full text-[9px] font-black text-gray-400 hover:text-white hover:border-blue-500 uppercase tracking-widest transition-all">Design Unit</button>
                            </>
                        ) : (
                            <span className={`text-xs font-black uppercase tracking-widest ${cell.forceState === 'up' ? 'text-white' : 'text-gray-700'}`}>
                                Forced {cell.forceState}
                            </span>
                        )}
                    </div>
                )}
            </div>

            {cell.weave && (
                <div className="p-2 bg-black/40 border-t border-gray-800 flex justify-between items-center">
                    <div className="flex gap-1">
                         <button onClick={() => onUpdate({ faceMode: cell.faceMode === 'face' ? 'back' : 'face' })} className={`p-1.5 rounded border ${cell.faceMode === 'back' ? 'bg-orange-600 border-orange-500 text-white' : 'bg-gray-800 border-gray-700 text-gray-400'}`} title="Flip Face/Back"><FlipIcon className="w-3.5 h-3.5" /></button>
                    </div>
                    <div className="flex gap-1 items-center bg-gray-800 rounded p-1">
                        <button onClick={() => onUpdate({ offsetX: cell.offsetX - 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftLeftIcon className="w-3 h-3"/></button>
                        <button onClick={() => onUpdate({ offsetY: cell.offsetY - 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftUpIcon className="w-3 h-3"/></button>
                        <div className="text-[8px] font-mono text-blue-400 w-8 text-center">{cell.offsetX},{cell.offsetY}</div>
                        <button onClick={() => onUpdate({ offsetY: cell.offsetY + 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftDownIcon className="w-3 h-3"/></button>
                        <button onClick={() => onUpdate({ offsetX: cell.offsetX + 1 })} className="p-1 text-gray-500 hover:text-white"><ShiftRightIcon className="w-3 h-3"/></button>
                    </div>
                </div>
            )}
        </div>
    );
};

export const WeaveStudio: React.FC<WeaveStudioProps> = ({ onSaveToLibrary }) => {
    const [state, setState] = useState<WeaveStudioState>({
        warpSystems: 2,
        weftSystems: 2,
        cells: [
            [ DEFAULT_CELL(0), DEFAULT_CELL(1) ],
            [ DEFAULT_CELL(2), DEFAULT_CELL(3) ]
        ],
        warpArrangement: [0, 1],
        weftArrangement: [0, 1]
    });

    const [complexName, setComplexName] = useState('Compound Weave');
    const [isTiled, setIsTiled] = useState(false);
    const [isColorPreview, setIsColorPreview] = useState(false);
    const [pixelEditor, setPixelEditor] = useState<{r: number, c: number, weave: LibraryWeave | null} | null>(null);

    const updateGridSize = (warps: number, wefts: number) => {
        const newCells = Array.from({ length: wefts }, (_, r) => 
            Array.from({ length: warps }, (_, c) => {
                if (state.cells[r] && state.cells[r][c]) return state.cells[r][c];
                return DEFAULT_CELL(r * warps + c);
            })
        );
        setState(prev => ({
            ...prev,
            warpSystems: warps,
            weftSystems: wefts,
            cells: newCells,
            warpArrangement: Array.from({length: warps}, (_, i) => i),
            weftArrangement: Array.from({length: wefts}, (_, i) => i)
        }));
    };

    const updateCell = (r: number, c: number, updates: Partial<WeaveStudioCell>) => {
        const nextCells = state.cells.map(row => [...row]);
        nextCells[r][c] = { ...nextCells[r][c], ...updates };
        setState(prev => ({ ...prev, cells: nextCells }));
    };

    // --- DYNAMIC COMPOSITION ENGINE ---
    const { compositeWeave, compW, compH, colorGrid } = useMemo(() => {
        let finalW = state.warpArrangement.length;
        let finalH = state.weftArrangement.length;

        for(let s = 0; s < state.warpSystems; s++) {
            let systemW = 1;
            for(let r = 0; r < state.weftSystems; r++) {
                const w = state.cells[r][s].weave?.draft[0].length || 1;
                systemW = lcm(systemW, w);
            }
            const countInArr = state.warpArrangement.filter(idx => idx === s).length;
            if (countInArr > 0) {
                const neededCycles = lcm(systemW, countInArr) / countInArr;
                finalW = lcm(finalW, neededCycles * state.warpArrangement.length);
            }
        }

        for(let s = 0; s < state.weftSystems; s++) {
            let systemH = 1;
            for(let c = 0; c < state.warpSystems; c++) {
                const h = state.cells[s][c].weave?.pegPlan.length || 1;
                systemH = lcm(systemH, h);
            }
            const countInArr = state.weftArrangement.filter(idx => idx === s).length;
            if (countInArr > 0) {
                const neededCycles = lcm(systemH, countInArr) / countInArr;
                finalH = lcm(finalH, neededCycles * state.weftArrangement.length);
            }
        }

        finalW = Math.min(finalW, 256);
        finalH = Math.min(finalH, 256);

        const grid = Array.from({ length: finalH }, () => new Array(finalW).fill(0));
        const colorMatrix = Array.from({ length: finalH }, () => new Array(finalW).fill('#000'));

        for (let y = 0; y < finalH; y++) {
            const weftSysIdx = state.weftArrangement[y % state.weftArrangement.length];
            const seqH = state.weftArrangement.length;
            const fullCyclesY = Math.floor(y / seqH);
            let localYBase = fullCyclesY * state.weftArrangement.filter(i => i === weftSysIdx).length;
            for(let k = 0; k < (y % seqH); k++) if(state.weftArrangement[k] === weftSysIdx) localYBase++;

            for (let x = 0; x < finalW; x++) {
                const warpSysIdx = state.warpArrangement[x % state.warpArrangement.length];
                const seqW = state.warpArrangement.length;
                const fullCyclesX = Math.floor(x / seqW);
                let localXBase = fullCyclesX * state.warpArrangement.filter(i => i === warpSysIdx).length;
                for(let k = 0; k < (x % seqW); k++) if(state.warpArrangement[k] === warpSysIdx) localXBase++;

                const cell = state.cells[weftSysIdx][warpSysIdx];
                let isUp = false;

                if (cell.forceState === 'up') isUp = true;
                else if (cell.forceState === 'down') isUp = false;
                else if (cell.weave) {
                    const { draft, pegPlan, harnesses } = cell.weave;
                    const w = draft[0].length;
                    const h = pegPlan.length;
                    const lx = ((localXBase + cell.offsetX) % w + w) % w;
                    const ly = ((localYBase + cell.offsetY) % h + h) % h;
                    const wToH = new Array(w).fill(-1);
                    for(let i=0; i<w; i++) for(let j=0; j<harnesses; j++) if(draft[j][i] === 1) { wToH[i] = j; break; }
                    const hIdx = wToH[lx];
                    isUp = (hIdx !== -1 && pegPlan[ly][hIdx] === 1);
                    if (cell.faceMode === 'back') isUp = !isUp;
                } else {
                    isUp = (x + y) % 2 === 0;
                }

                grid[y][x] = isUp ? 1 : 0;
                colorMatrix[y][x] = isUp ? cell.color : '#111827';
            }
        }

        const harnesses = Math.min(finalW, 64); 
        const compDraft = Array.from({length: harnesses}, (_, h) => Array.from({length: finalW}, (_, w) => (w % harnesses) === h ? 1 : 0));
        const compPeg = Array.from({length: finalH}, (_, p) => Array.from({length: harnesses}, (_, h) => grid[p][h % finalW] === 1 ? 1 : 0));

        return {
            compositeWeave: {
                id: `complex-${Date.now()}`,
                name: complexName,
                category: 'Compound',
                harnesses,
                draft: compDraft,
                pegPlan: compPeg
            } as LibraryWeave,
            compW: finalW,
            compH: finalH,
            colorGrid: colorMatrix
        };

    }, [state, complexName]);

    const handleSave = () => {
        onSaveToLibrary(compositeWeave);
        alert(`"${complexName}" saved. Size: ${compW}x${compH}`);
    };

    return (
        <div className="flex h-full w-full bg-gray-950 text-white overflow-hidden font-sans">
            <div className="w-72 border-r border-gray-800 flex flex-col bg-gray-900 shrink-0">
                <div className="p-4 border-b border-gray-800">
                    <h2 className="text-sm font-black text-white uppercase tracking-[0.2em] mb-4">Structure Bank</h2>
                    <input type="text" placeholder="Search..." className="w-full bg-black/50 border border-gray-700 rounded-lg p-2 text-xs focus:border-blue-500 outline-none" />
                </div>
                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar space-y-4">
                    {WEAVE_LIBRARY.map(weave => (
                        <div 
                            key={weave.id} draggable onDragStart={e => e.dataTransfer.setData('weave-obj', JSON.stringify(weave))}
                            className="group flex flex-col bg-gray-800/40 border border-gray-700 rounded-lg p-3 hover:border-blue-500 hover:bg-gray-800 cursor-grab transition-all"
                        >
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-[10px] font-bold text-gray-400 uppercase truncate">{weave.name}</span>
                                <span className="text-[8px] bg-blue-900/50 text-blue-400 px-1.5 rounded font-bold">{weave.harnesses}H</span>
                            </div>
                            <WeaveThumbnail weave={weave} className="w-full aspect-video border-none shadow-lg opacity-80 group-hover:opacity-100" />
                        </div>
                    ))}
                </div>
            </div>

            <div className="flex-1 flex flex-col min-w-0 bg-gray-950">
                <div className="h-16 border-b border-gray-800 bg-gray-900/50 flex items-center px-6 justify-between shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2 bg-black/40 rounded-lg p-1 border border-gray-800">
                            <label className="text-[10px] font-bold text-gray-500 uppercase px-2">Grid</label>
                            <input type="number" min="1" max="4" value={state.warpSystems} onChange={e => updateGridSize(parseInt(e.target.value) || 1, state.weftSystems)} className="w-10 bg-gray-800 border-none rounded text-center text-xs font-bold text-blue-400 py-1" />
                            <span className="text-gray-600">×</span>
                            <input type="number" min="1" max="4" value={state.weftSystems} onChange={e => updateGridSize(state.warpSystems, parseInt(e.target.value) || 1)} className="w-10 bg-gray-800 border-none rounded text-center text-xs font-bold text-blue-400 py-1" />
                        </div>
                        <input type="text" value={complexName} onChange={e => setComplexName(e.target.value)} className="bg-transparent border-b border-gray-800 focus:border-blue-500 outline-none text-sm font-bold text-white w-48 py-1" />
                    </div>
                    <button onClick={handleSave} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-2 transition-all"><PlusIcon className="w-4 h-4" /> Save Result</button>
                </div>

                <div className="flex-1 overflow-auto p-12 custom-scrollbar flex items-start justify-center">
                    <div className="grid gap-6 p-6 bg-white/5 rounded-3xl border border-white/10 shadow-2xl backdrop-blur-md" style={{ gridTemplateColumns: `repeat(${state.warpSystems}, 240px)`, gridTemplateRows: `repeat(${state.weftSystems}, 240px)` }}>
                        {state.cells.map((row, r) => row.map((cell, c) => (
                            <WeaveBox key={`${r}-${c}`} cell={cell} onUpdate={(u) => updateCell(r, c, u)} warpLabel={`Warp ${c+1}`} weftLabel={`Weft ${r+1}`} onDesign={() => setPixelEditor({ r, c, weave: cell.weave })} />
                        )))}
                    </div>
                </div>
            </div>

            <div className="w-96 border-l border-gray-800 bg-gray-900 flex flex-col shrink-0 shadow-[-20px_0_40px_rgba(0,0,0,0.4)]">
                <div className="p-6 border-b border-gray-800 bg-black/20">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest">Composite Result</h3>
                        <div className="flex bg-gray-800 rounded p-1 border border-gray-700">
                             <button onClick={() => setIsColorPreview(!isColorPreview)} className={`px-2 py-1 text-[9px] font-bold rounded uppercase transition-all flex items-center gap-1 ${isColorPreview ? 'bg-emerald-600 text-white shadow-sm' : 'text-gray-400 hover:text-white'}`}><PaletteIcon className="w-3 h-3" /> {isColorPreview ? 'Colored' : 'Structure'}</button>
                             <div className="w-px h-3 bg-gray-600 mx-1 self-center"></div>
                             <button onClick={() => setIsTiled(false)} className={`px-2 py-1 text-[9px] font-bold rounded transition-all ${!isTiled ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}>Unit</button>
                             <button onClick={() => setIsTiled(true)} className={`px-2 py-1 text-[9px] font-bold rounded transition-all ${isTiled ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}>Fabric</button>
                        </div>
                    </div>

                    <div className="relative group p-4 bg-gray-950 rounded-2xl border border-gray-800 overflow-hidden shadow-inner">
                        {!isTiled && (
                            <>
                                <div className="absolute top-1 left-8 right-8 flex justify-between px-2 text-[8px] font-mono text-gray-600 pointer-events-none uppercase"><span>1</span><span className="text-blue-500 font-black">Composite Warp Repeat</span><span>{compW}</span></div>
                                <div className="absolute top-8 bottom-8 left-1 flex flex-col justify-between py-2 text-[8px] font-mono text-gray-600 pointer-events-none text-right w-6 uppercase"><span>1</span><div className="transform -rotate-90 origin-center whitespace-nowrap text-emerald-500 font-black translate-x-[-2px]">Weft Picks</div><span>{compH}</span></div>
                            </>
                        )}
                        <div className="aspect-square relative flex items-center justify-center">
                            {isColorPreview ? (
                                <div className="w-full h-full relative" style={{ transform: `scale(${isTiled ? 0.25 : 1})`, transformOrigin: 'top left', width: isTiled ? '400%' : '100%', height: isTiled ? '400%' : '100%' }}>
                                    <InteractiveGrid 
                                        data={colorGrid} isColorGrid showGrid={false}
                                        renderRows={compH} renderCols={compW}
                                        width={isTiled ? 1200 : 320} height={isTiled ? 1200 : 320}
                                        className="w-full h-full"
                                    />
                                </div>
                            ) : (
                                <WeaveThumbnail weave={compositeWeave} faceMode="face" tile={isTiled} forceScale={isTiled ? 4 : 6} className="w-full h-full border-none bg-transparent" />
                            )}
                        </div>
                    </div>

                    <div className="mt-6 flex justify-between items-center bg-black/40 rounded-xl p-3 border border-gray-800">
                        <div className="text-center flex-1"><div className="text-[8px] font-black text-blue-500 uppercase mb-1">Total Ends</div><div className="text-lg font-black text-white font-mono">{compW}</div></div>
                        <div className="w-px h-8 bg-gray-800"></div>
                        <div className="text-center flex-1"><div className="text-[8px] font-black text-emerald-500 uppercase mb-1">Total Picks</div><div className="text-lg font-black text-white font-mono">{compH}</div></div>
                    </div>
                </div>
                <div className="flex-1 p-6 overflow-y-auto custom-scrollbar space-y-6">
                    <div>
                        <div className="flex items-center gap-2 mb-3"><ListIcon className="w-3.5 h-3.5 text-blue-400" /><h4 className="text-[10px] font-bold text-blue-400 uppercase tracking-wider">Interleaving Schedule</h4></div>
                        <div className="bg-black/40 rounded-xl p-4 border border-gray-800 space-y-5 shadow-inner">
                            <div>
                                <div className="flex justify-between items-center mb-1"><span className="text-[10px] text-gray-500 font-bold uppercase">Warp System Pattern</span><span className="text-[9px] font-mono text-gray-400">{state.warpArrangement.map(v => v+1).join(':')}</span></div>
                                <div className="flex h-1.5 bg-gray-800 rounded-full overflow-hidden">{state.warpArrangement.map((sys, i) => (<div key={i} className="h-full flex-1" style={{ backgroundColor: state.cells[0][sys]?.weave ? state.cells[0][sys].color : '#1f2937' }}></div>))}</div>
                            </div>
                            <div>
                                <div className="flex justify-between items-center mb-1"><span className="text-[10px] text-gray-500 font-bold uppercase">Weft System Pattern</span><span className="text-[9px] font-mono text-gray-400">{state.weftArrangement.map(v => v+1).join(':')}</span></div>
                                <div className="flex h-1.5 bg-gray-800 rounded-full overflow-hidden">{state.weftArrangement.map((sys, i) => (<div key={i} className="h-full flex-1" style={{ backgroundColor: state.cells[sys][0]?.weave ? state.cells[sys][0].color : '#1f2937' }}></div>))}</div>
                            </div>
                        </div>
                    </div>
                    <button onClick={() => { if (state.warpSystems >= 2 && state.weftSystems >= 2) { updateCell(0, 1, { forceState: 'up' }); updateCell(1, 0, { forceState: 'down' }); } }} className="w-full py-3 px-4 bg-gray-800 border border-gray-700 hover:border-emerald-500 rounded-xl text-left transition-all group">
                        <div className="text-xs font-bold text-gray-200 group-hover:text-emerald-400">Apply Layer Separation</div>
                        <div className="text-[9px] text-gray-500 font-medium">Standard 2-layer lifting offset</div>
                    </button>
                </div>
            </div>

            {pixelEditor && (
                <CustomWeaveModal 
                    isOpen={!!pixelEditor} 
                    onClose={() => setPixelEditor(null)} 
                    onSave={(w) => {
                        updateCell(pixelEditor.r, pixelEditor.c, { weave: w, forceState: 'none' });
                        setPixelEditor(null);
                    }}
                    initialWeave={pixelEditor.weave || undefined}
                />
            )}
        </div>
    );
};

