                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2 bg-black/40 rounded-lg p-1 border border-gray-800"><label className="text-[10px] font-bold text-gray-500 uppercase px-2">Grid</label><input type="number" min="1" max="4" value={state.warpSystems} onChange={e => updateGridSize(parseInt(e.target.value)||1, state.weftSystems)} className="w-10 bg-gray-800 border-none rounded text-center text-xs font-bold text-blue-400 py-1" /><span className="text-gray-600">×</span><input type="number" min="1" max="4" value={state.weftSystems} onChange={e => updateGridSize(state.warpSystems, parseInt(e.target.value)||1)} className="w-10 bg-gray-800 border-none rounded text-center text-xs font-bold text-blue-400 py-1" /></div>
                        <input type="text" value={complexName} onChange={e => setComplexName(e.target.value)} className="bg-transparent border-b border-gray-800 focus:border-blue-500 outline-none text-sm font-bold text-white w-48 py-1" />
                    </div>
                    <button onClick={() => onSaveToLibrary(composition.weave)} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-2 transition-all"><PlusIcon className="w-4 h-4" /> Save Structure</button>
                </div>
                <div className="flex-1 overflow-auto p-12 custom-scrollbar flex items-start justify-center">
                    <div className="grid gap-6 p-6 bg-white/5 rounded-3xl border border-white/10 shadow-2xl backdrop-blur-md" style={{ gridTemplateColumns: `repeat(${state.warpSystems}, 240px)`, gridTemplateRows: `repeat(${state.weftSystems}, 240px)` }}>
                        {state.cells.map((row, r) => row.map((cell, c) => <WeaveBox key={`${r}-${c}`} cell={cell} onUpdate={(u) => updateCell(r, c, u)} warpLabel={`Warp ${c+1}`} weftLabel={`Weft ${r+1}`} onDesign={() => setPixelEditor({ r, c, weave: cell.weave })} />))}
                    </div>
                </div>
            </div>

            <div className="w-96 border-l border-gray-800 bg-gray-900 flex flex-col shrink-0 shadow-2xl">
                <div className="p-6 border-b border-gray-800 bg-black/20">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest">Composite Result</h3>
                        <div className="flex bg-gray-800 rounded p-1 border border-gray-700">
                             <button onClick={() => setIsColorPreview(!isColorPreview)} className={`px-2 py-1 text-[9px] font-bold rounded uppercase transition-all flex items-center gap-1 ${isColorPreview ? 'bg-emerald-600 text-white' : 'text-gray-400'}`}><PaletteIcon className="w-3 h-3" /> {isColorPreview ? 'Colored' : 'Structure'}</button>
                             <div className="w-px h-3 bg-gray-600 mx-1 self-center"></div>
                             <button onClick={() => setIsTiled(false)} className={`px-2 py-1 text-[9px] font-bold rounded transition-all ${!isTiled ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>Unit</button>
                             <button onClick={() => setIsTiled(true)} className={`px-2 py-1 text-[9px] font-bold rounded transition-all ${isTiled ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>Fabric</button>
                        </div>
                    </div>
                    <div className="aspect-square relative p-4 bg-gray-950 rounded-2xl border border-gray-800 overflow-hidden shadow-inner flex items-center justify-center">
                        {isColorPreview ? (
                            <div className="w-full h-full relative overflow-hidden" style={{ transform: `scale(${isTiled ? 0.25 : 1})`, transformOrigin: 'top left', width: isTiled ? '400%' : '100%', height: isTiled ? '400%' : '100%' }}>
                                <InteractiveGrid data={composition.colors} isColorGrid showGrid={false} renderRows={composition.h} renderCols={composition.w} width={isTiled ? 1200 : 320} height={isTiled ? 1200 : 320} className="w-full h-full" />
                            </div>
                        ) : <WeaveThumbnail weave={composition.weave} faceMode="face" tile={isTiled} forceScale={isTiled ? 4 : 6} className="w-full h-full border-none bg-transparent" />}
                        {!isTiled && (
                            <>
                                <div className="absolute top-1 left-8 right-8 flex justify-between px-2 text-[8px] font-mono text-gray-700 uppercase tracking-tighter pointer-events-none"><span>1</span><span>{composition.w} Ends</span><span>{composition.w}</span></div>
                                <div className="absolute top-8 bottom-8 left-1 flex flex-col justify-between py-2 text-[8px] font-mono text-gray-700 uppercase pointer-events-none text-right w-6"><span>1</span><div className="transform -rotate-90 origin-center whitespace-nowrap">{composition.h} Picks</div><span>{composition.h}</span></div>
                            </>
                        )}
                    </div>
                    <div className="mt-6 flex justify-between items-center bg-black/40 rounded-xl p-3 border border-gray-800 text-center">
                        <div className="flex-1"><div className="text-[8px] font-black text-blue-500 uppercase mb-1">Total Ends</div><div className="text-lg font-black text-white font-mono">{composition.w}</div></div>
                        <div className="w-px h-8 bg-gray-800"></div>
                        <div className="flex-1"><div className="text-[8px] font-black text-emerald-500 uppercase mb-1">Total Picks</div><div className="text-lg font-black text-white font-mono">{composition.h}</div></div>
                    </div>
                </div>
                <div className="flex-1 p-6 overflow-y-auto custom-scrollbar space-y-6">
                    <div className="bg-black/40 rounded-xl p-4 border border-gray-800 space-y-5 shadow-inner">
                        <div><div className="flex justify-between items-center mb-1"><span className="text-[10px] text-gray-500 font-bold uppercase">Warp Map</span><span className="text-[9px] font-mono text-gray-400">{state.warpArrangement.map(v => v+1).join(':')}</span></div><div className="flex h-1.5 bg-gray-800 rounded-full overflow-hidden">{state.warpArrangement.map((s, i) => <div key={i} className="h-full flex-1" style={{ backgroundColor: state.cells[0][s]?.weave ? state.cells[0][s].color : '#1f2937' }} />)}</div></div>
                        <div><div className="flex justify-between items-center mb-1"><span className="text-[10px] text-gray-500 font-bold uppercase">Weft Map</span><span className="text-[9px] font-mono text-gray-400">{state.weftArrangement.map(v => v+1).join(':')}</span></div><div className="flex h-1.5 bg-gray-800 rounded-full overflow-hidden">{state.weftArrangement.map((s, i) => <div key={i} className="h-full flex-1" style={{ backgroundColor: state.cells[s][0]?.weave ? state.cells[s][0].color : '#1f2937' }} />)}</div></div>
                    </div>
                    <button onClick={() => { if (state.warpSystems >= 2 && state.weftSystems >= 2) { updateCell(0, 1, { forceState: 'up' }); updateCell(1, 0, { forceState: 'down' }); } }} className="w-full py-3 px-4 bg-gray-800 border border-gray-700 hover:border-emerald-500 rounded-xl text-left transition-all group">
                        <div className="text-xs font-bold text-gray-200 group-hover:text-emerald-400">Separation Preset</div>
                        <div className="text-[9px] text-gray-500 font-medium">Standard 2-layer structural offset</div>
                    </button>
                </div>
            </div>

            {pixelEditor && <CustomWeaveModal isOpen={!!pixelEditor} onClose={() => setPixelEditor(null)} onSave={(w) => { updateCell(pixelEditor.r, pixelEditor.c, { weave: w, forceState: 'none' }); setPixelEditor(null); }} initialWeave={pixelEditor.weave || undefined} />}
        </div>
    );
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { WeaveSettings, WeaveInput, YarnDefinition, LibraryWeave } from '../types';
import { 
    LayersIcon, ListIcon, PaletteIcon, GridFillIcon, GridIcon, 
    PencilIcon, TrashIcon, PlusIcon, FlipIcon, CopyIcon,
    ShiftUpIcon, ShiftDownIcon, ShiftLeftIcon, ShiftRightIcon
} from './icons';
import { WEAVE_LIBRARY } from '../services/weaveLibrary';
import { TextPatternEditor } from './TextPatternEditor';
import { AiControl } from './AiControl';
import { WeaveThumbnail } from './WeaveThumbnail';
import { YarnDesignerModal } from './YarnDesignerModal';
import { ColorPalette } from './ColorPalette';

interface RightPanelProps {
    settings: WeaveSettings;
    onSettingsChange: (newSettings: WeaveSettings) => void;
    dentingPattern: string;
    onDentingChange: (val: string) => void;
    onSnapshot: () => void;
    onLoadWeave: (weave: LibraryWeave) => void;
    customWeaves: LibraryWeave[];
    onAddWeave: (weave: LibraryWeave) => void;
    onUpdateWeave: (weave: LibraryWeave) => void;
    onDeleteWeave: (id: string) => void;
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    onUpdateWarpYarn: (char: string, def: YarnDefinition) => void;
    onUpdateWeftYarn: (char: string, def: YarnDefinition) => void;
    onUpdateAllYarns?: (type: 'warp' | 'weft', yarns: { [key: string]: YarnDefinition }) => void;
    paletteColors: string[];
    warpPatternString: string;
    setWarpPatternString: (val: string) => void;
    weftPatternString: string;
    setWeftPatternString: (val: string) => void;
    onOpenGridEditor: (type: 'warp' | 'weft') => void;
    onOpenPatternGenerator: (type: 'warp' | 'weft') => void;
    currentInput: WeaveInput;
    onApplyGenerated: (data: any) => void;
    onSimulate: () => void;
    selectedColorIndex?: number;
    onSelectColor?: (index: number) => void;
    onGridOperation: (gridType: 'draft' | 'peg', action: 'clear' | 'invert' | 'shiftUp' | 'shiftDown' | 'shiftLeft' | 'shiftRight' | 'double') => void;
    activeYarnId?: string;
    selectedYarnType?: 'warp' | 'weft'; 
    onSelectYarn?: (id: string, type: 'warp' | 'weft') => void; 
    onActiveYarnChange?: (char: string) => void; 
    forcedTab?: TabType; 
    onSyncGridDimensions?: (warpLen: number, weftLen: number) => void; 
    onOpenPixelEditor?: () => void;
}

type TabType = 'construction' | 'pattern' | 'weave' | 'yarns' | 'colors';

const TabButton: React.FC<{ id: TabType, activeTab: TabType, icon: React.ReactNode, label: string, onClick: (id: TabType) => void }> = ({ id, activeTab, icon, label, onClick }) => (
    <button
        onClick={() => onClick(id)}
        className={`flex-1 flex flex-col items-center justify-center py-3 gap-1 border-b-2 transition-colors ${activeTab === id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
    >
        {icon}
        <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
    </button>
);

const SliderInput: React.FC<{
    label: string; value: number; onChange?: (value: number) => void; min?: number; max?: number; step?: number; subLabel?: string; disabled?: boolean; onPointerDown?: () => void;
}> = ({ label, value, onChange, min, max, step, subLabel, disabled, onPointerDown }) => (
    <div className="mb-5">
        <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex justify-between">
            <span>{label} {subLabel && <span className="text-gray-400 normal-case ml-1">({subLabel})</span>}</span>
            <span className={`${disabled ? 'text-gray-500' : 'text-blue-600'} font-mono`}>{value}</span>
        </label>
        {!disabled && (
            <input
                type="range" min={min} max={max} step={step} value={value}
                onChange={(e) => onChange && onChange(parseInt(e.target.value, 10))}
                onPointerDown={onPointerDown}
                className="w-full h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600 hover:accent-blue-500"
            />
        )}
    </div>
);

const YarnList: React.FC<{ 
    yarns: {[key: string]: YarnDefinition}, 
    type: 'warp' | 'weft',
    activeId?: string,
    isSelectedType?: boolean,
    onSelect?: (id: string, type: 'warp' | 'weft') => void,
    onEdit: (char: string, def: YarnDefinition) => void,
    label: string 
}> = ({ yarns, type, activeId, isSelectedType, onSelect, onEdit, label }) => {
    const letters = ['A','B','C','D','E','F','G','H'];
    return (
        <div className="mb-4">
            <h2 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">{label}</h2>
            <div className="flex flex-col gap-1.5">
                {letters.map((char) => {
                    const yarn = yarns[char];
                    const isSelected = isSelectedType && activeId === char;
                    if (!yarn) return null;
                    return (
                        <div 
                            key={char} 
                            onClick={() => onSelect && onSelect(char, type)}
                            className={`flex items-center gap-3 p-2 rounded-lg border transition-all cursor-pointer ${isSelected ? 'bg-blue-50 border-blue-200 ring-1 ring-blue-100' : 'border-gray-100 hover:bg-gray-50'}`}
                        >
                            <div className="font-mono font-bold w-4 text-xs text-gray-500">{char}</div>
                            <div className="flex-1 min-w-0">
                                <div className="h-2 rounded-full mb-1" style={{ background: yarn.color }} />
                                <div className="text-[9px] text-gray-400 font-bold uppercase truncate">{yarn.fiberType} • {yarn.count}{yarn.countSystem}</div>
                            </div>
                            <button onClick={(e) => { e.stopPropagation(); onEdit(char, yarn); }} className="p-1.5 text-gray-400 hover:text-blue-500 rounded-md transition-colors"><PencilIcon className="w-3.5 h-3.5" /></button>
                        </div>
                    )
                })}
            </div>
        </div>
    );
}

const LibraryItem: React.FC<{ 
    weave: LibraryWeave; 
    onSnapshot: () => void; 
    onLoadWeave: (w: LibraryWeave) => void;
    layout: '1' | '2' | '3';
}> = ({ weave, onSnapshot, onLoadWeave, layout }) => {
    const [faceMode, setFaceMode] = useState<'face' | 'back'>('face');

    const getTransformedWeave = useCallback(() => {
        let transformed = { ...weave };
        if (faceMode === 'back') {
            transformed.name = `${weave.name} (Back)`;
            transformed.pegPlan = transformed.pegPlan.map(row => row.map(cell => cell === 1 ? 0 : 1));
        }
        return transformed;
    }, [weave, faceMode]);

    const handleApply = () => { onSnapshot(); onLoadWeave(getTransformedWeave()); };
    const handleDragStart = (e: React.DragEvent) => { e.dataTransfer.setData('weave-obj', JSON.stringify(getTransformedWeave())); };

    return (
        <div className={`relative group ${layout === '3' ? 'bg-white border rounded-xl shadow-sm hover:shadow-md transition-all overflow-hidden mb-2' : ''}`}>
            {layout === '3' ? (
                <div className="flex flex-col">
                    <div className="relative aspect-video bg-gray-950 group/preview cursor-grab" draggable onDragStart={handleDragStart} onClick={handleApply}>
                        <WeaveThumbnail weave={weave} faceMode={faceMode} showGrid={true} className="w-full h-full border-none rounded-none" />
                        <div className="absolute inset-0 bg-black/0 group-hover/preview:bg-black/10 transition-colors flex items-center justify-center">
                            <span className="opacity-0 group-hover/preview:opacity-100 bg-white/90 text-gray-900 text-[10px] font-bold px-3 py-1 rounded-full shadow-lg uppercase tracking-widest pointer-events-none transition-all transform translate-y-2 group-hover/preview:translate-y-0">Apply Unit</span>
                        </div>
                    </div>
                    <div className="p-3 border-t border-gray-100 bg-white">
                        <div className="flex justify-between items-start">
                            <div className="min-w-0">
                                <h3 className="font-bold text-gray-800 text-xs truncate uppercase tracking-tight">{weave.name}</h3>
                                <span className="text-[8px] text-gray-400 font-bold uppercase tracking-widest block mt-0.5">{weave.category}</span>
                            </div>
                            <button onClick={(e) => { e.stopPropagation(); setFaceMode(faceMode === 'face' ? 'back' : 'face'); }} className={`p-1.5 rounded-md border ${faceMode === 'back' ? 'bg-orange-50 text-orange-600' : 'text-gray-400'}`}><FlipIcon className="w-4 h-4" /></button>
                        </div>
                    </div>
                </div>
            ) : (
                <button draggable onDragStart={handleDragStart} onClick={handleApply} className={`flex ${layout === '1' ? 'flex-row items-center' : 'flex-col items-start'} p-2 bg-gray-50 border hover:border-blue-500 rounded-lg transition-all text-left w-full cursor-grab overflow-hidden gap-3`}>
                    <div className={`relative shrink-0 ${layout === '1' ? 'w-12 h-12' : 'w-full aspect-square'} pointer-events-none`}>
                        <WeaveThumbnail weave={weave} faceMode={faceMode} tile={layout === '2'} className="w-full h-full" />
                    </div>
                    <span className="text-[10px] font-bold text-gray-700 truncate w-full uppercase leading-tight block">{weave.name}</span>
                </button>
            )}
        </div>
    );
};

export const RightPanel: React.FC<RightPanelProps> = ({
    settings, onSettingsChange, dentingPattern, onDentingChange, onSnapshot, onLoadWeave,
    customWeaves, warpYarns, weftYarns, onUpdateWarpYarn, onUpdateWeftYarn, warpPatternString, setWarpPatternString, weftPatternString, setWeftPatternString, onOpenGridEditor,
    selectedColorIndex, onSelectColor, activeYarnId = 'A', selectedYarnType, onSelectYarn, forcedTab, onOpenPixelEditor
}) => {
    const [activeTab, setActiveTab] = useState<TabType>('construction');
    const [editingYarn, setEditingYarn] = useState<{ id: string, type: 'warp' | 'weft', def: YarnDefinition } | null>(null);
    const [weaveLayout, setWeaveLayout] = useState<'1' | '2' | '3'>('2');

    useEffect(() => { if (forcedTab) setActiveTab(forcedTab); }, [forcedTab]);

    const allWeaves = useMemo(() => [...WEAVE_LIBRARY, ...customWeaves], [customWeaves]);

    const colorMap = useMemo(() => {
        const map: {[key:string]: string} = {};
        Object.entries(warpYarns).forEach(([k,v]) => map[k] = v.color);
        Object.entries(weftYarns).forEach(([k,v]) => map[k] = v.color);
        return map;
    }, [warpYarns, weftYarns]);

    return (
        <>
            <div className="w-80 flex-shrink-0 bg-white border-l border-gray-200 flex flex-col z-20 shadow-xl overflow-hidden h-full">
                <div className="flex border-b border-gray-200 bg-gray-50 overflow-x-auto no-scrollbar shrink-0">
                    <TabButton id="construction" activeTab={activeTab} onClick={setActiveTab} icon={<LayersIcon className="w-5 h-5" />} label="Specs" />
                    <TabButton id="weave" activeTab={activeTab} onClick={setActiveTab} icon={<GridFillIcon className="w-5 h-5" />} label="Weave" />
                    <TabButton id="pattern" activeTab={activeTab} onClick={setActiveTab} icon={<GridIcon className="w-5 h-5" />} label="Pattern" />
                    <TabButton id="yarns" activeTab={activeTab} onClick={setActiveTab} icon={<ListIcon className="w-5 h-5" />} label="Yarns" />
                    <TabButton id="colors" activeTab={activeTab} onClick={setActiveTab} icon={<PaletteIcon className="w-5 h-5" />} label="Colors" />
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar p-5">
                    {activeTab === 'construction' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-6 border-b border-gray-100 pb-2">Global Settings</h2>
                            <SliderInput label="Warp Ends" value={settings.warpThreads} min={4} max={512} step={4} onChange={(v) => onSettingsChange({ ...settings, warpThreads: v })} />
                            <SliderInput label="Weft Picks" value={settings.weftPicks} min={4} max={512} step={4} onChange={(v) => onSettingsChange({ ...settings, weftPicks: v })} />
                            <SliderInput label="Ends/Inch" value={settings.epi} min={8} max={120} step={1} onChange={(v) => onSettingsChange({ ...settings, epi: v })} />
                            <SliderInput label="Picks/Inch" value={settings.ppi} min={8} max={120} step={1} onChange={(v) => onSettingsChange({ ...settings, ppi: v })} />
                            <div className="mt-4">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Denting Plan</label>
                                <input type="text" value={dentingPattern} onChange={(e) => onDentingChange(e.target.value)} className="w-full bg-gray-50 border border-gray-200 rounded p-2 text-sm font-mono focus:border-blue-500 focus:outline-none" />
                            </div>
                        </div>
                    )}

                    {activeTab === 'weave' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <div className="flex justify-between items-center mb-4">
                                <button onClick={onOpenPixelEditor} className="text-[10px] font-bold text-blue-600 uppercase tracking-widest border border-blue-200 px-2 py-1 rounded hover:bg-blue-50 transition-all">+ New Unit</button>
                                <div className="flex bg-gray-100 rounded p-0.5 border border-gray-200">
                                    <button onClick={() => setWeaveLayout('1')} className={`p-1 rounded transition-all ${weaveLayout === '1' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}><ListIcon className="w-3 h-3" /></button>
                                    <button onClick={() => setWeaveLayout('2')} className={`p-1 rounded transition-all ${weaveLayout === '2' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}><GridFillIcon className="w-3 h-3" /></button>
                                    <button onClick={() => setWeaveLayout('3')} className={`p-1 rounded transition-all ${weaveLayout === '3' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}><LayersIcon className="w-3 h-3" /></button>
                                </div>
                            </div>
                            <div className={`grid ${weaveLayout === '1' ? 'grid-cols-1' : (weaveLayout === '2' ? 'grid-cols-2' : 'grid-cols-1')} gap-3`}>
                                {allWeaves.map(weave => (
                                    /* Fix: Changed handleLoadWeave to onLoadWeave as handleLoadWeave is not defined in scope */
                                    <LibraryItem key={weave.id} weave={weave} onSnapshot={onSnapshot} onLoadWeave={onLoadWeave} layout={weaveLayout} />
                                ))}
                            </div>
                        </div>
                    )}

                    {activeTab === 'pattern' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200 space-y-6">
                            <TextPatternEditor title="Warp Sequence" value={warpPatternString} onValueChange={setWarpPatternString} colorMap={colorMap} onOpenGridEditor={() => onOpenGridEditor('warp')} />
                            <TextPatternEditor title="Weft Sequence" value={weftPatternString} onValueChange={setWeftPatternString} colorMap={colorMap} onOpenGridEditor={() => onOpenGridEditor('weft')} />
                        </div>
                    )}

                    {activeTab === 'yarns' && (
