                                        {appliedWeaves[idx] && (
                                            <div className="absolute inset-0 rounded-md overflow-hidden bg-black/40 flex items-center justify-center">
                                                <WeaveThumbnail weave={appliedWeaves[idx]} className="w-full h-full opacity-70" />
                                            </div>
                                        )}
                                    </div>
                                    <span className="text-[8px] font-mono text-gray-500 uppercase truncate max-w-[64px]">{appliedWeaves[idx] ? appliedWeaves[idx].name : color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end shrink-0"><span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drag weave to apply</span><button onClick={() => setArtwork(null)} className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded font-bold uppercase">Clear Art</button></div>
                    </div>
                )}
            </div>

            <RightPanel 
                settings={settings} onSettingsChange={(s) => { saveHistory(); setSettings(s); }} dentingPattern={dentingPattern} onDentingChange={setDentingPattern} onSnapshot={saveHistory} onLoadWeave={()=>{}} 
                customWeaves={customWeaves} onAddWeave={()=>{}} onUpdateWeave={()=>{}} onDeleteWeave={()=>{}} 
                warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(id, d) => { saveHistory(); setWarpYarns(p => ({...p, [id]: d})); }} onUpdateWeftYarn={(id, d) => { saveHistory(); setWeftYarns(p => ({...p, [id]: d})); }} paletteColors={PANTONE_PALETTE} warpPatternString={warpPatternString} setWarpPatternString={(s) => { saveHistory(); setWarpPatternString(s); }} weftPatternString={weftPatternString} setWeftPatternString={(s) => { saveHistory(); setWeftPatternString(s); }} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{} as any} onApplyGenerated={()=>{}} onSimulate={() => setShowSimModal(true)} onGridOperation={(t, a) => { saveHistory(); const newData = new Uint8Array(jacquardData.structure); if (a === 'clear') newData.fill(0); else if (a === 'invert') for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1; setJacquardData(prev => ({ ...prev, structure: newData })); }} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { setActiveYarnId(id); setSelectedYarnType(type); setAppMode('yarn'); }}
                onOpenPixelEditor={() => setShowCustomModal(true)}
            />
        </div>

        <FabricSimulationModal isOpen={showSimModal} onClose={() => setShowSimModal(false)} weavePattern={simData.colors} structure={simData.structure} epi={settings.epi} ppi={settings.ppi} dentingPlan={dentingPattern.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n))} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode } from '../types';

interface JacquardCanvasProps {
    data: JacquardData;
    artwork?: {
        data: Uint8Array;
        palette: string[];
        width: number;
        height: number;
    };
    onUpdate: (newData: Uint8Array) => void;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    epi: number;
    ppi: number;
    gridX: number;
    gridY: number;
}

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, artwork, onUpdate, tool, viewMode, faceMode, warpColors, weftColors, epi, ppi, gridX, gridY
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const [view, setView] = useState({ x: 40, y: 40, zoom: 1.0 }); 
    const [hoverPos, setHoverPos] = useState({ x: 0, y: 0 });
    const [isSpacePressed, setIsSpacePressed] = useState(false);

    const isInteracting = useRef(false);
    const lastMousePos = useRef({ x: 0, y: 0 });
    const lastGridPos = useRef({ x: -1, y: -1 });
    const localBuffer = useRef<Uint8Array>(data.structure);

    useEffect(() => {
        localBuffer.current = data.structure;
        render();
    }, [data.structure]);

    const HEADER_SIZE = 28; // Increased slightly for numbering

    const render = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        if (canvas.width !== w || canvas.height !== h) {
            canvas.width = w; canvas.height = h;
        }

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        // In graph mode, aspect is 1:1 (Square Pixels)
        const aspect = viewMode === 'graph' ? 1.0 : (epi / ppi);
        const cellW = zoom;
        const cellH = zoom * aspect;

        const startX = Math.floor((HEADER_SIZE - view.x) / cellW);
        const startY = Math.floor((HEADER_SIZE - view.y) / cellH);
        const endX = Math.min(data.width, startX + Math.ceil((w - HEADER_SIZE) / cellW) + 1);
        const endY = Math.min(data.height, startY + Math.ceil((h - HEADER_SIZE) / cellH) + 1);

        const isArtworkView = viewMode === 'structure';
        const isGraphView = viewMode === 'graph';
        const isReverse = faceMode === 'reverse';
        const buffer = localBuffer.current;

        // 1. Render Design Grid
        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * data.width + x;

                if (isGraphView) {
                    // Technical Graph: Pure Black and White
                    ctx.fillStyle = buffer[idx] === 1 ? '#000000' : '#ffffff';
                } else if (isArtworkView && artwork) {
                    // Artwork Mode: Colors from bitmap
                    ctx.fillStyle = artwork.palette[artwork.data[idx]] || '#000';
                } else {
                    // Interlace Mode: Colors from yarns
                    let val = buffer[idx] === 1;
                    if (isReverse) val = !val;
                    ctx.fillStyle = val ? warpColors[x % warpColors.length] : weftColors[y % weftColors.length];
                }

                ctx.fillRect(
                    Math.floor(view.x + x * cellW), 
                    Math.floor(view.y + y * cellH), 
                    Math.ceil(cellW), 
                    Math.ceil(cellH)
                );
            }
        }

        // 2. Render Headers
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, w, HEADER_SIZE); 
        ctx.fillRect(0, 0, HEADER_SIZE, h); 

        // RULER SETTINGS
        ctx.font = '9px "JetBrains Mono", monospace';
        ctx.textBaseline = 'top';
        const step = zoom < 2 ? 50 : (zoom < 8 ? 20 : 8);

        // Warp Bar (Hook Numbers)
        for (let x = Math.max(0, startX); x < endX; x++) {
            const px = Math.floor(view.x + x * cellW);
            ctx.fillStyle = warpColors[x % warpColors.length] || '#888';
            ctx.fillRect(px, 0, Math.ceil(cellW), 14); // Top half for color

            // Numbering
            if (x % step === 0 || x === 0) {
                ctx.fillStyle = '#94a3b8';
                ctx.fillText((x + 1).toString(), px + 2, 16);
                ctx.beginPath();
                ctx.moveTo(px, 14);
                ctx.lineTo(px, HEADER_SIZE);
                ctx.strokeStyle = 'rgba(148, 163, 184, 0.3)';
                ctx.stroke();
            }
        }

        // Current Hover Indicator (Top)
        const wx = Math.floor(view.x + hoverPos.x * cellW);
        if (wx >= HEADER_SIZE && wx < w) {
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(wx, 14 - 3, Math.ceil(cellW), 3);
        }

        // Weft Bar (Pick Numbers)
        ctx.textAlign = 'right';
        for (let y = Math.max(0, startY); y < endY; y++) {
            const py = Math.floor(view.y + y * cellH);
            ctx.fillStyle = weftColors[y % weftColors.length] || '#888';
            ctx.fillRect(0, py, 14, Math.ceil(cellH)); // Left half for color

            // Numbering
            if (y % step === 0 || y === 0) {
                ctx.fillStyle = '#94a3b8';
                ctx.fillText((y + 1).toString(), HEADER_SIZE - 2, py + 2);
                ctx.beginPath();
                ctx.moveTo(14, py);
                ctx.lineTo(HEADER_SIZE, py);
                ctx.strokeStyle = 'rgba(148, 163, 184, 0.3)';
                ctx.stroke();
            }
        }
        ctx.textAlign = 'left';

        // Current Hover Indicator (Left)
        const wy = Math.floor(view.y + hoverPos.y * cellH);
        if (wy >= HEADER_SIZE && wy < h) {
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(14 - 3, wy, 3, Math.ceil(cellH));
        }

        // Corner Block
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, HEADER_SIZE, HEADER_SIZE);
        ctx.strokeStyle = '#334155';
        ctx.strokeRect(0, 0, HEADER_SIZE, HEADER_SIZE);
        ctx.fillStyle = '#475569';
        ctx.font = '8px bold monospace';
        ctx.fillText('H/P', 4, 8);

        // 3. Technical Grid (Activate only at 400% zoom)
        if (zoom >= 4.0) {
            ctx.beginPath();
            // Vertical Lines
            for (let x = Math.max(0, startX); x <= endX; x++) {
                const px = view.x + x * cellW;
                const isMajor = x % gridX === 0;
                ctx.strokeStyle = isMajor ? 'rgba(45, 90, 80, 0.8)' : 'rgba(60, 100, 90, 0.2)';
                ctx.lineWidth = isMajor ? 2 : 0.5;
                ctx.moveTo(px, HEADER_SIZE);
                ctx.lineTo(px, h);
                ctx.stroke();
                ctx.beginPath();
            }
            // Horizontal Lines
            for (let y = Math.max(0, startY); y <= endY; y++) {
                const py = view.y + y * cellH;
                const isMajor = y % gridY === 0;
                ctx.strokeStyle = isMajor ? 'rgba(45, 90, 80, 0.8)' : 'rgba(60, 100, 90, 0.2)';
                ctx.lineWidth = isMajor ? 2 : 0.5;
                ctx.moveTo(HEADER_SIZE, py);
                ctx.lineTo(w, py);
                ctx.stroke();
                ctx.beginPath();
            }
        }
    }, [view, viewMode, faceMode, warpColors, weftColors, artwork, hoverPos, data.width, data.height, epi, ppi, gridX, gridY]);

    useEffect(() => { render(); }, [render]);

    useEffect(() => {
        const onDown = (e: KeyboardEvent) => { if (e.code === 'Space') { setIsSpacePressed(true); if (e.target === document.body) e.preventDefault(); } };
        const onUp = (e: KeyboardEvent) => { if (e.code === 'Space') setIsSpacePressed(false); };
        window.addEventListener('keydown', onDown);
        window.addEventListener('keyup', onUp);
        return () => { window.removeEventListener('keydown', onDown); window.removeEventListener('keyup', onUp); };
    }, []);

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;
        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        const aspect = viewMode === 'graph' ? 1.0 : (epi / ppi);

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const direction = wheelEv.deltaY > 0 ? -1 : 1;
            const zoomStep = 0.25;
            const newZoom = Math.min(64, Math.max(0.5, view.zoom + direction * zoomStep));

            if (newZoom !== view.zoom) {
                const worldX = (mouseX - view.x) / view.zoom;
                const worldY = (mouseY - view.y) / (view.zoom * aspect);
                setView({ x: mouseX - worldX * newZoom, y: mouseY - worldY * (newZoom * aspect), zoom: newZoom });
            }
            return;
        }

        const gridXPos = Math.floor((mouseX - view.x) / view.zoom);
        const gridYPos = Math.floor((mouseY - view.y) / (view.zoom * aspect));

        if (e.type === 'mousemove') {
            setHoverPos({ x: Math.max(0, Math.min(data.width - 1, gridXPos)), y: Math.max(0, Math.min(data.height - 1, gridYPos)) });
        }

        const isPanActive = isSpacePressed;

        if (isPanActive) {
            if (e.type === 'mousedown') {
                isInteracting.current = true;
                lastMousePos.current = { x: mouseX, y: mouseY };
            } else if (e.type === 'mousemove' && isInteracting.current) {
                const dx = mouseX - lastMousePos.current.x;
                const dy = mouseY - lastMousePos.current.y;
                setView(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
                lastMousePos.current = { x: mouseX, y: mouseY };
            } else {
                isInteracting.current = false;
            }
            return;
        }

        if (e.type === 'mousedown') {
            isInteracting.current = true;
            if (gridXPos >= 0 && gridXPos < data.width && gridYPos >= 0 && gridYPos < data.height) {
                localBuffer.current[gridYPos * data.width + gridXPos] = localBuffer.current[gridYPos * data.width + gridXPos] === 1 ? 0 : 1;
                lastGridPos.current = { x: gridXPos, y: gridYPos }; 
                render();
            }
        } else if (e.type === 'mousemove' && isInteracting.current) {
            if (gridXPos >= 0 && gridXPos < data.width && gridYPos >= 0 && gridYPos < data.height && (gridXPos !== lastGridPos.current.x || gridYPos !== lastGridPos.current.y)) {
                localBuffer.current[gridYPos * data.width + gridXPos] = 1; 
                lastGridPos.current = { x: gridXPos, y: gridYPos }; 
                render();
            }
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            if (isInteracting.current && !isPanActive) {
                isInteracting.current = false;
                onUpdate(new Uint8Array(localBuffer.current));
            } else {
                isInteracting.current = false;
            }
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden select-none relative">
            <canvas 
                ref={canvasRef} 
                onMouseDown={handleInteraction} 
                onMouseMove={handleInteraction} 
                onMouseUp={handleInteraction} 
                onMouseLeave={handleInteraction} 
                onWheel={handleInteraction} 
                className={`block ${isSpacePressed ? 'cursor-grabbing' : ''}`} 
            />
            <div className="absolute bottom-4 left-4 flex gap-2 pointer-events-none">
                <div className="bg-black/80 px-3 py-1 rounded text-[10px] font-mono text-blue-400 border border-blue-900/50 uppercase tracking-tighter flex items-center gap-4 shadow-xl">
                    <span>MODE: {isSpacePressed ? 'PAN' : tool.toUpperCase()} | VIEW: {viewMode.toUpperCase()} | ZOOM: {Math.round(view.zoom * 100)}%</span>
                    <span className="text-gray-400 border-l border-gray-800 pl-4">HOOKS: <span className="text-white font-bold">{hoverPos.x + 1}</span> | PICKS: <span className="text-white font-bold">{hoverPos.y + 1}</span></span>
                </div>
            </div>
            {isSpacePressed && (
                <div className="absolute inset-0 bg-white/5 pointer-events-none flex items-center justify-center">
                    <div className="bg-black/70 text-white px-6 py-3 rounded-full font-bold text-sm uppercase tracking-widest shadow-2xl border border-white/20">
                        Space + Drag to Pan
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useEffect, useState, useRef, MouseEvent, WheelEvent } from 'react';
import { ZoomInIcon, ZoomOutIcon, ResetZoomIcon, ChevronDownIcon, DownloadIcon, FlipIcon, RulerIcon, CubeIcon, EyeOffIcon, EyeIcon, MagicWandIcon } from './icons';
import { YarnDefinition, DensityZone } from '../types';
import { renderFabricToCanvas } from '../services/fabricRenderer';
import { Fabric3DStudio } from './Fabric3DStudio';

interface FabricSimulationModalProps {
  isOpen: boolean;
  onClose: () => void;
  weavePattern: string[][];
  structure: boolean[][]; 
  epi: number;
  ppi: number;
  dentingPlan?: number[];
  weftZones?: DensityZone[];
  warpYarns: { [key: string]: YarnDefinition };
  weftYarns: { [key: string]: YarnDefinition };
  warpYarnSequence: string[];
  weftYarnSequence: string[];
  embedded?: boolean; 
}

const SVGRuler: React.FC<{
    orientation: 'horizontal' | 'vertical';
    viewportSize: number;
    zoom: number;
    pan: number;
    unit: 'inch' | 'cm';
}> = ({ orientation, viewportSize, zoom, pan, unit }) => {
    const pixelsPerUnit = unit === 'inch' ? 96 : (96 / 2.54);
    const scaledPixelsPerUnit = pixelsPerUnit * zoom;
    const divisions = unit === 'inch' ? 8 : 10;

    const ticks = [];
    const startIndex = Math.floor(-pan / scaledPixelsPerUnit);
    const numUnits = Math.ceil(viewportSize / scaledPixelsPerUnit) + 2;

    for (let i = 0; i < numUnits; i++) {
        const unitIndex = startIndex + i;
        const basePos = pan + (unitIndex * scaledPixelsPerUnit);

        if (basePos < -scaledPixelsPerUnit || basePos > viewportSize + scaledPixelsPerUnit) continue;

        // Major Tick
        ticks.push(
            <g key={`unit-${unitIndex}`} transform={orientation === 'horizontal' ? `translate(${basePos}, 0)` : `translate(0, ${basePos})`}>
                <line 
                    x1="0.5" y1="0.5" 
                    x2={orientation === 'horizontal' ? "0.5" : "15"} 
                    y2={orientation === 'horizontal' ? "15" : "0.5"} 
                    stroke="currentColor" strokeWidth="1.2" 
                />
                <text 
                    x={orientation === 'horizontal' ? "4" : "12"} 
                    y={orientation === 'horizontal' ? "12" : "3"} 
                    fontSize="9" fontWeight="bold" 
                    textAnchor={orientation === 'horizontal' ? "start" : "end"}
                    className="fill-gray-500 font-sans select-none"
                    transform={orientation === 'vertical' ? `rotate(-90 12 3)` : ''}
                >
                    {unitIndex}
                </text>

                {/* Sub-divisions */}
                {Array.from({ length: divisions - 1 }).map((_, j) => {
                    const subPos = (j + 1) * (scaledPixelsPerUnit / divisions);
                    const isHalf = (j + 1) === Math.floor(divisions / 2);
                    const h = isHalf ? 10 : 5;
                    return (
                        <line 
                            key={`sub-${unitIndex}-${j}`}
                            x1={orientation === 'horizontal' ? subPos : "0"} 
                            y1={orientation === 'horizontal' ? "0" : subPos}
                            x2={orientation === 'horizontal' ? subPos : h} 
                            y2={orientation === 'horizontal' ? h : subPos}
                            stroke="currentColor" strokeWidth="0.5"
                            className="text-gray-300"
                        />
                    );
                })}
            </g>
        );
    }

    return (
        <svg 
            className={`absolute z-30 pointer-events-none bg-white/95 backdrop-blur-sm border-gray-200 text-gray-400 ${orientation === 'horizontal' ? 'w-full h-6 border-b left-0 top-0' : 'h-full w-6 border-r left-0 top-0'}`}
        >
            {ticks}
        </svg>
    );
};

export const FabricSimulationModal: React.FC<FabricSimulationModalProps> = ({
  isOpen, onClose, weavePattern, structure, epi, ppi, dentingPlan, weftZones,
  warpYarns, weftYarns, warpYarnSequence, weftYarnSequence, embedded
}) => {
  const [dataUrl, setDataUrl] = useState<string>('');
  const [simulationDpi, setSimulationDpi] = useState<number>(144); 
  const [smoothing, setSmoothing] = useState<'high' | 'medium' | 'low' | 'none'>('high');
  const [viewSide, setViewSide] = useState<'face' | 'back'>('face');
  const [bgMode, setBgMode] = useState<'dark' | 'light'>('dark');
  const [rulerUnit, setRulerUnit] = useState<'inch' | 'cm' | 'none'>('inch');
  const [activeTab, setActiveTab] = useState<'2d' | '3d'>('2d');
  const [hideFloats, setHideFloats] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isSmoothingMenuOpen, setIsSmoothingMenuOpen] = useState(false);

  const [transform, setTransform] = useState({ scale: 1.24, rotate: 0, x: 0, y: 0 }); 
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });
  const [viewportSize, setViewportSize] = useState({ w: 0, h: 0 });

  const viewportRef = useRef<HTMLDivElement>(null);
  const DISPLAY_WIDTH = 1200;
  const DISPLAY_HEIGHT = 720;

  useEffect(() => {
    if (!isOpen || activeTab !== '2d') return;
    const updateSize = () => {
        if (viewportRef.current) {
            setViewportSize({
                w: viewportRef.current.clientWidth,
                h: viewportRef.current.clientHeight
            });
        }
    };
    updateSize();
    window.addEventListener('resize', updateSize);
    return () => window.removeEventListener('resize', updateSize);
  }, [isOpen, activeTab]);

  useEffect(() => {
    if (!isOpen || !weavePattern.length || !weavePattern[0].length) return;

    setIsGenerating(true);
    const timer = setTimeout(() => {
        requestAnimationFrame(() => {
            const canvas = renderFabricToCanvas({
                weavePattern,
                structure,
                epi,
                ppi,
                dentingPlan,
                weftZones,
                warpYarns,
                weftYarns,
                warpYarnSequence,
                weftYarnSequence,
                viewSide,
                dpi: simulationDpi,
                smoothingQuality: smoothing,
                width: DISPLAY_WIDTH,
                height: DISPLAY_HEIGHT,
                hideFloats: hideFloats,
                backgroundColor: bgMode === 'dark' ? '#050505' : '#ffffff'
            });
            setDataUrl(canvas.toDataURL());
            setIsGenerating(false);
        });
    }, 100);

    return () => clearTimeout(timer);
  }, [isOpen, weavePattern, structure, epi, ppi, dentingPlan, weftZones, warpYarns, weftYarns, warpYarnSequence, weftYarnSequence, simulationDpi, smoothing, viewSide, hideFloats, bgMode]);

  const handleDownload = () => {
      if (!dataUrl) return;
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `fabric-simulation-${epi}epi-${ppi}ppi.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleWheel = (e: WheelEvent) => { 
      e.stopPropagation(); 
      e.preventDefault(); 
      const zoomStep = 0.20;
      const direction = e.deltaY > 0 ? -1 : 1;
      const newScale = Math.min(Math.max(transform.scale + (direction * zoomStep), 0.1), 5);
      setTransform(prev => ({ ...prev, scale: Math.round(newScale * 100) / 100 })); 
  };

  const handleMouseDown = (e: MouseEvent) => { 
      if (e.button === 0) {
          e.preventDefault(); 
          setIsDragging(true); 
          setLastMousePos({ x: e.clientX, y: e.clientY });
      }
  };

  const handleMouseMove = (e: MouseEvent) => { 
      if (!isDragging) return; 
      e.preventDefault(); 
      const dx = e.clientX - lastMousePos.x; 
      const dy = e.clientY - lastMousePos.y; 
      setTransform(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy })); 
      setLastMousePos({ x: e.clientX, y: e.clientY }); 
  };

  const handleMouseUp = () => { setIsDragging(false); };

  const handleReset = () => { 
      setTransform({ scale: 1.24, rotate: 0, x: 0, y: 0 }); 
  };

  const handlePrintSize = () => {
      setTransform({ scale: 0.84, rotate: 0, x: 0, y: 0 });
  };

  const smoothingOptions: ('high' | 'medium' | 'low' | 'none')[] = ['high', 'medium', 'low', 'none'];

  const rulerPanX = (viewportSize.w / 2) + transform.x - (DISPLAY_WIDTH * transform.scale / 2);
  const rulerPanY = (viewportSize.h / 2) + transform.y - (DISPLAY_HEIGHT * transform.scale / 2);

  if (!isOpen) return null;

  return (
    <div className={embedded ? "w-full h-full flex flex-col bg-gray-900 overflow-hidden" : "fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-in fade-in duration-200"}>
      <div className={embedded ? "flex flex-col flex-1 overflow-hidden" : "bg-gray-900 border border-gray-700 rounded-lg shadow-2xl w-full max-w-[95vw] h-[90vh] flex flex-col overflow-hidden"}>

        <div className="flex items-center justify-between p-4 border-b border-gray-800 bg-gray-900 shrink-0">
          <div className="flex items-center gap-6">
              <div>
                <h2 className="text-xl font-bold text-white tracking-tight">Fabric Simulation</h2>
                <p className="text-xs text-gray-400 font-mono mt-1">{epi} EPI × {ppi} PPI</p>
              </div>

              <div className="flex items-center bg-gray-800 rounded-lg p-1 border border-gray-700">
                  <button onClick={() => setActiveTab('2d')} className={`px-4 py-1.5 text-xs font-bold rounded transition-all ${activeTab === '2d' ? 'bg-gray-700 text-white shadow-sm' : 'text-gray-400 hover:text-white'}`}>2D View</button>
                  <button onClick={() => setActiveTab('3d')} className={`px-4 py-1.5 text-xs font-bold rounded transition-all ${activeTab === '3d' ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400 hover:text-white'}`}>3D View</button>
              </div>

              {activeTab === '2d' && (
                  <div className="flex items-center gap-4 border-l border-gray-800 pl-4 ml-2">
                        <button
                            onClick={() => setHideFloats(!hideFloats)}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs font-bold transition-all ${hideFloats ? 'bg-red-900/50 border-red-700 text-red-200' : 'bg-gray-800 border-gray-700 text-gray-300 hover:bg-gray-700'}`}
                        >
                            {hideFloats ? <EyeOffIcon className="w-4 h-4" /> : <EyeIcon className="w-4 h-4" />}
                            <span>{hideFloats ? 'Hidden Floats' : 'Visible Floats'}</span>
                        </button>

                        <button
                            onClick={() => setViewSide(prev => prev === 'face' ? 'back' : 'face')}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs font-bold transition-all ${viewSide === 'back' ? 'bg-orange-900/50 border-orange-700 text-orange-200' : 'bg-gray-800 border-gray-700 text-gray-300 hover:bg-gray-700'}`}
                        >
                            <FlipIcon className="w-4 h-4" />
                            <span>{viewSide === 'face' ? 'Face' : 'Back'}</span>
                        </button>

                        <div className="relative">
                            <button onClick={() => setIsSmoothingMenuOpen(!isSmoothingMenuOpen)} className="flex items-center gap-2 px-3 py-1.5 bg-gray-800 border border-gray-700 rounded-md text-xs font-bold text-gray-200 hover:bg-gray-700 transition-colors">
                                Smoothing: {smoothing.toUpperCase()} <ChevronDownIcon className="w-3 h-3 text-gray-400" />
                            </button>
                            {isSmoothingMenuOpen && (
                                <div className="absolute top-full left-0 mt-2 w-32 bg-gray-800 border border-gray-700 rounded shadow-xl overflow-hidden z-50">
                                    {smoothingOptions.map(opt => (
                                        <button key={opt} onClick={() => { setSmoothing(opt); setIsSmoothingMenuOpen(false); }} className={`w-full text-left px-4 py-2 text-xs font-medium hover:bg-gray-700 ${smoothing === opt ? 'text-blue-400' : 'text-gray-300'}`}>{opt.toUpperCase()}</button>
                                    ))}
                                </div>
                            )}
                        </div>

                        {/* TEMPORARY FEATURE: Manual DPI Input */}
                        <div className="flex items-center bg-gray-800 border border-gray-700 rounded-md overflow-hidden group">
                            <div className="pl-3 py-1.5 text-gray-500">
                                <MagicWandIcon className="w-3.5 h-3.5" />
                            </div>
                            <input 
                                type="number" 
                                value={simulationDpi} 
                                onChange={(e) => setSimulationDpi(parseInt(e.target.value) || 72)}
                                className="w-20 bg-transparent border-none text-xs font-bold text-blue-400 px-2 focus:ring-0 focus:outline-none"
                                title="Manual DPI Render (Test Feature)"
                            />
                            <div className="text-[9px] font-black text-gray-500 pr-3 uppercase tracking-tighter">DPI</div>
                        </div>
                  </div>
              )}
          </div>
          {!embedded && <button onClick={onClose} className="text-gray-400 hover:text-white p-2 rounded-full hover:bg-gray-800 transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>}
        </div>

        <div className="flex-1 bg-gray-950 overflow-hidden relative flex items-center justify-center p-0">
             {activeTab === '3d' ? (
                 <Fabric3DStudio weavePattern={weavePattern} structure={structure} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={warpYarnSequence} weftYarnSequence={weftYarnSequence} textureUrl={dataUrl} epi={epi} ppi={ppi} />
             ) : (
                 <div className="w-full h-full relative overflow-hidden flex flex-col" ref={viewportRef}>
                    {/* Viewport Area */}
                    <div 
                        className={`flex-1 relative flex items-center justify-center ${isDragging ? 'cursor-grabbing' : 'cursor-grab'}`} 
                        onWheel={handleWheel} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}
                    >
                        {/* SVG Rulers */}
                        {rulerUnit !== 'none' && (
                            <>
                                <SVGRuler orientation="horizontal" viewportSize={viewportSize.w} zoom={transform.scale} pan={rulerPanX} unit={rulerUnit as any} />
                                <SVGRuler orientation="vertical" viewportSize={viewportSize.h} zoom={transform.scale} pan={rulerPanY} unit={rulerUnit as any} />
                            </>
                        )}

                        <div 
                            className={`shadow-2xl shadow-black ring-1 ring-white/10 relative z-10 transition-transform ${isDragging ? 'duration-0' : 'duration-150'} ${bgMode === 'dark' ? 'bg-[#050505]' : 'bg-white'}`} 
                            style={{ 
                                width: `${DISPLAY_WIDTH}px`, 
                                height: `${DISPLAY_HEIGHT}px`, 
                                transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) translateZ(0)`, 
                                transformOrigin: 'center center',
                                imageRendering: 'auto',
                                backfaceVisibility: 'hidden'
                            }}
                        >
                            {isGenerating && <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/50 backdrop-blur-sm"><div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-2"></div><span className="text-white font-medium text-sm">Weaving...</span></div>}
                            {dataUrl && <img src={dataUrl} alt="Fabric Simulation" className="w-full h-full object-cover" style={{ pointerEvents: 'none', display: 'block', width: `${DISPLAY_WIDTH}px`, height: `${DISPLAY_HEIGHT}px` }} />}
                        </div>
                    </div>

                    {/* Simulation Toolbar */}
                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-gray-800/90 backdrop-blur-md p-1.5 rounded-lg border border-gray-700 shadow-2xl z-40 flex items-center gap-1">
                        <button onClick={() => setTransform(prev => ({...prev, scale: Math.round(Math.max(0.1, prev.scale - 0.20) * 100) / 100}))} className="p-2 text-gray-300 hover:text-white hover:bg-gray-700 rounded"><ZoomOutIcon className="w-5 h-5"/></button>
                        <button onClick={handlePrintSize} className="px-3 py-1.5 text-[10px] font-bold text-blue-400 hover:bg-gray-700 rounded transition-colors uppercase tracking-widest border border-blue-900/30">Print Size</button>
                        <div className="px-2 min-w-[3.5rem] text-center text-[11px] font-mono font-bold text-white select-none">{Math.round(transform.scale * 100)}%</div>
                        <button onClick={() => setTransform(prev => ({...prev, scale: Math.round(Math.min(5, prev.scale + 0.20) * 100) / 100}))} className="p-2 text-gray-300 hover:text-white hover:bg-gray-700 rounded"><ZoomInIcon className="w-5 h-5"/></button>
                        <button onClick={handleReset} className="p-2 text-gray-300 hover:text-white hover:bg-gray-700 rounded"><ResetZoomIcon className="w-5 h-5"/></button>
                        <div className="w-px h-6 bg-gray-600 mx-1"></div>
                        <button onClick={handleDownload} className="p-2 text-blue-400 hover:text-white hover:bg-blue-600 rounded"><DownloadIcon className="w-5 h-5"/></button>
                        <div className="w-px h-6 bg-gray-600 mx-1"></div>
                        <button onClick={() => setRulerUnit(prev => prev === 'inch' ? 'cm' : (prev === 'cm' ? 'none' : 'inch'))} className={`p-2 rounded ${rulerUnit !== 'none' ? 'text-blue-400 bg-blue-900/20' : 'text-gray-400'}`} title="Toggle Ruler"><RulerIcon className="w-5 h-5"/></button>
                    </div>
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

