const LibraryItem: React.FC<{
    weave: LibraryWeave;
    onSnapshot: () => void;
    onLoadWeave: (weave: LibraryWeave) => void;
    layout: '1' | '2' | '3';
}> = ({ weave, onSnapshot, onLoadWeave, layout }) => {
    const handleLoad = () => {
        onSnapshot();
        onLoadWeave(weave);
    };

    if (layout === '3') {
        return (
            <div 
                onClick={handleLoad}
                className="bg-white border border-gray-100 rounded-xl p-3 flex items-center gap-4 hover:border-blue-500 hover:shadow-md cursor-pointer transition-all group"
            >
                <WeaveThumbnail weave={weave} className="w-16 h-16 shrink-0" />
                <div className="flex-1 min-w-0">
                    <h4 className="text-xs font-bold text-gray-800 truncate uppercase tracking-tight">{weave.name}</h4>
                    <p className="text-[10px] text-gray-400 font-medium uppercase tracking-widest">{weave.category}</p>
                </div>
                <div className="text-[10px] font-black text-blue-600 bg-blue-50 px-2 py-1 rounded-md">{weave.harnesses}H</div>
            </div>
        );
    }

    return (
        <div 
            onClick={handleLoad}
            className={`group bg-white border border-gray-100 rounded-xl overflow-hidden cursor-pointer hover:border-blue-500 hover:shadow-lg transition-all flex flex-col ${layout === '1' ? 'h-auto' : 'aspect-square'}`}
        >
            <div className="flex-1 relative bg-gray-50 overflow-hidden">
                <WeaveThumbnail weave={weave} className="w-full h-full border-none" tile={layout === '2'} />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 transition-colors" />
            </div>
            <div className="p-2 border-t border-gray-50 flex flex-col">
                <div className="flex justify-between items-center gap-1">
                    <span className="text-[9px] font-black text-gray-800 uppercase truncate" title={weave.name}>{weave.name}</span>
                    <span className="text-[8px] font-bold text-blue-500 shrink-0">{weave.harnesses}H</span>
                </div>
