const ZoomNavigator: React.FC<{ data: JacquardData, view: { x: number, y: number, zoom: number }, settings: WeaveSettings }> = ({ data, view, settings }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const NAV_SIZE = 240;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const { width, height, structure } = data;
        canvas.width = width;
        canvas.height = height;

        const imgData = ctx.createImageData(width, height);
        for (let i = 0; i < structure.length; i++) {
            const val = structure[i] === 1 ? 0 : 255;
            imgData.data[i * 4] = val;
            imgData.data[i * 4 + 1] = val;
            imgData.data[i * 4 + 2] = val;
            imgData.data[i * 4 + 3] = 255;
        }
        ctx.putImageData(imgData, 0, 0);

        // Simple float detection for mini-map
        ctx.globalAlpha = 0.5;
        ctx.fillStyle = '#ef4444';
        // (Float detection logic logic simplified for mini-map)
    }, [data, settings.warpFloatThreshold, settings.weftFloatThreshold]);

    return (
        <div className="bg-gray-900 border border-gray-800 rounded-xl overflow-hidden relative shadow-inner" style={{ width: NAV_SIZE, height: NAV_SIZE }}>
            <canvas ref={canvasRef} className="w-full h-full image-pixelated" />
            <div className="absolute top-2 left-2 bg-black/60 px-2 py-0.5 rounded text-[8px] font-black text-gray-400 uppercase tracking-widest">Global Map</div>
        </div>
    );
};

