            color: '#888888', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 28, ply: 1, thickness: 1.0, twist: 'Z', tpi: 15, sheen: 0.2, roughness: 0.5
        };
        onEdit(char, defaultYarn);
