      bindingDepth: 0.05
  });

  const defaultWarp: { [key: string]: YarnDefinition } = { 'A': createDefaultYarn(PANTONE_PALETTE[42]), 'B': createDefaultYarn(PANTONE_PALETTE[0]) };
  const defaultWeft: { [key: string]: YarnDefinition } = { 'A': createDefaultYarn(PANTONE_PALETTE[0]), 'B': createDefaultYarn(PANTONE_PALETTE[38]) };

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>(defaultWarp);
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>(defaultWeft);

  const [colorways, setColorways] = useState<Colorway[]>([]);

  const warpColors = useMemo(() => {
      const map: {[key:string]: string} = {};
      Object.entries(warpYarns).forEach(([k,v]) => { if(v) map[k] = v.color; });
      return map;
  }, [warpYarns]);

  const weftColors = useMemo(() => {
      const map: {[key:string]: string} = {};
      Object.entries(weftYarns).forEach(([k,v]) => { if(v) map[k] = v.color; });
      return map;
  }, [weftYarns]);

  const [activeYarnId, setActiveYarnId] = useState<string>('A');
  const [selectedYarnType, setSelectedYarnType] = useState<'warp' | 'weft'>('warp');
  const [studioYarnDef, setStudioYarnDef] = useState<YarnDefinition>(defaultWarp['A']);

  useEffect(() => {
      const source = selectedYarnType === 'warp' ? warpYarns : weftYarns;
      if (source[activeYarnId]) {
          setStudioYarnDef(source[activeYarnId]);
      }
  }, [activeYarnId, selectedYarnType, warpYarns, weftYarns]); 

  const [warpPatternString, setWarpPatternString] = useState('8A8B');
  const [weftPatternString, setWeftPatternString] = useState('8A8B');
  const [weftZones, setWeftZones] = useState<DensityZone[]>([]);

  const [dentingPatternString, setDentingPatternString] = useState('2');
  const [dentingPlan, setDentingPlan] = useState<number[]>(() => Array(8).fill(2));

  const [draft, setDraft] = useState<boolean[][]>(() => Array.from({ length: 8 }, (_, h) => Array.from({ length: 16 }, (_, w) => (w % 8) === h)));
  const [pegPlan, setPegPlan] = useState<boolean[][]>(() => Array.from({ length: 16 }, (_, p) => Array.from({ length: 8 }, (_, h) => ((p + h) % 4 < 2))));

  const [history, setHistory] = useState<{ past: HistoryState[], future: HistoryState[] }>({ past: [], future: [] });

  const copyGrid = (grid: boolean[][]) => grid.map(row => [...row]);

  const saveHistory = useCallback(() => {
    setHistory(prev => {
        const currentSnapshot: HistoryState = {
            draft: copyGrid(draft), pegPlan: copyGrid(pegPlan), warpPatternString, weftPatternString, dentingPatternString, dentingPlan: [...dentingPlan], settings: { ...settings }, warpYarns: { ...warpYarns }, weftYarns: { ...weftYarns }, weftZones: [...weftZones]
        };
        const newPast = [...prev.past, currentSnapshot];
        if (newPast.length > 50) newPast.shift(); 
        return { past: newPast, future: [] };
    });
  }, [draft, pegPlan, warpPatternString, weftPatternString, dentingPatternString, dentingPlan, settings, warpYarns, weftYarns, weftZones]);

  const undo = useCallback(() => {
      setHistory(prev => {
          if (prev.past.length === 0) return prev;
          const previous = prev.past[prev.past.length - 1];
          const newPast = prev.past.slice(0, -1);
          setDraft(previous.draft); setPegPlan(previous.pegPlan); setWarpPatternString(previous.warpPatternString); setWeftPatternString(previous.weftPatternString); setDentingPatternString(previous.dentingPatternString || '2'); setDentingPlan(previous.dentingPlan || [2]); setSettings(previous.settings); setWarpYarns(previous.warpYarns); setWeftYarns(previous.weftYarns); setWeftZones(previous.weftZones || []);
          return { past: newPast, future: [previous, ...prev.future] }; 
      });
  }, []);

  const warpPattern = useMemo(() => {
    const parsed = parsePatternString(warpPatternString, warpColors);
    if (parsed.length === 0) return Array(settings.warpThreads).fill('#888888');
    return Array.from({ length: settings.warpThreads }, (_, i) => parsed[i % parsed.length]);
  }, [warpPatternString, warpColors, settings.warpThreads]);

  const weftPattern = useMemo(() => {
    const parsed = parsePatternString(weftPatternString, weftColors);
     if (parsed.length === 0) return Array(settings.weftPicks).fill('#888888');
    return Array.from({ length: settings.weftPicks }, (_, i) => parsed[i % parsed.length]);
  }, [weftPatternString, weftColors, settings.weftPicks]);

  const weavePattern: WeavePattern = useMemo(() => {
    return generateWeave({ draft, pegPlan, warpPattern, weftPattern });
  }, [draft, pegPlan, warpPattern, weftPattern]);

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');
  const [currentFillPatternId, setCurrentFillPatternId] = useState<string>('twill-2-2');

  const isDrawing = useRef(false);
  const drawVal = useRef(true);

  const handleDraftInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      if (type === 'down' || (type === 'enter' && isDrawing.current)) {
          if (type === 'down') { saveHistory(); isDrawing.current = true; }
          const newDraft = copyGrid(draft);
          for (let h = 0; h < newDraft.length; h++) if (newDraft[h]) newDraft[h][col % newDraft[h].length] = false;
          if (newDraft[row]) newDraft[row][col % newDraft[row].length] = true;
          setDraft(newDraft);
      } else if (type === 'up') isDrawing.current = false;
  };

  const handlePegPlanInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      if (type === 'down') {
          saveHistory(); isDrawing.current = true;
          drawVal.current = pegPlan[row % pegPlan.length] ? !pegPlan[row % pegPlan.length][col % settings.harnesses] : true;
          const newPeg = copyGrid(pegPlan);
          if (newPeg[row % pegPlan.length]) newPeg[row % pegPlan.length][col % settings.harnesses] = drawVal.current;
          setPegPlan(newPeg);
      } else if (type === 'enter' && isDrawing.current) {
          const newPeg = copyGrid(pegPlan);
          if (newPeg[row % pegPlan.length] && newPeg[row % pegPlan.length][col % settings.harnesses] !== drawVal.current) {
              newPeg[row % pegPlan.length][col % settings.harnesses] = drawVal.current;
              setPegPlan(newPeg);
          }
      } else if (type === 'up') isDrawing.current = false;
  };

  const handleDrawdownInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      let harnessIndex = -1;
      for(let h=0; h<draft.length; h++) if(draft[h] && draft[h][col % settings.warpThreads]) { harnessIndex = h; break; }
      if (harnessIndex === -1) return;
      if (type === 'down') {
          saveHistory(); isDrawing.current = true;
          drawVal.current = (pegPlan[row % settings.weftPicks] && pegPlan[row % settings.weftPicks][harnessIndex]) ? !pegPlan[row % settings.weftPicks][harnessIndex] : true;
          const newPeg = copyGrid(pegPlan);
          if (newPeg[row % settings.weftPicks]) newPeg[row % settings.weftPicks][harnessIndex] = drawVal.current;
          setPegPlan(newPeg);
      } else if (type === 'up') isDrawing.current = false;
  };

  return (
    <div className="flex flex-col flex-1 h-full min-w-0 bg-[#0f172a] text-gray-200">
         <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool} viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode} currentFillPatternId={currentFillPatternId}
            onFillPatternChange={setCurrentFillPatternId} canUndo={history.past.length > 0} canRedo={false}
            onUndo={undo} onRedo={()=>{}} onSave={()=>{}} onLoad={() => setShowProjectManager(true)}
            onImport={() => fileInputRef.current?.click()}
        />

        <div className="flex flex-1 overflow-hidden relative">
            <div className="absolute left-0 top-0 bottom-0 z-40 bg-gray-900 shadow-2xl">
                <ProgressiveToolbar mode={appMode} onModeChange={setAppMode} />
            </div>

            <div className="flex-1 relative overflow-hidden flex flex-row min-w-0 pl-20">
                {appMode === 'yarn' ? (
                    <YarnStudio yarn={studioYarnDef} onChange={setStudioYarnDef} onApply={() => { saveHistory(); if (selectedYarnType === 'warp') setWarpYarns(p => ({...p, [activeYarnId]: studioYarnDef})); else setWeftYarns(p => ({...p, [activeYarnId]: studioYarnDef})); }} />
                ) : appMode === 'tech' ? (
                    <ProductionCalculator settings={settings} warpYarns={warpYarns} weftYarns={weftYarns} warpPatternString={warpPatternString} weftPatternString={weftPatternString} draft={draft} pegPlan={pegPlan} generateThumbnail={() => ""} />
                ) : (
                    <div className="flex-1 relative bg-[#0f172a] overflow-hidden">
                        <WeaveArea 
                            draft={draft} pegPlan={pegPlan} 
                            warpPattern={warpPattern} weftPattern={weftPattern} 
                            weavePattern={weavePattern.pattern} structure={weavePattern.structure} 
                            handleDraftInteraction={handleDraftInteraction} 
                            handlePegPlanInteraction={handlePegPlanInteraction} 
                            handleDrawdownInteraction={handleDrawdownInteraction}
                            pegPlanActiveColor="#3B82F6" draftActiveColor="#10b981" 
                            currentTool={currentTool} gridDivision={settings.gridDivision} 
                            viewMode={viewMode} faceMode={faceMode} 
                            epi={settings.epi} ppi={settings.ppi} 
                            warpRepeat={settings.warpThreads} weftRepeat={settings.weftPicks}
                        />
                    </div>
                )}

                <div className="w-80 flex-shrink-0 bg-gray-900 border-l border-gray-800 flex flex-col z-20">
                    <div className="p-6 border-b border-gray-800">
                        <h2 className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] mb-4">Draft AI</h2>
                        <AiControl 
                            currentInput={{draft, pegPlan, warpPattern, weftPattern}} 
                            settings={settings} 
                            onApplyGenerated={(res) => {
                                saveHistory();
                                if(res.draft) setDraft(deserializeGrid(res.draft));
                                if(res.pegPlan) setPegPlan(deserializeGrid(res.pegPlan));
                                if(res.warpPattern) setWarpPatternString(res.warpPattern);
                            }}
                        />
                    </div>
                    {/* Fix: Added missing onUpdateWeave and onDeleteWeave props to RightPanel */}
                    <RightPanel
                        settings={settings} onSettingsChange={setSettings} 
                        dentingPattern={dentingPatternString} onDentingChange={setDentingPatternString} 
                        onSnapshot={saveHistory} onLoadWeave={(w) => { saveHistory(); setDraft(deserializeGrid(w.draft)); setPegPlan(deserializeGrid(w.pegPlan)); }}
                        customWeaves={customWeaves} onAddWeave={(w) => setCustomWeaves(p => [...p, w])}
                        onUpdateWeave={(w) => setCustomWeaves(p => p.map(item => item.id === w.id ? w : item))}
                        onDeleteWeave={(id) => setCustomWeaves(p => p.filter(item => item.id !== id))}
                        warpYarns={warpYarns} weftYarns={weftYarns}
                        onUpdateWarpYarn={(c,d) => { saveHistory(); setWarpYarns(p => ({...p,[c]:d})) }}
                        onUpdateWeftYarn={(c,d) => { saveHistory(); setWeftYarns(p => ({...p,[c]:d})) }}
                        paletteColors={paletteColors} warpPatternString={warpPatternString} setWarpPatternString={setWarpPatternString} 
                        weftPatternString={weftPatternString} setWeftPatternString={setWeftPatternString}
                        onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}}
                        currentInput={{draft, pegPlan, warpPattern, weftPattern}}
                        onApplyGenerated={()=>{}} onSimulate={()=>setShowSimModal(true)}
                        onGridOperation={()=>{}} activeYarnId={activeYarnId}
                    />
                </div>
            </div>
        </div>

        <FabricSimulationModal isOpen={showSimModal} onClose={()=>setShowSimModal(false)} weavePattern={weavePattern.pattern} structure={weavePattern.structure} epi={settings.epi} ppi={settings.ppi} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
        <ProjectManagerModal isOpen={showProjectManager} onClose={()=>setShowProjectManager(false)} onLoadProject={()=>{}} onImport={()=>{}} />
    </div>
  );
};

