                                    <button onClick={() => setWeaveLayout('2')} className={`p-1 rounded transition-all ${weaveLayout === '2' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}><GridFillIcon className="w-3 h-3" /></button>
