                                onSelect={onSelectYarn} 
                                onEdit={(id, def) => setEditingYarn({id, type: 'warp', def})} 
                                usedChars={usedWarpChars}
                                onAssignColor={handleAssignColor}
                                onDropYarn={handleDropYarn}
                            />
                            <YarnList 
                                label="Weft Yarn Registry" 
                                yarns={weftYarns} 
                                type="weft" 
                                activeId={activeYarnId} 
