                    <div className="flex-1 flex overflow-hidden">
                        {techState.columns.map(col => (
                            <div key={col.id} style={{ width: COL_WIDTH }} className="shrink-0 border-r border-gray-800 flex items-center justify-center relative group">
                                <span className="text-[8px] font-bold text-gray-400 truncate px-1">{col.hookNumber}</span>
                                <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 bg-gray-800 text-white text-[8px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap border border-gray-700 pointer-events-none transition-all">
