            <LoomTechConfigModal 
                isOpen={isConfigOpen} 
                onClose={() => setIsConfigOpen(false)} 
                state={techState} 
                onUpdate={setTechState} 
            />
        </div>
    );
};

import React from 'react';
import { LoomTechState, LoomTechColumn } from '../types';
import { PlusIcon, TrashIcon, CheckIcon } from './icons';

interface LoomTechConfigModalProps {
    isOpen: boolean;
    onClose: () => void;
    state: LoomTechState;
    onUpdate: (state: LoomTechState) => void;
}

const DEFAULT_TYPE_COLORS: { [key: string]: string } = {
    'weft-selector': '#3b82f6',
    'cramming': '#f59e0b',
    'pile': '#10b981',
    'regulator': '#8b5cf6',
    'custom': '#64748b'
};

export const LoomTechConfigModal: React.FC<LoomTechConfigModalProps> = ({
    isOpen, onClose, state, onUpdate
}) => {
    if (!isOpen) return null;

    const addColumn = () => {
        const nextHook = state.columns.length > 0 ? Math.max(...state.columns.map(c => c.hookNumber)) + 1 : 1;
        const defaultType = 'weft-selector';
        const newCol: LoomTechColumn = {
            id: `hook-${Date.now()}`,
            hookNumber: nextHook,
            label: `Hook ${nextHook}`,
            type: defaultType,
            color: DEFAULT_TYPE_COLORS[defaultType]
        };
        const newGrid = state.grid.map(row => [...row, false]);
        onUpdate({ columns: [...state.columns, newCol], grid: newGrid });
    };

    const removeColumn = (idx: number) => {
        if (state.columns.length <= 1) return;
        const newCols = state.columns.filter((_, i) => i !== idx);
        const newGrid = state.grid.map(row => row.filter((_, i) => i !== idx));
        onUpdate({ columns: newCols, grid: newGrid });
    };

    const updateColumn = (idx: number, updates: Partial<LoomTechColumn>) => {
        const newCols = [...state.columns];
        const oldCol = newCols[idx];
        newCols[idx] = { ...oldCol, ...updates };

        // If type changed and user hasn't manually set a color before (or we just want to follow defaults)
        // we update the color to the type's default.
        if (updates.type && !updates.color) {
            newCols[idx].color = DEFAULT_TYPE_COLORS[updates.type] || '#64748b';
        }

        onUpdate({ ...state, columns: newCols });
    };

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-in fade-in duration-200">
            <div className="bg-gray-900 border border-gray-700 rounded-3xl shadow-2xl w-full max-w-4xl flex flex-col overflow-hidden max-h-[85vh]">
                <div className="p-6 border-b border-gray-800 flex justify-between items-center bg-gray-900 shrink-0">
                    <div>
                        <h2 className="text-xl font-black text-white tracking-tight">HARDWARE HOOK CONFIGURATION</h2>
                        <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">Map technical selectors to loom electronics</p>
                    </div>
                    <button onClick={onClose} className="p-2 text-gray-400 hover:text-white transition-colors">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 bg-gray-950 custom-scrollbar">
                    <div className="grid grid-cols-1 gap-4">
                        {state.columns.map((col, idx) => (
                            <div key={col.id} className="bg-gray-900 border border-gray-800 rounded-2xl p-4 flex items-center gap-6 group transition-all hover:border-gray-600 shadow-lg">
                                <div className="flex flex-col items-center gap-1 shrink-0">
                                    <span className="text-[9px] font-black text-gray-500 uppercase">Hook</span>
                                    <input 
                                        type="number" 
                                        value={col.hookNumber} 
                                        onChange={e => updateColumn(idx, { hookNumber: parseInt(e.target.value) || 0 })}
                                        className="w-14 bg-black border border-gray-800 rounded-lg py-2 text-center text-blue-400 font-mono font-bold focus:border-blue-500 outline-none"
                                    />
                                </div>

                                <div className="flex-1 flex flex-col gap-1">
                                    <span className="text-[9px] font-black text-gray-500 uppercase">Display Label</span>
                                    <input 
                                        value={col.label} 
                                        onChange={e => updateColumn(idx, { label: e.target.value })}
                                        className="bg-transparent border-b border-gray-800 focus:border-blue-500 outline-none text-sm font-bold text-white w-full py-1"
                                    />
                                </div>

                                <div className="w-48 flex flex-col gap-1 shrink-0">
                                    <span className="text-[9px] font-black text-gray-500 uppercase">Function Type</span>
                                    <select 
                                        value={col.type} 
                                        onChange={e => updateColumn(idx, { type: e.target.value as any })}
                                        className="w-full bg-black border border-gray-800 rounded-lg py-2 px-3 text-xs font-bold text-gray-300 focus:border-blue-500 outline-none"
                                    >
                                        <option value="weft-selector">Weft Selector</option>
                                        <option value="cramming">Cramming (Regulator Stop)</option>
                                        <option value="pile">Pile / Loop Hook</option>
                                        <option value="regulator">Weft Density Zone (Regulator)</option>
                                        <option value="custom">Custom Control</option>
                                    </select>
                                </div>

                                <div className="flex flex-col items-center gap-1 shrink-0">
                                    <span className="text-[9px] font-black text-gray-500 uppercase">Color</span>
                                    <div className="relative w-8 h-8 rounded-full border border-gray-700 overflow-hidden shadow-inner group/color">
                                        <input 
                                            type="color" 
                                            value={col.color} 
                                            onChange={e => updateColumn(idx, { color: e.target.value })}
                                            className="absolute inset-0 w-full h-full p-0 border-none cursor-pointer scale-[2.0]"
                                        />
                                        <div className="absolute inset-0 pointer-events-none border-2 border-white/10 rounded-full"></div>
                                    </div>
                                </div>

                                <button 
                                    onClick={() => removeColumn(idx)}
                                    className="p-2 text-gray-600 hover:text-red-500 transition-colors self-end mb-1"
                                >
                                    <TrashIcon className="w-5 h-5" />
                                </button>
                            </div>
                        ))}

                        <button 
                            onClick={addColumn}
                            className="py-4 border-2 border-dashed border-gray-800 rounded-2xl flex items-center justify-center gap-3 text-gray-500 hover:text-blue-400 hover:border-blue-500/50 transition-all hover:bg-blue-500/5"
                        >
                            <PlusIcon className="w-5 h-5" />
                            <span className="text-xs font-black uppercase tracking-[0.2em]">Add Technical Hook</span>
                        </button>
                    </div>
                </div>

                <div className="p-6 border-t border-gray-800 bg-gray-900 flex justify-end gap-3 shrink-0">
                    <button 
                        onClick={onClose}
                        className="px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-full font-black text-xs uppercase tracking-widest shadow-2xl transition-all active:scale-95 flex items-center gap-2"
                    >
                        <CheckIcon className="w-4 h-4" />
                        Apply Map
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { JacquardData, LoomTechState, LoomTechColumn, WeaveSettings, YarnDefinition } from '../types';
import { InteractiveGrid } from './InteractiveGrid';
import { LoomTechConfigModal } from './LoomTechConfigModal';
import { SettingsIcon, TerminalIcon, PlusIcon, TrashIcon, ZoomInIcon, ZoomOutIcon, ResetZoomIcon } from './icons';
import { expandPatternString } from '../utils/patternParser';

interface LoomTechModuleProps {
    data: JacquardData;
    settings: WeaveSettings;
    weftYarns: { [key: string]: YarnDefinition };
    weftPatternString: string;
    warpYarns: { [key: string]: YarnDefinition };
    warpPatternString: string;
}

export const LoomTechModule: React.FC<LoomTechModuleProps> = ({
    data, settings, weftYarns, weftPatternString, warpYarns, warpPatternString
}) => {
    const [techState, setTechState] = useState<LoomTechState>(() => ({
        columns: [
            { id: 'sel1', hookNumber: 1, label: 'W-Selector 1', type: 'weft-selector', color: '#3b82f6' },
            { id: 'sel2', hookNumber: 2, label: 'W-Selector 2', type: 'weft-selector', color: '#3b82f6' },
            { id: 'cram', hookNumber: 3, label: 'Cramming', type: 'cramming', color: '#f59e0b' },
            { id: 'pile', hookNumber: 4, label: 'Pile Hook', type: 'pile', color: '#10b981' }
        ],
        grid: Array.from({ length: data.height }, () => Array(4).fill(false))
    }));

    const [isConfigOpen, setIsConfigOpen] = useState(false);
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const [scale, setScale] = useState(1.0);

    // Sync grid height if picks change
    useEffect(() => {
        if (techState.grid.length !== data.height) {
            setTechState(prev => {
                const newGrid = Array.from({ length: data.height }, (_, r) => 
                    Array.from({ length: prev.columns.length }, (_, c) => prev.grid[r]?.[c] || false)
                );
                return { ...prev, grid: newGrid };
            });
        }
    }, [data.height]);

    const handleCellToggle = (r: number, c: number) => {
        setTechState(prev => {
            const next = [...prev.grid];
            next[r] = [...next[r]];
            next[r][c] = !next[r][c];
            return { ...prev, grid: next };
        });
    };

    const warpColorArray = useMemo(() => {
        const seq = expandPatternString(warpPatternString);
        return Array.from({ length: data.width }, (_, i) => warpYarns[seq[i % seq.length] || 'A']?.color || '#888');
    }, [warpYarns, warpPatternString, data.width]);

    const weftColorArray = useMemo(() => {
        const seq = expandPatternString(weftPatternString);
        return Array.from({ length: data.height }, (_, i) => weftYarns[seq[i % seq.length] || 'A']?.color || '#888');
    }, [weftYarns, weftPatternString, data.height]);

    // Construct preview grid: [PickIdx][ThreadIdx]
    const previewGrid = useMemo(() => {
        const rows: string[][] = [];
        for (let y = 0; y < data.height; y++) {
            const row: string[] = [];
            for (let x = 0; x < data.width; x++) {
                const isUp = data.structure[y * data.width + x] === 1;
                row.push(isUp ? warpColorArray[x] : weftColorArray[y]);
            }
            rows.push(row);
        }
        return rows;
    }, [data, warpColorArray, weftColorArray]);

    const BASE_COL_WIDTH = 40;
    const BASE_PICK_HEIGHT = 20;

    const colWidth = BASE_COL_WIDTH * scale;
    const pickHeight = BASE_PICK_HEIGHT * scale;
    const indicatorWidth = 48 * scale;

    const handleZoom = (dir: 'in' | 'out') => {
        setScale(prev => {
            const next = dir === 'in' ? prev * 1.25 : prev * 0.8;
            return Math.min(Math.max(next, 0.25), 4);
        });
    };

    const resetZoom = () => setScale(1.0);

    return (
        <div className="flex flex-col h-full bg-[#0f172a] text-white overflow-hidden">
            <div className="h-12 border-b border-gray-800 bg-gray-900 px-4 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-3">
                    <TerminalIcon className="w-5 h-5 text-blue-400" />
                    <h2 className="text-sm font-black uppercase tracking-widest">Loom Technical Draft</h2>
                </div>
                <div className="flex items-center gap-4">
                    {/* Zoom Controls */}
                    <div className="flex items-center gap-1 bg-gray-800 p-1 rounded-lg border border-gray-700">
                        <button 
                            onClick={() => handleZoom('out')}
                            className="p-1.5 text-gray-400 hover:text-white transition-colors"
                            title="Zoom Out"
                        >
                            <ZoomOutIcon className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={resetZoom}
                            className="px-2 text-[10px] font-mono font-bold text-blue-400 hover:text-blue-300 transition-colors"
                            title="Reset Zoom"
                        >
                            {Math.round(scale * 100)}%
                        </button>
                        <button 
                            onClick={() => handleZoom('in')}
                            className="p-1.5 text-gray-400 hover:text-white transition-colors"
                            title="Zoom In"
                        >
                            <ZoomInIcon className="w-4 h-4" />
                        </button>
                    </div>

                    <button 
                        onClick={() => setIsConfigOpen(true)}
                        className="flex items-center gap-2 px-3 py-1.5 bg-gray-800 hover:bg-gray-700 rounded-lg text-[10px] font-bold uppercase transition-all border border-gray-700"
                    >
                        <SettingsIcon className="w-3.5 h-3.5" />
                        Configure Selectors
                    </button>
                </div>
            </div>

            <div className="flex-1 flex overflow-hidden relative">
                {/* Tech Legend Header (Sticky Top Left) */}
                <div className="absolute top-0 left-0 z-30 w-full h-8 bg-gray-900 border-b border-gray-800 flex">
                    <div style={{ width: indicatorWidth }} className="shrink-0 flex items-center justify-center border-r border-gray-800 text-[9px] font-mono text-gray-500 uppercase">Pick</div>
                    <div className="flex-1 flex overflow-hidden">
                        {techState.columns.map(col => (
                            <div key={col.id} style={{ width: colWidth }} className="shrink-0 border-r border-gray-800 flex items-center justify-center relative group">
                                <span className="text-[8px] font-bold text-gray-400 truncate px-1" style={{ fontSize: `${Math.max(7, 8 * scale)}px` }}>{col.hookNumber}</span>
                                <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 bg-gray-800 text-white text-[8px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap border border-gray-700 pointer-events-none transition-all z-50">
                                    {col.label} ({col.type})
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="w-px h-full bg-blue-500/30"></div>
                    <div className="flex-1 px-4 flex items-center text-[9px] font-black text-gray-600 uppercase">Drawdown Preview (Locked)</div>
                </div>

                <div ref={scrollContainerRef} className="flex-1 overflow-auto custom-scrollbar pt-8">
                    <div className="flex min-w-max min-h-max">
                        {/* 1. Pick Indicator Column */}
                        <div style={{ width: indicatorWidth }} className="shrink-0 bg-gray-900/50 border-r border-gray-800">
                            {Array.from({ length: data.height }).map((_, i) => (
                                <div key={i} style={{ height: pickHeight }} className="flex items-center justify-center border-b border-gray-800/50 text-[9px] font-mono text-gray-500"  sx={{ fontSize: `${Math.max(7, 9 * scale)}px` }}>{i + 1}</div>
                            ))}
                        </div>

                        {/* 2. Technical Selector Grid */}
                        <div className="shrink-0 bg-gray-950">
                            <InteractiveGrid 
                                data={techState.grid} 
                                renderRows={data.height} 
                                renderCols={techState.columns.length} 
                                width={techState.columns.length * colWidth}
                                height={data.height * pickHeight}
                                activeColor="#3b82f6"
                                onCellInteraction={(r, c, type) => type === 'down' && handleCellToggle(r, c)}
                                showGrid={true}
                                gridDivision={1}
                            />
                        </div>

                        {/* Divider */}
                        <div className="w-2 bg-blue-500/10 border-x border-blue-500/20 shadow-[inset_0_0_10px_rgba(0,0,0,0.5)]"></div>

                        {/* 3. Main Design Preview (Synchronized) */}
                        <div className="flex-1 bg-black">
                            <InteractiveGrid 
                                data={previewGrid} 
                                isColorGrid 
                                renderRows={data.height} 
                                renderCols={data.width} 
                                width={data.width * pickHeight} // Keep cells square in this view
                                height={data.height * pickHeight}
                                allowInteraction={false}
                                showGrid={true}
                                gridDivision={settings.gridDivision}
                            />
                        </div>
                    </div>
                </div>
            </div>

            <LoomTechConfigModal 
                isOpen={isConfigOpen} 
                onClose={() => setIsConfigOpen(false)} 
                state={techState} 
                onUpdate={setTechState} 
            />
        </div>
    );
};

