                    </div>

                    {/* Predefined selector zone indicator - Moved to end of list because hooks are at the end */}
                    <div className="bg-emerald-900/20 border border-emerald-500/30 rounded-xl p-3 opacity-80 ring-1 ring-emerald-500/10">
                        <div className="flex items-center gap-3 mb-2">
