                </div>

                {artwork && (appMode === 'art' || appMode === 'weave') && (
                    <div className="h-24 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl">
                        <div className="flex flex-col"><span className="text-[9px] font-bold text-gray-500 uppercase mb-1">Palette Optimized</span><span className="text-[10px] text-gray-400 font-mono italic">Drop yarn or weave</span></div>
                        <div className="flex-1 flex items-center gap-3 overflow-x-auto no-scrollbar py-2">
                            {artwork.palette.map((color, idx) => (
                                <div 
                                    key={idx} 
                                    draggable
                                    onDragStart={(e) => { e.dataTransfer.setData('color-idx', idx.toString()); }}
                                    onDragOver={e => { e.preventDefault(); setDragOverColorIdx(idx); }} 
                                    onDragLeave={() => setDragOverColorIdx(null)} 
                                    onDrop={e => { 
                                        e.preventDefault(); 
                                        setDragOverColorIdx(null); 
                                        const weaveD = e.dataTransfer.getData('weave-obj'); 
                                        const sourceC = e.dataTransfer.getData('color-idx');
                                        const yarnId = e.dataTransfer.getData('yarn-id');
                                        const yarnType = e.dataTransfer.getData('yarn-type');
                                        if (weaveD) handleApplyWeaveToColor(JSON.parse(weaveD), idx); 
                                        else if (sourceC !== "") handleMergeColors(parseInt(sourceC), idx);
                                        else if (yarnId) {
                                            const def = (yarnType === 'warp' ? warpYarns : weftYarns)[yarnId];
                                            if (def && artwork) {
                                                const newPalette = [...artwork.palette];
                                                newPalette[idx] = def.color;
                                                setArtwork({ ...artwork, palette: newPalette });
                                            }
                                        }
                                    }} 
                                    className={`group flex flex-col items-center gap-1 shrink-0 bg-gray-800/40 p-2 rounded-lg border transition-all ${dragOverColorIdx === idx ? 'bg-blue-900/40 border-blue-500 scale-105 shadow-lg shadow-blue-500/20' : 'border-gray-700/50 hover:bg-gray-800'}`}
                                >
                                    <div className="relative w-10 h-10">
                                        <div className="w-full h-full rounded-md border border-white/10 shadow-md" style={{ backgroundColor: color }} />
                                        {appliedWeaves[idx] && (
                                            <div className="absolute inset-0 rounded-md overflow-hidden bg-black/40 flex items-center justify-center">
                                                <WeaveThumbnail weave={appliedWeaves[idx]} className="w-full h-full opacity-70" />
                                            </div>
                                        )}
                                    </div>
                                    <span className="text-[8px] font-mono text-gray-500 uppercase truncate max-w-[64px]">{appliedWeaves[idx] ? appliedWeaves[idx].name : color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end shrink-0"><span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drop unit to apply</span><button onClick={() => setArtwork(null)} className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded font-bold uppercase">Clear Art</button></div>
                    </div>
                )}
            </div>

            <RightPanel 
                settings={settings} onSettingsChange={(s) => { saveHistory(); setSettings(s); }} dentingPattern={dentingPattern} onDentingChange={setDentingPattern} onSnapshot={saveHistory} onLoadWeave={()=>{}} 
                customWeaves={customWeaves} onAddWeave={()=>{}} onUpdateWeave={()=>{}} onDeleteWeave={()=>{}} 
                warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(id, d) => { saveHistory(); setWarpYarns(p => ({...p, [id]: d})); }} onUpdateWeftYarn={(id, d) => { saveHistory(); setWeftYarns(p => ({...p, [id]: d})); }} paletteColors={PANTONE_PALETTE} warpPatternString={warpPatternString} setWarpPatternString={(s) => { saveHistory(); setWarpPatternString(s); }} weftPatternString={weftPatternString} setWeftPatternString={(s) => { saveHistory(); setWeftPatternString(s); }} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{} as any} onApplyGenerated={()=>{}} onSimulate={() => setShowSimModal(true)} onGridOperation={(t, a) => { saveHistory(); const newData = new Uint8Array(jacquardData.structure); if (a === 'clear') newData.fill(0); else if (a === 'invert') for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1; setJacquardData(prev => ({ ...prev, structure: newData })); }} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { setActiveYarnId(id); setSelectedYarnType(type); setAppMode('yarn'); }}
                onOpenPixelEditor={() => setShowCustomModal(true)}
                jacquardData={jacquardData}
                canvasView={canvasView}
            />
        </div>

        <FabricSimulationModal isOpen={showSimModal} onClose={() => setShowSimModal(false)} weavePattern={simData.colors} structure={simData.structure} epi={settings.epi} ppi={settings.ppi} dentingPlan={dentingPattern.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n))} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { JacquardData, LoomTechState, LoomTechColumn, WeaveSettings, YarnDefinition } from '../types';
import { InteractiveGrid } from './InteractiveGrid';
import { TerminalIcon, ZoomInIcon, ZoomOutIcon, ResetZoomIcon } from './icons';
import { expandPatternString } from '../utils/patternParser';

interface LoomTechModuleProps {
    data: JacquardData;
    settings: WeaveSettings;
    weftYarns: { [key: string]: YarnDefinition };
    weftPatternString: string;
    warpYarns: { [key: string]: YarnDefinition };
    warpPatternString: string;
    techState: LoomTechState;
    onTechStateUpdate: (state: LoomTechState) => void;
}

export const LoomTechModule: React.FC<LoomTechModuleProps> = ({
    data, settings, weftYarns, weftPatternString, warpYarns, warpPatternString,
    techState, onTechStateUpdate
}) => {
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const [scale, setScale] = useState(1.0);

    // Sync grid height if picks change
    useEffect(() => {
        if (techState.grid.length !== data.height) {
            onTechStateUpdate({
                ...techState,
                grid: Array.from({ length: data.height }, (_, r) => 
                    Array.from({ length: techState.columns.length }, (_, c) => techState.grid[r]?.[c] || false)
                )
            });
        }
    }, [data.height, techState.columns.length]);

    const handleCellToggle = (r: number, c: number) => {
        const next = [...techState.grid];
        next[r] = [...next[r]];
        next[r][c] = !next[r][c];
        onTechStateUpdate({ ...techState, grid: next });
    };

    const warpColorArray = useMemo(() => {
        const seq = expandPatternString(warpPatternString);
        return Array.from({ length: data.width }, (_, i) => warpYarns[seq[i % seq.length] || 'A']?.color || '#888');
    }, [warpYarns, warpPatternString, data.width]);

    const weftColorArray = useMemo(() => {
        const seq = expandPatternString(weftPatternString);
        return Array.from({ length: data.height }, (_, i) => weftYarns[seq[i % seq.length] || 'A']?.color || '#888');
    }, [weftYarns, weftPatternString, data.height]);

    // Construct preview grid: [PickIdx][ThreadIdx]
    const previewGrid = useMemo(() => {
        const rows: string[][] = [];
        for (let y = 0; y < data.height; y++) {
            const row: string[] = [];
            for (let x = 0; x < data.width; x++) {
                const isUp = data.structure[y * data.width + x] === 1;
                row.push(isUp ? warpColorArray[x] : weftColorArray[y]);
            }
            rows.push(row);
        }
        return rows;
    }, [data, warpColorArray, weftColorArray]);

    const BASE_COL_WIDTH = 40;
    const BASE_PICK_HEIGHT = 20;

    const colWidth = BASE_COL_WIDTH * scale;
    const pickHeight = BASE_PICK_HEIGHT * scale;
    const indicatorWidth = 48 * scale;

    const handleZoom = (dir: 'in' | 'out') => {
        setScale(prev => {
            const next = dir === 'in' ? prev * 1.25 : prev * 0.8;
            return Math.min(Math.max(next, 0.25), 4);
        });
    };

    const resetZoom = () => setScale(1.0);

    return (
        <div className="flex flex-col h-full bg-[#0f172a] text-white overflow-hidden">
            <div className="h-12 border-b border-gray-800 bg-gray-900 px-4 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-3">
                    <TerminalIcon className="w-5 h-5 text-blue-400" />
                    <h2 className="text-sm font-black uppercase tracking-widest">Loom Technical Draft</h2>
                </div>
                <div className="flex items-center gap-4">
                    {/* Zoom Controls */}
                    <div className="flex items-center gap-1 bg-gray-800 p-1 rounded-lg border border-gray-700">
                        <button 
                            onClick={() => handleZoom('out')}
                            className="p-1.5 text-gray-400 hover:text-white transition-colors"
                            title="Zoom Out"
                        >
                            <ZoomOutIcon className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={resetZoom}
                            className="px-2 text-[10px] font-mono font-bold text-blue-400 hover:text-blue-300 transition-colors"
                            title="Reset Zoom"
                        >
                            {Math.round(scale * 100)}%
                        </button>
                        <button 
                            onClick={() => handleZoom('in')}
                            className="p-1.5 text-gray-400 hover:text-white transition-colors"
                            title="Zoom In"
                        >
                            <ZoomInIcon className="w-4 h-4" />
                        </button>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex overflow-hidden relative">
                {/* Tech Legend Header (Sticky Top Left) */}
                <div className="absolute top-0 left-0 z-30 w-full h-8 bg-gray-900 border-b border-gray-800 flex">
                    <div style={{ width: indicatorWidth }} className="shrink-0 flex items-center justify-center border-r border-gray-800 text-[9px] font-mono text-gray-500 uppercase">Pick</div>
                    <div className="flex-1 flex overflow-hidden">
                        {techState.columns.map(col => (
                            <div key={col.id} style={{ width: colWidth }} className="shrink-0 border-r border-gray-800 flex items-center justify-center relative group">
                                <span className="text-[8px] font-bold text-gray-400 truncate px-1" style={{ fontSize: `${Math.max(7, 8 * scale)}px` }}>{col.hookNumber}</span>
                                <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 bg-gray-800 text-white text-[8px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 whitespace-nowrap border border-gray-700 pointer-events-none transition-all z-50">
                                    {col.label} ({col.type})
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="w-px h-full bg-blue-500/30"></div>
                    <div className="flex-1 px-4 flex items-center text-[9px] font-black text-gray-600 uppercase">Drawdown Preview (Locked)</div>
                </div>

                <div ref={scrollContainerRef} className="flex-1 overflow-auto custom-scrollbar pt-8">
                    <div className="flex min-w-max min-h-max">
                        {/* 1. Pick Indicator Column */}
                        <div style={{ width: indicatorWidth }} className="shrink-0 bg-gray-900/50 border-r border-gray-800">
                            {Array.from({ length: data.height }).map((_, i) => (
                                <div key={i} style={{ height: pickHeight, fontSize: `${Math.max(7, 9 * scale)}px` }} className="flex items-center justify-center border-b border-gray-800/50 text-[9px] font-mono text-gray-500">{i + 1}</div>
                            ))}
                        </div>

                        {/* 2. Technical Selector Grid */}
                        <div className="shrink-0 bg-gray-950">
                            <InteractiveGrid 
                                data={techState.grid} 
                                renderRows={data.height} 
                                renderCols={techState.columns.length} 
                                width={techState.columns.length * colWidth}
                                height={data.height * pickHeight}
                                activeColor="#3b82f6"
                                onCellInteraction={(r, c, type) => type === 'down' && handleCellToggle(r, c)}
                                showGrid={true}
                                gridDivision={1}
                            />
                        </div>

                        {/* Divider */}
                        <div className="w-2 bg-blue-500/10 border-x border-blue-500/20 shadow-[inset_0_0_10px_rgba(0,0,0,0.5)]"></div>

                        {/* 3. Main Design Preview (Synchronized) */}
                        <div className="flex-1 bg-black">
                            <InteractiveGrid 
                                data={previewGrid} 
                                isColorGrid 
                                renderRows={data.height} 
                                renderCols={data.width} 
                                width={data.width * pickHeight} 
                                height={data.height * pickHeight}
                                allowInteraction={false}
                                showGrid={true}
                                gridDivision={settings.gridDivision}
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { LoomConfiguration, LoomHookZone, LoomTechState } from '../types';
import { ProcessorIcon, PlusIcon, TrashIcon, CheckIcon, PencilIcon } from './icons';
import { LoomTechConfigModal } from './LoomTechConfigModal';

interface LoomEditorModuleProps {
    config: LoomConfiguration;
    onUpdate: (config: LoomConfiguration) => void;
    techState: LoomTechState;
    onTechStateUpdate: (state: LoomTechState) => void;
}

export const LoomEditorModule: React.FC<LoomEditorModuleProps> = ({ config, onUpdate, techState, onTechStateUpdate }) => {
    const [isConfigOpen, setIsConfigOpen] = useState(false);

    // We treat totalHooks as the weaving hooks + selectorHooks as control hooks
    // Selectors are now at the END of the array (Right side in landscape)
    const totalPhysical = config.totalHooks + config.selectorHooks;
    const cols = Math.ceil(totalPhysical / config.gridWidth);

    const updateZone = (id: string, updates: Partial<LoomHookZone>) => {
        const nextZones = config.zones.map(z => z.id === id ? { ...z, ...updates } : z);
        onUpdate({ ...config, zones: nextZones });
    };

    const addZone = () => {
        const lastZone = config.zones[config.zones.length - 1];
        const nextStart = lastZone ? lastZone.endHook + 1 : 1;
        const newZone: LoomHookZone = {
            id: `zone-${Date.now()}`,
            label: 'New Zone',
            startHook: nextStart,
            endHook: Math.min(config.totalHooks, nextStart + 100),
            color: '#3b82f6',
            type: 'design'
        };
        onUpdate({ ...config, zones: [...config.zones, newZone] });
    };

    const removeZone = (id: string) => {
        onUpdate({ ...config, zones: config.zones.filter(z => z.id !== id) });
    };

    // Helper to get color for a hook index
    const getHookColor = (idx: number) => {
        // Priority 1: Selector hooks (Now at the end/right)
        if (idx > config.totalHooks) {
            // Match color from techState if defined
            const techHook = techState.columns.find(c => c.hookNumber === idx);
            return techHook ? techHook.color : '#60a5fa'; // Fallback to bright blue
        }

        // Priority 2: User defined functional zones
        const zone = config.zones.find(z => idx >= z.startHook && idx <= z.endHook);
        return zone ? zone.color : '#1e293b'; // Default dark void
    };

    return (
        <div className="flex h-full bg-[#0f172a] text-white overflow-hidden">
            {/* LEFT: Parameters & Zones */}
            <div className="w-96 border-r border-gray-800 flex flex-col bg-gray-900 shadow-2xl z-10 shrink-0">
                <div className="p-6 border-b border-gray-800 bg-black/20">
                    <div className="flex items-center gap-3 mb-6">
                        <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center shadow-lg shadow-blue-900/40">
                            <ProcessorIcon className="w-6 h-6 text-white" />
                        </div>
                        <div>
                            <h2 className="text-lg font-black uppercase tracking-tight">Loom Controller</h2>
                            <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest leading-none">Industrial Hook Mapping</p>
                        </div>
                    </div>

                    <div className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-[10px] font-black text-gray-500 uppercase block mb-1">Design Hooks</label>
                                <input 
                                    type="number" 
                                    value={config.totalHooks} 
                                    onChange={e => onUpdate({ ...config, totalHooks: parseInt(e.target.value) || 0 })}
                                    className="w-full bg-black border border-gray-800 rounded-lg p-2 text-blue-400 font-mono font-bold focus:border-blue-500 outline-none"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] font-black text-gray-500 uppercase block mb-1">Selector Hooks</label>
                                <input 
                                    type="number" 
                                    value={config.selectorHooks} 
                                    onChange={e => onUpdate({ ...config, selectorHooks: parseInt(e.target.value) || 0 })}
                                    className="w-full bg-black border border-gray-800 rounded-lg p-2 text-emerald-400 font-mono font-bold focus:border-blue-500 outline-none"
                                />
                            </div>
                        </div>
                        <div>
                            <label className="text-[10px] font-black text-gray-500 uppercase block mb-1">Board Height (Rows)</label>
                            <select 
                                value={config.gridWidth}
                                onChange={e => onUpdate({ ...config, gridWidth: parseInt(e.target.value) })}
                                className="w-full bg-black border border-gray-800 rounded-lg p-2 text-gray-300 font-bold text-xs outline-none"
                            >
                                <option value={8}>8 Rows</option>
                                <option value={16}>16 Rows (Stäubli Standard)</option>
                                <option value={32}>32 Rows</option>
                            </select>
                        </div>
                        <div className="bg-blue-900/20 border border-blue-500/30 rounded-lg p-3">
                            <div className="flex justify-between items-center">
                                <span className="text-[10px] font-bold text-blue-400 uppercase">Total Capacity</span>
                                <span className="text-sm font-mono font-black text-white">{totalPhysical} Hooks</span>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-6 custom-scrollbar space-y-4 bg-gray-950">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest">Functional Zones</h3>
                        <button onClick={addZone} className="p-1.5 bg-blue-600 rounded-full hover:bg-blue-500 transition-colors shadow-lg"><PlusIcon className="w-3 h-3" /></button>
                    </div>

                    {/* Weaving Zones Container (Scrollable internally if many) */}
                    <div className="space-y-4">
                        {config.zones.map(zone => (
                            <div key={zone.id} className="bg-gray-900 border border-gray-800 rounded-xl p-3 group transition-all hover:border-gray-700">
                                <div className="flex items-center gap-3 mb-3">
                                    <input 
                                        type="color" 
                                        value={zone.color} 
                                        onChange={e => updateZone(zone.id, { color: e.target.value })}
                                        className="w-6 h-6 rounded border-none p-0 cursor-pointer bg-transparent shrink-0" 
                                    />
                                    <input 
                                        value={zone.label} 
                                        onChange={e => updateZone(zone.id, { label: e.target.value })}
                                        className="bg-transparent border-b border-transparent hover:border-gray-700 focus:border-blue-500 outline-none text-[11px] font-bold text-gray-300 w-full"
                                    />
                                    <button onClick={() => removeZone(zone.id)} className="text-gray-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><TrashIcon className="w-3.5 h-3.5" /></button>
