                                    <div className="space-y-1">
                                        <span className="text-[8px] font-black text-gray-600 uppercase">End</span>
                                        <input type="number" value={zone.endHook} onChange={e => updateZone(zone.id, { endHook: parseInt(e.target.value) || 1 })} className="w-full bg-black border border-gray-800 rounded p-1.5 text-[10px] font-mono font-bold" />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Predefined selector zone indicator - Activation trigger for technical mapping */}
                    <div className="bg-emerald-900/20 border border-emerald-500/30 rounded-xl p-3 opacity-90 ring-1 ring-emerald-500/10 group/sel relative overflow-hidden">
                        <div className="flex items-center justify-between mb-2">
                            <div className="flex items-center gap-3">
                                <div className="w-4 h-4 rounded-full bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.5)]" />
                                <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Control Selectors</span>
                            </div>
                            <button 
                                onClick={() => setIsConfigOpen(true)}
                                className="p-1.5 bg-emerald-600 rounded-md hover:bg-emerald-500 text-white shadow-lg transition-all transform hover:scale-110"
                                title="Configure Selector Hardware Mapping"
                            >
                                <PencilIcon className="w-3 h-3" />
                            </button>
                        </div>
                        <div className="flex justify-between text-[10px] font-mono text-emerald-500/70">
                            <span>H-{config.totalHooks + 1}</span>
                            <span>➜</span>
                            <span>H-{totalPhysical}</span>
                        </div>
                        <div className="mt-1 text-[8px] text-gray-500 italic uppercase">Hardware Control Unit ({config.selectorHooks} Channels)</div>
                        {/* Status Dots */}
                        <div className="mt-3 flex gap-1 items-center">
                            {techState.columns.slice(0, 8).map(c => (
                                <div key={c.id} className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: c.color }} />
                            ))}
                            {techState.columns.length > 8 && <span className="text-[7px] text-gray-600">+{techState.columns.length - 8}</span>}
                        </div>
                    </div>
                </div>
            </div>

            {/* RIGHT: Visual Board Map (Landscape) */}
            <div className="flex-1 flex flex-col overflow-hidden bg-black">
                <div className="h-10 border-b border-gray-800 bg-gray-900 flex items-center px-6 justify-between shrink-0">
                    <div className="flex items-center gap-4">
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Electronic Hook Array ({config.gridWidth} Rows Vertical)</span>
                        <div className="h-4 w-px bg-gray-800" />
                        <span className="text-[9px] text-gray-500 italic">Continuous address - Selectors assigned to the final {config.selectorHooks} hooks.</span>
                    </div>
                    <div className="flex gap-4">
                        {config.zones.map(z => (
                            <div key={z.id} className="flex items-center gap-1.5">
                                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: z.color }} />
                                <span className="text-[8px] font-black text-gray-400 uppercase tracking-tighter">{z.label}</span>
                            </div>
                        ))}
                        <div className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full bg-blue-400 shadow-[0_0_5px_#60a5fa]" />
                            <span className="text-[8px] font-black text-gray-400 uppercase tracking-tighter">Selectors</span>
                        </div>
                    </div>
                </div>

                <div className="flex-1 overflow-auto custom-scrollbar p-12 bg-[radial-gradient(#1e293b_1px,transparent_1px)] [background-size:20px_20px]">
                    <div className="bg-gray-900 p-8 rounded-[40px] shadow-[0_0_100px_rgba(0,0,0,0.5)] border border-gray-800 inline-block h-fit min-w-max">
                        {/* LANDSCAPE HOOK GRID - Unified */}
                        <div className="flex flex-col gap-2">
                            {Array.from({ length: config.gridWidth }).map((_, r) => (
                                <div key={r} className="flex gap-2 items-center">
                                    <span className="w-6 text-[8px] font-mono text-gray-600 text-right mr-2">{r + 1}</span>
                                    {Array.from({ length: cols }).map((_, c) => {
                                        // Calculate hookIdx for landscape layout (Counting down each vertical strip)
                                        const hookIdx = c * config.gridWidth + r + 1;
                                        if (hookIdx > totalPhysical) return <div key={c} className="w-4 h-4" />;

                                        const isSelector = hookIdx > config.totalHooks;
                                        const isStripStart = r === 0;

                                        return (
                                            <div key={c} className="flex flex-col items-center relative">
                                                {isStripStart && (c % 4 === 0 || isSelector) && (
                                                    <div className={`absolute -top-6 text-[7px] font-mono select-none whitespace-nowrap ${isSelector ? 'text-blue-400 font-bold' : 'text-gray-700'}`}>
                                                        {hookIdx}
                                                    </div>
                                                )}
                                                <div 
                                                    title={`Hook: ${hookIdx}${isSelector ? ' (Selector)' : ''} (Strip: ${c+1}, Row: ${r+1})`}
                                                    className={`w-4 h-4 rounded-full transition-all hover:scale-150 border border-white/5 shadow-inner relative group ${isSelector ? 'ring-1 ring-blue-500/40' : ''}`}
                                                    style={{ backgroundColor: getHookColor(hookIdx) }}
                                                >
                                                    {/* Detail indicator for selectors */}
                                                    {isSelector && (
                                                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                                                            <div className="w-1.5 h-1.5 bg-white/30 rounded-sm" />
                                                        </div>
                                                    )}
                                                    <div className="absolute inset-0 rounded-full bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity" />
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            ))}
                        </div>

                        <div className="mt-12 flex justify-center gap-12 border-t border-gray-800 pt-8">
                            <div className="flex items-center gap-3 bg-black/30 px-4 py-2 rounded-full border border-gray-800 shadow-lg">
                                <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Board Config</div>
                                <div className="text-sm font-mono font-black text-gray-300">{cols} Columns x {config.gridWidth} Rows</div>
                            </div>
                            <div className="flex items-center gap-3 bg-blue-900/10 px-4 py-2 rounded-full border border-blue-900/30 shadow-lg">
                                <div className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Selector Hook Start</div>
                                <div className="text-sm font-mono font-black text-blue-400">{config.totalHooks + 1}</div>
                            </div>
                            <div className="flex items-center gap-3 bg-black/30 px-4 py-2 rounded-full border border-gray-800 shadow-lg">
                                <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Grand Total</div>
                                <div className="text-sm font-mono font-black text-white">{totalPhysical}</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Selector Configuration Modal */}
            <LoomTechConfigModal 
                isOpen={isConfigOpen} 
                onClose={() => setIsConfigOpen(false)} 
                state={techState} 
                onUpdate={onTechStateUpdate} 
            />
        </div>
    );
};

