                                 <input 
                                    type="checkbox" 
                                    checked={config.castOut?.active || false}
                                    onChange={e => onUpdate({ ...config, castOut: { active: e.target.checked, on: config.castOut?.on || 1, off: config.castOut?.off || 1 } })}
                                    className="rounded border-gray-700 text-blue-600 focus:ring-blue-500 bg-gray-900"
                                 />
                                 <span className="text-[10px] font-bold text-gray-500 uppercase">Enable Pattern</span>
                             </label>
                             <div className="w-px h-4 bg-gray-800" />
                             <div className="flex items-center gap-2">
                                <span className="text-[9px] font-bold text-gray-600 uppercase">Active</span>
                                <input 
                                    type="number" min="1" max="64"
                                    value={config.castOut?.on || 1}
                                    onChange={e => onUpdate({ ...config, castOut: { active: config.castOut?.active || false, on: parseInt(e.target.value) || 1, off: config.castOut?.off || 1 } })}
                                    className="w-10 bg-black border border-gray-700 rounded text-center text-xs font-mono py-1"
                                />
                                <span className="text-[9px] font-bold text-gray-600 uppercase">Skip</span>
                                <input 
                                    type="number" min="1" max="64"
                                    value={config.castOut?.off || 1}
                                    onChange={e => onUpdate({ ...config, castOut: { active: config.castOut?.active || false, on: config.castOut?.on || 1, off: parseInt(e.target.value) || 1 } })}
                                    className="w-10 bg-black border border-gray-700 rounded text-center text-xs font-mono py-1"
                                />
                             </div>
                        </div>
                        <p className="text-[9px] text-gray-600 italic">Pattern repeated across all {config.totalHooks} design hooks for load balancing.</p>
                    </div>

                    <div className="flex gap-4">
                        <div className="flex items-center gap-3 bg-black/30 px-4 py-2 rounded-full border border-gray-800 shadow-lg">
                            <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Active Hooks</div>
                            <div className="text-sm font-mono font-black text-blue-500">
                                {totalPhysical - (config.castOut?.active ? Math.floor(config.totalHooks * (config.castOut.off / (config.castOut.on + config.castOut.off))) : 0)}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <LoomTechConfigModal 
                isOpen={isConfigOpen} 
                onClose={() => setIsConfigOpen(false)} 
                state={techState} 
                onUpdate={onTechStateUpdate} 
            />
        </div>
    );
};

import React from 'react';
