/**
 * HIGH PERFORMANCE CANVAS RENDERER FOR FULL TECHNICAL PUNCH CARD
 */
const FullDraftCanvas: React.FC<{
    config: LoomConfiguration;
    techState: LoomTechState;
    data: JacquardData;
    scale: number;
}> = ({ config, techState, data, scale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const totalPhysical = config.totalHooks + config.selectorHooks;
    const rowHeight = 20 * scale;
    const colWidth = 20 * scale;

    const weaveCache = useMemo(() => {
        const cache = new Map<string, Uint8Array>();
        config.zones.forEach(zone => {
            if (zone.type === 'selvedge' && zone.weaveId) {
                const weave = WEAVE_LIBRARY.find(w => w.id === zone.weaveId);
                if (weave) {
                    const { draft, pegPlan, harnesses } = weave;
                    const w = draft[0].length;
                    const h = pegPlan.length;
                    const bits = new Uint8Array(w * h);
                    const warpToH = new Int16Array(w).fill(-1);
                    for(let x=0; x<w; x++) for(let ha=0; ha<harnesses; ha++) if(draft[ha][x] === 1) { warpToH[x] = ha; break; }
                    for(let y=0; y<h; y++) for(let x=0; x<w; x++) if(warpToH[x] !== -1 && pegPlan[y][warpToH[x]] === 1) bits[y * w + x] = 1;
                    cache.set(zone.id, bits);
                }
            }
        });
        return cache;
    }, [config.zones]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        canvas.width = totalPhysical * colWidth;
        canvas.height = data.height * rowHeight;

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        for (let p = 0; p < data.height; p++) {
            const y = p * rowHeight;

            for (let h = 1; h <= totalPhysical; h++) {
                const x = (h - 1) * colWidth;

                let bit = false;
                let zoneColor = '#1e293b';

                if (h <= config.totalHooks) {
                    // Weaving Hook (Selvedge or Design)
                    const zone = config.zones.find(z => h >= z.startHook && h <= z.endHook);
                    if (zone) {
                        zoneColor = zone.color;
                        if (zone.type === 'design') {
                            // Map design hook to graph index with repetition
                            const localX = (h - zone.startHook) % data.width;
                            bit = data.structure[p * data.width + localX] === 1;
                        } else if (zone.type === 'selvedge' && zone.weaveId) {
                            const bits = weaveCache.get(zone.id);
                            const weave = WEAVE_LIBRARY.find(w => w.id === zone.weaveId);
                            if (bits && weave) {
                                const w = weave.draft[0].length;
                                const hW = weave.pegPlan.length;
                                const lx = (h - zone.startHook) % w;
                                const ly = p % hW;
                                bit = bits[ly * w + lx] === 1;
                            }
                        }
                    }
                } else {
                    // Selector Hook
                    const selIdx = h - config.totalHooks - 1;
                    const col = techState.columns[selIdx];
                    zoneColor = col ? col.color : '#60a5fa';
                    bit = techState.grid[p]?.[selIdx] || false;
                }

                if (bit) {
                    ctx.fillStyle = zoneColor;
                    ctx.fillRect(x + 1, y + 1, colWidth - 2, rowHeight - 2);
                    // Detail highlight
                    ctx.fillStyle = 'rgba(255,255,255,0.1)';
                    ctx.fillRect(x + 2, y + 2, colWidth - 4, 1);
                } else {
                    ctx.fillStyle = '#1e293b';
                    ctx.fillRect(x + 1, y + 1, colWidth - 2, rowHeight - 2);
                }
            }
        }
    }, [config, techState, data, scale, weaveCache]);

    return <canvas ref={canvasRef} className="block shadow-2xl" />;
};

