        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { JacquardData, LoomTechState, LoomConfiguration, LoomHookZone, WeaveSettings, YarnDefinition, LibraryWeave } from '../types';
import { TerminalIcon, ZoomInIcon, ZoomOutIcon, ResetZoomIcon, WeaveIcon } from './icons';
import { WEAVE_LIBRARY } from '../services/weaveLibrary';
import { WeaveThumbnail } from './WeaveThumbnail';

interface LoomTechModuleProps {
    data: JacquardData;
    settings: WeaveSettings;
    weftYarns: { [key: string]: YarnDefinition };
    weftPatternString: string;
    warpYarns: { [key: string]: YarnDefinition };
    warpPatternString: string;
    techState: LoomTechState;
    onTechStateUpdate: (state: LoomTechState) => void;
    config: LoomConfiguration;
    onConfigUpdate: (config: LoomConfiguration) => void;
}

/**
 * HIGH PERFORMANCE CANVAS RENDERER FOR FULL TECHNICAL PUNCH CARD
 * Optimized to handle industrial hook counts (2k-12k) across hundreds of picks.
 */
const FullDraftCanvas: React.FC<{
    config: LoomConfiguration;
    techState: LoomTechState;
    data: JacquardData;
    scale: number;
}> = ({ config, techState, data, scale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const totalPhysical = config.totalHooks + config.selectorHooks;
    const rowHeight = 20 * scale;
    const colWidth = 20 * scale;

    // PRE-CALCULATION: Create an optimized lookup table for hooks to avoid 'find' calls in the rendering loop
    const hookMap = useMemo(() => {
        const map = new Array(totalPhysical + 1);

        // 1. Weaving Hooks
        for (let h = 1; h <= config.totalHooks; h++) {
            const zone = config.zones.find(z => h >= z.startHook && h <= z.endHook);
            if (zone) {
                let weaveBits = null;
                let weaveWidth = 1;
                let weaveHeight = 1;

                if (zone.type === 'selvedge' && zone.weaveId) {
                    const weave = WEAVE_LIBRARY.find(w => w.id === zone.weaveId);
                    if (weave) {
                        const { draft, pegPlan, harnesses } = weave;
                        weaveWidth = draft[0].length;
                        weaveHeight = pegPlan.length;
                        weaveBits = new Uint8Array(weaveWidth * weaveHeight);
                        const warpToH = new Int16Array(weaveWidth).fill(-1);
                        for(let x=0; x<weaveWidth; x++) for(let ha=0; ha<harnesses; ha++) if(draft[ha][x] === 1) { warpToH[x] = ha; break; }
                        for(let y=0; y<weaveHeight; y++) for(let x=0; x<weaveWidth; x++) if(warpToH[x] !== -1 && pegPlan[y][warpToH[x]] === 1) weaveBits[y * weaveWidth + x] = 1;
                    }
                }

                map[h] = {
                    type: zone.type,
                    color: zone.color,
                    startHook: zone.startHook,
                    weaveBits,
                    weaveWidth,
                    weaveHeight
                };
            } else {
                map[h] = { type: 'empty', color: '#111827' };
            }
        }

        // 2. Selector Hooks
        for (let s = 0; s < config.selectorHooks; s++) {
            const hookIdx = config.totalHooks + s + 1;
            const col = techState.columns[s];
            map[hookIdx] = {
                type: 'selector',
                color: col?.color || '#60a5fa',
                selectorIndex: s
            };
        }

        return map;
    }, [config, techState.columns]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        canvas.width = totalPhysical * colWidth;
        canvas.height = data.height * rowHeight;

        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        const designW = data.width;
        const designS = data.structure;

        for (let p = 0; p < data.height; p++) {
            const y = Math.floor(p * rowHeight);

            for (let h = 1; h <= totalPhysical; h++) {
                const x = Math.floor((h - 1) * colWidth);
                const hDef = hookMap[h];
                if (!hDef) continue;

                let bit = false;
                let color = hDef.color;

                if (hDef.type === 'design') {
                    const localX = (h - hDef.startHook) % designW;
                    bit = designS[p * designW + localX] === 1;
                } else if (hDef.type === 'selvedge') {
                    if (hDef.weaveBits) {
                        const lx = (h - hDef.startHook) % hDef.weaveWidth;
                        const ly = p % hDef.weaveHeight;
                        bit = hDef.weaveBits[ly * hDef.weaveWidth + lx] === 1;
                    }
                } else if (hDef.type === 'selector') {
                    bit = techState.grid[p]?.[hDef.selectorIndex] || false;
                }

                if (bit) {
                    ctx.fillStyle = color;
                    ctx.fillRect(x + 1, y + 1, colWidth - 2, rowHeight - 2);
                    // Detail highlight for texture
                    ctx.fillStyle = 'rgba(255,255,255,0.15)';
                    ctx.fillRect(x + 2, y + 2, colWidth - 4, 1);
                } else {
                    ctx.fillStyle = '#1e293b'; // Background hook color (down)
                    ctx.fillRect(x + 1, y + 1, colWidth - 2, rowHeight - 2);
                }
            }
        }
    }, [totalPhysical, data.height, data.structure, data.width, rowHeight, colWidth, hookMap, techState.grid]);

    return <canvas ref={canvasRef} className="block shadow-2xl" />;
};

