/**
 * OPTIMIZED BLOCK RENDERER
 * Draws segments of identical bits to minimize draw calls
 */
const OptimizedCanvas: React.FC<{
    width: number;
    height: number;
    scale: number;
    renderFn: (ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => void;
    className?: string;
}> = ({ width, height, scale, renderFn, className }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const cellW = 6 * scale;
    const cellH = 6 * scale;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        canvas.width = width * cellW;
        canvas.height = height * cellH;
        ctx.fillStyle = '#020617';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        renderFn(ctx, cellW, cellH);
    }, [width, height, scale, renderFn]);

    return <canvas ref={canvasRef} className={className} />;
};

