        seq.forEach(s => {
            const count = parseInt(s);
            // Fix: 'slice' is now available as 's' is correctly typed as string
            const char = s.slice(-1).toUpperCase();
            const color = weftYarns[char]?.color || '#888';
            for(let i=0; i<count; i++) flat.push(color);
        });
        return flat;
    }, [weftPatternString, weftYarns]);

    // Technical Mapping Pre-calculation
    const hookMap = useMemo(() => {
        const map = new Array(config.totalHooks + 1);
        for (let h = 1; h <= config.totalHooks; h++) {
            const zone = config.zones.find(z => h >= z.startHook && h <= z.endHook);
            if (zone) {
                let weaveBits = null;
                let weaveWidth = 1, weaveHeight = 1;
                if (zone.type === 'selvedge' && zone.weaveId) {
                    const weave = WEAVE_LIBRARY.find(w => w.id === zone.weaveId);
                    if (weave) {
                        const { draft, pegPlan, harnesses } = weave;
                        weaveWidth = draft[0].length; weaveHeight = pegPlan.length;
                        weaveBits = new Uint8Array(weaveWidth * weaveHeight);
                        const warpToH = new Int16Array(weaveWidth).fill(-1);
                        for(let x=0; x<weaveWidth; x++) for(let ha=0; ha<harnesses; ha++) if(draft[ha][x] === 1) { warpToH[x] = ha; break; }
                        for(let y=0; y<weaveHeight; y++) for(let x=0; x<weaveWidth; x++) if(warpToH[x] !== -1 && pegPlan[y][warpToH[x]] === 1) weaveBits[y * weaveWidth + x] = 1;
                    }
                }
                map[h] = { type: zone.type, color: zone.color, startHook: zone.startHook, weaveBits, weaveWidth, weaveHeight };
            } else {
                map[h] = { type: 'empty', color: '#f8fafc' };
            }
        }
        return map;
    }, [config.zones, config.totalHooks]);

    const renderDesign = useCallback((ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => {
        const designW = data.width, designS = data.structure;
        const isInterlaced = viewMode === 'interlace';

        // Horizontal Draw Start hook
        let renderX = 0;

        for (let h = 1; h <= config.totalHooks; h++) {
            const hDef = hookMap[h];
            if (!hDef) continue;
            const isSelvedge = hDef.type === 'selvedge';
            if (!showSelvedge && isSelvedge) continue;

            for (let p = 0; p < data.height; p++) {
                const y = p * cellH;
                const x = renderX * cellW;

                let bit = false;
                if (hDef.type === 'design') {
                    const localX = (h - (hDef.startHook || 0)) % designW;
                    bit = designS[p * designW + localX] === 1;
                } else if (isSelvedge && hDef.weaveBits) {
                    const lx = (h - (hDef.startHook || 0)) % hDef.weaveWidth;
                    const ly = p % hDef.weaveHeight;
                    bit = hDef.weaveBits[ly * hDef.weaveWidth + lx] === 1;
                }

                if (bit) {
                    if (isInterlaced) {
                        ctx.fillStyle = warpColorsArray[ (h - (hDef.startHook || 1)) % warpColorsArray.length] || '#000';
                    } else {
                        ctx.fillStyle = '#1e293b'; // Standard Dark Hole
                    }
                } else {
                    if (isInterlaced) {
                        ctx.fillStyle = weftColorsArray[p % weftColorsArray.length] || '#ccc';
                    } else {
                        ctx.fillStyle = '#e2e8f0'; // Empty hole (Light Grey)
                    }
                }
                ctx.fillRect(x, y, cellW - 0.5, cellH - 0.5);
            }
            renderX++;
        }
    }, [hookMap, data.structure, data.width, data.height, viewMode, showSelvedge, config.totalHooks, warpColorsArray, weftColorsArray]);

    const renderSelectors = useCallback((ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => {
        for (let p = 0; p < data.height; p++) {
            const y = p * cellH;
            for (let s = 0; s < config.selectorHooks; s++) {
                const col = techState.columns[s];
                const bit = techState.grid[p]?.[s] || false;
                ctx.fillStyle = bit ? (col?.color || '#3b82f6') : '#f1f5f9';
                ctx.fillRect(s * cellW, y, cellW - 0.5, cellH - 0.5);
            }
        }
    }, [techState.grid, techState.columns, config.selectorHooks, data.height]);

    return (
        <div className="flex h-full bg-white text-gray-900 overflow-hidden font-sans">
            {/* SIDEBAR */}
            <div className="w-80 border-r border-gray-200 flex flex-col bg-gray-50 shrink-0 z-10">
                <div className="p-5 border-b border-gray-200 bg-white">
                    <div className="flex items-center gap-3 mb-6">
                        <TerminalIcon className="w-6 h-6 text-blue-600" />
                        <h2 className="text-sm font-black uppercase tracking-widest text-gray-800">Tech Module</h2>
                    </div>

                    <div className="space-y-6">
                        <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 space-y-4">
                            <h3 className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Card Display</h3>
                            <div className="flex bg-white rounded p-1 border border-gray-200">
                                <button 
                                    onClick={() => setViewMode('graph')} 
                                    className={`flex-1 py-1.5 text-[9px] font-bold rounded transition-all flex items-center justify-center gap-2 ${viewMode === 'graph' ? 'bg-gray-800 text-white shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
                                >
                                    <GridIcon className="w-3 h-3" /> Simple Graph
                                </button>
                                <button 
                                    onClick={() => setViewMode('interlace')} 
                                    className={`flex-1 py-1.5 text-[9px] font-bold rounded transition-all flex items-center justify-center gap-2 ${viewMode === 'interlace' ? 'bg-gray-800 text-white shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
                                >
                                    <WeaveIcon className="w-3 h-3" /> Interlaced
                                </button>
                            </div>

                            <label className="flex items-center justify-between cursor-pointer group pt-1">
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-bold text-gray-700 uppercase tracking-tight group-hover:text-blue-600 transition-colors">Show Selvedge</span>
                                    <span className="text-[8px] text-gray-400 font-medium">Independent zone toggle</span>
                                </div>
                                <input 
                                    type="checkbox" 
                                    checked={showSelvedge} 
                                    onChange={e => setShowSelvedge(e.target.checked)} 
                                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4" 
                                />
                            </label>
                        </div>

                        <div>
                            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Selvedge Display</h3>
                            <div className="space-y-3">
                                {selvedgeZones.map(zone => (
                                    <div key={zone.id} className={`bg-white border rounded-xl p-3 transition-opacity ${!showSelvedge ? 'opacity-30' : 'opacity-100'}`}>
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-[9px] font-black uppercase" style={{ color: zone.color }}>{zone.label}</span>
                                            <button 
                                                disabled={!showSelvedge}
                                                onClick={() => setActiveSelvedgeZone(activeSelvedgeZone === zone.id ? null : zone.id)} 
                                                className="text-[9px] font-bold text-blue-600 uppercase tracking-widest disabled:text-gray-300"
                                            >
                                                Change
                                            </button>
                                        </div>
                                        {zone.weaveId ? (
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded border border-gray-100 overflow-hidden shadow-sm">
                                                    <WeaveThumbnail weave={WEAVE_LIBRARY.find(w => w.id === zone.weaveId)!} className="w-full h-full border-none" />
                                                </div>
                                                <span className="text-[9px] font-bold text-gray-600 truncate">{WEAVE_LIBRARY.find(w => w.id === zone.weaveId)?.name}</span>
                                            </div>
                                        ) : (
                                            <div className="py-2 text-center border border-dashed border-gray-200 rounded text-gray-400 text-[9px] font-bold uppercase">No Weave</div>
                                        )}
                                        {activeSelvedgeZone === zone.id && showSelvedge && (
                                            <div className="mt-3 grid grid-cols-4 gap-2 border-t border-gray-100 pt-3 animate-in slide-in-from-top-1">
                                                {WEAVE_LIBRARY.slice(0, 8).map(w => (
                                                    <button 
                                                        key={w.id} 
                                                        onClick={() => { handleAssignWeave(zone.id, w.id); setActiveSelvedgeZone(null); }} 
                                                        className={`aspect-square rounded border transition-all ${zone.weaveId === w.id ? 'border-blue-500 ring-1 ring-blue-500' : 'border-gray-200 hover:border-gray-400'}`}
                                                    >
                                                        <WeaveThumbnail weave={w} className="w-full h-full border-none" />
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
                <div className="flex-1 p-5 bg-gray-50 overflow-y-auto custom-scrollbar">
                     <p className="text-[10px] text-gray-400 leading-relaxed italic border-t border-gray-200 pt-4">Technical control hooks remain stationary. Horizontal scroll reveals technical selvedge and design address space in high-contrast Light Mode.</p>
                </div>
            </div>

            {/* MAIN CONTENT SPLIT VIEW */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden bg-[#f1f5f9]">
                <div className="h-12 border-b border-gray-200 bg-white px-6 flex items-center justify-between shrink-0 shadow-sm z-20">
                    <div className="flex items-center gap-6">
                        <div className="flex items-baseline gap-2">
                            <span className="text-xs font-black text-gray-800 uppercase tracking-widest">Electronic Punch Card</span>
                            <span className="text-[10px] text-gray-400 font-mono">ADDR: 0 → {config.totalHooks + config.selectorHooks}</span>
                        </div>
                        <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-lg border border-gray-200">
                            <button onClick={() => setScale(s => Math.max(0.1, s - 0.1))} className="p-1.5 text-gray-400 hover:text-blue-600 transition-colors"><ZoomOutIcon className="w-4 h-4" /></button>
                            <span className="px-3 text-[10px] font-mono font-black text-blue-600 select-none">{Math.round(scale * 100)}%</span>
                            <button onClick={() => setScale(s => Math.min(1.5, s + 0.1))} className="p-1.5 text-gray-400 hover:text-blue-600 transition-colors"><ZoomInIcon className="w-4 h-4" /></button>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                         <div className="flex items-center gap-2 bg-emerald-50 border border-emerald-200 px-3 py-1 rounded-full">
                            <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse" />
                            <span className="text-[10px] font-black text-emerald-700 uppercase tracking-widest">Logic Live</span>
                        </div>
                    </div>
                </div>

                <div className="flex-1 flex overflow-hidden bg-white">
                    {/* LEFT PANE: SELECTORS (STATIC X) */}
                    <div className="flex flex-col border-r-4 border-blue-100 shrink-0 bg-white relative z-10 shadow-lg" style={{ width: config.selectorHooks * 5 * scale + 48 }}>
                        {/* Selector Header */}
                        <div className="h-20 border-b border-gray-200 bg-white flex shrink-0">
                             <div className="w-12 border-r border-gray-200 flex items-center justify-center text-[9px] font-black text-gray-400 uppercase [writing-mode:vertical-lr] rotate-180">PICK #</div>
                             <div className="flex-1 flex relative">
                                {techState.columns.map(col => (
                                    <div key={col.id} className="h-full border-r border-gray-100 flex items-center justify-center bg-blue-50/30" style={{ width: 5 * scale }}>
                                        <div className="transform -rotate-90 origin-center whitespace-nowrap text-[7px] font-black uppercase text-blue-500 tracking-tighter" style={{ fontSize: `${Math.min(7, 7 * scale)}px` }}>{col.label}</div>
                                    </div>
                                ))}
                             </div>
                        </div>
                        {/* Selector Grid */}
                        <div ref={scrollRefControl} className="flex-1 overflow-hidden no-scrollbar bg-white">
                            <div className="flex">
                                <div className="w-12 bg-white border-r border-gray-200 shrink-0">
                                    {Array.from({ length: data.height }).map((_, i) => (
                                        <div key={i} className="flex items-center justify-center border-b border-gray-100 text-[9px] font-mono font-bold text-gray-300" style={{ height: 5 * scale }}>{i + 1}</div>
                                    ))}
                                </div>
                                <OptimizedCanvas width={config.selectorHooks} height={data.height} scale={scale} renderFn={renderSelectors} />
                            </div>
                        </div>
                    </div>

                    {/* RIGHT PANE: DESIGN & SELVEDGE (SCROLLABLE X) */}
                    <div className="flex-1 flex flex-col min-w-0 bg-[#fafafa]">
                         {/* Design Header */}
                         <div className="h-20 border-b border-gray-200 bg-white flex overflow-hidden">
                            <div className="flex relative" style={{ width: visibleDesignHooks * 5 * scale }}>
                                {config.zones.map(z => {
                                    if (!showSelvedge && z.type === 'selvedge') return null;
                                    const width = (z.endHook - z.startHook + 1);
                                    return (
                                        <div key={z.id} className="h-full border-r border-gray-100 flex items-center justify-center bg-gray-50/50" style={{ width: width * 5 * scale }}>
                                            <span className="text-[8px] font-black uppercase text-gray-400 truncate px-2 tracking-tighter">{z.label}</span>
                                        </div>
                                    );
                                })}
                            </div>
                         </div>
                         {/* Design Grid */}
                         <div ref={scrollRefDesign} className="flex-1 overflow-auto custom-scrollbar" onScroll={handleVerticalScroll}>
                             <OptimizedCanvas width={visibleDesignHooks} height={data.height} scale={scale} renderFn={renderDesign} />
                         </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { JacquardData, LoomTechState, LoomConfiguration, LoomHookZone, WeaveSettings, YarnDefinition, LibraryWeave } from '../types';
import { TerminalIcon, ZoomInIcon, ZoomOutIcon, WeaveIcon, EyeIcon, EyeOffIcon, GridIcon, SettingsIcon } from './icons';
import { WEAVE_LIBRARY } from '../services/weaveLibrary';
import { WeaveThumbnail } from './WeaveThumbnail';

interface LoomTechModuleProps {
    data: JacquardData;
    settings: WeaveSettings;
    weftYarns: { [key: string]: YarnDefinition };
    weftPatternString: string;
    warpYarns: { [key: string]: YarnDefinition };
    warpPatternString: string;
    techState: LoomTechState;
    onTechStateUpdate: (state: LoomTechState) => void;
    config: LoomConfiguration;
    onConfigUpdate: (config: LoomConfiguration) => void;
}

/**
 * HIGH PERFORMANCE CANVAS RENDERER
 * Light Mode themed for industrial readability.
 */
const OptimizedCanvas: React.FC<{
    width: number;
    height: number;
    scale: number;
    renderFn: (ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => void;
    className?: string;
}> = ({ width, height, scale, renderFn, className }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const cellW = 5 * scale;
    const cellH = 5 * scale;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        canvas.width = width * cellW;
        canvas.height = height * cellH;

        ctx.fillStyle = '#ffffff'; // Light Mode Background
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        renderFn(ctx, cellW, cellH);
    }, [width, height, scale, renderFn]);

    return <canvas ref={canvasRef} className={className} />;
};

export const LoomTechModule: React.FC<LoomTechModuleProps> = ({
    data, settings, weftYarns, weftPatternString, warpYarns, warpPatternString,
    techState, onTechStateUpdate, config, onConfigUpdate
}) => {
    // Zoom capped at 1.5x
    const [scale, setScale] = useState(1.0);
    const [showSelvedge, setShowSelvedge] = useState(true);
    const [viewMode, setViewMode] = useState<'graph' | 'interlace'>('graph');
    const [autoMapWeft, setAutoMapWeft] = useState(true);
    const [activeSelvedgeZone, setActiveSelvedgeZone] = useState<string | null>(null);

    const scrollRefControl = useRef<HTMLDivElement>(null);
    const scrollRefDesign = useRef<HTMLDivElement>(null);

    // Sync Vertical Scroll
    const handleVerticalScroll = (e: React.UIEvent<HTMLDivElement>) => {
        const top = e.currentTarget.scrollTop;
        if (scrollRefControl.current) scrollRefControl.current.scrollTop = top;
        if (scrollRefDesign.current) scrollRefDesign.current.scrollTop = top;
    };

    const handleAssignWeave = (zoneId: string, weaveId: string) => {
        const nextZones = config.zones.map(z => z.id === zoneId ? { ...z, weaveId } : z);
        onConfigUpdate({ ...config, zones: nextZones });
    };

    const selvedgeZones = config.zones.filter(z => z.type === 'selvedge');
    const designZones = config.zones.filter(z => z.type === 'design');

    // Logic: When selvedge display is OFF, start design zone from end of control panel (0 offset)
    const visibleDesignHooks = useMemo(() => {
        if (showSelvedge) return config.totalHooks;
        return designZones.reduce((acc, z) => acc + (z.endHook - z.startHook + 1), 0);
    }, [showSelvedge, config.totalHooks, designZones]);

    // Expand weft sequence for picking logic
    const weftSequence = useMemo(() => {
        const regex = /(\d+)([A-Z])/gi;
        let match;
        const seq: string[] = [];
        const pattern = weftPatternString || "1A";
        while ((match = regex.exec(pattern)) !== null) {
            const count = parseInt(match[1]);
            const char = match[2].toUpperCase();
            for(let i=0; i<count; i++) seq.push(char);
        }
        return seq.length > 0 ? seq : ['A'];
    }, [weftPatternString]);

    // Color Lookup Pre-calc
    const warpColorsArray = useMemo(() => {
        const seq = (warpPatternString.match(/(\d+)([A-Z])/gi) || []) as string[];
        const flat: string[] = [];
        seq.forEach(s => {
            const count = parseInt(s);
            const char = s.slice(-1).toUpperCase();
            flat.push(...Array(count).fill(warpYarns[char]?.color || '#888'));
        });
        return flat;
    }, [warpPatternString, warpYarns]);

    const weftColorsArray = useMemo(() => {
        const seq = (weftPatternString.match(/(\d+)([A-Z])/gi) || []) as string[];
        const flat: string[] = [];
        seq.forEach(s => {
            const count = parseInt(s);
            const char = s.slice(-1).toUpperCase();
            flat.push(...Array(count).fill(weftYarns[char]?.color || '#888'));
        });
        return flat;
    }, [weftPatternString, weftYarns]);

    // Technical Mapping Pre-calculation
    const hookMap = useMemo(() => {
        const map = new Array(config.totalHooks + 1);
        for (let h = 1; h <= config.totalHooks; h++) {
            const zone = config.zones.find(z => h >= z.startHook && h <= z.endHook);
            if (zone) {
                let weaveBits = null;
                let weaveWidth = 1, weaveHeight = 1;
                if (zone.type === 'selvedge' && zone.weaveId) {
                    const weave = WEAVE_LIBRARY.find(w => w.id === zone.weaveId);
                    if (weave) {
                        const { draft, pegPlan, harnesses } = weave;
                        weaveWidth = draft[0].length; weaveHeight = pegPlan.length;
                        weaveBits = new Uint8Array(weaveWidth * weaveHeight);
                        const warpToH = new Int16Array(weaveWidth).fill(-1);
                        for(let x=0; x<weaveWidth; x++) for(let ha=0; ha<harnesses; ha++) if(draft[ha][x] === 1) { warpToH[x] = ha; break; }
                        for(let y=0; y<weaveHeight; y++) for(let x=0; x<weaveWidth; x++) if(warpToH[x] !== -1 && pegPlan[y][warpToH[x]] === 1) weaveBits[y * weaveWidth + x] = 1;
                    }
                }
                map[h] = { type: zone.type, color: zone.color, startHook: zone.startHook, weaveBits, weaveWidth, weaveHeight };
            } else {
                map[h] = { type: 'empty', color: '#f8fafc' };
            }
        }
        return map;
    }, [config.zones, config.totalHooks]);

    const renderDesign = useCallback((ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => {
        const designW = data.width, designS = data.structure;
        const isInterlace = viewMode === 'interlace';
        let renderX = 0;

        for (let h = 1; h <= config.totalHooks; h++) {
            const hDef = hookMap[h];
            if (!hDef) continue;
            if (!showSelvedge && hDef.type === 'selvedge') continue;

            const x = renderX * cellW;
            for (let p = 0; p < data.height; p++) {
                const y = p * cellH;
                let bit = false;
                if (hDef.type === 'design') {
                    bit = designS[p * designW + ((h - hDef.startHook) % designW)] === 1;
                } else if (hDef.type === 'selvedge' && hDef.weaveBits) {
                    bit = hDef.weaveBits[(p % hDef.weaveHeight) * hDef.weaveWidth + ((h - hDef.startHook) % hDef.weaveWidth)] === 1;
                }

                if (bit) {
                    ctx.fillStyle = isInterlace ? (warpColorsArray[(h-1)%warpColorsArray.length] || '#000') : '#1e293b';
                } else {
                    ctx.fillStyle = isInterlace ? (weftColorsArray[p%weftColorsArray.length] || '#ccc') : '#f1f5f9';
                }
                ctx.fillRect(x, y, cellW - 0.5, cellH - 0.5);
            }
            renderX++;
        }
    }, [hookMap, data.structure, data.width, data.height, viewMode, showSelvedge, config.totalHooks, warpColorsArray, weftColorsArray]);

    const renderSelectors = useCallback((ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => {
        const weftSelectorIndices = techState.columns
            .map((c, i) => c.type === 'weft-selector' ? i : -1)
            .filter(i => i !== -1);

        for (let p = 0; p < data.height; p++) {
            const y = p * cellH;
            const currentYarnChar = weftSequence[p % weftSequence.length];
            const yarnIdx = currentYarnChar.charCodeAt(0) - 65; // A=0, B=1...

            for (let s = 0; s < config.selectorHooks; s++) {
                const col = techState.columns[s];
                let bit = techState.grid[p]?.[s] || false;

                // Auto-map logic: if it's a weft-selector, activate based on pattern
                if (autoMapWeft && col.type === 'weft-selector') {
                    const selectorOrder = weftSelectorIndices.indexOf(s);
                    bit = selectorOrder === yarnIdx;
                }

                ctx.fillStyle = bit ? (col?.color || '#3b82f6') : '#f1f5f9';
                ctx.fillRect(s * cellW, y, cellW - 0.5, cellH - 0.5);
            }
        }
    }, [techState.grid, techState.columns, config.selectorHooks, data.height, weftSequence, autoMapWeft]);

    return (
        <div className="flex h-full bg-white text-gray-900 overflow-hidden font-sans">
            {/* SIDEBAR */}
            <div className="w-80 border-r border-gray-200 flex flex-col bg-gray-50 shrink-0 z-10 shadow-lg">
                <div className="p-5 border-b border-gray-200 bg-white">
                    <div className="flex items-center gap-3 mb-6">
                        <TerminalIcon className="w-6 h-6 text-blue-600" />
                        <h2 className="text-sm font-black uppercase tracking-widest text-gray-800">Tech Control</h2>
                    </div>

                    <div className="space-y-6">
                        <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 space-y-4">
                            <h3 className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Display Mode</h3>
                            <div className="flex bg-white rounded p-1 border border-gray-200 shadow-sm">
                                <button onClick={() => setViewMode('graph')} className={`flex-1 py-1.5 text-[9px] font-bold rounded transition-all ${viewMode === 'graph' ? 'bg-gray-800 text-white' : 'text-gray-400'}`}>Simple Graph</button>
                                <button onClick={() => setViewMode('interlace')} className={`flex-1 py-1.5 text-[9px] font-bold rounded transition-all ${viewMode === 'interlace' ? 'bg-gray-800 text-white' : 'text-gray-400'}`}>Interlaced</button>
                            </div>

                            <div className="space-y-2">
