                                        {activeSelvedgeZone === zone.id && showSelvedge && (
                                            <div className="mt-2 grid grid-cols-4 gap-1.5 border-t border-gray-100 pt-2">
                                                {WEAVE_LIBRARY.slice(0, 8).map(w => (
                                                    <button key={w.id} onClick={() => { handleAssignWeave(zone.id, w.id); setActiveSelvedgeZone(null); }} className={`aspect-square rounded border transition-all ${zone.weaveId === w.id ? 'border-blue-500 ring-2 ring-blue-100' : 'border-gray-200 hover:border-gray-400'}`}><WeaveThumbnail weave={w} className="w-full h-full border-none opacity-60" /></button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
                <div className="flex-1 p-5 bg-gray-50 overflow-y-auto custom-scrollbar border-t border-gray-200">
                     <p className="text-[10px] text-gray-400 leading-relaxed italic">Loom selectors are fixed in the left column. Horizontal scroll reveals technical selvedge and design address space in high-contrast light mode.</p>
                </div>
            </div>

            {/* MAIN CONTENT SPLIT VIEW */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden bg-white">
                <div className="h-10 border-b border-gray-200 bg-white px-6 flex items-center justify-between shrink-0 shadow-sm z-20">
                    <div className="flex items-center gap-6">
                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Address Logic: 0 → {config.totalHooks + config.selectorHooks}</span>
                        <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-lg border border-gray-200">
                            <button onClick={() => setScale(s => Math.max(0.1, s - 0.1))} className="p-1 text-gray-400 hover:text-blue-600 transition-colors"><ZoomOutIcon className="w-4 h-4" /></button>
                            <span className="px-3 text-[10px] font-mono font-bold text-blue-600">{Math.round(scale * 100)}%</span>
                            <button onClick={() => setScale(s => Math.min(1.5, s + 0.1))} className="p-1 text-gray-400 hover:text-blue-600 transition-colors"><ZoomInIcon className="w-4 h-4" /></button>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]" />
