    return () => clearTimeout(timer);
  }, [isOpen, weavePattern, structure, epi, ppi, dentingPlan, weftZones, warpYarns, weftYarns, warpYarnSequence, weftYarnSequence, simulationDpi, smoothing, viewSide, hideFloats, bgMode]);

