            weftYarns: { ...weftYarns },
            warpPatternString,
            weftPatternString,
            settings: { ...settings }
        };
        setJacquardData(prevData => ({ ...prevData, structure: lastSnapshot.structure, width: lastSnapshot.settings.warpThreads, height: lastSnapshot.settings.weftPicks }));
        setAppliedWeaves(lastSnapshot.appliedWeaves);
        setArtwork(lastSnapshot.artwork);
        setWarpYarns(lastSnapshot.warpYarns);
        setWeftYarns(lastSnapshot.weftYarns);
        setWarpPatternString(lastSnapshot.warpPatternString);
        setWeftPatternString(lastSnapshot.weftPatternString);
        setSettings(lastSnapshot.settings);
        return { past: newPast, future: [current, ...prev.future] };
    });
  }, [jacquardData, appliedWeaves, artwork, warpYarns, weftYarns, warpPatternString, weftPatternString, settings]);

  const redo = useCallback(() => {
    setHistory(prev => {
        if (prev.future.length === 0) return prev;
        const nextSnapshot = prev.future[0];
        const newFuture = prev.future.slice(1);
        const current: HistoryState = {
            structure: new Uint8Array(jacquardData.structure),
            appliedWeaves: { ...appliedWeaves },
            artwork: artwork ? { ...artwork, data: new Uint8Array(artwork.data) } : null,
            warpYarns: { ...warpYarns },
            weftYarns: { ...weftYarns },
            warpPatternString,
            weftPatternString,
            settings: { ...settings }
        };
        setJacquardData(prevData => ({ ...prevData, structure: nextSnapshot.structure, width: nextSnapshot.settings.warpThreads, height: nextSnapshot.settings.weftPicks }));
        setAppliedWeaves(nextSnapshot.appliedWeaves);
        setArtwork(lastSnapshot.artwork);
        setWarpYarns(nextSnapshot.warpYarns);
        setWeftYarns(nextSnapshot.weftYarns);
        setWarpPatternString(nextSnapshot.warpPatternString);
        setWeftPatternString(nextSnapshot.weftPatternString);
        setSettings(nextSnapshot.settings);
        return { past: [...prev.past, current], future: newFuture };
    });
  }, [jacquardData, appliedWeaves, artwork, warpYarns, weftYarns, warpPatternString, weftPatternString, settings]);

  useEffect(() => {
      const source = selectedYarnType === 'warp' ? warpYarns : weftYarns;
      if (source[activeYarnId]) setStudioYarnDef(source[activeYarnId]);
  }, [activeYarnId, selectedYarnType, warpYarns, weftYarns]);

  // Auto-collapse panel in wide UI modes
  useEffect(() => {
    if (['loom-tech', 'loom-editor', 'weave-studio'].includes(appMode)) {
        setIsPanelCollapsed(true);
    } else {
        setIsPanelCollapsed(false);
    }
  }, [appMode]);

  const handleResize = (size: number) => {
      saveHistory();
      const newStructure = new Uint8Array(size * size).fill(0);
      const minSize = Math.min(size, jacquardData.width);
      for(let y = 0; y < minSize; y++) newStructure.set(jacquardData.structure.subarray(y * jacquardData.width, y * jacquardData.width + minSize), y * size);
      setJacquardData({ width: size, height: size, structure: newStructure });
      setSettings(prev => ({ ...prev, warpThreads: size, weftPicks: size }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      saveHistory();
      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 
          setArtwork({ data: new Uint8Array(result.pixels), palette: result.palette, width: result.width, height: result.height });
          setAppliedWeaves({});
          setJacquardData({ width: result.width, height: result.height, structure: new Uint8Array(result.width * result.height).fill(0) });
          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`); setWeftPatternString(`${result.height}A`);
          setProjectName(file.name.split('.')[0]); setViewMode('structure'); setAppMode('art'); setLoadingStatus(null);
      } catch (err: any) { alert(err.message || "Error processing."); setLoadingStatus(null); }
  };

  const handleApplyWeaveToColor = (weave: LibraryWeave, colorIdx: number) => {
    if (!artwork) return;
    saveHistory();
    setLoadingStatus(`Applying ${weave.name}...`);
    setTimeout(() => {
        const newStructure = new Uint8Array(jacquardData.structure);
        const { width, height } = jacquardData, weaveDraft = weave.draft, weavePeg = weave.pegPlan, weaveW = weaveDraft[0].length, weaveH = weavePeg.length;
        const weaveLookup = new Uint8Array(weaveW * weaveH);
        const warpToHarness = new Int16Array(weaveW).fill(-1);
        for(let w=0; w<weaveW; w++) for(let h=0; h<weave.harnesses; h++) if(weaveDraft[h][w] === 1) { warpToHarness[w] = h; break; }
        for(let y=0; y<weaveH; y++) for(let x=0; x<weaveW; x++) if(warpToHarness[x] !== -1 && weavePeg[y][warpToHarness[x]] === 1) weaveLookup[y * weaveW + x] = 1;
        for(let i=0; i<artwork.data.length; i++) if(artwork.data[i] === colorIdx) { const x = i % width, y = Math.floor(i / width); newStructure[i] = weaveLookup[(y % weaveH) * weaveW + (x % weaveW)]; }
        setAppliedWeaves(prev => ({ ...prev, [colorIdx]: weave }));
        setJacquardData(prev => ({ ...prev, structure: newStructure })); 
        setLoadingStatus(null); setViewMode('interlace');
    }, 50);
  };

  const handleMergeColors = (sourceIdx: number, targetIdx: number) => {
    if (!artwork || sourceIdx === targetIdx) return;
    saveHistory();
    setLoadingStatus("Merging Colors...");
    setTimeout(() => {
        const newData = new Uint8Array(artwork.data);
        for(let i=0; i<newData.length; i++) {
            if(newData[i] === sourceIdx) newData[i] = targetIdx;
            else if(newData[i] > sourceIdx) newData[i]--; 
        }
        const newPalette = artwork.palette.filter((_, i) => i !== sourceIdx);
        const newApplied: {[key: number]: LibraryWeave} = {};
        Object.keys(appliedWeaves).forEach(k => {
            const ki = parseInt(k);
            if (ki === sourceIdx) return;
            const nextK = ki > sourceIdx ? ki - 1 : ki;
            newApplied[nextK] = appliedWeaves[ki];
        });
        setAppliedWeaves(newApplied);
        setArtwork({ ...artwork, data: newData, palette: newPalette });
        setLoadingStatus(null);
    }, 50);
  };

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      return Array.from({ length: jacquardData.width }, (_, i) => warpYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const weftColorArray = useMemo(() => {
      const seq = expandPatternString(weftPatternString);
      return Array.from({ length: jacquardData.height }, (_, i) => weftYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [weftYarns, weftPatternString, jacquardData.height]);

  const simData = useMemo(() => {
      const { width, height, structure } = jacquardData;
      const rows: boolean[][] = []; const colors: string[][] = [];
      for (let y = 0; y < height; y++) {
          const rowB: boolean[] = []; const rowC: string[] = [];
          for (let x = 0; x < width; x++) {
              const isUp = structure[y * width + x] === 1;
              rowB.push(isUp); rowC.push(isUp ? warpColorArray[x] : weftColorArray[y]);
          }
          rows.push(rowB); colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [jacquardData, warpColorArray, weftColorArray, showSimModal]);

  const handleApplyStudioYarn = () => {
    saveHistory();
    if (selectedYarnType === 'warp') setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    else setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    setAppMode('art'); 
  };

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />
        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={history.past.length > 0} canRedo={history.future.length > 0} 
            onUndo={undo} onRedo={redo}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex flex-1 overflow-hidden pl-20 relative">
            <div className="absolute left-0 top-0 bottom-0 z-40">
                <ProgressiveToolbar mode={appMode} onModeChange={(m) => {
                    if (m === 'sim') setShowSimModal(true);
                    else setAppMode(m);
                }} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                {appMode !== 'weave-studio' && appMode !== 'loom-tech' && appMode !== 'loom-editor' && (
                    <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                        <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                            <span className="text-blue-400 font-bold">{projectName}</span>
                            <span>{jacquardData.width} × {jacquardData.height}</span>
                        </div>
                        <div className="flex items-center gap-4">
                            <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                                <button onClick={() => setViewMode('interlace')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>INTERLACE</button>
                                <button onClick={() => setViewMode('structure')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>ARTWORK</button>
                                <button onClick={() => setViewMode('graph')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'graph' ? 'bg-blue-600 text-white' : 'text-gray-400'}`}>GRAPH</button>
                            </div>
                            <div className="flex items-center gap-1 border-l border-gray-800 pl-4">
                                {[1024, 2048, 4096].map(size => (<button key={size} onClick={() => handleResize(size)} className={`px-2 py-0.5 rounded text-[10px] border ${jacquardData.width === size ? 'bg-blue-600 border-blue-500 text-white' : 'border-gray-700 text-gray-400'}`}>{size}</button>))}
                            </div>
                        </div>
                    </div>
                )}

                <div className="flex-1 relative">
                    {appMode === 'yarn' ? (
                        <div className="absolute inset-0 h-full"><YarnStudio yarn={studioYarnDef} onChange={setStudioYarnDef} onApply={handleApplyStudioYarn} /></div>
                    ) : appMode === 'tech' ? (
                        <div className="bg-white text-gray-900 h-full overflow-hidden absolute inset-0"><ProductionCalculator settings={settings} warpYarns={warpYarns} weftYarns={weftYarns} warpPatternString={warpPatternString} weftPatternString={weftPatternString} draft={[]} pegPlan={[]} generateThumbnail={() => ""} /></div>
                    ) : appMode === 'weave-studio' ? (
                        <div className="absolute inset-0 h-full"><WeaveStudio onSaveToLibrary={(w) => setCustomWeaves(prev => [...prev, w])} /></div>
                    ) : appMode === 'loom-tech' ? (
                        <div className="absolute inset-0 h-full"><LoomTechModule data={jacquardData} settings={settings} weftYarns={weftYarns} weftPatternString={weftPatternString} warpYarns={warpYarns} warpPatternString={warpPatternString} techState={techState} onTechStateUpdate={setTechState} config={loomConfig} onConfigUpdate={setLoomConfig} /></div>
                    ) : appMode === 'loom-editor' ? (
                        <div className="absolute inset-0 h-full"><LoomEditorModule config={loomConfig} onUpdate={setLoomConfig} techState={techState} onTechStateUpdate={setTechState} /></div>
                    ) : (
                        <JacquardCanvas 
                            data={jacquardData} artwork={artwork || undefined} 
                            onUpdate={(d) => { saveHistory(); setJacquardData(prev => ({ ...prev, structure: d })); }} 
                            tool={currentTool} viewMode={viewMode} faceMode={faceMode} 
                            warpColors={warpColorArray} weftColors={weftColorArray} 
                            settings={settings}
                            onViewChange={setCanvasView}
                        />
                    )}
                </div>

                {artwork && (appMode === 'art' || appMode === 'weave') && (
                    <div className="h-24 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl">
                        <div className="flex flex-col"><span className="text-[9px] font-bold text-gray-500 uppercase mb-1">Palette Optimized</span><span className="text-[10px] text-gray-400 font-mono italic">Drop yarn or weave</span></div>
                        <div className="flex-1 flex items-center gap-3 overflow-x-auto no-scrollbar py-2">
                            {artwork.palette.map((color, idx) => (
                                <div 
                                    key={idx} 
                                    draggable
                                    onDragStart={(e) => { e.dataTransfer.setData('color-idx', idx.toString()); }}
                                    onDragOver={e => { e.preventDefault(); setDragOverColorIdx(idx); }} 
                                    onDragLeave={() => setDragOverColorIdx(null)} 
                                    onDrop={e => { 
                                        e.preventDefault(); 
                                        setDragOverColorIdx(null); 
                                        const weaveD = e.dataTransfer.getData('weave-obj'); 
                                        const sourceC = e.dataTransfer.getData('color-idx');
                                        const yarnId = e.dataTransfer.getData('yarn-id');
                                        const yarnType = e.dataTransfer.getData('yarn-type');
                                        if (weaveD) handleApplyWeaveToColor(JSON.parse(weaveD), idx); 
                                        else if (sourceC !== "") handleMergeColors(parseInt(sourceC), idx);
                                        else if (yarnId) {
                                            const def = (yarnType === 'warp' ? warpYarns : weftYarns)[yarnId];
                                            if (def && artwork) {
                                                const newPalette = [...artwork.palette];
                                                newPalette[idx] = def.color;
                                                setArtwork({ ...artwork, palette: newPalette });
                                            }
                                        }
                                    }} 
                                    className={`group flex flex-col items-center gap-1 shrink-0 bg-gray-800/40 p-2 rounded-lg border transition-all ${dragOverColorIdx === idx ? 'bg-blue-900/40 border-blue-500 scale-105 shadow-lg shadow-blue-500/20' : 'border-gray-700/50 hover:bg-gray-800'}`}
                                >
                                    <div className="relative w-10 h-10">
                                        <div className="w-full h-full rounded-md border border-white/10 shadow-md" style={{ backgroundColor: color }} />
                                        {appliedWeaves[idx] && (
                                            <div className="absolute inset-0 rounded-md overflow-hidden bg-black/40 flex items-center justify-center">
                                                <WeaveThumbnail weave={appliedWeaves[idx]} className="w-full h-full opacity-70" />
                                            </div>
                                        )}
                                    </div>
                                    <span className="text-[8px] font-mono text-gray-500 uppercase truncate max-w-[64px]">{appliedWeaves[idx] ? appliedWeaves[idx].name : color}</span>
                                </div>
                            ))}
                        </div>
                        <div className="flex flex-col gap-1 items-end shrink-0"><span className="text-[8px] font-bold text-blue-500 animate-pulse mb-1 uppercase">Drop unit to apply</span><button onClick={() => setArtwork(null)} className="px-3 py-1 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded font-bold uppercase">Clear Art</button></div>
                    </div>
                )}
            </div>

            <div className={`transition-all duration-300 ${isPanelCollapsed ? 'w-0 opacity-0 overflow-hidden' : 'w-80'}`}>
                <RightPanel 
                    settings={settings} onSettingsChange={(s) => { saveHistory(); setSettings(s); }} dentingPattern={dentingPattern} onDentingChange={setDentingPattern} onSnapshot={saveHistory} onLoadWeave={()=>{}} 
                    customWeaves={customWeaves} onAddWeave={()=>{}} onUpdateWeave={()=>{}} onDeleteWeave={()=>{}} 
                    warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(id, d) => { saveHistory(); setWarpYarns(p => ({...p, [id]: d})); }} onUpdateWeftYarn={(id, d) => { saveHistory(); setWeftYarns(p => ({...p, [id]: d})); }} paletteColors={PANTONE_PALETTE} warpPatternString={warpPatternString} setWarpPatternString={(s) => { saveHistory(); setWarpPatternString(s); }} weftPatternString={weftPatternString} setWeftPatternString={(s) => { saveHistory(); setWeftPatternString(s); }} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{} as any} onApplyGenerated={()=>{}} onSimulate={() => setShowSimModal(true)} onGridOperation={(t, a) => { saveHistory(); const newData = new Uint8Array(jacquardData.structure); if (a === 'clear') newData.fill(0); else if (a === 'invert') for(let i=0; i<newData.length; i++) newData[i] = newData[i] === 1 ? 0 : 1; setJacquardData(prev => ({ ...prev, structure: newData })); }} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { setActiveYarnId(id); setSelectedYarnType(type); setAppMode('yarn'); }}
                    onOpenPixelEditor={() => setShowCustomModal(true)}
                    jacquardData={jacquardData}
                    canvasView={canvasView}
                />
            </div>

            {/* Toggle Panel Button on Edge */}
            <button 
                onClick={() => setIsPanelCollapsed(!isPanelCollapsed)}
                className={`absolute top-1/2 -translate-y-1/2 z-50 bg-gray-800 border border-gray-700 p-1.5 rounded-l-md hover:bg-gray-700 transition-all ${isPanelCollapsed ? 'right-0' : 'right-80'}`}
                title={isPanelCollapsed ? "Expand Sidebar" : "Collapse Sidebar"}
            >
                <div className={`transition-transform duration-300 ${isPanelCollapsed ? 'rotate-180' : ''}`}>
                    <svg className="w-3 h-3 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
                </div>
            </button>
        </div>
        <FabricSimulationModal isOpen={showSimModal} onClose={() => setShowSimModal(false)} weavePattern={simData.colors} structure={simData.structure} epi={settings.epi} ppi={settings.ppi} dentingPlan={dentingPattern.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n))} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { WeaveArea } from './WeaveArea';
import { TopToolbar } from './TopToolbar';
import { RightPanel } from './RightPanel';
import { ProgressiveToolbar } from './ProgressiveToolbar';
import { FabricSimulationModal } from './FabricSimulationModal';
import { YarnSelectorModal } from './YarnSelectorModal';
import { generateWeave, reconstructWeaveFromGrid } from '../services/weaveGenerator';
import { WeaveSettings, WeavePattern, WeaveInput, ToolType, ViewMode, FaceMode, YarnDefinition, DensityZone, Colorway, AppMode, LibraryWeave } from '../types';
import { parsePatternString, getTotalThreads, expandPatternString, compressPatternString } from '../utils/patternParser';
import { WEAVE_LIBRARY } from '../services/weaveLibrary';
import { PANTONE_PALETTE } from '../services/pantoneColors';
import { generateSpecSheet } from '../services/pdfGenerator';
import { ProductionCalculator } from './ProductionCalculator'; 
import { YarnStudio } from './YarnStudio';
import { ProjectManagerModal } from './ProjectManagerModal'; 
import { ColorwayStudio } from './ColorwayStudio';

import { WeaveProjectFile, APP_VERSION } from '../services/io/schemas';
import { downloadFile, loadFile, serializeGrid, deserializeGrid } from '../services/io/fileHandler';
import { StorageService } from '../services/io/storage'; 
import { renderFabricToCanvas } from '../services/fabricRenderer'; 

interface HistoryState {
    draft: boolean[][];
    pegPlan: boolean[][];
    warpPatternString: string;
    weftPatternString: string;
    dentingPatternString: string;
    dentingPlan: number[];
    settings: WeaveSettings;
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    weftZones: DensityZone[];
}

export const DobbyMaster: React.FC = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [appMode, setAppMode] = useState<AppMode>('weave');
  const [showSimModal, setShowSimModal] = useState(false);
  const [showProjectManager, setShowProjectManager] = useState(false); 

  const [settings, setSettings] = useState<WeaveSettings>({
    warpThreads: 8, 
    weftPicks: 8, 
    harnesses: 8, 
    epi: 24, 
    ppi: 24, 
    gridDivision: 4, 
    gridX: 8, 
    gridY: 8,
    warpFloatThreshold: 8,
    weftFloatThreshold: 8
  });

  const [projectName, setProjectName] = useState('Untitled Project'); 
  const [paletteColors] = useState<string[]>(PANTONE_PALETTE);
  const [customWeaves, setCustomWeaves] = useState<LibraryWeave[]>([]);

  const createDefaultYarn = (color: string | undefined): YarnDefinition => ({
      color: color || '#CCCCCC', 
      model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 28, ply: 1, thickness: 1.0, twist: 'Z', tpi: 15, sheen: 0.5, roughness: 0.5, price: 0,
      bindingDepth: 0.05
  });

  const defaultWarp: { [key: string]: YarnDefinition } = { 'A': createDefaultYarn(PANTONE_PALETTE[38]), 'B': createDefaultYarn(PANTONE_PALETTE[20]) };
  const defaultWeft: { [key: string]: YarnDefinition } = { 'A': createDefaultYarn(PANTONE_PALETTE[35]), 'B': createDefaultYarn(PANTONE_PALETTE[27]) };

  const [warpYarns, setWarpYarns] = useState<{ [key: string]: YarnDefinition }>(defaultWarp);
  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>(defaultWeft);

  const [colorways, setColorways] = useState<Colorway[]>([]);

  const warpColors = useMemo(() => {
      const map: {[key:string]: string} = {};
      (Object.entries(warpYarns) as [string, YarnDefinition][]).forEach(([k,v]) => { if(v) map[k] = v.color; });
      return map;
  }, [warpYarns]);

  const weftColors = useMemo(() => {
      const map: {[key:string]: string} = {};
      (Object.entries(weftYarns) as [string, YarnDefinition][]).forEach(([k,v]) => { if(v) map[k] = v.color; });
      return map;
  }, [weftYarns]);

  const [selectedColorIndex, setSelectedColorIndex] = useState(0); 
  const [activeYarnId, setActiveYarnId] = useState<string>('A');
  const [selectedYarnType, setSelectedYarnType] = useState<'warp' | 'weft'>('warp');
  const [studioYarnDef, setStudioYarnDef] = useState<YarnDefinition>(defaultWarp['A']);

  useEffect(() => {
      const source = selectedYarnType === 'warp' ? warpYarns : weftYarns;
      if (source[activeYarnId]) {
          setStudioYarnDef(source[activeYarnId]);
      }
  }, [activeYarnId, selectedYarnType, warpYarns, weftYarns]); 

  const [warpPatternString, setWarpPatternString] = useState('4A4B');
  const [weftPatternString, setWeftPatternString] = useState('4A4B');
  const [weftZones, setWeftZones] = useState<DensityZone[]>([]);

  const [dentingPatternString, setDentingPatternString] = useState('2');
  const [dentingPlan, setDentingPlan] = useState<number[]>(() => Array(8).fill(2));

  const [draft, setDraft] = useState<boolean[][]>(() => Array.from({ length: 8 }, (_, h) => Array.from({ length: 8 }, (_, w) => (w % 8) === h)));
  const [pegPlan, setPegPlan] = useState<boolean[][]>(() => Array.from({ length: 8 }, (_, p) => Array.from({ length: 8 }, (_, h) => ((p % 8) === h))));

  const [history, setHistory] = useState<{ past: HistoryState[], future: HistoryState[] }>({ past: [], future: [] });

  const copyGrid = (grid: boolean[][]) => grid.map(row => [...row]);

  useEffect(() => {
      const parts = dentingPatternString.split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n) && n >= 0);
      setDentingPlan(parts.length > 0 ? parts : [2]);
  }, [dentingPatternString]);

  const saveHistory = useCallback(() => {
    setHistory(prev => {
        const currentSnapshot: HistoryState = {
            draft: copyGrid(draft), pegPlan: copyGrid(pegPlan), warpPatternString, weftPatternString, dentingPatternString, dentingPlan: [...dentingPlan], settings: { ...settings }, warpYarns: { ...warpYarns }, weftYarns: { ...weftYarns }, weftZones: [...weftZones]
        };
        const newPast = [...prev.past, currentSnapshot];
        if (newPast.length > 50) newPast.shift(); 
        return { past: newPast, future: [] };
    });
  }, [draft, pegPlan, warpPatternString, weftPatternString, dentingPatternString, dentingPlan, settings, warpYarns, weftYarns, weftZones]);

  const undo = useCallback(() => {
      setHistory(prev => {
          if (prev.past.length === 0) return prev;
          const previous = prev.past[prev.past.length - 1];
          const newPast = prev.past.slice(0, -1);
          setDraft(previous.draft); setPegPlan(previous.pegPlan); setWarpPatternString(previous.warpPatternString); setWeftPatternString(previous.weftPatternString); setDentingPatternString(previous.dentingPatternString || '2'); setDentingPlan(previous.dentingPlan || [2]); setSettings(previous.settings); setWarpYarns(previous.warpYarns); setWeftYarns(previous.weftYarns); setWeftZones(previous.weftZones || []);
          return { past: newPast, future: [previous, ...prev.future] }; 
      });
  }, [saveHistory]);

  const handleModeChange = (newMode: AppMode) => { 
      if (newMode === 'sim') setShowSimModal(true);
      else setAppMode(newMode); 
  };

  const handleYarnSelect = (id: string, type: 'warp' | 'weft') => {
      setActiveYarnId(id);
      setSelectedYarnType(type);
      setAppMode('yarn');
  };

  const handleApplyStudioYarn = () => {
      saveHistory();
      if (selectedYarnType === 'warp') {
          setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
      } else {
          setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
      }
  };

  const warpPattern = useMemo(() => {
    const parsed = parsePatternString(warpPatternString, warpColors);
    if (parsed.length === 0) return Array(settings.warpThreads).fill('#888888');
    return Array.from({ length: settings.warpThreads }, (_, i) => parsed[i % parsed.length]);
  }, [warpPatternString, warpColors, settings.warpThreads]);

  const weftPattern = useMemo(() => {
    const parsed = parsePatternString(weftPatternString, weftColors);
     if (parsed.length === 0) return Array(settings.weftPicks).fill('#888888');
    return Array.from({ length: settings.weftPicks }, (_, i) => parsed[i % parsed.length]);
  }, [weftPatternString, weftColors, settings.weftPicks]);

  const weavePattern: WeavePattern = useMemo(() => {
    return generateWeave({ draft, pegPlan, warpPattern, weftPattern });
  }, [draft, pegPlan, warpPattern, weftPattern]);

  const generateThumbnail = useCallback(() => {
      const thumbCanvas = renderFabricToCanvas({
          weavePattern: weavePattern.pattern, structure: weavePattern.structure, epi: settings.epi, ppi: settings.ppi, dentingPlan, warpYarns, weftYarns, warpYarnSequence: expandPatternString(warpPatternString), weftYarnSequence: expandPatternString(weftPatternString), viewSide: 'face', dpi: 72, width: 600, height: 300
      });
      return thumbCanvas.toDataURL('image/jpeg', 0.8);
  }, [weavePattern, settings, dentingPlan, warpYarns, weftYarns, warpPatternString, weftPatternString]);

  const handleExport = useCallback(async () => {
      try {
          const projectData = {
              fileType: 'wonderweaves-project', version: APP_VERSION, timestamp: Date.now(), name: projectName, loom: settings,
              grids: { draft: serializeGrid(draft), pegPlan: serializeGrid(pegPlan), denting: dentingPlan },
              patterns: { warpString: warpPatternString, weftString: weftPatternString },
              resources: { warpYarns, weftYarns, weftZones, palette: paletteColors }
          };
          const cleanName = (projectName || 'Untitled').replace(/[/\\?%*:|"<>]/g, '-').replace(/\s+/g, '_');
          const filename = `${cleanName}-${new Date().toISOString().split('T')[0]}.weave`;
          downloadFile(JSON.stringify(projectData, null, 2), filename);
      } catch (e) {
          console.error("Export failed:", e);
      }
  }, [projectName, settings, draft, pegPlan, dentingPlan, warpPatternString, weftPatternString, warpYarns, weftYarns, weftZones, paletteColors]);

  const loadProjectData = (data: WeaveProjectFile) => {
      saveHistory();
      setProjectName(data.name || 'Untitled');
      setSettings(data.loom);
      setDraft(deserializeGrid(data.grids.draft));
      setPegPlan(deserializeGrid(data.grids.pegPlan));
      setDentingPlan(data.grids.denting);
      setDentingPatternString(data.grids.denting.join(', '));
      setWarpPatternString(data.patterns.warpString);
      setWeftPatternString(data.patterns.weftString);
      setWarpYarns(data.resources.warpYarns);
      setWeftYarns(data.resources.weftYarns);
      setWeftZones(data.resources.weftZones || []);
  };

  const handleLoadFromFile = async (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;
      try {
          const content = await loadFile(file);
          if (!content.includes('wonderweaves-project')) {
              alert("Invalid project file format.");
              return;
          }
          loadProjectData(JSON.parse(content));
      } catch (e) { 
          console.error(e);
          alert("Failed to load design. Ensure the file is a valid .weave project.");
      } finally {
          if (fileInputRef.current) fileInputRef.current.value = "";
      }
  };

  const handleLoadFromStorage = async (id: string) => {
      try {
          const data = await StorageService.loadProject(id);
          loadProjectData(data);
      } catch (e) { console.error(e); }
  };

  const handlePdfDownload = () => {
      generateSpecSheet({ settings, warpYarns, weftYarns, warpPatternString, weftPatternString, dentingPlan, dentingPatternString, draft, pegPlan, weavePattern });
  };

  const [yarnSelectorState, setYarnSelectorState] = useState<{ isOpen: boolean; type: 'warp' | 'weft'; }>({ isOpen: false, type: 'warp' });

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');
  const [currentFillPatternId, setCurrentFillPatternId] = useState<string>('twill-2-2');

  const isDrawing = useRef(false);
  const drawVal = useRef(true);

  const dentingGrid = useMemo(() => {
      const dents = dentingPlan.length > 0 ? dentingPlan : [2];
      const row0: string[] = [];
      const row1: string[] = [];
      let dentIndex = 0, threadCount = 0, currentDentSize = dents[0];
      for(let i=0; i<settings.warpThreads; i++) {
          let loopGuard = 0;
          while(currentDentSize === 0 && loopGuard < dents.length * 2) {
              dentIndex++;
              currentDentSize = dents[dentIndex % dents.length];
              loopGuard++;
          }
          const isTop = dentIndex % 2 === 0;
          row0.push(isTop ? '#000000' : '#ffffff');
          row1.push(!isTop ? '#000000' : '#ffffff');
          threadCount++;
          if(threadCount >= currentDentSize) {
              dentIndex++;
              threadCount = 0;
              currentDentSize = dents[dentIndex % dents.length];
          }
      }
      return [row0, row1]; 
  }, [dentingPlan, settings.warpThreads]);

  const handleSettingsChange = (newSettings: WeaveSettings) => {
      saveHistory();
      setSettings(newSettings);
      if (newSettings.harnesses !== settings.harnesses || newSettings.warpThreads !== settings.warpThreads) {
          setDraft(Array.from({ length: newSettings.harnesses }, (_, h) => 
              Array.from({ length: newSettings.warpThreads }, (_, w) => draft[h] ? (draft[h][w] || false) : (w % newSettings.harnesses === h))));
      }
      if (newSettings.harnesses !== settings.harnesses || newSettings.weftPicks !== settings.weftPicks) {
          setPegPlan(Array.from({ length: newSettings.weftPicks }, (_, p) => 
              Array.from({ length: newSettings.harnesses }, (_, h) => pegPlan[p] ? (pegPlan[p][h] || false) : (p % newSettings.harnesses === h))));
      }
  };

  const handleSyncGrid = (warpLen: number, weftLen: number) => {
      saveHistory();
      const newSettings = { ...settings, warpThreads: Math.max(4, warpLen), weftPicks: Math.max(4, weftLen) };
      setSettings(newSettings);
      setDraft(Array.from({ length: newSettings.harnesses }, (_, h) => Array.from({ length: newSettings.warpThreads }, (_, w) => draft[h] ? draft[h][w % (draft[0]?.length||1)] : (w%newSettings.harnesses===h))));
      setPegPlan(Array.from({ length: newSettings.weftPicks }, (_, p) => Array.from({ length: newSettings.harnesses }, (_, h) => {
          const row = pegPlan[p % (pegPlan.length || 1)];
          return row ? row[h] : (p % newSettings.harnesses === h);
      })));
  };

  const handleDraftInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      if (type === 'down' || (type === 'enter' && isDrawing.current)) {
          if (type === 'down') { saveHistory(); isDrawing.current = true; }
          const newDraft = copyGrid(draft);
          for (let h = 0; h < newDraft.length; h++) if (newDraft[h]) newDraft[h][col] = false;
          if (newDraft[row]) newDraft[row][col] = true;
          setDraft(newDraft);
      } else if (type === 'up') isDrawing.current = false;
  };

  const handlePegPlanInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      if (type === 'down') {
          saveHistory(); isDrawing.current = true;
          drawVal.current = pegPlan[row] ? !pegPlan[row][col] : true;
          const newPeg = copyGrid(pegPlan);
          if (newPeg[row]) newPeg[row][col] = drawVal.current;
          setPegPlan(newPeg);
      } else if (type === 'enter' && isDrawing.current) {
          const newPeg = copyGrid(pegPlan);
          if (newPeg[row] && newPeg[row][col] !== drawVal.current) {
              newPeg[row][col] = drawVal.current;
              setPegPlan(newPeg);
          }
      } else if (type === 'up') isDrawing.current = false;
  };

  const handleDrawdownInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      let harnessIndex = -1;
      for(let h=0; h<draft.length; h++) if(draft[h] && draft[h][col]) { harnessIndex = h; break; }
      if (harnessIndex === -1) return;
      if (type === 'down') {
          saveHistory(); isDrawing.current = true;
          drawVal.current = (pegPlan[row] && pegPlan[row][harnessIndex]) ? !pegPlan[row][harnessIndex] : true;
          const newPeg = copyGrid(pegPlan);
          if (newPeg[row]) newPeg[row][harnessIndex] = drawVal.current;
          setPegPlan(newPeg);
      } else if (type === 'enter' && isDrawing.current) {
          const newPeg = copyGrid(pegPlan);
          if (newPeg[row] && newPeg[row][harnessIndex] !== drawVal.current) {
              newPeg[row][harnessIndex] = drawVal.current;
              setPegPlan(newPeg);
          }
      } else if (type === 'up') isDrawing.current = false;
  };

  const handleWarpColorInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      if (currentTool === 'brush') {
          if (type === 'down') { saveHistory(); isDrawing.current = true; }
          if (isDrawing.current || type === 'down') {
              const targetIdx = col % settings.warpThreads;
              const seq = expandPatternString(warpPatternString);
              while(seq.length < settings.warpThreads) {
                  const baseLen = seq.length || 1;
                  seq.push(seq[seq.length % baseLen] || 'A');
              }
              if (seq[targetIdx] !== activeYarnId) {
                  seq[targetIdx] = activeYarnId;
                  setWarpPatternString(compressPatternString(seq));
              }
          }
      } else if (type === 'down') {
          handleYarnSelect(expandPatternString(warpPatternString)[col % expandPatternString(warpPatternString).length], 'warp');
      }
      if (type === 'up') isDrawing.current = false;
  };

  const handleWeftColorInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      if (currentTool === 'brush') {
          if (type === 'down') { saveHistory(); isDrawing.current = true; }
          if (isDrawing.current || type === 'down') {
              const targetIdx = row % settings.weftPicks;
              const seq = expandPatternString(weftPatternString);
              while(seq.length < settings.weftPicks) {
                  const baseLen = seq.length || 1;
                  seq.push(seq[seq.length % baseLen] || 'A');
              }
              if (seq[targetIdx] !== activeYarnId) {
                  seq[targetIdx] = activeYarnId;
                  setWeftPatternString(compressPatternString(seq));
              }
          }
      } else if (type === 'down') {
          handleYarnSelect(expandPatternString(weftPatternString)[row % expandPatternString(weftPatternString).length], 'weft');
      }
      if (type === 'up') isDrawing.current = false;
  };

  const handleDentingInteraction = (row: number, col: number, type: 'down' | 'enter' | 'up') => {
      const currentPlan = dentingPlan.length > 0 ? dentingPlan : [2], boolMap: boolean[] = [];
      let state = true, pIdx = 0;
      while(boolMap.length < settings.warpThreads) {
          for(let k=0; k<currentPlan[pIdx % currentPlan.length]; k++) boolMap.push(state);
          state = !state; pIdx++;
      }
      let changed = false;
      const targetCol = col % settings.warpThreads;
      if (type === 'down') { saveHistory(); isDrawing.current = true; drawVal.current = row === 0; if (boolMap[targetCol] !== drawVal.current) { boolMap[targetCol] = drawVal.current; changed = true; } }
      else if (type === 'enter' && isDrawing.current) { if (boolMap[targetCol] !== drawVal.current) { boolMap[targetCol] = drawVal.current; changed = true; } }
      else if (type === 'up') { isDrawing.current = false; return; }
      if (changed) {
          const newPlan: number[] = [];
          if (boolMap.length > 0) {
              if (boolMap[0] === false) newPlan.push(0);
              let run = 1, last = boolMap[0];
              for(let i=1; i<boolMap.length; i++) { if (boolMap[i] === last) run++; else { newPlan.push(run); last = boolMap[0]; run = 1; } }
              newPlan.push(run);
          }
          setDentingPlan(newPlan); setDentingPatternString(newPlan.join(','));
      }
  };

  const handleLoadWeave = (weave: LibraryWeave) => {
      saveHistory();
      setSettings(prev => ({ ...prev, harnesses: weave.harnesses }));
      setDraft(Array.from({ length: weave.harnesses }, (_, h) => Array.from({ length: settings.warpThreads }, (_, w) => weave.draft[h][w % weave.draft[0].length] === 1)));
      setPegPlan(Array.from({ length: settings.weftPicks }, (_, p) => Array.from({ length: weave.harnesses }, (_, h) => weave.pegPlan[p % weave.pegPlan.length][h] === 1)));
  };

  const handleStructureApply = (char: string, dent?: number) => {
      saveHistory();

      const isWarp = yarnSelectorState.type === 'warp';
      const totalWarpEnds = settings.warpThreads;

      const baseSeq = expandPatternString(warpPatternString);
      const fullWarpSeq: string[] = [];
      while(fullWarpSeq.length < totalWarpEnds) { fullWarpSeq.push(...baseSeq); }
      fullWarpSeq.length = totalWarpEnds;

      const seq = isWarp ? fullWarpSeq : expandPatternString(weftPatternString);
      const indices = seq.map((c, i) => c === char ? i : -1).filter(i => i !== -1);
      const targetW = WEAVE_LIBRARY.find(w => w.id === currentFillPatternId) || customWeaves.find(w => w.id === currentFillPatternId);

      if (indices.length && targetW) {
        const { structure: libS } = generateWeave({ draft: targetW.draft.map(r=>r.map(c=>c===1)), pegPlan: targetW.pegPlan.map(r=>r.map(c=>c===1)), warpPattern: Array(targetW.draft[0].length).fill('A'), weftPattern: Array(targetW.pegPlan.length).fill('A') });
        const { structure: currentS } = generateWeave({ draft, pegPlan, warpPattern, weftPattern });
        const nG = currentS.map(row => [...row]);
        indices.forEach(idx => {
            if (isWarp) for(let r=0; r<settings.weftPicks; r++) nG[r][idx] = libS[r % libS.length][idx % libS[0].length];
            else for(let c=0; c<settings.warpThreads; c++) nG[idx][c] = libS[idx % libS.length][c % libS[0].length];
        });
        const { draft: nD, pegPlan: nP, harnesses: nH } = reconstructWeaveFromGrid(nG, settings.warpThreads, settings.weftPicks);
        setSettings(prev => ({ ...prev, harnesses: nH })); setDraft(nD); setPegPlan(nP);
      }

      if (isWarp && dent !== undefined && dent > 0) {
          const currentPlan = dentingPlan.length > 0 ? dentingPlan : [2];
          const threadDents: number[] = [];
          let pIdx = 0, tIdx = 0;
          while(tIdx < totalWarpEnds) {
              const size = currentPlan[pIdx % currentPlan.length];
              for(let k=0; k<size && tIdx < totalWarpEnds; k++) {
                  threadDents[tIdx++] = size;
              }
              pIdx++;
          }

          let i = 0;
          while (i < totalWarpEnds) {
              if (fullWarpSeq[i] === char) {
                  let run = 0;
                  while (i + run < totalWarpEnds && fullWarpSeq[i + run] === char && run < dent) {
                      run++;
                  }
                  for (let k = 0; k < run; k++) { threadDents[i + k] = run; }
                  i += run;
              } else {
                  i++;
              }
          }

          const newPlan: number[] = [];
          let cursor = 0;
          while (cursor < totalWarpEnds) {
              const groupSize = threadDents[cursor] || 2;
              newPlan.push(groupSize);
              cursor += groupSize;
          }
          setDentingPlan(newPlan);
          setDentingPatternString(newPlan.join(', '));
      }
  };

  const isYarnMode = appMode === 'yarn', isSpecsMode = appMode === 'specs', isWeaveMode = appMode === 'weave', isColorwayMode = appMode === 'colorways';
  const rightPanelTab = isSpecsMode ? 'construction' : (isYarnMode ? 'yarns' : 'weave');

  return (
    <div className="flex flex-col flex-1 h-full min-w-0">
         <input type="file" ref={fileInputRef} onChange={handleLoadFromFile} accept=".weave" style={{ display: 'none' }} />
         <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool} viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode} currentFillPatternId={currentFillPatternId}
            onFillPatternChange={setCurrentFillPatternId} canUndo={history.past.length > 0} canRedo={false}
            onUndo={undo} onRedo={()=>{}} onSave={handleExport} onLoad={() => setShowProjectManager(true)}
            onImport={() => fileInputRef.current?.click()}
            onDownloadPdf={handlePdfDownload} onApplyToWarp={() => { setYarnSelectorState({ isOpen: true, type: 'warp' }); }}
            onApplyToWeft={() => { setYarnSelectorState({ isOpen: true, type: 'weft' }); }}
        />
        <div className="absolute top-3 left-1/2 -translate-x-1/2 z-40 bg-white/90 backdrop-blur px-4 py-1 rounded-full shadow-sm border border-gray-200 hidden md:block">
            <input type="text" value={projectName} onChange={(e) => setProjectName(e.target.value)} className="bg-transparent text-center font-bold text-gray-700 text-xs focus:outline-none focus:text-blue-600 w-48" placeholder="Untitled Project" />
        </div>
        <div className="absolute left-0 top-14 bottom-0 z-40"><ProgressiveToolbar mode={appMode} onModeChange={handleModeChange} /></div>
        <div className="flex-1 relative overflow-hidden flex flex-row min-w-0 pl-20">
             {isYarnMode && <YarnStudio yarn={studioYarnDef} onChange={setStudioYarnDef} onApply={handleApplyStudioYarn} />}
             {isColorwayMode && <ColorwayStudio initialWarpYarns={warpYarns} initialWeftYarns={weftYarns} warpPatternString={warpPatternString} weftPatternString={weftPatternString} dentingPlan={dentingPlan} epi={settings.epi} ppi={settings.ppi} weavePattern={weavePattern} colorways={colorways} onColorwaysChange={setColorways} onApplyColorway={(w, p) => { saveHistory(); setWarpYarns(w); setWeftYarns(p); }} expandPatternString={expandPatternString} />}
             {(isWeaveMode || isSpecsMode) && (
                 <div className="flex-1 relative bg-gray-50 overflow-hidden">
                     <WeaveArea draft={draft} pegPlan={pegPlan} warpPattern={warpPattern} weftPattern={weftPattern} weavePattern={weavePattern.pattern} structure={weavePattern.structure} handleDraftInteraction={handleDraftInteraction} handlePegPlanInteraction={handlePegPlanInteraction} handleDrawdownInteraction={handleDrawdownInteraction} handleWarpColorInteraction={handleWarpColorInteraction} handleWeftColorInteraction={handleWeftColorInteraction} handleDentingInteraction={handleDentingInteraction} pegPlanActiveColor="#3B82F6" draftActiveColor="#3B82F6" currentTool={currentTool} gridDivision={settings.gridDivision} viewMode={viewMode} faceMode={faceMode} epi={settings.epi} ppi={settings.ppi} warpRepeat={settings.warpThreads} weftRepeat={settings.weftPicks} dentingGrid={dentingGrid} weftZones={weftZones} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
                 </div>
             )}
             {appMode === 'tech' && <ProductionCalculator settings={settings} warpYarns={warpYarns} weftYarns={weftYarns} warpPatternString={warpPatternString} weftPatternString={weftPatternString} dentingPlan={dentingPlan} draft={draft} pegPlan={pegPlan} generateThumbnail={generateThumbnail} />}
             {(isWeaveMode || isSpecsMode || isYarnMode) && (
                 <RightPanel
                    settings={settings} onSettingsChange={handleSettingsChange} dentingPattern={dentingPatternString} onDentingChange={setDentingPatternString} onSnapshot={saveHistory} onLoadWeave={handleLoadWeave} customWeaves={customWeaves} onAddWeave={(w)=>setCustomWeaves(p=>[...p,w])} onUpdateWeave={(w)=>setCustomWeaves(p=>p.map(cw=>cw.id===w.id?w:cw))} onDeleteWeave={(id)=>setCustomWeaves(p=>p.filter(cw=>cw.id!==id))} warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(c,d)=>setWarpYarns(p=>({...p,[c]:d}))} onUpdateWeftYarn={(c,d)=>setWeftYarns(p=>({...p,[c]:d}))} onUpdateAllYarns={(t,y)=>t==='warp'?setWarpYarns(y):setWeftYarns(y)} paletteColors={paletteColors} warpPatternString={warpPatternString} setWarpPatternString={setWarpPatternString} weftPatternString={weftPatternString} setWeftPatternString={setWeftPatternString} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{draft,pegPlan,warpPattern,weftPattern}} onApplyGenerated={(res)=>{saveHistory();if(res.draft)setDraft(deserializeGrid(res.draft));if(res.pegPlan)setPegPlan(deserializeGrid(res.pegPlan));if(res.warpPattern)setWarpPatternString(res.warpPattern);if(res.weftPattern)setWeftPatternString(res.weftPattern);}} onSimulate={()=>setShowSimModal(true)} selectedColorIndex={selectedColorIndex} onSelectColor={setSelectedColorIndex} onGridOperation={(t,op)=>{saveHistory();const g=t==='draft'?draft:pegPlan,sG=t==='draft'?setDraft:setPegPlan;let nG=copyGrid(g);if(op==='clear')nG=Array.from({length:g.length},()=>Array(g[0].length).fill(false));else if(op==='invert')nG=g.map(r=>r.map(c=>!c));else if(op==='shiftUp')nG=[...g.slice(1),g[0]];else if(op==='shiftDown')nG=[g[g.length-1],...g.slice(0,g.length-1)];else if(op==='shiftLeft')nG=g.map(r=>[...r.slice(1),r[0]]);else if(op==='shiftRight')nG=g.map(r=>[r[r.length-1],...r.slice(0,r.length-1)]);sG(nG);}} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { handleYarnSelect(id, type); setCurrentTool('brush'); }} onActiveYarnChange={(id) => { setActiveYarnId(id); setCurrentTool('brush'); }} forcedTab={rightPanelTab as any} onSyncGridDimensions={handleSyncGrid} />
             )}
        </div>
        <FabricSimulationModal isOpen={showSimModal} onClose={()=>setShowSimModal(false)} weavePattern={weavePattern.pattern} structure={weavePattern.structure} epi={settings.epi} ppi={settings.ppi} dentingPlan={dentingPlan} weftZones={weftZones} warpYarns={warpYarns} weftYarns={weftYarns} warpYarnSequence={expandPatternString(warpPatternString)} weftYarnSequence={expandPatternString(weftPatternString)} />
        <YarnSelectorModal isOpen={yarnSelectorState.isOpen} onClose={()=>setYarnSelectorState({...yarnSelectorState,isOpen:false})} title={`Select ${yarnSelectorState.type==='warp'?'Warp':'Weft'} Yarn`} yarns={yarnSelectorState.type==='warp'?warpYarns:weftYarns} onSelect={(c, d)=>handleStructureApply(c, d)} isWarp={yarnSelectorState.type==='warp'} />
        <ProjectManagerModal isOpen={showProjectManager} onClose={()=>setShowProjectManager(false)} onLoadProject={handleLoadFromStorage} onImport={()=>fileInputRef.current?.click()} />
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { JacquardData, LoomTechState, LoomConfiguration, LoomHookZone, WeaveSettings, YarnDefinition, LibraryWeave } from '../types';
import { TerminalIcon, ZoomInIcon, ZoomOutIcon, WeaveIcon, EyeIcon, EyeOffIcon, GridIcon, SettingsIcon, PencilIcon, CheckIcon, RulerIcon } from './icons';
import { WEAVE_LIBRARY } from '../services/weaveLibrary';
import { WeaveThumbnail } from './WeaveThumbnail';

interface LoomTechModuleProps {
    data: JacquardData;
    settings: WeaveSettings;
    weftYarns: { [key: string]: YarnDefinition };
    weftPatternString: string;
    warpYarns: { [key: string]: YarnDefinition };
    warpPatternString: string;
    techState: LoomTechState;
    onTechStateUpdate: (state: LoomTechState) => void;
    config: LoomConfiguration;
    onConfigUpdate: (config: LoomConfiguration) => void;
}

const OptimizedCanvas: React.FC<{
    width: number;
    height: number;
    scale: number;
    aspectRatio: number;
    renderFn: (ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => void;
    onInteract?: (row: number, col: number) => void;
    className?: string;
}> = ({ width, height, scale, aspectRatio, renderFn, onInteract, className }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const cellW = 5 * scale;
    const cellH = (5 * scale) * aspectRatio;

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        canvas.width = width * cellW;
        canvas.height = height * cellH;

        ctx.fillStyle = '#ffffff'; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        renderFn(ctx, cellW, cellH);
    }, [width, height, scale, aspectRatio, renderFn]);

    const handleMouseDown = (e: React.MouseEvent) => {
        if (!onInteract || !canvasRef.current) return;
        const rect = canvasRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const col = Math.floor(x / (rect.width / width));
        const row = Math.floor(y / (rect.height / height));
        onInteract(row, col);
    };

    return (
        <canvas 
            ref={canvasRef} 
            onMouseDown={handleMouseDown}
            className={className} 
            style={{ width: width * cellW, height: height * cellH }}
        />
    );
};

export const LoomTechModule: React.FC<LoomTechModuleProps> = ({
    data, settings, weftYarns, weftPatternString, warpYarns, warpPatternString,
    techState, onTechStateUpdate, config, onConfigUpdate
}) => {
    const [workflow, setWorkflow] = useState<'view' | 'edit'>('view');
    const [scale, setScale] = useState(workflow === 'edit' ? 2.5 : 1.0);
    const [showSelvedge, setShowSelvedge] = useState(true);
    const [viewMode, setViewMode] = useState<'graph' | 'interlace'>('graph');
    const [useEpiPpiRatio, setUseEpiPpiRatio] = useState(false);
    const [autoMapWeft, setAutoMapWeft] = useState(true);
    const [activeSelvedgeZone, setActiveSelvedgeZone] = useState<string | null>(null);

    const scrollRefControl = useRef<HTMLDivElement>(null);
    const scrollRefDesign = useRef<HTMLDivElement>(null);

    const currentAspectRatio = useEpiPpiRatio ? (settings.epi / settings.ppi) : 1.0;

    const isEditing = workflow === 'edit';
    const maxZoom = isEditing ? 8.0 : 1.5;
    const minZoom = 0.1;

    useEffect(() => {
        if (workflow === 'edit') setScale(3.0);
        else setScale(1.0);
    }, [workflow]);

    const handleVerticalScroll = (e: React.UIEvent<HTMLDivElement>) => {
        const top = e.currentTarget.scrollTop;
        if (scrollRefControl.current) scrollRefControl.current.scrollTop = top;
        if (scrollRefDesign.current) scrollRefDesign.current.scrollTop = top;
    };

    const handleAssignWeave = (zoneId: string, weaveId: string) => {
        const nextZones = config.zones.map(z => z.id === zoneId ? { ...z, weaveId } : z);
        onConfigUpdate({ ...config, zones: nextZones });
    };

    const selvedgeZones = config.zones.filter(z => z.type === 'selvedge');
    const designZones = config.zones.filter(z => z.type === 'design');

    const visibleDesignHooks = useMemo(() => {
        if (isEditing) return data.width; 
        if (showSelvedge) return config.totalHooks;
        return designZones.reduce((acc, z) => acc + (z.endHook - z.startHook + 1), 0);
    }, [workflow, showSelvedge, config.totalHooks, designZones, data.width]);

    const weftSequence = useMemo(() => {
        const regex = /(\d+)([A-Z])/gi;
        let match;
        const seq: string[] = [];
        const pattern = weftPatternString || "1A";
        while ((match = (regex.exec(pattern) as any)) !== null) {
            const count = parseInt(match[1]);
            const char = match[2].toUpperCase();
            for(let i=0; i<count; i++) seq.push(char);
        }
        return seq.length > 0 ? seq : ['A'];
    }, [weftPatternString]);

    const warpColorsArray = useMemo(() => {
        const seq = (warpPatternString.match(/(\d+)([A-Z])/gi) || []) as string[];
        const flat: string[] = [];
        seq.forEach(s => {
            const count = parseInt(s);
            const char = s.slice(-1).toUpperCase();
            const color = warpYarns[char]?.color || '#888';
            for (let i = 0; i < count; i++) flat.push(color);
        });
        return flat;
    }, [warpPatternString, warpYarns]);

    const weftColorsArray = useMemo(() => {
        const seq = (weftPatternString.match(/(\d+)([A-Z])/gi) || []) as string[];
        const flat: string[] = [];
        seq.forEach(s => {
            const count = parseInt(s);
            const char = s.slice(-1).toUpperCase();
            const color = weftYarns[char]?.color || '#888';
            for (let i = 0; i < count; i++) flat.push(color);
        });
        return flat;
    }, [weftPatternString, weftYarns]);

    const hookMap = useMemo(() => {
        const map = new Array(config.totalHooks + 1);
        for (let h = 1; h <= config.totalHooks; h++) {
            const zone = config.zones.find(z => h >= z.startHook && h <= z.endHook);
            if (zone) {
                let weaveBits = null;
                let weaveWidth = 1, weaveHeight = 1;
                if (zone.type === 'selvedge' && zone.weaveId) {
                    const weave = WEAVE_LIBRARY.find(w => w.id === zone.weaveId);
                    if (weave) {
                        const { draft, pegPlan, harnesses } = weave;
                        weaveWidth = draft[0].length; weaveHeight = pegPlan.length;
                        weaveBits = new Uint8Array(weaveWidth * weaveHeight);
                        const warpToH = new Int16Array(weaveWidth).fill(-1);
                        for(let x=0; x<weaveWidth; x++) for(let ha=0; ha<harnesses; ha++) if(draft[ha][x] === 1) { warpToH[x] = ha; break; }
                        for(let y=0; y<weaveHeight; y++) for(let x=0; x<weaveWidth; x++) if(warpToH[x] !== -1 && pegPlan[y][warpToH[x]] === 1) weaveBits[y * weaveWidth + x] = 1;
                    }
                }
                map[h] = { type: zone.type, color: zone.color, startHook: zone.startHook, weaveBits, weaveWidth, weaveHeight };
            } else {
                map[h] = { type: 'empty', color: '#f8fafc' };
            }
        }
        return map;
    }, [config.zones, config.totalHooks]);

    const renderDesign = useCallback((ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => {
        const designW = data.width, designS = data.structure;
        const isInterlace = viewMode === 'interlace';
        const gap = isEditing ? 0.5 : 0; 
        let renderX = 0;

        if (isEditing) {
            for (let x = 0; x < designW; x++) {
                const rx = x * cellW;
                for (let y = 0; y < data.height; y++) {
                    const ry = y * cellH;
                    const bit = designS[y * designW + x] === 1;
                    if (bit) ctx.fillStyle = isInterlace ? (warpColorsArray[x % warpColorsArray.length] || '#000') : '#1e293b';
                    else ctx.fillStyle = isInterlace ? (weftColorsArray[y % weftColorsArray.length] || '#ccc') : '#f1f5f9';
                    ctx.fillRect(rx, ry, cellW - gap, cellH - gap);
                }
            }
            return;
        }

        for (let h = 1; h <= config.totalHooks; h++) {
            const hDef = hookMap[h];
            if (!hDef) continue;
            if (!showSelvedge && hDef.type === 'selvedge') continue;

            const x = renderX * cellW;
            for (let p = 0; p < data.height; p++) {
                const y = p * cellH;
                let bit = false;
                if (hDef.type === 'design') {
                    bit = designS[p * designW + ((h - hDef.startHook) % designW)] === 1;
                } else if (hDef.type === 'selvedge' && hDef.weaveBits) {
                    bit = hDef.weaveBits[(p % hDef.weaveHeight) * hDef.weaveWidth + ((h - hDef.startHook) % hDef.weaveWidth)] === 1;
                }

                if (bit) {
                    ctx.fillStyle = isInterlace ? (warpColorsArray[(h-1)%warpColorsArray.length] || '#000') : '#1e293b';
                } else {
                    ctx.fillStyle = isInterlace ? (weftColorsArray[p%weftColorsArray.length] || '#ccc') : '#f1f5f9';
                }
                ctx.fillRect(x, y, cellW, cellH); 
            }
            renderX++;
        }
    }, [workflow, hookMap, data.structure, data.width, data.height, viewMode, showSelvedge, config.totalHooks, warpColorsArray, weftColorsArray]);

    const renderSelectors = useCallback((ctx: CanvasRenderingContext2D, cellW: number, cellH: number) => {
        const gap = isEditing ? 0.5 : 0;
        const columns = techState.columns || [];
        const weftSelectorIndices = columns
            .map((c, i) => c?.type === 'weft-selector' ? i : -1)
            .filter(i => i !== -1);

        for (let p = 0; p < data.height; p++) {
            const y = p * cellH;
            const currentYarnChar = weftSequence[p % weftSequence.length];
            const yarnIdx = currentYarnChar.charCodeAt(0) - 65; 

            for (let s = 0; s < config.selectorHooks; s++) {
                const col = columns[s];
                let bit = techState.grid[p]?.[s] || false;

                if (col && autoMapWeft && col.type === 'weft-selector') {
                    const selectorOrder = weftSelectorIndices.indexOf(s);
                    bit = selectorOrder === yarnIdx;
                }

                ctx.fillStyle = bit ? (col?.color || '#3b82f6') : '#f1f5f9';
                ctx.fillRect(s * cellW, y, cellW - gap, cellH - gap);
            }
        }
    }, [workflow, techState.grid, techState.columns, config.selectorHooks, data.height, weftSequence, autoMapWeft]);

    const handleSelectorEdit = (row: number, col: number) => {
        if (!isEditing) return;
        const nextGrid = [...techState.grid.map(r => [...r])];
        if (nextGrid[row]) {
            nextGrid[row][col] = !nextGrid[row][col];
            onTechStateUpdate({ ...techState, grid: nextGrid });
        }
    };

    return (
        <div className="flex h-full bg-white text-gray-900 overflow-hidden font-sans">
            {/* SIDEBAR */}
            <div className="w-80 border-r border-gray-200 flex flex-col bg-gray-50 shrink-0 z-10 shadow-lg overflow-y-auto custom-scrollbar">
                <div className="p-5 border-b border-gray-200 bg-white">
                    <div className="flex items-center gap-3 mb-6">
                        <TerminalIcon className="w-6 h-6 text-blue-600" />
                        <h2 className="text-sm font-black uppercase tracking-widest text-gray-800">Tech Module</h2>
                    </div>

                    <div className="space-y-6">
                        {/* Workflow Toggle */}
                        <div className="bg-white p-1 rounded-xl border border-gray-200 flex shadow-inner">
                            <button 
                                onClick={() => setWorkflow('view')}
                                className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all flex items-center justify-center gap-2 ${workflow === 'view' ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
                            >
                                <EyeIcon className="w-3.5 h-3.5" /> View
                            </button>
                            <button 
                                onClick={() => setWorkflow('edit')}
                                className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all flex items-center justify-center gap-2 ${workflow === 'edit' ? 'bg-orange-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
                            >
                                <PencilIcon className="w-3.5 h-3.5" /> Edit
                            </button>
                        </div>

                        <div className="bg-blue-50/50 p-4 rounded-xl border border-blue-100 space-y-4">
                            <h3 className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Display Controls</h3>
                            <div className="flex bg-white rounded p-1 border border-gray-200 shadow-sm">
                                <button onClick={() => setViewMode('graph')} className={`flex-1 py-1.5 text-[9px] font-bold rounded transition-all flex items-center justify-center gap-1.5 ${viewMode === 'graph' ? 'bg-gray-800 text-white shadow-sm' : 'text-gray-400 hover:bg-gray-50'}`}><GridIcon className="w-3 h-3" /> Graph</button>
                                <button onClick={() => setViewMode('interlace')} className={`flex-1 py-1.5 text-[9px] font-bold rounded transition-all flex items-center justify-center gap-1.5 ${viewMode === 'interlace' ? 'bg-gray-800 text-white shadow-sm' : 'text-gray-400 hover:bg-gray-50'}`}><WeaveIcon className="w-3 h-3" /> Interlace</button>
                            </div>

                            <div className="space-y-3 pt-1">
                                <label className="flex items-center justify-between cursor-pointer group">
                                    <div className="flex flex-col">
                                        <span className="text-[10px] font-bold text-gray-700 uppercase tracking-tight group-hover:text-blue-600 transition-colors">Aspect Correction</span>
                                        <span className="text-[8px] text-gray-400 font-medium">Render in EPI:PPI Ratio</span>
                                    </div>
                                    <input type="checkbox" checked={useEpiPpiRatio} onChange={e => setUseEpiPpiRatio(e.target.checked)} className="rounded border-gray-300 text-blue-600 w-4 h-4 focus:ring-0 focus:ring-offset-0" />
                                </label>

                                {!isEditing && (
                                    <label className="flex items-center justify-between cursor-pointer group border-t border-blue-100 pt-3">
                                        <span className="text-[10px] font-bold text-gray-700 uppercase tracking-tight group-hover:text-blue-600 transition-colors">Show Selvedges</span>
                                        <input type="checkbox" checked={showSelvedge} onChange={e => setShowSelvedge(e.target.checked)} className="rounded border-gray-300 text-blue-600 w-4 h-4 focus:ring-0 focus:ring-offset-0" />
                                    </label>
                                )}

                                <label className="flex items-center justify-between cursor-pointer group border-t border-blue-100 pt-3">
                                    <span className="text-[10px] font-bold text-gray-700 uppercase tracking-tight group-hover:text-blue-600 transition-colors">Auto-Map Weft</span>
                                    <input type="checkbox" checked={autoMapWeft} onChange={e => setAutoMapWeft(e.target.checked)} className="rounded border-gray-300 text-emerald-600 w-4 h-4 focus:ring-0 focus:ring-offset-0" />
                                </label>
                            </div>
                        </div>

                        {!isEditing && (
                            <div>
                                <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Selvedge Definitions</h3>
                                <div className="space-y-3">
                                    {selvedgeZones.map(zone => (
                                        <div key={zone.id} className={`bg-white border border-gray-200 rounded-xl p-3 shadow-sm transition-opacity ${!showSelvedge ? 'opacity-30' : 'opacity-100'}`}>
                                            <div className="flex justify-between items-center mb-2">
                                                <span className="text-[9px] font-black uppercase" style={{ color: zone.color }}>{zone.label}</span>
                                                <button disabled={!showSelvedge} onClick={() => setActiveSelvedgeZone(activeSelvedgeZone === zone.id ? null : zone.id)} className="text-[9px] font-bold text-blue-600 uppercase tracking-widest">Change</button>
                                            </div>
                                            {zone.weaveId ? (
                                                <div className="flex items-center gap-2">
                                                    <div className="w-8 h-8 rounded border border-gray-100 overflow-hidden"><WeaveThumbnail weave={WEAVE_LIBRARY.find(w => w.id === zone.weaveId)!} className="w-full h-full border-none" /></div>
                                                    <span className="text-[9px] font-bold text-gray-500 truncate">{WEAVE_LIBRARY.find(w => w.id === zone.weaveId)?.name}</span>
                                                </div>
                                            ) : <div className="py-2 text-center border border-dashed border-gray-200 rounded text-gray-400 text-[9px] font-bold uppercase">No Assignment</div>}
                                            {activeSelvedgeZone === zone.id && showSelvedge && (
                                                <div className="mt-2 grid grid-cols-4 gap-1.5 border-t border-gray-100 pt-2">
                                                    {WEAVE_LIBRARY.slice(0, 8).map(w => (
                                                        <button key={w.id} onClick={() => { handleAssignWeave(zone.id, w.id); setActiveSelvedgeZone(null); }} className={`aspect-square rounded border transition-all ${zone.weaveId === w.id ? 'border-blue-500 ring-2 ring-blue-100' : 'border-gray-200 hover:border-gray-400'}`}><WeaveThumbnail weave={w} className="w-full h-full border-none opacity-60" /></button>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {isEditing && (
                             <div className="bg-orange-50 p-4 rounded-xl border border-orange-100 space-y-4">
                                <h3 className="text-[10px] font-black text-orange-800 uppercase tracking-widest">Hardware Editor</h3>
                                <p className="text-[10px] text-orange-700 leading-relaxed italic">Technical bits are editable on the left grid. Click cells to toggle. Right grid displays the design repeat for reference.</p>
                                <div className="p-3 bg-white rounded border border-orange-200 flex items-center gap-2">
                                    <div className="w-2 h-2 rounded-full bg-orange-500 animate-pulse" />
                                    <span className="text-[9px] font-black uppercase text-orange-900">Direct Edit Mode</span>
                                </div>
                             </div>
                        )}
                    </div>
                </div>
            </div>

            {/* MAIN CONTENT SPLIT VIEW */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden bg-white">
                <div className={`h-12 border-b border-gray-200 px-6 flex items-center justify-between shrink-0 shadow-sm z-20 transition-colors ${isEditing ? 'bg-orange-50' : 'bg-white'}`}>
                    <div className="flex items-center gap-6">
                        <div className="flex items-baseline gap-3">
                            <span className={`text-xs font-black uppercase tracking-widest transition-colors ${isEditing ? 'text-orange-700' : 'text-gray-800'}`}>
                                {isEditing ? 'Electronic Selector Editor' : 'Machine Addressing Map'}
                            </span>
                            <span className="text-[10px] text-gray-400 font-mono">
                                ADDR: 0 → {isEditing ? config.selectorHooks : config.totalHooks + config.selectorHooks}
                            </span>
                        </div>
                        <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-lg border border-gray-200 shadow-inner">
                            <button onClick={() => setScale(s => Math.max(minZoom, s - 0.2))} className="p-1.5 text-gray-400 hover:text-blue-600 transition-colors"><ZoomOutIcon className="w-4 h-4" /></button>
                            <span className="px-3 text-[10px] font-mono font-black text-blue-600 select-none min-w-[50px] text-center">{Math.round(scale * 100)}%</span>
                            <button onClick={() => setScale(s => Math.min(maxZoom, s + 0.2))} className="p-1.5 text-gray-400 hover:text-blue-600 transition-colors"><ZoomInIcon className="w-4 h-4" /></button>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="flex items-center gap-2 bg-emerald-50 border border-emerald-100 px-3 py-1.5 rounded-full shadow-sm">
                            <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_#10b981]" />
                            <span className="text-[9px] font-black text-emerald-700 uppercase tracking-widest">Logic Live</span>
                        </div>
                    </div>
                </div>

                <div className="flex-1 flex overflow-hidden bg-white">
                    {/* LEFT PANE: SELECTORS (STATIC X, EDITABLE) */}
                    <div className="flex flex-col border-r-4 border-blue-100 shrink-0 bg-white shadow-xl relative z-10" style={{ width: config.selectorHooks * 5 * scale + 48 }}>
                        {/* Selector Header */}
                        <div className="h-20 border-b border-gray-200 bg-white flex shrink-0">
                             <div className="w-12 border-r border-gray-200 flex items-center justify-center text-[9px] font-black text-gray-300 uppercase [writing-mode:vertical-lr] rotate-180">PICK #</div>
                             <div className="flex-1 flex overflow-hidden">
                                {(techState.columns || []).map(col => (
