                    const zone = config.zones.find(z => i >= z.startHook && i <= z.endHook);
                    if (zone?.type === 'design') {
                        const posInCycle = (i - 1) % cycle;
                        if (posInCycle >= config.castOut.on) casted = true;
                    }
                } else {
                    const posInCycle = (i - 1) % cycle;
                    if (posInCycle >= config.castOut.on) casted = true;
