                                                        <button onClick={() => handleUpdateLayer(idx, { backWeaveId: undefined })} className="absolute inset-0 bg-red-600/60 opacity-0 group-hover/back:opacity-100 flex items-center justify-center transition-opacity"><TrashIcon className="w-3 h-3 text-white" /></button>
                                                    </div>
                                                ) : <div className="flex-1 flex items-center justify-center text-[8px] text-gray-600 font-bold uppercase tracking-tighter text-center px-1">Back</div>}
                                            </div>
                                        </div>
                                        <span className="text-[8px] font-mono text-gray-500 uppercase tracking-widest">{config?.type === 'ground' ? 'Base' : `Ch ${config?.weftSelector || 1}`}</span>
                                    </div>
                                );
                            })}
                        </div>
                        <div className="flex flex-col gap-1 items-end shrink-0 ml-auto pr-6">
                            <span className="text-[8px] font-black text-blue-500 animate-pulse mb-1 uppercase tracking-widest">Logic: Stäubli / Bonas</span>
                            <button onClick={() => setArtwork(null)} className="px-4 py-1.5 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded-lg font-black uppercase tracking-widest hover:bg-red-900/50 transition-all">Clear Deck</button>
                        </div>
                    </div>
                )}
            </div>

            <div className={`shrink-0 transition-all duration-300 border-l border-gray-800 bg-white ${isPanelCollapsed ? 'w-0 opacity-0 overflow-hidden' : 'w-80'}`}>
                <RightPanel 
                    settings={settings} onSettingsChange={setSettings} dentingPattern={dentingPattern} onDentingChange={setDentingPattern} onSnapshot={()=>{}} onLoadWeave={()=>{}} 
                    customWeaves={customWeaves} onAddWeave={()=>{}} onUpdateWeave={()=>{}} onDeleteWeave={()=>{}} 
                    warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))} onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))} paletteColors={PANTONE_PALETTE} warpPatternString={warpPatternString} setWarpPatternString={setWarpPatternString} weftPatternString={weftPatternString} setWeftPatternString={setWeftPatternString} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{} as any} onApplyGenerated={()=>{}} onSimulate={() => setShowSimModal(true)} onGridOperation={()=>{}} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { setActiveYarnId(id); setSelectedYarnType(type); setAppMode('yarn'); }}
                    onOpenPixelEditor={() => setShowCustomModal(true)}
                    jacquardData={jacquardData}
                    canvasView={canvasView}
                />
            </div>
        </div>

        {activeLayerIdx !== null && artwork && (
            <LayerPropertyModal 
                isOpen={activeLayerIdx !== null} 
                onClose={() => setActiveLayerIdx(null)}
                color={artwork.palette[activeLayerIdx]}
                layer={layerConfigs[activeLayerIdx] || { colorIndex: activeLayerIdx, type: 'ground', sequence: '1:1', isCrammed: false, yarnId: 'A', weftSelector: 1 }}
                onUpdate={(updates) => handleUpdateLayer(activeLayerIdx!, updates)}
                customWeaves={customWeaves}
                yarns={weftYarns}
            />
        )}

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)} 
            weavePattern={simData.colors} 
            structure={simData.structure} 
            epi={settings.epi} 
            ppi={settings.ppi} 
            techGrid={technicalData.techGrid}
            techColumns={techState.columns}
            dentingPlan={dentingPattern.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n))} 
            warpYarns={warpYarns} 
            weftYarns={weftYarns} 
            warpYarnSequence={expandPatternString(warpPatternString)} 
            weftYarnSequence={expandedWeftPattern} 
        />
        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import { YarnDefinition, DensityZone, LoomTechColumn } from '../types';
import { generateYarnTexture } from './yarnRenderer';

interface RenderOptions {
    weavePattern: string[][];
    structure: boolean[][];
    epi: number;
    ppi: number;
    techGrid?: boolean[][];
    techColumns?: LoomTechColumn[];
    dentingPlan?: number[];
    weftZones?: DensityZone[];
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpYarnSequence: string[];
    weftYarnSequence: string[];
    viewSide: 'face' | 'back';
    dpi: number;
    width?: number; 
    height?: number; 
    hideFloats?: boolean; 
    backgroundColor?: string; 
    smoothingQuality?: 'low' | 'medium' | 'high' | 'none';
}

const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = 128;
shadowCanvas.height = 128;
const sCtx = shadowCanvas.getContext('2d');
if (sCtx) {
    const grad = sCtx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,0.7)');
    grad.addColorStop(0.6, 'rgba(0,0,0,0.15)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    sCtx.fillStyle = grad;
    sCtx.fillRect(0, 0, 128, 128);
}

export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern, structure, epi, ppi, techGrid, techColumns, dentingPlan, weftZones,
        warpYarns, weftYarns, warpYarnSequence, weftYarnSequence,
        viewSide, dpi, width: displayW = 1200, height: displayH = 750,
        hideFloats = false,
        backgroundColor = '#050505',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    const SS_FACTOR = (epi > 70 || ppi > 70) ? 1.5 : 1.0; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const PHYSICAL_WIDTH_INCH = displayW / 96; 
    const PHYSICAL_HEIGHT_INCH = displayH / 96;
    const CANVAS_WIDTH = Math.round(PHYSICAL_WIDTH_INCH * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round(PHYSICAL_HEIGHT_INCH * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    if (smoothingQuality === 'none') {
        ctx.imageSmoothingEnabled = false;
    } else {
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = smoothingQuality;
    }

    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = safePlan.reduce((a, b) => a + b, 0) / safePlan.length;
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    while (currentX < CANVAS_WIDTH) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) currentX += dentWidthPx;
        else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.05) });
                currentX += w;
            }
        }
        dIdx++;
    }
    const totalCols = warpPositions.length;

    // --- CRAMMING-AWARE COORDINATE SYSTEM ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const crammingIdx = techColumns?.findIndex(c => c.type === 'cramming') ?? -1;

    const nominalH = PX_PER_INCH / Math.max(1, ppi);
    const picksInFullUnit = weavePattern.length;

    let currentY = 0;
    let unitCount = 0;
    const MAX_UNITS = 300; 

    // We pre-calculate all row positions. 
    // Key: Y only advances if NOT crammed.
    while (currentY < CANVAS_HEIGHT && unitCount < MAX_UNITS) {
        for (let r = 0; r < picksInFullUnit; r++) {
            const isCrammed = crammingIdx !== -1 && techGrid && techGrid[r] && techGrid[r][crammingIdx];

            let h = nominalH;
            if (weftZones) {
                const z = weftZones.find(z => r >= z.startPick && z.endPick >= r);
                if (z) h = PX_PER_INCH / Math.max(1, z.ppi);
            }
            const preferred = weftYarns[weftYarnSequence[r % weftYarnSequence.length]]?.preferredPPI;
            if (preferred) h = PX_PER_INCH / Math.max(1, preferred);

            rowY.push(currentY);

            if (isCrammed) {
                rowHeights.push(0); 
                // Don't increment currentY, so the NEXT pick overlaps at this exact Y
            } else {
                rowHeights.push(h);
                currentY += h; 
            }
        }
        unitCount++;
    }
    const rCount = rowY.length;

    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR)));
    Object.keys(weftYarns).forEach(k => textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR)));

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);
    const TEX_VISUAL_SCALE = 2.0; 

    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, rIdx: number, cIdx: number, op: number, over: number, wave: number, ao: number, taper: number, jitter: number) => {
        const cx = gx + gw/2 + jitter, cy = gy + gh/2 + jitter;
        let dx_o = 0, dy_o = 0;
        if (wave > 0) { const w = Math.sin((isV ? gy : gx) * 0.015 + (isV ? cIdx : rIdx) * 12.5) * (gw * 0.2 * wave); if(isV) dx_o = w; else dy_o = w; }

        const effThick = thickness * (1.0 + over) * (1.0 - taper);
        const sFact = 1.0 - (spacing || 0);
        let dw, dh, dx, dy;
        if (isV) {
            dw = NOMINAL_WARP_W * effThick * sFact * TEX_VISUAL_SCALE + 0.5; 
            dh = gh + 0.5;
            dx = (cx - dw / 2) + dx_o; dy = gy;
        } else {
            // Even if gh is 0 (crammed), the yarn itself has volume
            dh = NOMINAL_WEFT_H * effThick * sFact * TEX_VISUAL_SCALE + 0.5;
            dw = gw + 0.5;
            dx = gx; dy = (cy - dh / 2) + dy_o;
        }

        ctx.save();
        ctx.globalAlpha = op;
        ctx.translate(dx + dw/2, dy + dh/2);
        const phase = Math.floor(Math.abs((Math.sin((isV ? cIdx : rIdx) * 12.98) * 43758.54) % 1) * tex.width);
        if (isV) {
            ctx.rotate(Math.PI / 2);
            const sX = Math.floor((gy + phase) % tex.width), sW = Math.min(gh, tex.width - sX), sc = dh / Math.max(1, gh);
            ctx.drawImage(tex, sX, 0, sW, tex.height, -dh/2, -dw/2, sW * sc, dw);
            if (gh > sW) ctx.drawImage(tex, 0, 0, gh - sW, tex.height, -dh/2 + (sW * sc), -dw/2, (gh - sW) * sc, dw);
        } else {
            const sX = Math.floor((gx + phase) % tex.width), sW = Math.min(gw, tex.width - sX), sc = dw / Math.max(1, gw);
            ctx.drawImage(tex, sX, 0, sW, tex.height, -dw/2, -dh/2, sW * sc, dh);
            if (gw > sW) ctx.drawImage(tex, 0, 0, gw - sW, tex.height, -dw/2 + (sW * sc), -dh/2, (gw - sW) * sc, dh);
        }
        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao * 0.5})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(-dw/2, -dh/2, dw, dh); 
        }
        ctx.restore();
    };

    for (let r = 0; r < rCount; r++) {
        const pR = r % rows;
        const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
        const wDef = weftYarns[wYId];
        const wTex = textureMap.get(`weft-${wYId}`);
        const baseGY = rowY[r];

        // MICRO-OFFSET: Subtly offset stacked picks so they look tiered but share the same logical space
        const stackIdx = r % expansion; 
        const gY = baseGY + (stackIdx * 0.2); 
        const gH = Math.max(NOMINAL_WEFT_H, rowHeights[r]); 

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols, waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A', waDef = warpYarns[waYId], waTex = textureMap.get(`warp-${waYId}`), gX = warpPositions[c].x, gW = warpPositions[c].w, jit = warpPositions[c].jitter;

            const wTopR = (structure[pR] && structure[pR][pC]) || false;
            const wTop = viewSide === 'face' ? wTopR : !wTopR;

            const pWT = viewSide === 'face' ? ((structure[pR] && structure[pR][(pC - 1 + cols) % cols]) || false) : !((structure[pR] && structure[pR][(pC - 1 + cols) % cols]) || false);
            const nWT = viewSide === 'face' ? ((structure[pR] && structure[pR][(pC + 1) % cols]) || false) : !((structure[pR] && structure[pR][(pC + 1) % cols]) || false);
            const uWT = viewSide === 'face' ? ((structure[(pR - 1 + rows) % rows] && structure[(pR - 1 + rows) % rows][pC]) || false) : !((structure[(pR - 1 + rows) % rows] && structure[(pR - 1 + rows) % rows][pC]) || false);
            const dWT = viewSide === 'face' ? ((structure[(pR + 1) % rows] && structure[(pR + 1) % rows][pC]) || false) : !((structure[(pR + 1) % rows] && structure[(pR + 1) % rows][pC]) || false);

            let wAO = 0, waAO = 0, wT = 0, waT = 0;
            if (!wTop && (pWT || nWT)) { wAO = wDef?.bindingDepth || 0.4; wT = wDef?.floatTaper || 0; }
            if (wTop && (!uWT || !dWT)) { waAO = waDef?.bindingDepth || 0.4; waT = waDef?.floatTaper || 0; }

            let wOp = 1.0, wOv = 0.0, waOp = 1.0, waOv = 0.0;
            if (wDef?.isExtraWeft) { if (wTop) wOp = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08); else wOv = wDef.extraOverlap ?? 0; }
            if (waDef?.isExtraWarp) { if (!wTop) waOp = hideFloats ? 0 : (waDef.extraFloatOpacity ?? 0.08); else waOv = waDef.extraOverlap ?? 0; }

            if (wTop) { 
                if (wTex && wOp > 0) drawThread(wTex, gX, gY, gW, gH, wDef?.thickness || 1, wDef?.spacing || 0, false, r, c, wOp, wOv, wDef?.floatWaviness, wAO, wT, jit); 
            }
            else { 
                if (waTex && waOp > 0) drawThread(waTex, gX, gY, gW, gH, waDef?.thickness || 1, waDef?.spacing || 0, true, r, c, waOp, waOv, waDef?.floatWaviness, waAO, waT, jit); 
            }

            const tD = wTop ? waDef : wDef, tOp = wTop ? waOp : wOp, sTh = (tD?.shadowThrow ?? 1.0) * SS_FACTOR * (dpi/96), sAn = (tD?.shadowAngle ?? 135) * Math.PI/180;
            if (tOp > 0.1 && sTh > 0) {
                const sW = wTop ? NOMINAL_WARP_W * (tD?.thickness || 1) * (1+waOv) : gW * 1.1, sH = wTop ? gH * 1.1 : NOMINAL_WEFT_H * (tD?.thickness || 1) * (1+wOv);
                const sX = (gX + gW/2 - sW/2) + Math.cos(sAn)*sTh, sY = (gY + gH/2 - sH/2) + Math.sin(sAn)*sTh;
                ctx.globalAlpha = 0.4; ctx.drawImage(shadowCanvas, sX - sW*0.1, sY - sH*0.1, sW*1.2, sH*1.2); ctx.globalAlpha = 1.0;
            }

            if (wTop) { 
                if (waTex && waOp > 0) drawThread(waTex, gX, gY, gW, gH, waDef?.thickness || 1, waDef?.spacing || 0, true, r, c, waOp, waOv, waDef?.floatWaviness, waAO, waT, jit); 
            }
            else { 
                if (wTex && wOp > 0) drawThread(wTex, gX, gY, gW, gH, wDef?.thickness || 1, wDef?.spacing || 0, false, r, c, wOp, wOv, wDef?.floatWaviness, waAO, waT, jit); 
            }
        }
    }

    if (SS_FACTOR > 1.0) {
        const finalCanvas = document.createElement('canvas');
        finalCanvas.width = Math.round(PHYSICAL_WIDTH_INCH * dpi);
        finalCanvas.height = Math.round(PHYSICAL_HEIGHT_INCH * dpi);
        const finalCtx = finalCanvas.getContext('2d');
        if (finalCtx) {
            if (smoothingQuality === 'none') finalCtx.imageSmoothingEnabled = false;
            else { finalCtx.imageSmoothingEnabled = true; finalCtx.imageSmoothingQuality = 'high'; }
            finalCtx.drawImage(canvas, 0, 0, finalCanvas.width, finalCanvas.height);
            return finalCanvas;
        }
    }
    return canvas;
};

