                                    className={`w-10 h-10 rounded-full font-mono font-bold text-xs border transition-all ${layer.weftSelector === num ? 'bg-blue-600 border-blue-400 text-white shadow-[0_0_15px_rgba(37,99,235,0.4)] scale-110' : 'bg-gray-800 border-gray-700 text-gray-400 hover:border-gray-500'}`}
                                >
