interface FabricSimulationModalProps {
  isOpen: boolean;
  onClose: () => void;
  weavePattern: string[][];
  structure: boolean[][]; 
  epi: number;
  ppi: number;
  techGrid?: boolean[][];
  techColumns?: LoomTechColumn[];
  dentingPlan?: number[];
  weftZones?: DensityZone[];
  warpYarns: { [key: string]: YarnDefinition };
  weftYarns: { [key: string]: YarnDefinition };
  warpYarnSequence: string[];
  weftYarnSequence: string[];
  embedded?: boolean; 
}

const SVGRuler: React.FC<{
    orientation: 'horizontal' | 'vertical';
    viewportSize: number;
    zoom: number;
    pan: number;
    unit: 'inch' | 'cm';
}> = ({ orientation, viewportSize, zoom, pan, unit }) => {
    const pixelsPerUnit = unit === 'inch' ? 96 : (96 / 2.54);
    const scaledPixelsPerUnit = pixelsPerUnit * zoom;
    const divisions = unit === 'inch' ? 8 : 10;

    const ticks = [];
    const startIndex = Math.floor(-pan / scaledPixelsPerUnit);
    const numUnits = Math.ceil(viewportSize / scaledPixelsPerUnit) + 2;

    for (let i = 0; i < numUnits; i++) {
        const unitIndex = startIndex + i;
        const basePos = pan + (unitIndex * scaledPixelsPerUnit);

        if (basePos < -scaledPixelsPerUnit || basePos > viewportSize + scaledPixelsPerUnit) continue;

        ticks.push(
            <g key={`unit-${unitIndex}`} transform={orientation === 'horizontal' ? `translate(${basePos}, 0)` : `translate(0, ${basePos})`}>
                <line 
                    x1="0.5" y1="0.5" 
                    x2={orientation === 'horizontal' ? "0.5" : "15"} 
                    y2={orientation === 'horizontal' ? "15" : "0.5"} 
                    stroke="currentColor" strokeWidth="1.2" 
                />
                <text 
                    x={orientation === 'horizontal' ? "4" : "12"} 
                    y={orientation === 'horizontal' ? "12" : "3"} 
                    fontSize="9" fontWeight="bold" 
                    textAnchor={orientation === 'horizontal' ? "start" : "end"}
                    className="fill-gray-500 font-sans select-none"
                    transform={orientation === 'vertical' ? `rotate(-90 12 3)` : ''}
                >
                    {unitIndex}
                </text>

                {Array.from({ length: divisions - 1 }).map((_, j) => {
                    const subPos = (j + 1) * (scaledPixelsPerUnit / divisions);
                    const isHalf = (j + 1) === Math.floor(divisions / 2);
                    const h = isHalf ? 10 : 5;
                    return (
                        <line 
                            key={`sub-${unitIndex}-${j}`}
                            x1={orientation === 'horizontal' ? subPos : "0"} 
                            y1={orientation === 'horizontal' ? "0" : subPos}
                            x2={orientation === 'horizontal' ? subPos : h} 
                            y2={orientation === 'horizontal' ? h : subPos}
                            stroke="currentColor" strokeWidth="0.5"
                            className="text-gray-300"
                        />
                    );
                })}
            </g>
        );
    }

    return (
        <svg 
            className={`absolute z-30 pointer-events-none bg-white/90 backdrop-blur-sm border-gray-200 text-gray-400 ${orientation === 'horizontal' ? 'w-full h-6 border-b left-0 top-0' : 'h-full w-6 border-r left-0 top-0'}`}
        >
            {ticks}
        </svg>
    );
};

export const FabricSimulationModal: React.FC<FabricSimulationModalProps> = ({
  isOpen, onClose, weavePattern, structure, epi, ppi, techGrid, techColumns, dentingPlan, weftZones,
  warpYarns, weftYarns, warpYarnSequence, weftYarnSequence, embedded
}) => {
  const [dataUrl, setDataUrl] = useState<string>('');
  const [simulationDpi, setSimulationDpi] = useState<number>(144); 
  const [smoothing, setSmoothing] = useState<'high' | 'medium' | 'low' | 'none'>('high');
  const [viewSide, setViewSide] = useState<'face' | 'back'>('face');
  const [bgMode, setBgMode] = useState<'dark' | 'light'>('dark');
  const [rulerUnit, setRulerUnit] = useState<'inch' | 'cm' | 'none'>('inch');
  const [activeTab, setActiveTab] = useState<'2d' | '3d'>('2d');
  const [hideFloats, setHideFloats] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isDpiMenuOpen, setIsDpiMenuOpen] = useState(false);
  const [isSmoothingMenuOpen, setIsSmoothingMenuOpen] = useState(false);

  const [transform, setTransform] = useState({ scale: 1.0, rotate: 0, x: 0, y: 0 }); 
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });
  const [viewportSize, setViewportSize] = useState({ w: window.innerWidth, h: window.innerHeight });

  const viewportRef = useRef<HTMLDivElement>(null);

  // Measure actual available viewport for dynamic rendering
  useEffect(() => {
    if (!isOpen) return;
    const observer = new ResizeObserver((entries) => {
        for (let entry of entries) {
            setViewportSize({ w: entry.contentRect.width, h: entry.contentRect.height });
        }
    });
    if (viewportRef.current) observer.observe(viewportRef.current);
    return () => observer.disconnect();
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || !weavePattern.length || viewportSize.w < 10) return;

    setIsGenerating(true);
    const timer = setTimeout(() => {
        requestAnimationFrame(() => {
            const canvas = renderFabricToCanvas({
                weavePattern,
                structure,
                epi,
                ppi,
                techGrid,
                techColumns,
                dentingPlan,
                weftZones,
                warpYarns,
                weftYarns,
                warpYarnSequence,
                weftYarnSequence,
                viewSide,
                dpi: simulationDpi,
                smoothingQuality: smoothing,
                width: viewportSize.w, // Dynamic sizing
                height: viewportSize.h, // Dynamic sizing
                hideFloats: hideFloats,
                backgroundColor: bgMode === 'dark' ? '#050505' : '#ffffff'
            });
            setDataUrl(canvas.toDataURL());
            setIsGenerating(false);
        });
    }, 100);

    return () => clearTimeout(timer);
  }, [isOpen, viewportSize, weavePattern, structure, epi, ppi, techGrid, techColumns, dentingPlan, weftZones, warpYarns, weftYarns, warpYarnSequence, weftYarnSequence, simulationDpi, smoothing, viewSide, hideFloats, bgMode]);

  const handleDownload = () => {
      if (!dataUrl) return;
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `fabric-simulation-${epi}epi-${ppi}ppi.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleWheel = (e: WheelEvent) => { 
      e.stopPropagation(); 
      const zoomStep = transform.scale * 0.15;
      const direction = e.deltaY > 0 ? -1 : 1;
      const newScale = Math.min(Math.max(transform.scale + (direction * zoomStep), 0.1), 10);
      setTransform(prev => ({ ...prev, scale: newScale })); 
  };

  const handleMouseDown = (e: MouseEvent) => { 
      if (e.button === 0) {
          e.preventDefault(); 
          setIsDragging(true); 
          setLastMousePos({ x: e.clientX, y: e.clientY });
      }
  };

  const handleMouseMove = (e: MouseEvent) => { 
      if (!isDragging) return; 
      e.preventDefault(); 
      const dx = (e.clientX - lastMousePos.x); 
      const dy = (e.clientY - lastMousePos.y); 
      setTransform(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy })); 
      setLastMousePos({ x: e.clientX, y: e.clientY }); 
  };

  const handleMouseUp = () => { setIsDragging(false); };
  const handleReset = () => { setTransform({ scale: 1.0, rotate: 0, x: 0, y: 0 }); };

  const dpiOptions = [72, 96, 144, 192, 300, 600];
  const smoothingOptions: ('high' | 'medium' | 'low' | 'none')[] = ['high', 'medium', 'low', 'none'];

  const rulerPanX = (viewportSize.w / 2) + transform.x - (viewportSize.w * transform.scale / 2);
  const rulerPanY = (viewportSize.h / 2) + transform.y - (viewportSize.h * transform.scale / 2);

  if (!isOpen) return null;

  return (
    <div className={embedded ? "w-full h-full flex flex-col bg-gray-950 overflow-hidden" : "fixed inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-xl animate-in fade-in duration-300"}>
      <div className={embedded ? "flex flex-col flex-1 overflow-hidden" : "bg-gray-950 w-full h-full flex flex-col overflow-hidden"}>

        {/* ENHANCED OVERLAY TOOLBAR */}
        <div className="absolute top-4 inset-x-4 z-50 pointer-events-none flex items-center justify-between">
          <div className="pointer-events-auto flex items-center gap-4">
              <div className="bg-gray-900/90 backdrop-blur border border-gray-700 rounded-2xl p-2 px-4 shadow-2xl flex items-center gap-6">
