                        <button onClick={handleDownload} className="p-2 text-blue-400 hover:text-white transition-colors" title="Export PNG"><DownloadIcon className="w-5 h-5"/></button>
                        <button onClick={() => setRulerUnit(prev => prev === 'inch' ? 'cm' : (prev === 'cm' ? 'none' : 'inch'))} className={`p-2 transition-all ${rulerUnit !== 'none' ? 'text-blue-400 scale-110' : 'text-gray-400'}`} title="Measurement Tool"><RulerIcon className="w-5 h-5"/></button>
