import React, { useRef, useEffect, useState, useCallback, useMemo } from 'react';
import { JacquardData, ToolType, ViewMode, FaceMode, WeaveSettings } from '../types';
import { compressPatternString, expandPatternString } from '../utils/patternParser';

interface JacquardCanvasProps {
    data: JacquardData;
    artwork?: {
        data: Uint8Array;
        palette: string[];
        width: number;
        height: number;
    };
    onUpdate: (newData: Uint8Array) => void;
    onUpdateWarpPattern?: (newPattern: string) => void;
    onUpdateWeftPattern?: (newPattern: string) => void;
    activeYarnId: string;
    tool: ToolType;
    viewMode: ViewMode;
    faceMode: FaceMode;
    warpColors: string[];
    weftColors: string[];
    warpPatternString: string;
    weftPatternString: string;
    settings: WeaveSettings;
    onViewChange?: (view: { x: number, y: number, zoom: number }) => void;
}

export const JacquardCanvas: React.FC<JacquardCanvasProps> = ({
    data, artwork, onUpdate, onUpdateWarpPattern, onUpdateWeftPattern, 
    activeYarnId, tool, viewMode, faceMode, warpColors, weftColors,
    warpPatternString, weftPatternString, settings, onViewChange
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Header is now large enough to hold Yarn Swatches + Numbers
    const HEADER_SIZE = 48; 

    const [view, setView] = useState({ x: HEADER_SIZE, y: HEADER_SIZE, zoom: 1.0 }); 
    const [hoverPos, setHoverPos] = useState({ x: 0, y: 0 });
    const [isSpacePressed, setIsSpacePressed] = useState(false);

    const isInteracting = useRef(false);
    const lastMousePos = useRef({ x: 0, y: 0 });
    const lastGridPos = useRef({ x: -1, y: -1 });
    const localBuffer = useRef<Uint8Array>(data.structure);

    const currentAspect = useMemo(() => {
        return viewMode === 'graph' ? 1.0 : (settings.epi / settings.ppi);
    }, [viewMode, settings.epi, settings.ppi]);

    // ANCHORED TO LEFT Logic
    const resetToTopLeft = useCallback(() => {
        setView({ x: HEADER_SIZE, y: HEADER_SIZE, zoom: 1.0 });
    }, []);

    const lastDataDim = useRef({ w: data.width, h: data.height });
    useEffect(() => {
        if (data.width !== lastDataDim.current.w || data.height !== lastDataDim.current.h) {
            resetToTopLeft();
            lastDataDim.current = { w: data.width, h: data.height };
        }
    }, [data.width, data.height, resetToTopLeft]);

    const initialCentered = useRef(false);
    useEffect(() => {
        if (!initialCentered.current && containerRef.current?.clientWidth) {
            resetToTopLeft();
            initialCentered.current = true;
        }
    }, [resetToTopLeft]);

    useEffect(() => {
        localBuffer.current = data.structure;
        render();
    }, [data.structure]);

    useEffect(() => {
        onViewChange?.(view);
    }, [view, onViewChange]);

    const render = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !containerRef.current) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const w = containerRef.current.clientWidth;
        const h = containerRef.current.clientHeight;
        if (canvas.width !== w || canvas.height !== h) {
            canvas.width = w; canvas.height = h;
        }

        ctx.fillStyle = '#0a0a0f'; // Even darker for industrial feel
        ctx.fillRect(0, 0, w, h);

        const zoom = view.zoom;
        const aspect = currentAspect;
        const cellW = zoom;
        const cellH = zoom * aspect;

        const startX = Math.floor((HEADER_SIZE - view.x) / cellW);
        const startY = Math.floor((HEADER_SIZE - view.y) / cellH);
        const endX = Math.min(data.width, startX + Math.ceil((w - HEADER_SIZE) / cellW) + 1);
        const endY = Math.min(data.height, startY + Math.ceil((h - HEADER_SIZE) / cellH) + 1);

        const isArtworkView = viewMode === 'structure';
        const isGraphView = viewMode === 'graph';
        const isReverse = faceMode === 'reverse';
        const buffer = localBuffer.current;

        // 1. Render Design Grid
        for (let y = Math.max(0, startY); y < endY; y++) {
            for (let x = Math.max(0, startX); x < endX; x++) {
                const idx = y * data.width + x;
                const px = Math.floor(view.x + x * cellW);
                const py = Math.floor(view.y + y * cellH);

                if (isGraphView) {
                    ctx.fillStyle = buffer[idx] === 1 ? '#000000' : '#ffffff';
                } else if (isArtworkView && artwork) {
                    ctx.fillStyle = artwork.palette[artwork.data[idx]] || '#000';
                } else {
                    let val = buffer[idx] === 1;
                    if (isReverse) val = !val;
                    ctx.fillStyle = val ? (warpColors[x % warpColors.length] || '#444') : (weftColors[y % weftColors.length] || '#222');
                }

                ctx.fillRect(px, py, Math.ceil(cellW), Math.ceil(cellH));
            }
        }

        // 2. Render Headers (Frozen UI)
        // Backgrounds
        ctx.fillStyle = '#111827';
        ctx.fillRect(0, 0, w, HEADER_SIZE); 
        ctx.fillRect(0, 0, HEADER_SIZE, h); 

        // Static Corner
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, HEADER_SIZE, HEADER_SIZE);

        ctx.font = 'bold 9px "JetBrains Mono", monospace';
        const step = zoom < 2 ? 50 : (zoom < 8 ? 20 : 8);

        // TOP HEADER: Warp Sequence & Selectors
        for (let x = Math.max(0, startX); x < endX; x++) {
            const px = Math.floor(view.x + x * cellW);
            if (px > w) break;

            // Yarn Color Swatch
            ctx.fillStyle = warpColors[x % warpColors.length] || '#444';
            ctx.fillRect(px, 0, Math.ceil(cellW), 24); 

            if (x % step === 0 || x === 0) {
                ctx.fillStyle = '#64748b';
                ctx.textAlign = 'left';
                ctx.fillText((x + 1).toString(), px + 2, 28);
                ctx.beginPath();
                ctx.moveTo(px, 24);
                ctx.lineTo(px, HEADER_SIZE);
                ctx.strokeStyle = 'rgba(148, 163, 184, 0.2)';
                ctx.stroke();
            }
        }

        // LEFT HEADER: Weft Sequence & Selectors
        ctx.textAlign = 'right';
        for (let y = Math.max(0, startY); y < endY; y++) {
            const py = Math.floor(view.y + y * cellH);
            if (py > h) break;

            // Yarn Color Swatch
            ctx.fillStyle = weftColors[y % weftColors.length] || '#444';
            ctx.fillRect(0, py, 24, Math.ceil(cellH));

            if (y % step === 0 || y === 0) {
                ctx.fillStyle = '#64748b';
                ctx.fillText((y + 1).toString(), HEADER_SIZE - 4, py + 2);
                ctx.beginPath();
                ctx.moveTo(24, py);
                ctx.lineTo(HEADER_SIZE, py);
                ctx.strokeStyle = 'rgba(148, 163, 184, 0.2)';
                ctx.stroke();
            }
        }

        // 3. Grid Overlays
        if (zoom >= 4.0) {
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
            ctx.lineWidth = 0.5;
            for (let x = Math.max(0, startX); x <= endX; x++) {
                const px = view.x + x * cellW;
                ctx.moveTo(px, HEADER_SIZE); ctx.lineTo(px, h);
            }
            for (let y = Math.max(0, startY); y <= endY; y++) {
                const py = view.y + y * cellH;
                ctx.moveTo(HEADER_SIZE, py); ctx.lineTo(w, py);
            }
            ctx.stroke();
        }

        // Major Technical Grid
        if (zoom >= 1.5) {
            ctx.beginPath();
            ctx.lineWidth = 1;
            for (let x = Math.max(0, startX); x <= endX; x++) {
                if (x % settings.gridX === 0) {
                    const px = view.x + x * cellW;
                    ctx.strokeStyle = 'rgba(59, 130, 246, 0.4)';
                    ctx.moveTo(px, HEADER_SIZE); ctx.lineTo(px, h);
                }
            }
            for (let y = Math.max(0, startY); y <= endY; y++) {
                if (y % settings.gridY === 0) {
                    const py = view.y + y * cellH;
                    ctx.strokeStyle = 'rgba(59, 130, 246, 0.4)';
                    ctx.moveTo(HEADER_SIZE, py); ctx.lineTo(w, py);
                }
            }
            ctx.stroke();
        }
    }, [view, viewMode, faceMode, warpColors, weftColors, artwork, data.width, data.height, settings, currentAspect]);

    useEffect(() => { render(); }, [render]);

    useEffect(() => {
        const onDown = (e: KeyboardEvent) => { if (e.code === 'Space') { setIsSpacePressed(true); if (e.target === document.body) e.preventDefault(); } };
        const onUp = (e: KeyboardEvent) => { if (e.code === 'Space') setIsSpacePressed(false); };
        window.addEventListener('keydown', onDown);
        window.addEventListener('keyup', onUp);
        return () => { window.removeEventListener('keydown', onDown); window.removeEventListener('keyup', onUp); };
    }, []);

    const handleInteraction = (e: React.MouseEvent | React.WheelEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;
        const mouseX = ('clientX' in e ? e.clientX : 0) - rect.left;
        const mouseY = ('clientY' in e ? e.clientY : 0) - rect.top;

        const aspect = currentAspect;

        if (e.type === 'wheel') {
            const wheelEv = e as React.WheelEvent;
            const direction = wheelEv.deltaY > 0 ? -1 : 1;
            const zoomStep = view.zoom * 0.15;
            const newZoom = Math.min(256, Math.max(0.1, view.zoom + direction * zoomStep));

            if (newZoom !== view.zoom) {
                const worldX = (mouseX - view.x) / view.zoom;
                const worldY = (mouseY - view.y) / (view.zoom * aspect);
                setView({ x: mouseX - worldX * newZoom, y: mouseY - worldY * (newZoom * aspect), zoom: newZoom });
            }
            return;
        }

        const isPanActive = isSpacePressed || tool === 'pan';

        if (isPanActive) {
            if (e.type === 'mousedown') {
                isInteracting.current = true;
                lastMousePos.current = { x: mouseX, y: mouseY };
            } else if (e.type === 'mousemove' && isInteracting.current) {
                const dx = mouseX - lastMousePos.current.x;
                const dy = mouseY - lastMousePos.current.y;
                setView(prev => ({ ...prev, x: prev.x + dx, y: prev.y + dy }));
                lastMousePos.current = { x: mouseX, y: mouseY };
            } else {
                isInteracting.current = false;
            }
            return;
        }

        // --- SEQUENCE PAINTING LOGIC ---
        const isBrush = tool === 'brush';

        // Check if in Top Header (Warp sequence edit)
        if (mouseY < HEADER_SIZE && mouseX > HEADER_SIZE) {
            const warpIdx = Math.floor((mouseX - view.x) / view.zoom);
            if (warpIdx >= 0 && warpIdx < data.width && onUpdateWarpPattern) {
                if (e.type === 'mousedown') { isInteracting.current = true; lastGridPos.current = { x: warpIdx, y: -1 }; }
                if ((e.type === 'mousedown' || (e.type === 'mousemove' && isInteracting.current)) && warpIdx !== lastGridPos.current.x) {
                    const seq = expandPatternString(warpPatternString);
                    while(seq.length < data.width) seq.push(seq[seq.length % (seq.length || 1)] || 'A');
                    seq[warpIdx] = activeYarnId;
                    onUpdateWarpPattern(compressPatternString(seq));
                    lastGridPos.current = { x: warpIdx, y: -1 };
                }
            }
            if (e.type === 'mouseup' || e.type === 'mouseleave') isInteracting.current = false;
            return;
        }

        // Check if in Left Header (Weft sequence edit)
        if (mouseX < HEADER_SIZE && mouseY > HEADER_SIZE) {
            const weftIdx = Math.floor((mouseY - view.y) / (view.zoom * aspect));
            if (weftIdx >= 0 && weftIdx < data.height && onUpdateWeftPattern) {
                if (e.type === 'mousedown') { isInteracting.current = true; lastGridPos.current = { x: -1, y: weftIdx }; }
                if ((e.type === 'mousedown' || (e.type === 'mousemove' && isInteracting.current)) && weftIdx !== lastGridPos.current.y) {
                    const seq = expandPatternString(weftPatternString);
                    while(seq.length < data.height) seq.push(seq[seq.length % (seq.length || 1)] || 'A');
                    seq[weftIdx] = activeYarnId;
                    onUpdateWeftPattern(compressPatternString(seq));
                    lastGridPos.current = { x: -1, y: weftIdx };
                }
            }
            if (e.type === 'mouseup' || e.type === 'mouseleave') isInteracting.current = false;
            return;
        }

        // --- GRID INTERACTION ---
        const gridXPos = Math.floor((mouseX - view.x) / view.zoom);
        const gridYPos = Math.floor((mouseY - view.y) / (view.zoom * aspect));

        if (e.type === 'mousemove') {
            setHoverPos({ x: Math.max(0, Math.min(data.width - 1, gridXPos)), y: Math.max(0, Math.min(data.height - 1, gridYPos)) });
        }

        if (e.type === 'mousedown') {
            isInteracting.current = true;
            if (gridXPos >= 0 && gridXPos < data.width && gridYPos >= 0 && gridYPos < data.height) {
                localBuffer.current[gridYPos * data.width + gridXPos] = localBuffer.current[gridYPos * data.width + gridXPos] === 1 ? 0 : 1;
                lastGridPos.current = { x: gridXPos, y: gridYPos }; 
                render();
            }
        } else if (e.type === 'mousemove' && isInteracting.current) {
            if (gridXPos >= 0 && gridXPos < data.width && gridYPos >= 0 && gridYPos < data.height && (gridXPos !== lastGridPos.current.x || gridYPos !== lastGridPos.current.y)) {
                localBuffer.current[gridYPos * data.width + gridXPos] = 1; 
                lastGridPos.current = { x: gridXPos, y: gridYPos }; 
                render();
            }
        } else if (e.type === 'mouseup' || e.type === 'mouseleave') {
            if (isInteracting.current) {
                isInteracting.current = false;
                onUpdate(new Uint8Array(localBuffer.current));
            }
        }
    };

    return (
        <div ref={containerRef} className="w-full h-full cursor-crosshair overflow-hidden select-none relative">
            <canvas 
                ref={canvasRef} 
                onMouseDown={handleInteraction} 
                onMouseMove={handleInteraction} 
                onMouseUp={handleInteraction} 
                onMouseLeave={handleInteraction} 
                onWheel={handleInteraction} 
                className={`block ${isSpacePressed ? 'cursor-grabbing' : ''}`} 
            />
            <div className="absolute bottom-4 left-4 flex gap-2 pointer-events-none">
                <div className="bg-black/90 px-4 py-2 rounded-xl text-[10px] font-mono text-blue-400 border border-white/5 uppercase tracking-tighter flex items-center gap-6 shadow-2xl backdrop-blur-md">
                    <div className="flex flex-col">
                        <span className="text-white font-bold">{isSpacePressed ? 'PAN MODE' : tool.toUpperCase()}</span>
                        <span className="text-gray-500">ZOOM: {Math.round(view.zoom * 100)}%</span>
                    </div>
                    <div className="h-6 w-px bg-gray-800" />
                    <div className="flex flex-col">
                        <span className="text-gray-400">CARP: <span className="text-white font-bold">{hoverPos.x + 1}</span></span>
                        <span className="text-gray-400">PICK: <span className="text-white font-bold">{hoverPos.y + 1}</span></span>
                    </div>
                    <div className="h-6 w-px bg-gray-800" />
                    <div className="flex items-center gap-2">
                        <div className="w-4 h-4 rounded-full border border-white/10" style={{ background: (activeYarnId && (warpColors[hoverPos.x] || '#555')) }} />
                        <span className="text-white font-black">{activeYarnId}</span>
                    </div>
                </div>
            </div>

            {tool === 'brush' && (
                <div className="absolute top-16 left-1/2 -translate-x-1/2 bg-blue-600/90 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] shadow-lg animate-bounce pointer-events-none">
                    Sequence Edit Active
                </div>
            )}
        </div>
    );
};

