  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleUpdateLayer = (idx: number, updates: Partial<JacquardLayer>) => {
      setLayerConfigs(prev => ({ ...prev, [idx]: { ...prev[idx], ...updates } }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 
          setArtwork({ data: new Uint8Array(result.pixels), palette: result.palette, width: result.width, height: result.height });
          setJacquardData({ width: result.width, height: result.height, structure: new Uint8Array(result.width * result.height).fill(0) });
          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`);
          setWeftPatternString(`${result.height}A`);

          const initialLayers: { [key: number]: JacquardLayer } = {};
          result.palette.forEach((_, i) => {
              const char = String.fromCharCode(65 + (i % 8));
              initialLayers[i] = { 
                  colorIndex: i, 
                  type: i === 0 ? 'ground' : 'extra-weft', 
                  sequence: '1:1', 
                  isCrammed: i !== 0,
                  yarnId: char,
                  weftSelector: (i % 8) + 1
              };
          });
          setLayerConfigs(initialLayers);
          setProjectName(file.name.split('.')[0]); setViewMode('structure'); setAppMode('art'); setLoadingStatus(null);
      } catch (err: any) { alert(err.message || "Error processing."); setLoadingStatus(null); }
  };

  const technicalData = useMemo(() => {
    if (!artwork) {
        return { 
            width: jacquardData.width, 
            height: jacquardData.height, 
            structure: jacquardData.structure, 
            techGrid: Array.from({ length: jacquardData.height }, () => Array(techState.columns.length).fill(false)) 
        };
    }

    const layers = (Object.values(layerConfigs) as JacquardLayer[]).sort((a, b) => a.colorIndex - b.colorIndex);
    const extraWeftLayers = layers.filter(l => l.type === 'extra-weft' && (l.faceWeaveId || l.backWeaveId));

    const expansion = extraWeftLayers.length + 1;
    const maxSafePicks = 2048;
    const rawHeight = artwork.height * expansion;
    const newHeight = Math.min(rawHeight, maxSafePicks);
    const safeArtHeight = Math.floor(newHeight / expansion);

    const newStructure = new Uint8Array(artwork.width * newHeight);
    const newTechGrid = Array.from({ length: newHeight }, () => Array(techState.columns.length).fill(false));
    const weftSelectorIndices = techState.columns.map((c, i) => c?.type === 'weft-selector' ? i : -1).filter(i => i !== -1);
    const crammingIdx = techState.columns.findIndex(c => c?.type === 'cramming');

    const weaveGrids = new Map<string, Uint8Array>();
    const getWeaveGrid = (id: string) => {
        if (weaveGrids.has(id)) return weaveGrids.get(id)!;
        const w = allWeaves.find(v => v.id === id);
        if (!w || !w.draft[0]) return new Uint8Array(1).fill(0);
        const ww = w.draft[0].length, wh = w.pegPlan.length;
        const bits = new Uint8Array(ww * wh);
        const wToH = new Int16Array(ww).fill(-1);
        for(let x=0; x<ww; x++) {
            for(let ha=0; ha<w.harnesses; ha++) {
                if(w.draft[ha] && w.draft[ha][x] === 1) { wToH[x] = ha; break; }
            }
        }
        for(let y=0; y<wh; y++) {
            for(let x=0; x<ww; x++) {
                if(wToH[x] !== -1 && w.pegPlan[y] && w.pegPlan[y][wToH[x]] === 1) {
                    bits[y * ww + x] = 1;
                }
            }
        }
        weaveGrids.set(id, bits);
        return bits;
    };

    const groundLayer = (layers.find(l => l.type === 'ground') || layers[0] || ({ 
        colorIndex: 0, type: 'ground', sequence: '1:1', isCrammed: false, yarnId: 'A', weftSelector: 1 
    } as JacquardLayer));

    for (let y = 0; y < safeArtHeight; y++) {
        // --- 1. GROUND PICK PROCESSING ---
        const targetGroundPick = y * expansion;
        const gFaceGrid = groundLayer?.faceWeaveId ? getWeaveGrid(groundLayer.faceWeaveId) : null;
        const gBackGrid = groundLayer?.backWeaveId ? getWeaveGrid(groundLayer.backWeaveId) : null;

        if (weftSelectorIndices.length > 0) {
            const gSelIdx = weftSelectorIndices[(groundLayer.weftSelector - 1) % weftSelectorIndices.length];
            if (gSelIdx !== -1 && newTechGrid[targetGroundPick]) newTechGrid[targetGroundPick][gSelIdx] = true;
        }

        for (let x = 0; x < artwork.width; x++) {
            const artIdx = y * artwork.width + x;
            const colorIdx = artwork.data[artIdx];

            // In a ground pick, the ground yarn is on top if the pixel IS ground color.
            // Otherwise, the ground yarn goes to the back (Back Weave).
            const isGroundActive = colorIdx === groundLayer.colorIndex;
            const grid = isGroundActive ? gFaceGrid : gBackGrid;
            const weaveId = isGroundActive ? groundLayer.faceWeaveId : groundLayer.backWeaveId;

            if (grid && weaveId) {
                const w = allWeaves.find(v => v.id === weaveId);
                if (w && w.draft[0]) {
                    const ww = w.draft[0].length, wh = w.pegPlan.length;
                    newStructure[targetGroundPick * artwork.width + x] = grid[(y % wh) * ww + (x % ww)];
                }
            } else {
                // Fallback to plain if no weaves specified
                newStructure[targetGroundPick * artwork.width + x] = isGroundActive ? ((x + y) % 2 === 0 ? 1 : 0) : 1;
            }
        }

        // --- 2. EXTRA WEFT PICK PROCESSING ---
        extraWeftLayers.forEach((layer, lIdx) => {
            const targetPick = (y * expansion) + lIdx + 1;
            if (targetPick >= newHeight) return;

            if (weftSelectorIndices.length > 0) {
                const lSelIdx = weftSelectorIndices[(layer.weftSelector - 1) % weftSelectorIndices.length];
                if (lSelIdx !== -1 && newTechGrid[targetPick]) newTechGrid[targetPick][lSelIdx] = true;
            }

            if (crammingIdx !== -1 && layer.isCrammed && newTechGrid[targetPick]) {
                newTechGrid[targetPick][crammingIdx] = true;
            }

            const weaveIdFace = layer.faceWeaveId;
            const weaveIdBack = layer.backWeaveId;

            for (let x = 0; x < artwork.width; x++) {
                const artIdx = y * artwork.width + x;
                const isFace = artwork.data[artIdx] === layer.colorIndex;

                if (isFace) {
                    // YARN ON FACE (ACTIVE DESIGN PIXEL)
                    if (weaveIdFace) {
                        const grid = getWeaveGrid(weaveIdFace);
                        const w = allWeaves.find(v => v.id === weaveIdFace);
                        if (w && w.draft[0]) {
                            const ww = w.draft[0].length, wh = w.pegPlan.length;
                            newStructure[targetPick * artwork.width + x] = grid[(y % wh) * ww + (x % ww)];
                        } else {
                            newStructure[targetPick * artwork.width + x] = 0; // Absolute Float
                        }
                    } else {
                        newStructure[targetPick * artwork.width + x] = 0; // Pure Effect Float
                    }
                } else {
                    // YARN ON BACK (INACTIVE DESIGN PIXEL)
                    if (weaveIdBack) {
                        const grid = getWeaveGrid(weaveIdBack);
                        const w = allWeaves.find(v => v.id === weaveIdBack);
                        if (w && w.draft[0]) {
                            const ww = w.draft[0].length, wh = w.pegPlan.length;
                            // Sampling back weave on the reverse side
                            newStructure[targetPick * artwork.width + x] = grid[(y % wh) * ww + (x % ww)];
                        } else {
                            newStructure[targetPick * artwork.width + x] = 1; // Pure Warp Up (Full Burial)
                        }
                    } else {
                        newStructure[targetPick * artwork.width + x] = 1; // Standard burial behind fabric
                    }
                }
            }
        });
    }

    return { width: artwork.width, height: newHeight, structure: newStructure, techGrid: newTechGrid };
  }, [artwork, layerConfigs, customWeaves, jacquardData, allWeaves, techState]);

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      if (seq.length === 0) return Array.from({ length: jacquardData.width }, () => '#888');
      return Array.from({ length: jacquardData.width }, (_, i) => warpYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const expandedWeftPattern = useMemo(() => {
    if (!artwork) return expandPatternString(weftPatternString);
    const layers = (Object.values(layerConfigs) as JacquardLayer[]).sort((a, b) => a.colorIndex - b.colorIndex);
    const extraWeftLayers = layers.filter(l => l.type === 'extra-weft' && (l.faceWeaveId || l.backWeaveId));
    const finalSequence: string[] = [];

    const ground = layers.find(l => l.type === 'ground') || layers[0] || ({ yarnId: 'A' } as JacquardLayer);
    const maxSafePicks = 2048;
    for(let y=0; y < artwork.height; y++) {
        if (finalSequence.length >= maxSafePicks) break;
        finalSequence.push(ground.yarnId || 'A');
        extraWeftLayers.forEach(l => {
            if (finalSequence.length < maxSafePicks) finalSequence.push(l.yarnId || 'A');
        });
    }
    return finalSequence;
  }, [layerConfigs, artwork, weftPatternString]);

  const weftColorArray = useMemo(() => {
    return expandedWeftPattern.map(key => {
        return weftYarns[key]?.color || weftYarns['A']?.color || '#888';
    });
  }, [expandedWeftPattern, weftYarns]);

  const simData = useMemo(() => {
      const { width, height, structure } = technicalData;
      const rows: boolean[][] = []; const colors: string[][] = [];
      for (let y = 0; y < height; y++) {
          const rowB: boolean[] = []; const rowC: string[] = [];
          for (let x = 0; x < width; x++) {
              const idx = y * width + x;
              const isUp = idx < structure.length ? structure[idx] === 1 : false;
              rowB.push(isUp); 
              rowC.push(isUp ? (warpColorArray[x % warpColorArray.length] || '#000') : (weftColorArray[y % weftColorArray.length] || '#ccc'));
          }
          rows.push(rowB); colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [technicalData, warpColorArray, weftColorArray]);

  const handleApplyStudioYarn = () => {
    if (selectedYarnType === 'warp') setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    else setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    setAppMode('art'); 
  };

  const handleDropToLayer = (weave: LibraryWeave, layerIdx: number, slot: 'face' | 'back') => {
      handleUpdateLayer(layerIdx, { [slot === 'face' ? 'faceWeaveId' : 'backWeaveId']: weave.id });
  };

  const currentVisibleData = useMemo(() => {
    if (artwork && (viewMode === 'graph' || viewMode === 'interlace')) return technicalData;
    return jacquardData;
  }, [viewMode, technicalData, jacquardData, artwork]);

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />
        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl animate-in zoom-in-95 duration-200">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200 uppercase tracking-widest">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex-1 overflow-hidden relative flex">
            <div className="shrink-0 z-40 bg-gray-900 border-r border-gray-800">
                <ProgressiveToolbar mode={appMode} onModeChange={(m) => m === 'sim' ? setShowSimModal(true) : setAppMode(m)} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{currentVisibleData.width} × {currentVisibleData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                            <button onClick={() => setViewMode('interlace')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-gray-200'}`}>INTERLACE</button>
                            <button onClick={() => setViewMode('structure')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-gray-200'}`}>ARTWORK</button>
                            <button onClick={() => setViewMode('graph')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'graph' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-gray-200'}`}>TECH CARD</button>
                        </div>
                    </div>
                </div>

                <div className="flex-1 flex overflow-hidden">
                    {(appMode === 'art' || appMode === 'weave') && viewMode === 'graph' && technicalData.techGrid && (
                        <div className="w-16 bg-gray-900 border-r border-gray-800 flex flex-col shrink-0 overflow-hidden shadow-2xl relative z-10">
                            <div className="h-10 border-b border-gray-800 flex items-center justify-center text-[8px] font-black text-blue-500 uppercase tracking-tighter">Selectors</div>
                            <div className="flex-1 relative overflow-hidden" style={{ height: currentVisibleData.height * canvasView.zoom }}>
                                <div className="absolute inset-0" style={{ transform: `translateY(${canvasView.y}px)` }}>
                                    {technicalData.techGrid.map((row, i) => (
                                        <div key={i} className="flex border-b border-gray-800/20" style={{ height: canvasView.zoom }}>
                                            {row.map((active, j) => (
                                                <div key={j} className={`flex-1 ${active ? 'bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]' : 'bg-transparent'}`} />
                                            ))}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="flex-1 relative">
                        {appMode === 'yarn' ? (
                            <YarnStudio yarn={studioYarnDef} onChange={setStudioYarnDef} onApply={handleApplyStudioYarn} />
                        ) : appMode === 'tech' ? (
                            <ProductionCalculator settings={settings} warpYarns={warpYarns} weftYarns={weftYarns} warpPatternString={warpPatternString} weftPatternString={weftPatternString} draft={[]} pegPlan={[]} generateThumbnail={() => ""} />
                        ) : appMode === 'weave-studio' ? (
                            <WeaveStudio onSaveToLibrary={(w) => setCustomWeaves(prev => [...prev, w])} />
                        ) : appMode === 'loom-tech' ? (
                            <LoomTechModule data={technicalData} settings={settings} weftYarns={weftYarns} weftPatternString={weftPatternString} warpYarns={warpYarns} warpPatternString={warpPatternString} techState={techState} onTechStateUpdate={setTechState} config={loomConfig} onConfigUpdate={setLoomConfig} />
                        ) : appMode === 'loom-editor' ? (
                            <LoomEditorModule config={loomConfig} onUpdate={setLoomConfig} techState={techState} onTechStateUpdate={setTechState} />
                        ) : (
                            <JacquardCanvas 
                                data={currentVisibleData} artwork={artwork || undefined} 
                                onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))} 
                                onUpdateWarpPattern={setWarpPatternString}
                                onUpdateWeftPattern={setWeftPatternString}
                                activeYarnId={activeYarnId}
                                tool={currentTool} viewMode={viewMode} faceMode={faceMode} 
                                warpColors={warpColorArray} weftColors={weftColorArray} 
                                warpPatternString={warpPatternString}
                                weftPatternString={weftPatternString}
                                settings={settings}
                                onViewChange={setCanvasView}
                            />
                        )}
                    </div>
                </div>

                {artwork && (appMode === 'art' || appMode === 'weave') && (
                    <div className="h-32 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl overflow-x-auto custom-scrollbar">
                        <div className="flex flex-col shrink-0">
                            <span className="text-[9px] font-black text-gray-500 uppercase mb-1 tracking-widest">Deck Management</span>
                            <span className="text-[10px] text-gray-400 font-mono italic">Drag structure to Face/Back</span>
                        </div>
                        <div className="flex items-center gap-4 py-2">
                            {artwork.palette.map((color, idx) => {
                                const config = layerConfigs[idx];
                                const faceW = allWeaves.find(w => w.id === config?.faceWeaveId);
                                const backW = allWeaves.find(w => w.id === config?.backWeaveId);

                                return (
                                    <div key={idx} className="group flex flex-col items-center gap-1.5 shrink-0 bg-gray-800/40 p-2.5 rounded-xl border border-gray-700 hover:bg-gray-800 transition-all">
                                        <div className="flex gap-1">
                                            <div 
                                                onDragOver={e => e.preventDefault()}
                                                onDrop={e => {
                                                    const d = e.dataTransfer.getData('weave-obj');
                                                    if (d) handleDropToLayer(JSON.parse(d), idx, 'face');
                                                }}
                                                className="w-[44px] h-[60px] bg-black/40 rounded border border-dashed border-gray-700 flex flex-col overflow-hidden relative group/face"
                                            >
                                                <div className="h-2 w-full absolute top-0 z-10 opacity-60" style={{ background: color }} />
                                                {faceW ? (
                                                    <div className="flex-1 relative">
                                                        <WeaveThumbnail weave={faceW} className="w-full h-full opacity-80" />
                                                        <button onClick={() => handleUpdateLayer(idx, { faceWeaveId: undefined })} className="absolute inset-0 bg-red-600/60 opacity-0 group-hover/face:opacity-100 flex items-center justify-center transition-opacity"><TrashIcon className="w-3  h-3 text-white" /></button>
                                                    </div>
                                                ) : <div className="flex-1 flex items-center justify-center text-[8px] text-gray-600 font-bold uppercase tracking-tighter text-center px-1">Face</div>}
                                            </div>

                                            <button 
                                                onClick={() => setActiveLayerIdx(idx)}
                                                className="w-[30px] h-[60px] rounded border border-white/10 shadow-lg relative overflow-hidden flex items-center justify-center hover:brightness-110 transition-all"
                                                style={{ backgroundColor: color }}
                                            >
                                                <SettingsIcon className="w-4 h-4 text-white/50" />
                                                {config?.isCrammed && (
                                                    <div className="absolute top-0 right-0 p-0.5 bg-orange-600 rounded-bl shadow-sm animate-pulse">
                                                        <ProcessorIcon className="w-2.5 h-2.5 text-white" />
                                                    </div>
                                                )}
                                                <div className="absolute bottom-0 inset-x-0 bg-black/40 text-[9px] font-black text-white py-0.5 text-center">{config?.weftSelector || 1}</div>
                                            </button>

                                            <div 
                                                onDragOver={e => e.preventDefault()}
                                                onDrop={e => {
                                                    const d = e.dataTransfer.getData('weave-obj');
                                                    if (d) handleDropToLayer(JSON.parse(d), idx, 'back');
                                                }}
                                                className="w-[44px] h-[60px] bg-black/40 rounded border border-dashed border-gray-700 flex flex-col overflow-hidden relative group/back"
                                            >
                                                <div className="h-2 w-full absolute bottom-0 z-10 opacity-60" style={{ background: color }} />
                                                {backW ? (
                                                    <div className="flex-1 relative">
                                                        <WeaveThumbnail weave={backW} className="w-full h-full opacity-80" />
                                                        <button onClick={() => handleUpdateLayer(idx, { backWeaveId: undefined })} className="absolute inset-0 bg-red-600/60 opacity-0 group-hover/back:opacity-100 flex items-center justify-center transition-opacity"><TrashIcon className="w-3 h-3 text-white" /></button>
                                                    </div>
                                                ) : <div className="flex-1 flex items-center justify-center text-[8px] text-gray-600 font-bold uppercase tracking-tighter text-center px-1">Back</div>}
                                            </div>
                                        </div>
                                        <span className="text-[8px] font-mono text-gray-500 uppercase tracking-widest">{config?.type === 'ground' ? 'Base' : `Ch ${config?.weftSelector || 1}`}</span>
                                    </div>
                                );
                            })}
                        </div>
                        <div className="flex flex-col gap-1 items-end shrink-0 ml-auto pr-6">
                            <span className="text-[8px] font-black text-blue-500 animate-pulse mb-1 uppercase tracking-widest">Logic: Stäubli / Bonas</span>
                            <button onClick={() => setArtwork(null)} className="px-4 py-1.5 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded-lg font-black uppercase tracking-widest hover:bg-red-900/50 transition-all">Clear Deck</button>
                        </div>
                    </div>
                )}
            </div>

            <div className={`shrink-0 transition-all duration-300 border-l border-gray-800 bg-white ${isPanelCollapsed ? 'w-0 opacity-0 overflow-hidden' : 'w-80'}`}>
                <RightPanel 
                    settings={settings} onSettingsChange={setSettings} dentingPattern={dentingPattern} onDentingChange={setDentingPattern} onSnapshot={()=>{}} onLoadWeave={()=>{}} 
                    customWeaves={customWeaves} onAddWeave={()=>{}} onUpdateWeave={()=>{}} onDeleteWeave={()=>{}} 
                    warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))} onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))} paletteColors={PANTONE_PALETTE} warpPatternString={warpPatternString} setWarpPatternString={setWarpPatternString} weftPatternString={weftPatternString} setWeftPatternString={setWeftPatternString} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{} as any} onApplyGenerated={()=>{}} onSimulate={() => setShowSimModal(true)} onGridOperation={()=>{}} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { setActiveYarnId(id); setSelectedYarnType(type); setAppMode('yarn'); }}
                    onOpenPixelEditor={() => setShowCustomModal(true)}
                    jacquardData={jacquardData}
                    canvasView={canvasView}
                />
            </div>
        </div>

        {activeLayerIdx !== null && artwork && (
            <LayerPropertyModal 
                isOpen={activeLayerIdx !== null} 
                onClose={() => setActiveLayerIdx(null)}
                color={artwork.palette[activeLayerIdx]}
                layer={layerConfigs[activeLayerIdx] || { colorIndex: activeLayerIdx, type: 'ground', sequence: '1:1', isCrammed: false, yarnId: 'A', weftSelector: 1 }}
                onUpdate={(updates) => handleUpdateLayer(activeLayerIdx!, updates)}
                customWeaves={customWeaves}
                yarns={weftYarns}
            />
        )}

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)} 
            weavePattern={simData.colors} 
            structure={simData.structure} 
            epi={settings.epi} 
            ppi={settings.ppi} 
            techGrid={technicalData.techGrid}
            techColumns={techState.columns}
            dentingPlan={dentingPattern.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n))} 
            warpYarns={warpYarns} 
            weftYarns={weftYarns} 
            warpYarnSequence={expandPatternString(warpPatternString)} 
            weftYarnSequence={expandedWeftPattern} 
        />
        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import { YarnDefinition, DensityZone, LoomTechColumn } from '../types';
import { generateYarnTexture } from './yarnRenderer';

interface RenderOptions {
    weavePattern: string[][];
    structure: boolean[][];
    epi: number;
    ppi: number;
    techGrid?: boolean[][];
    techColumns?: LoomTechColumn[];
    dentingPlan?: number[];
    weftZones?: DensityZone[];
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpYarnSequence: string[];
    weftYarnSequence: string[];
    viewSide: 'face' | 'back';
    dpi: number;
    width: number; 
    height: number; 
    hideFloats?: boolean; 
    backgroundColor?: string; 
    smoothingQuality?: 'low' | 'medium' | 'high' | 'none';
}

const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = 128;
shadowCanvas.height = 128;
const sCtx = shadowCanvas.getContext('2d');
if (sCtx) {
    const grad = sCtx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,0.6)');
    grad.addColorStop(0.6, 'rgba(0,0,0,0.1)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    sCtx.fillStyle = grad;
    sCtx.fillRect(0, 0, 128, 128);
}

export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern, structure, epi, ppi, techGrid, techColumns, dentingPlan, weftZones,
        warpYarns, weftYarns, warpYarnSequence, weftYarnSequence,
        viewSide, dpi, width: displayW, height: displayH,
        hideFloats = false,
        backgroundColor = '#050505',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    const SS_FACTOR = 1.1; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const CANVAS_WIDTH = Math.round((displayW / 96) * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round((displayH / 96) * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    ctx.imageSmoothingEnabled = smoothingQuality !== 'none';
    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- WARP POSITIONS ---
    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = safePlan.reduce((a, b) => a + b, 0) / safePlan.length;
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    const MAX_COLS = 2000;
    while (currentX < CANVAS_WIDTH && warpPositions.length < MAX_COLS) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) currentX += dentWidthPx;
        else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                if (warpPositions.length >= MAX_COLS) break;
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.03) });
                currentX += w;
            }
        }
        dIdx++;
    }
    const totalCols = warpPositions.length;

    // --- VERTICAL STACKING LOGIC ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const crammingIdx = techColumns?.findIndex(c => c.type === 'cramming') ?? -1;
    const nominalH = PX_PER_INCH / Math.max(1, ppi);

    let currentY = 0;
    const MAX_PICKS = 2000;

    // Calculate vertical coordinates with stacking for extra wefts/cramming
    for (let r = 0; r < Math.min(rows, MAX_PICKS); r++) {
        const isCrammed = crammingIdx !== -1 && techGrid?.[r]?.[crammingIdx];
        let h = nominalH;

        const yid = weftYarnSequence[r % weftYarnSequence.length];
        const preferred = weftYarns[yid]?.preferredPPI;
        if (preferred) h = PX_PER_INCH / Math.max(1, preferred);

        rowY.push(currentY);
        if (isCrammed) {
            rowHeights.push(0); // This pick doesn't advance the loom (Cramming)
        } else {
            rowHeights.push(h);
            currentY += h; 
        }
    }

    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR)));
    Object.keys(weftYarns).forEach(k => textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR)));

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);
    const VISUAL_THICKNESS_SCALE = 2.2; 

    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, rIdx: number, cIdx: number, op: number, over: number, ao: number, taper: number, jitter: number, isExtra: boolean = false) => {
        if (op <= 0) return;
        const cx = gx + gw/2 + jitter, cy = gy + gh/2 + jitter;

        // Bloom Effect for decorative yarns
        const bloom = isExtra ? (1.0 + over * 2.5) : (1.0 + over);
        const effThick = thickness * bloom * (1.0 - taper);
        const sFact = 1.0 - (spacing || 0);

        let dw, dh, dx, dy;
        if (isV) {
            dw = NOMINAL_WARP_W * effThick * sFact * VISUAL_THICKNESS_SCALE + 0.5; 
            dh = gh + 0.5;
            dx = (cx - dw / 2); dy = gy;
        } else {
            dh = (isExtra ? NOMINAL_WEFT_H * 1.6 : NOMINAL_WEFT_H) * effThick * sFact * VISUAL_THICKNESS_SCALE + 0.5;
            dw = gw + 0.5;
            dx = gx; dy = (cy - dh / 2);
        }

        ctx.save();
        ctx.globalAlpha = op;
        ctx.translate(dx + dw/2, dy + dh/2);

        const phase = Math.floor(Math.abs((Math.sin((isV ? cIdx : rIdx) * 12.98) * 43758.54) % 1) * tex.width);
        if (isV) {
            ctx.rotate(Math.PI / 2);
            ctx.drawImage(tex, (gy + phase) % tex.width, 0, 1, tex.height, -dh/2, -dw/2, dh, dw);
        } else {
            ctx.drawImage(tex, (gx + phase) % tex.width, 0, 1, tex.height, -dw/2, -dh/2, dw, dh);
        }

        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao * 0.45})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(-dw/2, -dh/2, dw, dh); 
        }
        ctx.restore();
    };

    // --- 3-PASS LAYERED RENDER ---
    // Pass 1: Ground Structure
    // Pass 2: Extra Wefts (Floating decorative layer)
    // Pass 3: Top Interlacements (Warp threads that bind the extra wefts)
    for (let pass = 1; pass <= 3; pass++) {
        for (let r = 0; r < rowY.length; r++) {
            const pR = r % rows;
            const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
            const wDef = weftYarns[wYId];
            const isExtra = wDef?.isExtraWeft || false;

            // Skip logic for passes
            if (pass === 1 && isExtra) continue;
            if (pass === 2 && !isExtra) continue;
            if (pass === 3 && isExtra) continue;

            const gY = rowY[r];
            const gH = Math.max(NOMINAL_WEFT_H, rowHeights[r]); 

            // Culling
            if (gY > CANVAS_HEIGHT + 100 || gY + gH < -100) continue;

            const wTex = textureMap.get(`weft-${wYId}`);

            for (let c = 0; c < totalCols; c++) {
                const pC = c % cols;
                const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
                const waDef = warpYarns[waYId];
                const waTex = textureMap.get(`warp-${waYId}`);
                const gX = warpPositions[c].x;
                const gW = warpPositions[c].w;
                const jit = warpPositions[c].jitter;

                const wTopR = structure[pR]?.[pC] || false;
                const wTop = viewSide === 'face' ? wTopR : !wTopR;

                let wOp = 1.0;
                let wOv = wDef?.extraOverlap ?? 0;

                // Extra weft specific opacity for floating areas
                if (isExtra && wTop) {
                    wOp = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);
                }

                let wAO = 0, wT = 0;
                // Shadow / Tapering logic
                if ((!wTop && pass === 1) || (wTop && pass === 3)) {
                   const pWT = viewSide === 'face' ? (structure[pR]?.[(pC-1+cols)%cols] || false) : !(structure[pR]?.[(pC-1+cols)%cols] || false);
                   const nWT = viewSide === 'face' ? (structure[pR]?.[(pC+1)%cols] || false) : !(structure[pR]?.[(pC+1)%cols] || false);
                   if (!wTop && (pWT || nWT)) { 
                       wAO = wDef?.bindingDepth || 0.35; 
                       wT = wDef?.floatTaper || 0.12; 
                   }
                }

                if (pass === 1) {
                    // Draw Ground Base
                    if (wTop) { 
                        if (wTex) drawThread(wTex, gX, gY, gW, gH, wDef?.thickness || 1, wDef?.spacing || 0, false, r, c, wOp, wOv, wAO, wT, jit); 
                    } else { 
                        if (waTex) drawThread(waTex, gX, gY, gW, gH, waDef?.thickness || 1, waDef?.spacing || 0, true, r, c, 1.0, waDef?.extraOverlap ?? 0, 0, 0, jit); 
                    }
                } else if (pass === 2) {
                    // Draw Extra Wefts with decorative blooming and depth
                    if (!wTop && wTex) {
                        // Cast a shadow from the float onto the background
                        const sTh = (wDef?.shadowThrow ?? 1.5) * SS_FACTOR;
                        const sAn = (wDef?.shadowAngle ?? 135) * Math.PI/180;
                        ctx.globalAlpha = 0.2;
                        ctx.drawImage(shadowCanvas, (gX + gW/2) + Math.cos(sAn)*sTh, (gY + gH/2) + Math.sin(sAn)*sTh, gW*1.8, gH*1.8);

                        drawThread(wTex, gX, gY, gW, gH, wDef?.thickness || 1, wDef?.spacing || 0, false, r, c, wOp, wOv, wAO, wT, jit, true);
                    }
                } else if (pass === 3) {
                    // Draw Warp binding on top of ground weft
                    if (wTop && waTex) {
                        drawThread(waTex, gX, gY, gW, gH, waDef?.thickness || 1, waDef?.spacing || 0, true, r, c, 1.0, waDef?.extraOverlap ?? 0, 0, 0, jit);
                    }
                }
            }
        }
    }

    return canvas;
};

