type TabType = 'construction' | 'pattern' | 'weave' | 'yarns' | 'colors';

const TabButton: React.FC<{ id: TabType, activeTab: TabType, icon: React.ReactNode, label: string, onClick: (id: TabType) => void }> = ({ id, activeTab, icon, label, onClick }) => (
    <button
        onClick={() => onClick(id)}
        className={`flex-1 flex flex-col items-center justify-center py-3 gap-1 border-b-2 transition-colors ${activeTab === id ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
    >
        {icon}
        <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
    </button>
);

const SliderInput: React.FC<{
    label: string; 
    value: number; 
    onChange?: (value: number) => void; 
    min?: number; 
    max?: number; 
    step?: number; 
    subLabel?: string; 
    disabled?: boolean; 
    onPointerDown?: () => void;
}> = ({ label, value, onChange, min, max, step, subLabel, disabled, onPointerDown }) => (
    <div className="mb-5">
        <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 flex justify-between items-end">
            <span className="leading-tight">{label} {subLabel && <span className="text-gray-400 normal-case ml-1">({subLabel})</span>}</span>
            <input 
                type="number" 
                value={value}
                min={min}
                max={max}
                step={step}
                onChange={(e) => onChange && onChange(parseFloat(e.target.value) || 0)}
                className="w-16 bg-gray-50 border border-gray-200 rounded px-1.5 py-0.5 text-right text-xs font-mono font-bold text-blue-600 focus:border-blue-500 outline-none"
            />
        </label>
        {!disabled && (
            <input
                type="range" min={min} max={max} step={step} value={value}
                onChange={(e) => onChange && onChange(parseInt(e.target.value, 10))}
