                    )}

                    {activeTab === 'yarns' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200 space-y-8">
                            <YarnList label="Warp Yarn Registry" yarns={warpYarns} type="warp" activeId={activeYarnId} isSelectedType={selectedYarnType === 'warp'} onSelect={onSelectYarn} onEdit={(id, def) => setEditingYarn({id, type: 'warp', def})} usedChars={usedWarpChars} />
                            <YarnList label="Weft Yarn Registry" yarns={weftYarns} type="weft" activeId={activeYarnId} isSelectedType={selectedYarnType === 'weft'} onSelect={onSelectYarn} onEdit={(id, def) => setEditingYarn({id, type: 'weft', def})} usedChars={usedWeftChars} />
                        </div>
                    )}

                    {activeTab === 'colors' && (
                        <div className="animate-in fade-in slide-in-from-right-2 duration-200">
                            <ColorPalette colorMap={colorMap} onSelectColor={onSelectColor} selectedColorIndex={selectedColorIndex} />
                        </div>
                    )}
                </div>
            </div>

            {editingYarn && (
                <YarnDesignerModal 
                    isOpen={!!editingYarn} onClose={() => setEditingYarn(null)} yarnId={editingYarn.id} yarnType={editingYarn.type} initialYarn={editingYarn.def}
                    onSave={(newYarn) => { 
                        onSnapshot(); 
                        if (editingYarn.type === 'warp') onUpdateWarpYarn(editingYarn.id, newYarn); 
                        else onUpdateWeftYarn(editingYarn.id, newYarn); 
                    }}
                />
            )}
        </>
    );
};

import { YarnDefinition, DensityZone, LoomTechColumn } from '../types';
import { generateYarnTexture } from './yarnRenderer';

interface RenderOptions {
    weavePattern: string[][];
    structure: boolean[][];
    epi: number;
    ppi: number;
    techGrid?: boolean[][];
    techColumns?: LoomTechColumn[];
    dentingPlan?: number[];
    weftZones?: DensityZone[];
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpYarnSequence: string[];
    weftYarnSequence: string[];
    viewSide: 'face' | 'back';
    dpi: number;
    width: number; 
    height: number; 
    hideFloats?: boolean; 
    backgroundColor?: string; 
    smoothingQuality?: 'low' | 'medium' | 'high' | 'none';
}

const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = 128;
shadowCanvas.height = 128;
const sCtx = shadowCanvas.getContext('2d');
if (sCtx) {
    const grad = sCtx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,0.6)');
    grad.addColorStop(0.6, 'rgba(0,0,0,0.1)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    sCtx.fillStyle = grad;
    sCtx.fillRect(0, 0, 128, 128);
}

export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern = [], structure = [], epi, ppi, techGrid, techColumns, dentingPlan,
        warpYarns = {}, weftYarns = {}, warpYarnSequence = [], weftYarnSequence = [],
        viewSide, dpi, width: displayW, height: displayH,
        hideFloats = false,
        backgroundColor = '#050505',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    const SS_FACTOR = 1.1; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const CANVAS_WIDTH = Math.round((displayW / 96) * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round((displayH / 96) * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    ctx.imageSmoothingEnabled = smoothingQuality !== 'none';
    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- WARP GEOMETRY ---
    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = Math.max(1, safePlan.reduce((a, b) => a + b, 0) / safePlan.length);
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    while (currentX < CANVAS_WIDTH && warpPositions.length < 2000) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) {
            currentX += dentWidthPx;
        } else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.03) });
                currentX += w;
                if (warpPositions.length >= 2000) break;
            }
        }
        dIdx++;
        if (dIdx > 5000) break; // Infinite loop protection
    }
    const totalCols = warpPositions.length;

    // --- WEFT GEOMETRY & STACKING ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const crammingIdx = techColumns?.findIndex(c => c.type === 'cramming') ?? -1;
    const nominalH = PX_PER_INCH / Math.max(1, ppi);
    let currentY = 0;

    for (let r = 0; r < rows; r++) {
        const isCrammed = crammingIdx !== -1 && techGrid?.[r]?.[crammingIdx];
        const yid = weftYarnSequence.length > 0 ? weftYarnSequence[r % weftYarnSequence.length] : 'A';
        const preferred = weftYarns[yid]?.preferredPPI;
        let h = preferred ? (PX_PER_INCH / Math.max(1, preferred)) : nominalH;

        rowY.push(currentY);
        if (isCrammed) {
            rowHeights.push(h * 0.8); 
        } else {
            rowHeights.push(h);
            currentY += h; 
        }
        if (currentY > CANVAS_HEIGHT + 200) break;
    }

    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => {
        if (warpYarns[k]) textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR));
    });
    Object.keys(weftYarns).forEach(k => {
        if (weftYarns[k]) textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR));
    });

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);
    const THICK_SCALE = 2.2; 

    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, rIdx: number, cIdx: number, op: number, over: number, ao: number, taper: number, jitter: number, isExtra: boolean = false) => {
        if (op <= 0 || !tex) return;
        const cx = gx + gw/2 + jitter, cy = gy + gh/2 + jitter;

        const bloom = isExtra ? (1.0 + over * 2.5) : (1.0 + over);
        const effThick = thickness * bloom * (1.0 - taper);
        const sFact = 1.0 - (spacing || 0);

        let dw, dh, dx, dy;
        if (isV) {
            dw = NOMINAL_WARP_W * effThick * sFact * THICK_SCALE + 0.5; 
            dh = gh + 0.5;
            dx = (cx - dw / 2); dy = gy;
        } else {
            dh = (isExtra ? NOMINAL_WEFT_H * 1.6 : NOMINAL_WEFT_H) * effThick * sFact * THICK_SCALE + 0.5;
            dw = gw + 0.5;
            dx = gx; dy = (cy - dh / 2);
        }

        ctx.save();
        ctx.globalAlpha = op;
        ctx.translate(dx + dw/2, dy + dh/2);

        const phase = Math.floor(Math.abs((Math.sin((isV ? cIdx : rIdx) * 12.98) * 43758.54) % 1) * tex.width);
        if (isV) {
            ctx.rotate(Math.PI / 2);
            ctx.drawImage(tex, (gy + phase) % tex.width, 0, 1, tex.height, -dh/2, -dw/2, dh, dw);
        } else {
            ctx.drawImage(tex, (gx + phase) % tex.width, 0, 1, tex.height, -dw/2, -dh/2, dw, dh);
        }

        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao * 0.45})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(-dw/2, -dh/2, dw, dh); 
        }
        ctx.restore();
    };

    // PASS 1: THE WARP FOREST
    if (warpYarnSequence.length > 0) {
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
            const waDef = warpYarns[waYId];
            const waTex = textureMap.get(`warp-${waYId}`);
            if (!waTex || !waDef) continue;

            const gX = warpPositions[c].x;
            const gW = warpPositions[c].w;
            const jit = warpPositions[c].jitter;

            for (let r = 0; r < rowY.length; r++) {
                const gY = rowY[r];
                const gH = rowHeights[r];
                if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;
                drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, r, c, 1.0, 0, 0, 0, jit);
            }
        }
    }

    // PASS 2: THE SHUTTLE LAYERS
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        const wYId = weftYarnSequence.length > 0 ? (weftYarnSequence[pR % weftYarnSequence.length] || 'A') : 'A';
        const wDef = weftYarns[wYId];
        if (!wDef) continue;
        const wTex = textureMap.get(`weft-${wYId}`);
        if (!wTex) continue;

        const isExtra = wDef.isExtraWeft;
        const gY = rowY[r];
        const gH = rowHeights[r];
        if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const wTop = viewSide === 'face' ? wTopR : !wTopR;

            const gX = warpPositions[c].x;
            const gW = warpPositions[c].w;
            const jit = warpPositions[c].jitter;

            if (!wTop || isExtra) {
                let op = 1.0;
                if (isExtra && wTop) op = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);

                if (isExtra && !wTop) {
                    const sTh = (wDef?.shadowThrow ?? 1.5) * SS_FACTOR;
                    const sAn = (wDef?.shadowAngle ?? 135) * Math.PI/180;
                    ctx.globalAlpha = 0.15;
                    ctx.drawImage(shadowCanvas, (gX + gW/2) + Math.cos(sAn)*sTh, (gY + gH/2) + Math.sin(sAn)*sTh, gW*2.0, gH*2.0);
                }

                drawThread(wTex, gX, gY, gW, gH, wDef.thickness || 1, wDef.spacing || 0, false, r, c, op, wDef.extraOverlap ?? 0, 0, 0, jit, isExtra);
            }
        }
    }

    // PASS 3: THE WARP CAPS
    if (warpYarnSequence.length > 0) {
        for (let r = 0; r < rowY.length; r++) {
            const pR = r % rows;
            const gY = rowY[r];
            const gH = rowHeights[r];
            if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

            for (let c = 0; c < totalCols; c++) {
                const pC = c % cols;
                const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
                const waDef = warpYarns[waYId];
                const waTex = textureMap.get(`warp-${waYId}`);
                if (!waTex || !waDef) continue;

                const wTopR = structure[pR]?.[pC] || false;
                const wTop = viewSide === 'face' ? wTopR : !wTopR;

                if (wTop) {
                    const gX = warpPositions[c].x;
                    const gW = warpPositions[c].w;
                    const jit = warpPositions[c].jitter;

                    let wAO = 0, wT = 0;
                    const pWT = viewSide === 'face' ? (structure[pR]?.[(pC-1+cols)%cols] || false) : !(structure[pR]?.[(pC-1+cols)%cols] || false);
                    const nWT = viewSide === 'face' ? (structure[pR]?.[(pC+1)%cols] || false) : !(structure[pR]?.[(pC+1)%cols] || false);
                    if (!pWT || !nWT) {
                        wAO = 0.25;
                        wT = 0.08;
                    }
                    drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, r, c, 1.0, 0, wAO, wT, jit);
                }
            }
        }
    }

    return canvas;
};

export interface QuantizationResult {
  pixels: number[]; // Array of palette indices
  palette: string[]; // Array of hex colors
  width: number;
  height: number;
}

const rgbToHex = (r: number, g: number, b: number) => {
    return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1).toUpperCase();
};

const hexToRgb = (hex: string) => {
    if (!hex) return [0, 0, 0];
    const r = parseInt(hex.slice(1, 3), 16) || 0;
    const g = parseInt(hex.slice(3, 5), 16) || 0;
    const b = parseInt(hex.slice(5, 7), 16) || 0;
    return [r, g, b];
};

const colorDistanceSq = (r1: number, g1: number, b1: number, r2: number, g2: number, b2: number) => {
    return (r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2;
};

export const loadImage = (file: File): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => {
            URL.revokeObjectURL(url);
            resolve(img);
        };
        img.onerror = () => {
            URL.revokeObjectURL(url);
            reject(new Error(`Failed to load image: ${file.name}. Ensure it is a valid image file.`));
        };
        img.src = url;
    });
};

export const processImage = (
    img: HTMLImageElement, 
    maxColors: number = 12, 
    maxWidth: number = 1024
): QuantizationResult => {
    let w = img.width;
    let h = img.height;

    if (w > maxWidth) {
        const ratio = maxWidth / w;
        w = maxWidth;
        h = Math.floor(h * ratio);
    }

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, w);
    canvas.height = Math.max(1, h);
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    if (!ctx) throw new Error("Could not initialize 2D context.");

    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imgData.data;
    const pixelCount = canvas.width * canvas.height;

    // 1. Detect Unique Colors
    const uniqueColorsMap = new Map<string, number>();
    for (let i = 0; i < pixelCount; i++) {
        const offset = i * 4;
        if (data[offset + 3] < 128) continue; 
        const hex = rgbToHex(data[offset], data[offset+1], data[offset+2]);
        uniqueColorsMap.set(hex, (uniqueColorsMap.get(hex) || 0) + 1);
    }

    let palette: string[] = [];
    let pixels: number[] = new Array(pixelCount).fill(0);

    if (uniqueColorsMap.size <= maxColors) {
        palette = Array.from(uniqueColorsMap.entries())
            .sort((a, b) => b[1] - a[1])
            .map(entry => entry[0]);
        for (let i = 0; i < pixelCount; i++) {
            const hex = rgbToHex(data[i*4], data[i*4+1], data[i*4+2]);
            const pIdx = palette.indexOf(hex);
            pixels[i] = pIdx === -1 ? 0 : pIdx;
        }
    } else {
        // K-Means
        let centroids = Array.from(uniqueColorsMap.entries())
            .sort((a, b) => b[1] - a[1])
            .slice(0, maxColors)
            .map(entry => hexToRgb(entry[0]));

        const assignments = new Uint8Array(pixelCount);
        for (let iter = 0; iter < 8; iter++) {
            const sums = centroids.map(() => [0, 0, 0, 0]); 
            for (let i = 0; i < pixelCount; i++) {
                const r = data[i*4], g = data[i*4+1], b = data[i*4+2];
                let minDist = Infinity, best = 0;
                for (let c = 0; c < centroids.length; c++) {
                    const ct = centroids[c];
                    if (!ct) continue;
                    const d = colorDistanceSq(r, g, b, ct[0], ct[1], ct[2]);
                    if (d < minDist) { minDist = d; best = c; }
                }
                assignments[i] = best;
                if (sums[best]) {
                    sums[best][0] += r; sums[best][1] += g; sums[best][2] += b; sums[best][3]++;
                }
            }
            centroids = sums.map((s, idx) => s[3] > 0 ? [s[0]/s[3], s[1]/s[3], s[2]/s[3]] : centroids[idx]);
        }

        const counts = new Array(centroids.length).fill(0);
        assignments.forEach(a => { if (counts[a] !== undefined) counts[a]++; });

        const indexedCentroids = centroids.map((c, i) => ({ color: c, count: counts[i] || 0, oldIdx: i }));
        indexedCentroids.sort((a, b) => b.count - a.count);

        palette = indexedCentroids.map(ic => rgbToHex(Math.round(ic.color[0]), Math.round(ic.color[1]), Math.round(ic.color[2])));
        const remapping = new Int32Array(centroids.length);
        indexedCentroids.forEach((ic, newIdx) => remapping[ic.oldIdx] = newIdx);

        pixels = Array.from(assignments).map(oldIdx => remapping[oldIdx]);
    }

    return { pixels, palette, width: canvas.width, height: canvas.height };
};

