interface ProductionCalculatorProps {
    settings: WeaveSettings;
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpPatternString: string;
    weftPatternString: string;
    dentingPlan?: number[];
    draft: boolean[][];
    pegPlan: boolean[][];
    generateThumbnail: () => string; // Function to get current sim image
}

const InputRow: React.FC<{label: string, value: any, onChange: (v:any)=>void, type?: string, unit?: string}> = ({label, value, onChange, type='number', unit}) => (
    <div className="flex justify-between items-center mb-2">
        <label className="text-xs text-gray-500 font-medium">{label}</label>
        <div className="flex items-center gap-1">
            <input 
                type={type} 
                value={value} 
                onChange={e => onChange(type==='number'? (e.target.value === '' ? 0 : parseFloat(e.target.value)) : e.target.value)} 
                className="w-20 bg-gray-50 border border-gray-200 rounded p-1 text-right text-sm font-mono focus:border-blue-500 focus:outline-none"
            />
            {unit && <span className="text-[10px] text-gray-400 w-4">{unit}</span>}
        </div>
    </div>
);

export const ProductionCalculator: React.FC<ProductionCalculatorProps> = ({
    settings, warpYarns = {}, weftYarns = {}, warpPatternString = "", weftPatternString = "", dentingPlan, draft, pegPlan, generateThumbnail
}) => {
    // --- State ---
    const [prodSettings, setProdSettings] = useState<ProductionSettings & { loomSpeed: number, efficiency: number, hourlyRate: number, setupTime: number, metersPerPirn: number }>({
        clientName: '',
        orderNumber: '',
        loomId: '',
        weaverName: '',
        finishedWidth: 140, // cm
        finishedLength: 50, // meters
        warpTakeUp: 8, // %
        weftContraction: 5, // %
        warpWaste: 0.8, // m (loom waste)
        weftWaste: 2, // %
        priceCurrency: '€',
        loomSpeed: 120, // PPM (Picks Per Minute)
        efficiency: 85, // %
        hourlyRate: 25, // Currency/hr
        setupTime: 4, // Hours
        metersPerPirn: 300 // Standard shuttle pirn capacity
    });

    const [ticketConfig, setTicketConfig] = useState<MillTicketConfig>({
        showDraft: true,
        showPegPlan: true,
        showYarns: true,
        showCosting: true,
        showSwatch: true,
        showWarpPattern: true,
        showWeftPattern: true,
        paperSize: 'A4'
    });

    // --- Calculations ---
    const calculations = useMemo(() => {
        const reedWidthCm = prodSettings.finishedWidth / Math.max(0.001, (1 - (prodSettings.weftContraction / 100)));
        const totalWarpLengthM = (prodSettings.finishedLength / Math.max(0.001, (1 - (prodSettings.warpTakeUp / 100)))) + prodSettings.warpWaste;
        const reedWidthInch = reedWidthCm / 2.54;
        const totalEnds = Math.ceil(reedWidthInch * settings.epi);
        const finLengthInch = prodSettings.finishedLength * 39.37;
        const totalPicks = Math.ceil(finLengthInch * settings.ppi);

        const getRatios = (patternStr: string) => {
            const counts: {[k:string]:number} = {};
            const parsed = parsePatternString(patternStr, {A:'A',B:'B',C:'C',D:'D',E:'E',F:'F',G:'G',H:'H'});
            if (parsed.length === 0) return {};
            parsed.forEach(c => counts[c] = (counts[c] || 0) + 1);
            const patLen = parsed.length;
            const ratios: {[k:string]:number} = {};
            Object.keys(counts).forEach(k => ratios[k] = counts[k] / patLen);
            return ratios;
        };

        const warpRatios = getRatios(warpPatternString);
        const weftRatios = getRatios(weftPatternString);

        const yarnRequirements: {
            id: string; type: 'warp' | 'weft'; def: YarnDefinition; 
            endsOrPicks: number; totalMeters: number; weightKg: number; cost: number;
            packages: number; 
        }[] = [];

        let totalWeightKg = 0;
        let totalMaterialCost = 0;

        Object.keys(warpYarns).forEach(key => {
            if (warpRatios[key]) {
                const ends = Math.ceil(totalEnds * warpRatios[key]);
                const meters = ends * totalWarpLengthM;
                const phys = calculateYarnPhysics(warpYarns[key]);
                const weightKg = (meters * phys.tex) / 1000000; 
                const cost = weightKg * (warpYarns[key].price || 0);
                yarnRequirements.push({
                    id: key, type: 'warp', def: warpYarns[key],
                    endsOrPicks: ends, totalMeters: meters, weightKg, cost,
                    packages: 1 
                });
                totalWeightKg += weightKg;
                totalMaterialCost += cost;
            }
        });

        const weftLenPerPickM = (reedWidthCm / 100) * (1 + (prodSettings.weftWaste / 100));
        Object.keys(weftYarns).forEach(key => {
            if (weftRatios[key]) {
                const picks = Math.ceil(totalPicks * weftRatios[key]);
                const meters = picks * weftLenPerPickM;
                const phys = calculateYarnPhysics(weftYarns[key]);
                const weightKg = (meters * phys.tex) / 1000000;
                const cost = weightKg * (weftYarns[key].price || 0);
                const bobbins = Math.ceil(meters / Math.max(1, prodSettings.metersPerPirn));
                yarnRequirements.push({
                    id: key, type: 'weft', def: weftYarns[key],
                    endsOrPicks: picks, totalMeters: meters, weightKg, cost,
                    packages: bobbins
                });
                totalWeightKg += weightKg;
                totalMaterialCost += cost;
            }
        });

        const finishedSqM = (prodSettings.finishedWidth / 100) * prodSettings.finishedLength;
        const gsm = finishedSqM > 0 ? (totalWeightKg * 1000) / finishedSqM : 0;
        const glm = prodSettings.finishedLength > 0 ? (totalWeightKg * 1000) / prodSettings.finishedLength : 0;

        const warpAvgTex = yarnRequirements.filter(y=>y.type==='warp').reduce((a,b) => a + calculateYarnPhysics(b.def).tex, 0) / Math.max(1, Object.keys(warpRatios).length);
        const weftAvgTex = yarnRequirements.filter(y=>y.type==='weft').reduce((a,b) => a + calculateYarnPhysics(b.def).tex, 0) / Math.max(1, Object.keys(weftRatios).length);
        const warpCover = settings.epi * (Math.sqrt(warpAvgTex) / 28); 
        const weftCover = settings.ppi * (Math.sqrt(weftAvgTex) / 28); 
        const coverFactor = warpCover + weftCover;

        const heddleCounts: number[] = new Array(settings.harnesses).fill(0);
        const draftWidth = (draft && draft[0]) ? draft[0].length : 0;
        if (draftWidth > 0) {
            for (let i = 0; i < totalEnds; i++) {
                const draftCol = i % draftWidth;
                for (let h = 0; h < settings.harnesses; h++) {
                    if (draft[h] && draft[h][draftCol]) heddleCounts[h]++;
                }
            }
        }

        const actualPPM = prodSettings.loomSpeed * (prodSettings.efficiency / 100);
        const weavingMinutes = totalPicks / Math.max(0.001, actualPPM);
        const weavingHours = weavingMinutes / 60;
        const totalHours = weavingHours + prodSettings.setupTime;
        const laborCost = totalHours * prodSettings.hourlyRate;
        const totalProjectCost = totalMaterialCost + laborCost;

        return {
            reedWidthCm, totalWarpLengthM, totalEnds, totalPicks,
            yarnRequirements, totalWeightKg, totalMaterialCost,
            gsm, glm, coverFactor, heddleCounts, weavingHours,
            totalHours, laborCost, totalProjectCost
        };
    }, [prodSettings, settings, warpYarns, weftYarns, warpPatternString, weftPatternString, draft]);

    const handlePrint = () => {
        const doc = new jsPDF();
        const pageWidth = doc.internal.pageSize.getWidth();
        const pageHeight = doc.internal.pageSize.getHeight();
        const margin = 15;
        let y = 20;

        const checkPageBreak = (neededHeight: number) => {
            if (y + neededHeight > pageHeight - margin) {
                doc.addPage();
                y = 20;
            }
        };

        doc.setFontSize(22);
        doc.text("Loom Ticket", margin, y);
        y += 8;
        doc.setFontSize(10);
        const headerInfo = [`Client: ${prodSettings.clientName || 'Internal'}`, `Order: ${prodSettings.orderNumber || 'N/A'}`, `Loom: ${prodSettings.loomId || 'Unassigned'}`, `Weaver: ${prodSettings.weaverName || 'Unassigned'}`, `Date: ${new Date().toLocaleDateString()}`];
        let xPos = margin;
        headerInfo.forEach((info, i) => {
            if (i === 3) { xPos = margin; y += 6; }
            doc.text(info, xPos, y);
            xPos += 60;
        });
        y += 10;
        doc.line(margin, y, 210-margin, y);
        y += 10;

        doc.setFontSize(12);
        doc.setFont("helvetica", "bold");
        doc.text("Production Parameters", margin, y);
        y += 6;
        const dimData = [
            ['Finished Width', `${prodSettings.finishedWidth} cm`, 'Finished Length', `${prodSettings.finishedLength} m`],
            ['Reed Width', `${calculations.reedWidthCm.toFixed(1)} cm`, 'Warp Length', `${calculations.totalWarpLengthM.toFixed(1)} m`],
            ['Warp Crimp', `${prodSettings.warpTakeUp}%`, 'Weft Shrink', `${prodSettings.weftContraction}%`],
            ['Total Ends', `${calculations.totalEnds}`, 'Total Picks', `${calculations.totalPicks}`],
            ['GSM', `${Math.round(calculations.gsm)} g/m²`, 'Linear Wt', `${Math.round(calculations.glm)} g/m`]
        ];
        autoTable(doc, { startY: y, body: dimData, theme: 'grid', styles: { fontSize: 9, cellPadding: 1.5 }, margin: { left: margin, right: margin } });
        y = (doc as any).lastAutoTable.finalY + 10;

        const matBody = calculations.yarnRequirements.map(y => [
            y.type.toUpperCase(), y.id, `${y.def.ply}/${y.def.count} ${y.def.countSystem} ${y.def.fiberType}`, y.def.color, `${Math.ceil(y.totalMeters).toLocaleString()} m`, y.type === 'weft' ? `${y.packages}` : '-', `${y.weightKg.toFixed(3)} kg`, ticketConfig.showCosting ? `${prodSettings.priceCurrency}${y.cost.toFixed(2)}` : '-'
        ]);

        if (ticketConfig.showYarns && matBody.length > 0) {
            checkPageBreak(60);
            doc.setFontSize(12);
            doc.text("Material Requirements", margin, y);
            y += 6;
            autoTable(doc, {
                startY: y,
                head: [['Type', 'ID', 'Description', 'Color', 'Length', 'Pirns/Pkg', 'Weight', 'Cost']],
                body: matBody,
                theme: 'striped',
                styles: { fontSize: 9 },
                didDrawCell: (data: any) => {
                    if (data.section === 'body' && data.column.index === 3) {
                        const rowData = matBody[data.row.index];
                        if (rowData && rowData[3]) {
                            doc.setFillColor(rowData[3] as string);
                            doc.rect(data.cell.x + 2, data.cell.y + 2, 4, 4, 'FD');
                        }
                    }
                },
                margin: { left: margin, right: margin }
            });
            y = (doc as any).lastAutoTable.finalY + 10;
        }

        if (ticketConfig.showCosting) {
            checkPageBreak(40);
            doc.setFontSize(12);
            doc.text("Time & Cost Estimation", margin, y);
            y += 6;
            const costData = [
                ['Setup Time', `${prodSettings.setupTime} hrs`, 'Hourly Rate', `${prodSettings.priceCurrency}${prodSettings.hourlyRate}`],
                ['Weaving Time', `${calculations.weavingHours.toFixed(1)} hrs`, 'Labor Cost', `${prodSettings.priceCurrency}${calculations.laborCost.toFixed(2)}`],
                ['Total Time', `${calculations.totalHours.toFixed(1)} hrs`, 'Material Cost', `${prodSettings.priceCurrency}${calculations.totalMaterialCost.toFixed(2)}`],
                ['', '', 'TOTAL COST', `${prodSettings.priceCurrency}${calculations.totalProjectCost.toFixed(2)}`]
            ];
            autoTable(doc, { startY: y, body: costData, theme: 'grid', styles: { fontSize: 9 }, columnStyles: { 3: { fontStyle: 'bold' } }, margin: { left: margin, right: margin } });
            y = (doc as any).lastAutoTable.finalY + 10;
        }

        doc.save("mill-ticket.pdf");
    };

    return (
        <div className="flex flex-col h-full bg-white">
            <div className="p-4 border-b border-gray-200 flex justify-between items-center bg-gray-50">
                <div>
                    <h2 className="text-xl font-bold text-gray-800">Production Engine</h2>
                    <p className="text-xs text-gray-500">Commercial costing and mill ticket generation.</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={handlePrint} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg shadow-sm font-bold text-xs transition-colors"><PrinterIcon className="w-4 h-4" /> Print Ticket</button>
                </div>
            </div>

            <div className="flex flex-1 overflow-hidden">
                <div className="w-80 border-r border-gray-200 overflow-y-auto custom-scrollbar p-6 bg-white">
                    <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest mb-4">Order Details</h3>
                    <div className="space-y-3 mb-6">
                        <div>
                            <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Client / Project</label>
                            <input type="text" value={prodSettings.clientName} onChange={e => setProdSettings({...prodSettings, clientName: e.target.value})} className="w-full border border-gray-300 rounded p-2 text-sm" />
                        </div>
                    </div>
                    <div className="h-px bg-gray-100 mb-6"></div>
                    <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest mb-4">Loom Setup</h3>
                    <div className="grid grid-cols-2 gap-3 mb-4">
                        <InputRow label="PPM" value={prodSettings.loomSpeed} onChange={v => setProdSettings({...prodSettings, loomSpeed: v})} />
                        <InputRow label="Eff %" value={prodSettings.efficiency} onChange={v => setProdSettings({...prodSettings, efficiency: v})} />
                    </div>
                </div>

                <div className="flex-1 bg-gray-50 overflow-y-auto custom-scrollbar p-8">
                    <div className="grid grid-cols-4 gap-4 mb-8">
                        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200"><span className="text-[10px] font-bold text-gray-400 uppercase">Reed Width</span><div className="text-2xl font-bold text-gray-800 mt-1">{calculations.reedWidthCm.toFixed(1)} cm</div></div>
                        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200"><span className="text-[10px] font-bold text-gray-400 uppercase">Total Weight</span><div className="text-2xl font-bold text-blue-600 mt-1">{calculations.totalWeightKg.toFixed(2)} kg</div></div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useRef } from 'react';
import { LibraryWeave } from '../types';

interface WeaveThumbnailProps {
  weave: LibraryWeave;
  className?: string;
  faceMode?: 'face' | 'back';
  showGrid?: boolean;
  tile?: boolean;
  forceScale?: number;
}

export const WeaveThumbnail: React.FC<WeaveThumbnailProps> = ({ 
    weave, 
    className, 
    faceMode = 'face', 
    showGrid = false,
    tile = false,
    forceScale
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !weave || !weave.draft) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { draft, pegPlan } = weave;
    const harnesses = draft.length;
    const unitWidth = (draft[0] && Array.isArray(draft[0])) ? draft[0].length : 0;
    const unitHeight = pegPlan ? pegPlan.length : 0;

    if (unitWidth === 0 || unitHeight === 0) return;

    // Determine scale and dimensions
    const scale = forceScale || Math.min(16, Math.floor(160 / Math.max(unitWidth, unitHeight)));

    // In tiling mode, we fill a standard container size
    const drawWidth = tile ? 160 : unitWidth * scale;
    const drawHeight = tile ? 160 : unitHeight * scale;

    canvas.width = drawWidth;
    canvas.height = drawHeight;

    ctx.imageSmoothingEnabled = false;

    // Background
    ctx.fillStyle = '#0a0a0a'; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const warpToHarness = new Array(unitWidth).fill(-1);
    for(let w=0; w<unitWidth; w++) {
        for(let h=0; h<harnesses; h++) {
            if(draft[h] && draft[h][w] === 1) {
                warpToHarness[w] = h;
                break;
            }
        }
    }

    // Render cells
    const colsToDraw = Math.ceil(canvas.width / scale);
    const rowsToDraw = Math.ceil(canvas.height / scale);

    for(let y=0; y<rowsToDraw; y++) {
        for(let x=0; x<colsToDraw; x++) {
            const unitX = x % unitWidth;
            const unitY = y % unitHeight;
            const harness = warpToHarness[unitX];

            let isWarpUp = false;
            if(harness !== -1 && pegPlan[unitY] && pegPlan[unitY][harness] === 1) {
                isWarpUp = true;
            }

            if (faceMode === 'back') isWarpUp = !isWarpUp;

            if (isWarpUp) {
                ctx.fillStyle = '#ffffff'; // Pure white for warp
                ctx.fillRect(x*scale, y*scale, scale, scale);
            }
        }
    }

    if (showGrid) {
        ctx.strokeStyle = 'rgba(255,255,255,0.4)';
        ctx.lineWidth = 1;
        for(let i=0; i<=colsToDraw; i++) {
            ctx.beginPath();
            ctx.moveTo(i*scale, 0); ctx.lineTo(i*scale, canvas.height);
            ctx.stroke();
        }
        for(let i=0; i<=rowsToDraw; i++) {
            ctx.beginPath();
            ctx.moveTo(0, i*scale); ctx.lineTo(canvas.width, i*scale);
            ctx.stroke();
        }
    }

  }, [weave, faceMode, showGrid, tile, forceScale]);

  return (
    <div className={`bg-gray-950 rounded-lg border border-gray-800 flex items-center justify-center overflow-hidden transition-all duration-300 ${className}`}>
        <canvas ref={canvasRef} className="max-w-full max-h-full block shadow-inner" style={{ imageRendering: 'pixelated' }} />
    </div>
  );
};

