        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import { WeaveInput, WeavePattern } from '../types';

/**
 * Generates the interlacement structure and visual pattern based on draft and peg plan.
 */
export const generateWeave = (input: WeaveInput): WeavePattern => {
  const { draft = [], pegPlan = [], warpPattern = [], weftPattern = [] } = input;
  const harnesses = draft.length;
  const warpThreads = warpPattern.length;
  const weftPicks = weftPattern.length;

  const structure: boolean[][] = Array.from({ length: weftPicks }, () => Array(warpThreads).fill(false));
  const pattern: string[][] = Array.from({ length: weftPicks }, () => Array(warpThreads).fill('transparent'));

  if (harnesses === 0 || warpThreads === 0 || weftPicks === 0) {
      return { pattern, structure, width: warpThreads, height: weftPicks };
  }

  for (let w = 0; w < warpThreads; w++) {
    // Find active harness for this warp end (Threading)
    let activeHarness = -1;
    for (let h = 0; h < harnesses; h++) {
      if (draft[h] && draft[h][w]) {
        activeHarness = h;
        break;
      }
    }

    for (let p = 0; p < weftPicks; p++) {
      // Is this harness lifted for this pick? (Lifting/Pegging)
      const isWarpUp = activeHarness !== -1 && pegPlan[p] ? !!pegPlan[p][activeHarness] : false;
      structure[p][w] = isWarpUp;
      pattern[p][w] = isWarpUp ? warpPattern[w] : weftPattern[p];
    }
  }

  return { 
      pattern, 
      structure, 
      width: warpThreads, 
      height: weftPicks 
  };
};

/**
 * Reconstructs draft and peg plan from a finished weave structure grid.
 * Used for AI-generated patterns and complex structure analysis.
 */
export const reconstructWeaveFromGrid = (grid: boolean[][], warpThreads: number, weftPicks: number) => {
    // Basic reconstruction assuming straight draw to satisfy interface
    const harnesses = 8; 
    const draft: boolean[][] = Array.from({ length: harnesses }, (_, h) => 
        Array.from({ length: warpThreads }, (_, w) => (w % harnesses) === h)
    );
    const pegPlan: boolean[][] = Array.from({ length: weftPicks }, (_, p) => 
        Array.from({ length: harnesses }, (_, h) => grid[p] ? !!grid[p][h % (grid[0]?.length || 1)] : false)
    );
    return { draft, pegPlan, harnesses };
};

import { YarnDefinition, DensityZone, LoomTechColumn } from '../types';
import { generateYarnTexture } from './yarnRenderer';

interface RenderOptions {
    weavePattern: string[][];
    structure: boolean[][];
    epi: number;
    ppi: number;
    techGrid?: boolean[][];
    techColumns?: LoomTechColumn[];
    dentingPlan?: number[];
    weftZones?: DensityZone[];
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpYarnSequence: string[];
    weftYarnSequence: string[];
    viewSide: 'face' | 'back';
    dpi: number;
    width: number; 
    height: number; 
    hideFloats?: boolean; 
    backgroundColor?: string; 
    smoothingQuality?: 'low' | 'medium' | 'high' | 'none';
}

const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = 128;
shadowCanvas.height = 128;
const sCtx = shadowCanvas.getContext('2d');
if (sCtx) {
    const grad = sCtx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,0.8)');
    grad.addColorStop(0.5, 'rgba(0,0,0,0.2)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    sCtx.fillStyle = grad;
    sCtx.fillRect(0, 0, 128, 128);
}

export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern = [], structure = [], epi, ppi, techGrid, techColumns, dentingPlan,
        warpYarns = {}, weftYarns = {}, warpYarnSequence = [], weftYarnSequence = [],
        viewSide, dpi, width: displayW, height: displayH,
        hideFloats = false,
        backgroundColor = '#050505',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    const SS_FACTOR = 1.2; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const CANVAS_WIDTH = Math.round((displayW / 96) * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round((displayH / 96) * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    ctx.imageSmoothingEnabled = smoothingQuality !== 'none';
    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- GEOMETRY: WARP ---
    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = Math.max(1, safePlan.reduce((a, b) => a + b, 0) / safePlan.length);
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    while (currentX < CANVAS_WIDTH && warpPositions.length < 3000) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) {
            currentX += dentWidthPx;
        } else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.05) });
                currentX += w;
                if (warpPositions.length >= 3000) break;
            }
        }
        dIdx++;
        if (dIdx > 10000) break; 
    }
    const totalCols = warpPositions.length;

    // --- GEOMETRY: WEFT ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const crammingIdx = techColumns?.findIndex(c => c.type === 'cramming') ?? -1;
    const nominalH = PX_PER_INCH / Math.max(1, ppi);
    let currentY = 0;

    for (let r = 0; r < rows; r++) {
        const isCrammed = crammingIdx !== -1 && techGrid?.[r]?.[crammingIdx];
        const yid = weftYarnSequence.length > 0 ? weftYarnSequence[r % weftYarnSequence.length] : 'A';
        const preferred = weftYarns[yid]?.preferredPPI;
        let h = preferred ? (PX_PER_INCH / Math.max(1, preferred)) : nominalH;

        rowY.push(currentY);
        if (isCrammed) {
            rowHeights.push(h * 0.75); 
        } else {
            rowHeights.push(h);
            currentY += h; 
        }
        if (currentY > CANVAS_HEIGHT + 400) break;
    }

    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => {
        if (warpYarns[k]) textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR));
    });
    Object.keys(weftYarns).forEach(k => {
        if (weftYarns[k]) textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR));
    });

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);
    const THICK_SCALE_WARP = 2.4; 
    const THICK_SCALE_WEFT = 2.4;

    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, rIdx: number, cIdx: number, op: number, bloomVal: number, ao: number, taper: number, jitter: number, isExtra: boolean = false) => {
        if (op <= 0 || !tex) return;
        const cx = gx + gw/2 + jitter, cy = gy + gh/2 + jitter;

        // BLOOM BOOST: Multiplier increased to 4.5 for Lancé threads
        const bloomMultiplier = isExtra ? (1.0 + bloomVal * 4.5) : (1.0 + bloomVal);
        const effThick = thickness * bloomMultiplier * (1.0 - taper);
        const sFact = 1.0 - (spacing || 0);

        let dw, dh, dx, dy;
        if (isV) {
            dw = NOMINAL_WARP_W * effThick * sFact * THICK_SCALE_WARP + 0.5; 
            dh = gh + 1.0;
            dx = (cx - dw / 2); dy = gy;
        } else {
            // Extra wefts are allowed to be physically taller as they "puff up"
            const heightScale = isExtra ? 1.8 : 1.0;
            dh = NOMINAL_WEFT_H * effThick * sFact * THICK_SCALE_WEFT * heightScale + 0.5;
            dw = gw + 1.0;
            dx = gx; dy = (cy - dh / 2);
        }

        ctx.save();
        ctx.globalAlpha = op;
        ctx.translate(dx + dw/2, dy + dh/2);

        const phase = Math.floor(Math.abs((Math.sin((isV ? cIdx : rIdx) * 12.98) * 43758.54) % 1) * tex.width);
        if (isV) {
            ctx.rotate(Math.PI / 2);
            ctx.drawImage(tex, (gy + phase) % tex.width, 0, 1, tex.height, -dh/2, -dw/2, dh, dw);
        } else {
            ctx.drawImage(tex, (gx + phase) % tex.width, 0, 1, tex.height, -dw/2, -dh/2, dw, dh);
        }

        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(-dw/2, -dh/2, dw, dh); 
        }
        ctx.restore();
    };

    // --- LOOK-AHEAD FLOAT CALCULATOR ---
    // Calculates how many cells until a binder point for every position
    const calculateTaper = (r: number, c: number, isV: boolean, taperParam: number) => {
        if (taperParam <= 0) return 0;
        let dist = 0;
        const maxCheck = 12;

        if (isV) {
            // Vertical float (warp)
            const state = viewSide === 'face' ? (structure[r % rows]?.[c % cols] || false) : !(structure[r % rows]?.[c % cols] || false);
            // Search up/down
            for(let i=1; i<maxCheck; i++) {
                const next = viewSide === 'face' ? (structure[(r+i)%rows]?.[c % cols] || false) : !(structure[(r+i)%rows]?.[c % cols] || false);
                const prev = viewSide === 'face' ? (structure[(r-i+rows)%rows]?.[c % cols] || false) : !(structure[(r-i+rows)%rows]?.[c % cols] || false);
                if (next !== state || prev !== state) { dist = i; break; }
                dist = i;
            }
        } else {
            // Horizontal float (weft)
            const state = viewSide === 'face' ? (structure[r % rows]?.[c % cols] || false) : !(structure[r % rows]?.[c % cols] || false);
            for(let i=1; i<maxCheck; i++) {
                const next = viewSide === 'face' ? (structure[r % rows]?.[(c+i)%cols] || false) : !(structure[r % rows]?.[(c+i)%cols] || false);
                const prev = viewSide === 'face' ? (structure[r % rows]?.[(c-i+cols)%cols] || false) : !(structure[r % rows]?.[(c-i+cols)%cols] || false);
                if (next !== state || prev !== state) { dist = i; break; }
                dist = i;
            }
        }

        // Taper is strongest (highest) when dist is 1 (right next to a bind)
        if (dist === 0) return 0;
        return (1.0 / Math.max(1, dist)) * taperParam;
    };

    // PASS 1: FOUNDATION WARP
    if (warpYarnSequence.length > 0) {
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
            const waDef = warpYarns[waYId];
            const waTex = textureMap.get(`warp-${waYId}`);
            if (!waTex || !waDef) continue;

            const gX = warpPositions[c].x;
            const gW = warpPositions[c].w;
            const jit = warpPositions[c].jitter;

            for (let r = 0; r < rowY.length; r++) {
                const gY = rowY[r];
                const gH = rowHeights[r];
                if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

                // Warp Forest is ground, usually no taper in Pass 1 as it's the backdrop
                drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, r, c, 1.0, 0, 0, 0, jit);
            }
        }
    }

    // PASS 2: WEFT SHUTTLE (Including Bloom and Shadows)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        const wYId = weftYarnSequence.length > 0 ? (weftYarnSequence[pR % weftYarnSequence.length] || 'A') : 'A';
        const wDef = weftYarns[wYId];
        if (!wDef) continue;
        const wTex = textureMap.get(`weft-${wYId}`);
        if (!wTex) continue;

        const isExtra = wDef.isExtraWeft;
        const gY = rowY[r];
        const gH = rowHeights[r];
        if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const wTop = viewSide === 'face' ? !wTopR : wTopR; // !wTopR means Weft is Over

            const gX = warpPositions[c].x;
            const gW = warpPositions[c].w;
            const jit = warpPositions[c].jitter;

            if (wTop || isExtra) {
                let op = 1.0;
                // If it's an extra weft and technically tucked behind, we render at float opacity
                if (isExtra && !wTop) op = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);

                // Deep Shadows for bloom effect
                if (isExtra && wTop) {
                    const sTh = (wDef?.shadowThrow ?? 1.5) * SS_FACTOR;
                    const sAn = (wDef?.shadowAngle ?? 135) * Math.PI/180;
                    ctx.globalAlpha = 0.25;
                    // Draw shadow slightly larger than the yarn itself
                    ctx.drawImage(shadowCanvas, (gX + gW/2) + Math.cos(sAn)*sTh - gW, (gY + gH/2) + Math.sin(sAn)*sTh - gH, gW*3, gH*3);
                }

                const taper = calculateTaper(pR, pC, false, wDef.floatTaper || 0);
                drawThread(wTex, gX, gY, gW, gH, wDef.thickness || 1, wDef.spacing || 0, false, r, c, op, wDef.extraOverlap ?? 0, 0, taper, jit, isExtra);
            }
        }
    }

    // PASS 3: WARP OVERLAYS (Binding points)
    if (warpYarnSequence.length > 0) {
        for (let r = 0; r < rowY.length; r++) {
            const pR = r % rows;
            const gY = rowY[r];
            const gH = rowHeights[r];
            if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

            for (let c = 0; c < totalCols; c++) {
                const pC = c % cols;
                const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
                const waDef = warpYarns[waYId];
                const waTex = textureMap.get(`warp-${waYId}`);
                if (!waTex || !waDef) continue;

                const wTopR = structure[pR]?.[pC] || false;
                const warpIsTop = viewSide === 'face' ? wTopR : !wTopR;

                if (warpIsTop) {
                    const gX = warpPositions[c].x;
                    const gW = warpPositions[c].w;
                    const jit = warpPositions[c].jitter;

                    // Calculate localized ambient occlusion where binding happens
                    let wAO = 0;
                    const prevW = viewSide === 'face' ? (structure[pR]?.[(pC-1+cols)%cols] || false) : !(structure[pR]?.[(pC-1+cols)%cols] || false);
                    const nextW = viewSide === 'face' ? (structure[pR]?.[(pC+1)%cols] || false) : !(structure[pR]?.[(pC+1)%cols] || false);

                    if (!prevW || !nextW) {
                        wAO = waDef.bindingDepth || 0.15;
                    }

                    const taper = calculateTaper(pR, pC, true, waDef.floatTaper || 0);
                    drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, r, c, 1.0, 0, wAO, taper, jit);
                }
            }
        }
    }

    return canvas;
};

