        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import { YarnDefinition, DensityZone, LoomTechColumn } from '../types';
import { generateYarnTexture } from './yarnRenderer';

interface RenderOptions {
    weavePattern: string[][];
    structure: boolean[][];
    epi: number;
    ppi: number;
    techGrid?: boolean[][];
    techColumns?: LoomTechColumn[];
    dentingPlan?: number[];
    weftZones?: DensityZone[];
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpYarnSequence: string[];
    weftYarnSequence: string[];
    viewSide: 'face' | 'back';
    dpi: number;
    width: number; 
    height: number; 
    hideFloats?: boolean; 
    backgroundColor?: string; 
    smoothingQuality?: 'low' | 'medium' | 'high' | 'none';
}

const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = 128;
shadowCanvas.height = 128;
const sCtx = shadowCanvas.getContext('2d');
if (sCtx) {
    const grad = sCtx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,1.0)'); 
    grad.addColorStop(0.7, 'rgba(0,0,0,0.5)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    sCtx.fillStyle = grad;
    sCtx.fillRect(0, 0, 128, 128);
}

export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern = [], structure = [], epi, ppi, techGrid, techColumns, dentingPlan,
        warpYarns = {}, weftYarns = {}, warpYarnSequence = [], weftYarnSequence = [],
        viewSide, dpi, width: displayW, height: displayH,
        hideFloats = false,
        backgroundColor = '#050508',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    const SS_FACTOR = 1.25; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const CANVAS_WIDTH = Math.round((displayW / 96) * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round((displayH / 96) * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    ctx.imageSmoothingEnabled = smoothingQuality !== 'none';
    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- GEOMETRY: WARP ---
    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = Math.max(1, safePlan.reduce((a, b) => a + b, 0) / safePlan.length);
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    while (currentX < CANVAS_WIDTH && warpPositions.length < 3000) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) {
            currentX += dentWidthPx;
        } else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.1) });
                currentX += w;
                if (warpPositions.length >= 3000) break;
            }
        }
        dIdx++;
        if (dIdx > 10000) break; 
    }
    const totalCols = warpPositions.length;

    // --- GEOMETRY: WEFT ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const nominalH = PX_PER_INCH / Math.max(1, ppi);
    let currentY = 0;

    for (let r = 0; r < rows; r++) {
        const yid = weftYarnSequence.length > 0 ? weftYarnSequence[r % weftYarnSequence.length] : 'A';
        const preferred = weftYarns[yid]?.preferredPPI;
        let h = preferred ? (PX_PER_INCH / Math.max(1, preferred)) : nominalH;
        rowY.push(currentY);
        rowHeights.push(h);
        currentY += h; 
        if (currentY > CANVAS_HEIGHT + 400) break;
    }

    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => {
        if (warpYarns[k]) textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR));
    });
    Object.keys(weftYarns).forEach(k => {
        if (weftYarns[k]) textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR));
    });

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);

    /**
     * DRAW THREAD: RE-ENGINEERED FOR PACKED COVERAGE
     */
    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, op: number, bloomVal: number, ao: number, taper: number, isExtra: boolean = false) => {
        if (op <= 0 || !tex) return;

        // PHYSICAL BLOOM (Super-Saturation logic)
        // Global multiplier (2.6) ensures ground coverage. 
        // Extra Bloom (up to 3.5x for Extra Weft) creates the packed swivel effect.
        const baseMultiplier = 2.6; 
        let effThick = thickness * baseMultiplier;

        if (isExtra && bloomVal > 0.0) {
            // Aggressive expansion for Lancé yarns to exceed pick height
            effThick *= (1.0 + bloomVal * 3.5); 
        }

        const taperMod = 1.0 - taper;

        let dw, dh, dx, dy;
        if (isV) {
            dw = NOMINAL_WARP_W * effThick * (1.0 - (spacing || 0)) * taperMod; 
            dh = gh + 1.5;
            dx = gx + gw/2 - dw/2; dy = gy;
        } else {
            // For weft, dh is the screen height (lateral spread)
            // baseH is the pick height. We multiply this by effThick to exceed neighbors.
            const baseH = gh; 
            dh = baseH * effThick * (1.0 - (spacing || 0)) * taperMod;
            dw = gw + 1.5;
            dx = gx; dy = gy + gh/2 - dh/2;
        }

        ctx.save();
        ctx.globalAlpha = op;
        const phase = Math.floor((Math.abs(Math.sin((isV ? gx : gy) * 997.1)) * 3000) % tex.width);

        if (isV) {
            ctx.translate(dx + dw/2, dy + dh/2);
            ctx.rotate(Math.PI / 2);
            ctx.drawImage(tex, (gy + phase) % tex.width, 0, 1, tex.height, -dh/2, -dw/2, dh, dw);
        } else {
            ctx.drawImage(tex, (gx + phase) % tex.width, 0, 1, tex.height, dx, dy, dw, dh);
        }

        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(dx, dy, dw, dh); 
        }

        // Edge "Lancé Lift" Highlight
        if (isExtra && op > 0.6) {
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 1;
            if(!isV) { ctx.beginPath(); ctx.moveTo(dx, dy); ctx.lineTo(dx+dw, dy); ctx.stroke(); }
        }
        ctx.restore();
    };

    /**
     * TAPER CALCULATOR
     * Using Sinusoidal easing for smooth "bulge" in float centers.
     */
    const calculateTaper = (r: number, c: number, isV: boolean, taperParam: number) => {
        if (taperParam <= 0) return 0;
        let dist = 100;
        const maxCheck = 24;
        const state = viewSide === 'face' ? (structure[r % rows]?.[c % cols] || false) : !(structure[r % rows]?.[c % cols] || false);

        if (isV) {
            for(let i=1; i<maxCheck; i++) {
                const n = viewSide === 'face' ? (structure[(r+i)%rows]?.[c % cols] || false) : !(structure[(r+i)%rows]?.[c % cols] || false);
                const p = viewSide === 'face' ? (structure[(r-i+rows)%rows]?.[c % cols] || false) : !(structure[(r-i+rows)%rows]?.[c % cols] || false);
                if (n !== state || p !== state) { dist = i; break; }
            }
        } else {
            for(let i=1; i<maxCheck; i++) {
                const n = viewSide === 'face' ? (structure[r % rows]?.[(c+i)%cols] || false) : !(structure[r % rows]?.[(c+i)%cols] || false);
                const p = viewSide === 'face' ? (structure[r % rows]?.[(c-i+cols)%cols] || false) : !(structure[r % rows]?.[(c-i+cols)%cols] || false);
                if (n !== state || p !== state) { dist = i; break; }
            }
        }

        if (dist >= maxCheck) return 0;
        const falloff = 5.0;
        const intensity = Math.max(0, (falloff - dist) / falloff);
        const sineWave = Math.sin(intensity * Math.PI / 2);
        return sineWave * taperParam * 0.5; // Reduced factor for stability
    };

    // PASS 1: GROUND WARP (Foundation)
    for (let c = 0; c < totalCols; c++) {
        const waYId = warpYarnSequence[c % warpYarnSequence.length] || 'A';
        const waDef = warpYarns[waYId];
        const waTex = textureMap.get(`warp-${waYId}`);
        if (!waTex || !waDef) continue;
        const gX = warpPositions[c].x, gW = warpPositions[c].w;
        for (let r = 0; r < rowY.length; r++) {
            const gY = rowY[r], gH = rowHeights[r];
            if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;
            // Full opacity for Pass 1 to prevent black bleed
            drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, 1.0, 0, 0, 0);
        }
    }

    // PASS 2: WEFT PICKS (Ground & Bloom Lancé)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
        const wDef = weftYarns[wYId];
        const wTex = textureMap.get(`weft-${wYId}`);
        if (!wDef || !wTex) continue;

        const isExtra = wDef.isExtraWeft;
        const gY = rowY[r], gH = rowHeights[r];
        if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            // Structure check: If Weft is OVER Warp
            const wTop = viewSide === 'face' ? !wTopR : wTopR; 

            if (wTop || isExtra) {
                const gX = warpPositions[c].x, gW = warpPositions[c].w;
                let op = 1.0;
                if (isExtra && !wTop) op = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);

                // Shadows for Blooms
                if (isExtra && wTop) {
                    const sTh = (wDef?.shadowThrow ?? 1.5) * SS_FACTOR;
                    const sAn = (wDef?.shadowAngle ?? 135) * Math.PI/180;
                    ctx.globalAlpha = 0.6 * (wDef.extraOverlap || 1.0);
                    // Drop shadow slightly larger to simulate depth
                    ctx.drawImage(shadowCanvas, (gX + gW/2) + Math.cos(sAn)*sTh - gW*4, (gY + gH/2) + Math.sin(sAn)*sTh - gH*4, gW*9, gH*9);
                }

                const taper = calculateTaper(pR, pC, false, wDef.floatTaper || 0);
                drawThread(wTex, gX, gY, gW, gH, wDef.thickness || 1, wDef.spacing || 0, false, op, wDef.extraOverlap ?? 0, 0, taper, isExtra);
            }
        }
    }

    // PASS 3: WARP OVERLAYS (Tie-up points)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const waYId = warpYarnSequence[c % warpYarnSequence.length] || 'A';
            const waDef = warpYarns[waYId];
            const waTex = textureMap.get(`warp-${waYId}`);
            if (!waTex || !waDef) continue;

            const wTopR = structure[pR]?.[pC] || false;
            const warpIsTop = viewSide === 'face' ? wTopR : !wTopR;

            if (warpIsTop) {
                const gX = warpPositions[c].x, gW = warpPositions[c].w, gY = rowY[r], gH = rowHeights[r];
                if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

                let wAO = 0;
                // Check neighbors for localized ambient occlusion (at binding sites)
                const prevW = viewSide === 'face' ? (structure[pR]?.[(pC-1+cols)%cols] || false) : !(structure[pR]?.[(pC-1+cols)%cols] || false);
                const nextW = viewSide === 'face' ? (structure[pR]?.[(pC+1)%cols] || false) : !(structure[pR]?.[(pC+1)%cols] || false);
                if (!prevW || !nextW) wAO = (waDef.bindingDepth || 0.15) * 2.0;

                const taper = calculateTaper(pR, pC, true, waDef.floatTaper || 0);
                drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, 1.0, 0, wAO, taper);
            }
        }
    }

    return canvas;
};

import { YarnDefinition, DensityZone, LoomTechColumn } from '../types';
import { generateYarnTexture } from './yarnRenderer';

interface RenderOptions {
    weavePattern: string[][];
    structure: boolean[][];
    epi: number;
    ppi: number;
    techGrid?: boolean[][];
    techColumns?: LoomTechColumn[];
    dentingPlan?: number[];
    weftZones?: DensityZone[];
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpYarnSequence: string[];
    weftYarnSequence: string[];
    viewSide: 'face' | 'back';
    dpi: number;
    width: number; 
    height: number; 
    hideFloats?: boolean; 
    backgroundColor?: string; 
    smoothingQuality?: 'low' | 'medium' | 'high' | 'none';
}

const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = 128;
shadowCanvas.height = 128;
const sCtx = shadowCanvas.getContext('2d');
if (sCtx) {
    const grad = sCtx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,0.8)'); 
    grad.addColorStop(0.7, 'rgba(0,0,0,0.3)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    sCtx.fillStyle = grad;
    sCtx.fillRect(0, 0, 128, 128);
}

export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern = [], structure = [], epi, ppi, techGrid, techColumns, dentingPlan,
        warpYarns = {}, weftYarns = {}, warpYarnSequence = [], weftYarnSequence = [],
        viewSide, dpi, width: displayW, height: displayH,
        hideFloats = false,
        backgroundColor = '#0c0c10',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    const SS_FACTOR = 1.25; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const CANVAS_WIDTH = Math.round((displayW / 96) * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round((displayH / 96) * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    ctx.imageSmoothingEnabled = smoothingQuality !== 'none';
    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- GEOMETRY: WARP ---
    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = Math.max(1, safePlan.reduce((a, b) => a + b, 0) / safePlan.length);
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    while (currentX < CANVAS_WIDTH && warpPositions.length < 3000) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) {
            currentX += dentWidthPx;
        } else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.05) });
                currentX += w;
                if (warpPositions.length >= 3000) break;
            }
        }
        dIdx++;
        if (dIdx > 10000) break; 
    }
    const totalCols = warpPositions.length;

    // --- GEOMETRY: WEFT ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const nominalH = PX_PER_INCH / Math.max(1, ppi);
    let currentY = 0;

    for (let r = 0; r < rows; r++) {
        const yid = weftYarnSequence.length > 0 ? weftYarnSequence[r % weftYarnSequence.length] : 'A';
        const preferred = weftYarns[yid]?.preferredPPI;
        let h = preferred ? (PX_PER_INCH / Math.max(1, preferred)) : nominalH;
        rowY.push(currentY);
        rowHeights.push(h);
        currentY += h; 
        if (currentY > CANVAS_HEIGHT + 400) break;
    }

    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => {
        if (warpYarns[k]) textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR));
    });
    Object.keys(weftYarns).forEach(k => {
        if (weftYarns[k]) textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR));
    });

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);

    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, op: number, bloomVal: number, ao: number, taper: number, isExtra: boolean = false) => {
        if (op <= 0 || !tex) return;

        // Stabilized Multipliers:
        // baseFactor 2.1 ensures coverage. Bloom is added for Lancé.
        const baseFactor = 2.1;
        let effThick = thickness * baseFactor;

        if (isExtra && bloomVal > 0.0) {
            // Lancé bloom pushes the thread to spread over its neighbors
            effThick *= (1.0 + bloomVal * 0.8);
        }

        const taperMod = 1.0 - taper;

        let dw, dh, dx, dy;
        if (isV) {
            dw = NOMINAL_WARP_W * effThick * (1.0 - (spacing || 0)) * taperMod; 
            dh = gh + 1.2;
            dx = gx + gw/2 - dw/2; dy = gy;
        } else {
            // weft spread
            dh = gh * effThick * (1.0 - (spacing || 0)) * taperMod;
            dw = gw + 1.2;
            dx = gx; dy = gy + gh/2 - dh/2;
        }

        ctx.save();
        ctx.globalAlpha = op;
        const phase = Math.floor((Math.abs(Math.sin((isV ? gx : gy) * 113.7)) * 4000) % tex.width);

        if (isV) {
            ctx.translate(dx + dw/2, dy + dh/2);
            ctx.rotate(Math.PI / 2);
            ctx.drawImage(tex, (gy + phase) % tex.width, 0, 1, tex.height, -dh/2, -dw/2, dh, dw);
        } else {
            ctx.drawImage(tex, (gx + phase) % tex.width, 0, 1, tex.height, dx, dy, dw, dh);
        }

        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(dx, dy, dw, dh); 
        }

        if (isExtra && op > 0.7) {
            ctx.strokeStyle = 'rgba(255,255,255,0.06)';
            ctx.lineWidth = 1;
            if(!isV) { ctx.beginPath(); ctx.moveTo(dx, dy); ctx.lineTo(dx+dw, dy); ctx.stroke(); }
        }
        ctx.restore();
    };

    const calculateTaper = (r: number, c: number, isV: boolean, taperParam: number) => {
        if (taperParam <= 0) return 0;
        let dist = 100;
        const maxCheck = 16;
        const state = viewSide === 'face' ? (structure[r % rows]?.[c % cols] || false) : !(structure[r % rows]?.[c % cols] || false);

        if (isV) {
            for(let i=1; i<maxCheck; i++) {
                const n = viewSide === 'face' ? (structure[(r+i)%rows]?.[c % cols] || false) : !(structure[(r+i)%rows]?.[c % cols] || false);
                const p = viewSide === 'face' ? (structure[(r-i+rows)%rows]?.[c % cols] || false) : !(structure[(r-i+rows)%rows]?.[c % cols] || false);
                if (n !== state || p !== state) { dist = i; break; }
            }
        } else {
            for(let i=1; i<maxCheck; i++) {
                const n = viewSide === 'face' ? (structure[r % rows]?.[(c+i)%cols] || false) : !(structure[r % rows]?.[(c+i)%cols] || false);
                const p = viewSide === 'face' ? (structure[r % rows]?.[(c-i+cols)%cols] || false) : !(structure[r % rows]?.[(c-i+cols)%cols] || false);
                if (n !== state || p !== state) { dist = i; break; }
            }
        }

        if (dist >= maxCheck) return 0;
        const falloff = 4.0;
        const intensity = Math.max(0, (falloff - dist) / falloff);
        return Math.sin(intensity * Math.PI / 2) * taperParam * 0.4;
    };

    // PASS 1: GROUND WARP
    for (let c = 0; c < totalCols; c++) {
        const waYId = warpYarnSequence[c % warpYarnSequence.length] || 'A';
        const waDef = warpYarns[waYId];
        const waTex = textureMap.get(`warp-${waYId}`);
        if (!waTex || !waDef) continue;
        const gX = warpPositions[c].x, gW = warpPositions[c].w;
        for (let r = 0; r < rowY.length; r++) {
            const gY = rowY[r], gH = rowHeights[r];
            if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;
            drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, 1.0, 0, 0, 0);
        }
    }

    // PASS 2: WEFT PICKS
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
        const wDef = weftYarns[wYId];
        const wTex = textureMap.get(`weft-${wYId}`);
        if (!wDef || !wTex) continue;

        const isExtra = wDef.isExtraWeft;
        const gY = rowY[r], gH = rowHeights[r];
        if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const wTop = viewSide === 'face' ? !wTopR : wTopR; 

            if (wTop || isExtra) {
                const gX = warpPositions[c].x, gW = warpPositions[c].w;
                let op = 1.0;
                if (isExtra && !wTop) op = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);

                if (isExtra && wTop) {
                    const sTh = (wDef?.shadowThrow ?? 1.5) * SS_FACTOR;
                    const sAn = (wDef?.shadowAngle ?? 135) * Math.PI/180;
                    ctx.globalAlpha = 0.5 * (wDef.extraOverlap || 1.0);
                    ctx.drawImage(shadowCanvas, (gX + gW/2) + Math.cos(sAn)*sTh - gW*1.5, (gY + gH/2) + Math.sin(sAn)*sTh - gH*1.5, gW*4, gH*4);
                }

                const taper = calculateTaper(pR, pC, false, wDef.floatTaper || 0);
                drawThread(wTex, gX, gY, gW, gH, wDef.thickness || 1, wDef.spacing || 0, false, op, wDef.extraOverlap ?? 0, 0, taper, isExtra);
            }
        }
    }

    // PASS 3: WARP OVERLAYS
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const waYId = warpYarnSequence[c % warpYarnSequence.length] || 'A';
            const waDef = warpYarns[waYId];
            const waTex = textureMap.get(`warp-${waYId}`);
            if (!waTex || !waDef) continue;

            const wTopR = structure[pR]?.[pC] || false;
            const warpIsTop = viewSide === 'face' ? wTopR : !wTopR;

            if (warpIsTop) {
                const gX = warpPositions[c].x, gW = warpPositions[c].w, gY = rowY[r], gH = rowHeights[r];
                if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

                let wAO = 0;
                const prevW = viewSide === 'face' ? (structure[pR]?.[(pC-1+cols)%cols] || false) : !(structure[pR]?.[(pC-1+cols)%cols] || false);
                const nextW = viewSide === 'face' ? (structure[pR]?.[(pC+1)%cols] || false) : !(structure[pR]?.[(pC+1)%cols] || false);
                if (!prevW || !nextW) wAO = (waDef.bindingDepth || 0.12) * 1.5;

                const taper = calculateTaper(pR, pC, true, waDef.floatTaper || 0);
                drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, 1.0, 0, wAO, taper);
            }
        }
    }

    return canvas;
};

