  });

  const [weftYarns, setWeftYarns] = useState<{ [key: string]: YarnDefinition }>({
      'A': { color: '#f8fafc', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 15, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS },
      'B': { color: '#2563eb', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 15, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS, isExtraWeft: true },
      'C': { color: '#ef4444', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 15, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS, isExtraWeft: true },
      'D': { color: '#10b981', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 15, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS, isExtraWeft: true },
      'E': { color: '#f59e0b', model: 'simple', construction: 'standard', fiberType: 'Cotton', countSystem: 'Nm', count: 30, ply: 2, thickness: 1, twist: 'Z', tpi: 15, sheen: 0.1, roughness: 0.5, ...DEFAULT_PHYSICS, isExtraWeft: true }
  });

  const [activeYarnId, setActiveYarnId] = useState<string>('A');
  const [selectedYarnType, setSelectedYarnType] = useState<'warp' | 'weft'>('warp');
  const [studioYarnDef, setStudioYarnDef] = useState<YarnDefinition>(warpYarns['A']);

  const [warpPatternString, setWarpPatternString] = useState('512A');
  const [weftPatternString, setWeftPatternString] = useState('512A');

  const [currentTool, setCurrentTool] = useState<ToolType>('pencil');
  const [viewMode, setViewMode] = useState<ViewMode>('interlace');
  const [faceMode, setFaceMode] = useState<FaceMode>('face');

  const handleUpdateLayer = (idx: number, updates: Partial<JacquardLayer>) => {
      setLayerConfigs(prev => ({ ...prev, [idx]: { ...prev[idx], ...updates } }));
  };

  const handleLoadBitmap = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]; if (!file) return;
      setLoadingStatus("Processing Bitmap...");
      try {
          const img = await loadImage(file);
          const result = processImage(img, 16, 1024); 
          setArtwork({ data: new Uint8Array(result.pixels), palette: result.palette, width: result.width, height: result.height });
          setJacquardData({ width: result.width, height: result.height, structure: new Uint8Array(result.width * result.height).fill(0) });
          setSettings(prev => ({ ...prev, warpThreads: result.width, weftPicks: result.height }));
          setWarpPatternString(`${result.width}A`);
          setWeftPatternString(`${result.height}A`);

          const initialLayers: { [key: number]: JacquardLayer } = {};
          result.palette.forEach((_, i) => {
              const char = String.fromCharCode(65 + (i % 8));
              initialLayers[i] = { 
                  colorIndex: i, 
                  type: i === 0 ? 'ground' : 'extra-weft', 
                  sequence: '1:1', 
                  isCrammed: i !== 0,
                  yarnId: char,
                  weftSelector: (i % 8) + 1
              };
          });
          setLayerConfigs(initialLayers);
          setProjectName(file.name.split('.')[0]); setViewMode('structure'); setAppMode('art'); setLoadingStatus(null);
      } catch (err: any) { alert(err.message || "Error processing."); setLoadingStatus(null); }
  };

  const technicalData = useMemo(() => {
    if (!artwork) {
        return { 
            width: jacquardData.width, 
            height: jacquardData.height, 
            structure: jacquardData.structure, 
            techGrid: Array.from({ length: jacquardData.height }, () => Array(techState.columns.length).fill(false)) 
        };
    }

    // Stable Sort by Palette Index to prevent drift
    const allLayerList = artwork.palette.map((_, i) => layerConfigs[i]).filter(Boolean);
    const extraWeftLayers = allLayerList.filter(l => l.type === 'extra-weft');
    const groundLayers = allLayerList.filter(l => l.type === 'ground');
    const primaryGround = groundLayers[0] || allLayerList[0];

    const expansion = extraWeftLayers.length + 1;
    const maxSafePicks = 8192;
    const rawHeight = artwork.height * expansion;
    const newHeight = Math.min(rawHeight, maxSafePicks);
    const safeArtHeight = Math.floor(newHeight / expansion);

    const newStructure = new Uint8Array(artwork.width * newHeight);
    const newTechGrid = Array.from({ length: newHeight }, () => Array(techState.columns.length).fill(false));
    const weftSelectorIndices = techState.columns.map((c, i) => c?.type === 'weft-selector' ? i : -1).filter(i => i !== -1);
    const crammingIdx = techState.columns.findIndex(c => c?.type === 'cramming');

    const weaveGrids = new Map<string, Uint8Array>();
    const getWeaveGrid = (id: string) => {
        if (weaveGrids.has(id)) return weaveGrids.get(id)!;
        const w = allWeaves.find(v => v.id === id);
        if (!w || !w.draft || !w.draft[0]) return new Uint8Array(1).fill(0);
        const ww = w.draft[0].length, wh = w.pegPlan.length;
        if (ww === 0 || wh === 0) return new Uint8Array(1).fill(0);
        const bits = new Uint8Array(ww * wh);
        const wToH = new Int16Array(ww).fill(-1);
        for(let x=0; x<ww; x++) for(let ha=0; ha<w.harnesses; ha++) if(w.draft[ha] && w.draft[ha][x] === 1) { wToH[x] = ha; break; }
        for(let y=0; y<wh; y++) for(let x=0; x<ww; x++) if(wToH[x] !== -1 && w.pegPlan[y] && w.pegPlan[y][wToH[x]] === 1) bits[y * ww + x] = 1;
        weaveGrids.set(id, bits);
        return bits;
    };

    // Pre-calculate grids for all layers to speed up loop
    const faceGrids = new Map<number, Uint8Array | null>();
    const backGrids = new Map<number, Uint8Array | null>();
    allLayerList.forEach(l => {
        faceGrids.set(l.colorIndex, l.faceWeaveId ? getWeaveGrid(l.faceWeaveId) : null);
        backGrids.set(l.colorIndex, l.backWeaveId ? getWeaveGrid(l.backWeaveId) : null);
    });

    for (let y = 0; y < safeArtHeight; y++) {
        const targetGroundPick = y * expansion;
        if (targetGroundPick >= newHeight) break;

        // TECHNICAL: Weft Selectors for Ground Pick
        if (weftSelectorIndices.length > 0 && primaryGround) {
            const gSelIdx = weftSelectorIndices[(primaryGround.weftSelector - 1) % weftSelectorIndices.length];
            if (gSelIdx !== -1 && newTechGrid[targetGroundPick]) newTechGrid[targetGroundPick][gSelIdx] = true;
        }

        // GROUND PICK RENDERING
        for (let x = 0; x < artwork.width; x++) {
            const artIdx = y * artwork.width + x;
            if (artIdx >= artwork.data.length) continue;
            const colorIdx = artwork.data[artIdx];
            const pixelLayer = layerConfigs[colorIdx];

            // If the pixel belongs to a ground-pick layer (type ground), use its face weave
            // If it belongs to an extra-weft layer, it is technically "background" on the ground pick, so use primary ground's back weave
            if (pixelLayer && pixelLayer.type === 'ground') {
                const grid = faceGrids.get(colorIdx);
                if (grid) {
                    const w = allWeaves.find(v => pixelLayer.faceWeaveId === v.id);
                    const wh = w?.pegPlan.length || 1, ww = w?.draft[0].length || 1;
                    newStructure[targetGroundPick * artwork.width + x] = grid[(y % wh) * ww + (x % ww)];
                } else {
                    newStructure[targetGroundPick * artwork.width + x] = (x + y) % 2 === 0 ? 1 : 0;
                }
            } else {
                // Background on ground pick: use primary ground back weave
                const bgGrid = backGrids.get(primaryGround.colorIndex);
                if (bgGrid) {
                    const w = allWeaves.find(v => primaryGround.backWeaveId === v.id);
                    const wh = w?.pegPlan.length || 1, ww = w?.draft[0].length || 1;
                    newStructure[targetGroundPick * artwork.width + x] = bgGrid[(y % wh) * ww + (x % ww)];
                } else {
                    newStructure[targetGroundPick * artwork.width + x] = 1; // Default back
                }
            }
        }

        // EXTRA WEFT PICK RENDERING
        extraWeftLayers.forEach((layer, lIdx) => {
            const targetPick = (y * expansion) + lIdx + 1;
            if (targetPick >= newHeight) return;

            if (weftSelectorIndices.length > 0) {
                const lSelIdx = weftSelectorIndices[(layer.weftSelector - 1) % weftSelectorIndices.length];
                if (lSelIdx !== -1 && newTechGrid[targetPick]) newTechGrid[targetPick][lSelIdx] = true;
            }
            if (crammingIdx !== -1 && layer.isCrammed && newTechGrid[targetPick]) newTechGrid[targetPick][crammingIdx] = true;

            const gridFace = faceGrids.get(layer.colorIndex);
            const gridBack = backGrids.get(layer.colorIndex);

            for (let x = 0; x < artwork.width; x++) {
                const artIdx = y * artwork.width + x;
                const isFace = artwork.data[artIdx] === layer.colorIndex;
                const activeGrid = isFace ? gridFace : gridBack;

                if (activeGrid) {
                    const activeId = isFace ? layer.faceWeaveId : layer.backWeaveId;
                    const w = allWeaves.find(v => v.id === activeId);
                    if (w && w.draft && w.draft[0]) {
                        const ww = w.draft[0].length, wh = w.pegPlan.length;
                        newStructure[targetPick * artwork.width + x] = activeGrid[(y % wh) * ww + (x % ww)];
                    } else {
                        newStructure[targetPick * artwork.width + x] = isFace ? 0 : 1;
                    }
                } else {
                    newStructure[targetPick * artwork.width + x] = isFace ? 0 : 1; 
                }
            }
        });
    }

    return { width: artwork.width, height: newHeight, structure: newStructure, techGrid: newTechGrid };
  }, [artwork, layerConfigs, customWeaves, jacquardData, allWeaves, techState]);

  const expandedWeftPattern = useMemo(() => {
    if (!artwork) return expandPatternString(weftPatternString);
    const layers = artwork.palette.map((_, i) => layerConfigs[i]).filter(Boolean);
    if (layers.length === 0) return expandPatternString(weftPatternString);

    const extraWeftLayers = layers.filter(l => l.type === 'extra-weft');
    const finalSequence: string[] = [];

    const ground = layers.find(l => l.type === 'ground') || layers[0];
    const maxSafePicks = 8192;
    for(let y=0; y < artwork.height; y++) {
        if (finalSequence.length >= maxSafePicks) break;
        finalSequence.push(ground?.yarnId || 'A');
        extraWeftLayers.forEach(l => {
            if (finalSequence.length < maxSafePicks) finalSequence.push(l.yarnId || 'A');
        });
    }
    return finalSequence;
  }, [layerConfigs, artwork, weftPatternString]);

  const weftColorArray = useMemo(() => {
    return expandedWeftPattern.map(key => weftYarns[key]?.color || weftYarns['A']?.color || '#888');
  }, [expandedWeftPattern, weftYarns]);

  const warpColorArray = useMemo(() => {
      const seq = expandPatternString(warpPatternString);
      if (seq.length === 0) return Array.from({ length: jacquardData.width }, () => '#888');
      return Array.from({ length: jacquardData.width }, (_, i) => warpYarns[seq[i % seq.length] || 'A']?.color || '#888');
  }, [warpYarns, warpPatternString, jacquardData.width]);

  const simData = useMemo(() => {
      const { width, height, structure } = technicalData;
      const rows: boolean[][] = []; const colors: string[][] = [];
      for (let y = 0; y < height; y++) {
          const rowB: boolean[] = []; const rowC: string[] = [];
          for (let x = 0; x < width; x++) {
              const idx = y * width + x;
              const isUp = idx < structure.length ? structure[idx] === 1 : false;
              rowB.push(isUp); 
              rowC.push(isUp ? (warpColorArray[x % warpColorArray.length] || '#000') : (weftColorArray[y % weftColorArray.length] || '#ccc'));
          }
          rows.push(rowB); colors.push(rowC);
      }
      return { structure: rows, colors };
  }, [technicalData, warpColorArray, weftColorArray]);

  const handleApplyStudioYarn = () => {
    if (selectedYarnType === 'warp') setWarpYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    else setWeftYarns(prev => ({ ...prev, [activeYarnId]: studioYarnDef }));
    setAppMode('art'); 
  };

  const handleDropToLayer = (weave: LibraryWeave, layerIdx: number, slot: 'face' | 'back') => {
      handleUpdateLayer(layerIdx, { [slot === 'face' ? 'faceWeaveId' : 'backWeaveId']: weave.id });
  };

  const currentVisibleData = useMemo(() => {
    if (artwork && (viewMode === 'graph' || viewMode === 'interlace')) return technicalData;
    return jacquardData;
  }, [viewMode, technicalData, jacquardData, artwork]);

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white overflow-hidden font-sans">
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLoadBitmap} />
        {loadingStatus && (
            <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center">
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 flex flex-col items-center gap-4 shadow-2xl animate-in zoom-in-95 duration-200">
                    <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                    <span className="font-bold text-sm text-gray-200 uppercase tracking-widest">{loadingStatus}</span>
                </div>
            </div>
        )}

        <TopToolbar 
            currentTool={currentTool} onToolChange={setCurrentTool}
            viewMode={viewMode} onViewModeChange={setViewMode}
            faceMode={faceMode} onFaceModeChange={setFaceMode}
            currentFillPatternId="plain" onFillPatternChange={()=>{}}
            canUndo={false} canRedo={false} onUndo={()=>{}} onRedo={()=>{}}
            onSave={()=>{}} onLoad={() => fileInputRef.current?.click()} onImport={()=>{}}
        />

        <div className="flex-1 overflow-hidden relative flex">
            <div className="shrink-0 z-40 bg-gray-900 border-r border-gray-800">
                <ProgressiveToolbar mode={appMode} onModeChange={(m) => m === 'sim' ? setShowSimModal(true) : setAppMode(m)} />
            </div>

            <div className="flex-1 relative bg-gray-950 flex flex-col overflow-hidden">
                <div className="h-8 bg-gray-900 border-b border-gray-800 flex items-center px-4 justify-between shrink-0">
                    <div className="flex items-center gap-4 text-[10px] font-mono text-gray-500 uppercase tracking-widest">
                        <span className="text-blue-400 font-bold">{projectName}</span>
                        <span>{currentVisibleData.width} × {currentVisibleData.height}</span>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex bg-gray-800 rounded p-0.5 border border-gray-700">
                            <button onClick={() => setViewMode('interlace')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'interlace' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-gray-200'}`}>INTERLACE</button>
                            <button onClick={() => setViewMode('structure')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'structure' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-gray-200'}`}>ARTWORK</button>
                            <button onClick={() => setViewMode('graph')} className={`px-2 py-0.5 rounded text-[9px] font-bold transition-all ${viewMode === 'graph' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-gray-200'}`}>TECH CARD</button>
                        </div>
                    </div>
                </div>

                <div className="flex-1 flex overflow-hidden">
                    {(appMode === 'art' || appMode === 'weave') && viewMode === 'graph' && technicalData.techGrid && (
                        <div className="w-16 bg-gray-900 border-r border-gray-800 flex flex-col shrink-0 overflow-hidden shadow-2xl relative z-10">
                            <div className="h-10 border-b border-gray-800 flex items-center justify-center text-[8px] font-black text-blue-500 uppercase tracking-tighter">Selectors</div>
                            <div className="flex-1 relative overflow-hidden" style={{ height: currentVisibleData.height * canvasView.zoom }}>
                                <div className="absolute inset-0" style={{ transform: `translateY(${canvasView.y}px)` }}>
                                    {technicalData.techGrid.map((row, i) => (
                                        <div key={i} className="flex border-b border-gray-800/20" style={{ height: canvasView.zoom }}>
                                            {row.map((active, j) => (
                                                <div key={j} className={`flex-1 ${active ? 'bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]' : 'bg-transparent'}`} />
                                            ))}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="flex-1 relative">
                        {appMode === 'yarn' ? (
                            <YarnStudio yarn={studioYarnDef} onChange={setStudioYarnDef} onApply={handleApplyStudioYarn} />
                        ) : appMode === 'tech' ? (
                            <ProductionCalculator settings={settings} warpYarns={warpYarns} weftYarns={weftYarns} warpPatternString={warpPatternString} weftPatternString={weftPatternString} draft={[]} pegPlan={[]} generateThumbnail={() => ""} />
                        ) : appMode === 'weave-studio' ? (
                            <WeaveStudio onSaveToLibrary={(w) => setCustomWeaves(prev => [...prev, w])} />
                        ) : appMode === 'loom-tech' ? (
                            <LoomTechModule data={technicalData} settings={settings} weftYarns={weftYarns} weftPatternString={weftPatternString} warpYarns={warpYarns} warpPatternString={warpPatternString} techState={techState} onTechStateUpdate={setTechState} config={loomConfig} onConfigUpdate={setLoomConfig} />
                        ) : appMode === 'loom-editor' ? (
                            <LoomEditorModule config={loomConfig} onUpdate={setLoomConfig} techState={techState} onTechStateUpdate={setTechState} />
                        ) : (
                            <JacquardCanvas 
                                data={currentVisibleData} artwork={artwork || undefined} 
                                onUpdate={(d) => setJacquardData(prev => ({ ...prev, structure: d }))} 
                                onUpdateWarpPattern={setWarpPatternString}
                                onUpdateWeftPattern={setWeftPatternString}
                                activeYarnId={activeYarnId}
                                tool={currentTool} viewMode={viewMode} faceMode={faceMode} 
                                warpColors={warpColorArray} weftColors={weftColorArray} 
                                warpPatternString={warpPatternString}
                                weftPatternString={weftPatternString}
                                settings={settings}
                                onViewChange={setCanvasView}
                            />
                        )}
                    </div>
                </div>

                {artwork && (appMode === 'art' || appMode === 'weave') && (
                    <div className="h-32 bg-gray-900 border-t border-gray-800 flex items-center px-6 gap-6 shrink-0 z-10 shadow-2xl overflow-x-auto custom-scrollbar">
                        <div className="flex flex-col shrink-0">
                            <span className="text-[9px] font-black text-gray-500 uppercase mb-1 tracking-widest">Deck Management</span>
                            <span className="text-[10px] text-gray-400 font-mono italic">Drag structure to Face/Back</span>
                        </div>
                        <div className="flex items-center gap-4 py-2">
                            {artwork.palette.map((color, idx) => {
                                const config = layerConfigs[idx];
                                const faceW = allWeaves.find(w => w.id === config?.faceWeaveId);
                                const backW = allWeaves.find(w => w.id === config?.backWeaveId);

                                return (
                                    <div key={idx} className="group flex flex-col items-center gap-1.5 shrink-0 bg-gray-800/40 p-2.5 rounded-xl border border-gray-700 hover:bg-gray-800 transition-all">
                                        <div className="flex gap-1">
                                            <div 
                                                onDragOver={e => e.preventDefault()}
                                                onDrop={e => {
                                                    const d = e.dataTransfer.getData('weave-obj');
                                                    if (d) handleDropToLayer(JSON.parse(d), idx, 'face');
                                                }}
                                                className="w-[44px] h-[60px] bg-black/40 rounded border border-dashed border-gray-700 flex flex-col overflow-hidden relative group/face"
                                            >
                                                <div className="h-2 w-full absolute top-0 z-10 opacity-60" style={{ background: color }} />
                                                {faceW ? (
                                                    <div className="flex-1 relative">
                                                        <WeaveThumbnail weave={faceW} className="w-full h-full opacity-80" />
                                                        <button onClick={() => handleUpdateLayer(idx, { faceWeaveId: undefined })} className="absolute inset-0 bg-red-600/60 opacity-0 group-hover/face:opacity-100 flex items-center justify-center transition-opacity"><TrashIcon className="w-3  h-3 text-white" /></button>
                                                    </div>
                                                ) : <div className="flex-1 flex items-center justify-center text-[8px] text-gray-600 font-bold uppercase tracking-tighter text-center px-1">Face</div>}
                                            </div>

                                            <button 
                                                onClick={() => setActiveLayerIdx(idx)}
                                                className="w-[30px] h-[60px] rounded border border-white/10 shadow-lg relative overflow-hidden flex items-center justify-center hover:brightness-110 transition-all"
                                                style={{ backgroundColor: color }}
                                            >
                                                <SettingsIcon className="w-4 h-4 text-white/50" />
                                                {config?.isCrammed && (
                                                    <div className="absolute top-0 right-0 p-0.5 bg-orange-600 rounded-bl shadow-sm animate-pulse">
                                                        <ProcessorIcon className="w-2.5 h-2.5 text-white" />
                                                    </div>
                                                )}
                                                <div className="absolute bottom-0 inset-x-0 bg-black/40 text-[9px] font-black text-white py-0.5 text-center">{config?.weftSelector || 1}</div>
                                            </button>

                                            <div 
                                                onDragOver={e => e.preventDefault()}
                                                onDrop={e => {
                                                    const d = e.dataTransfer.getData('weave-obj');
                                                    if (d) handleDropToLayer(JSON.parse(d), idx, 'back');
                                                }}
                                                className="w-[44px] h-[60px] bg-black/40 rounded border border-dashed border-gray-700 flex flex-col overflow-hidden relative group/back"
                                            >
                                                <div className="h-2 w-full absolute bottom-0 z-10 opacity-60" style={{ background: color }} />
                                                {backW ? (
                                                    <div className="flex-1 relative">
                                                        <WeaveThumbnail weave={backW} className="w-full h-full opacity-80" />
                                                        <button onClick={() => handleUpdateLayer(idx, { backWeaveId: undefined })} className="absolute inset-0 bg-red-600/60 opacity-0 group-hover/back:opacity-100 flex items-center justify-center transition-opacity"><TrashIcon className="w-3 h-3 text-white" /></button>
                                                    </div>
                                                ) : <div className="flex-1 flex items-center justify-center text-[8px] text-gray-600 font-bold uppercase tracking-tighter text-center px-1">Back</div>}
                                            </div>
                                        </div>
                                        <span className="text-[8px] font-mono text-gray-500 uppercase tracking-widest">{config?.type === 'ground' ? 'Base' : `Ch ${config?.weftSelector || 1}`}</span>
                                    </div>
                                );
                            })}
                        </div>
                        <div className="flex flex-col gap-1 items-end shrink-0 ml-auto pr-6">
                            <span className="text-[8px] font-black text-blue-500 animate-pulse mb-1 uppercase tracking-widest">Logic: Stäubli / Bonas</span>
                            <button onClick={() => setArtwork(null)} className="px-4 py-1.5 text-[10px] bg-red-900/30 text-red-400 border border-red-900/50 rounded-lg font-black uppercase tracking-widest hover:bg-red-900/50 transition-all">Clear Deck</button>
                        </div>
                    </div>
                )}
            </div>

            <div className={`shrink-0 transition-all duration-300 border-l border-gray-800 bg-white ${isPanelCollapsed ? 'w-0 opacity-0 overflow-hidden' : 'w-80'}`}>
                <RightPanel 
                    settings={settings} onSettingsChange={setSettings} dentingPattern={dentingPattern} onDentingChange={setDentingPattern} onSnapshot={()=>{}} onLoadWeave={()=>{}} 
                    customWeaves={customWeaves} onAddWeave={()=>{}} onUpdateWeave={()=>{}} onDeleteWeave={()=>{}} 
                    warpYarns={warpYarns} weftYarns={weftYarns} onUpdateWarpYarn={(id, d) => setWarpYarns(p => ({...p, [id]: d}))} onUpdateWeftYarn={(id, d) => setWeftYarns(p => ({...p, [id]: d}))} paletteColors={PANTONE_PALETTE} warpPatternString={warpPatternString} setWarpPatternString={setWarpPatternString} weftPatternString={weftPatternString} setWeftPatternString={setWeftPatternString} onOpenGridEditor={()=>{}} onOpenPatternGenerator={()=>{}} currentInput={{} as any} onApplyGenerated={()=>{}} onSimulate={() => setShowSimModal(true)} onGridOperation={()=>{}} activeYarnId={activeYarnId} selectedYarnType={selectedYarnType} onSelectYarn={(id, type) => { setActiveYarnId(id); setSelectedYarnType(type); setAppMode('yarn'); }}
                    onOpenPixelEditor={() => setShowCustomModal(true)}
                    jacquardData={jacquardData}
                    canvasView={canvasView}
                />
            </div>
        </div>

        {activeLayerIdx !== null && artwork && (
            <LayerPropertyModal 
                isOpen={activeLayerIdx !== null} 
                onClose={() => setActiveLayerIdx(null)}
                color={artwork.palette[activeLayerIdx] || '#000'}
                layer={layerConfigs[activeLayerIdx] || { colorIndex: activeLayerIdx, type: 'ground', sequence: '1:1', isCrammed: false, yarnId: 'A', weftSelector: 1 }}
                onUpdate={(updates) => handleUpdateLayer(activeLayerIdx!, updates)}
                customWeaves={customWeaves}
                yarns={weftYarns}
            />
        )}

        <FabricSimulationModal 
            isOpen={showSimModal} 
            onClose={() => setShowSimModal(false)} 
            weavePattern={simData.colors} 
            structure={simData.structure} 
            epi={settings.epi} 
            ppi={settings.ppi} 
            techGrid={technicalData.techGrid}
            techColumns={techState.columns}
            dentingPlan={dentingPattern.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n))} 
            warpYarns={warpYarns} 
            weftYarns={weftYarns} 
            warpYarnSequence={expandPatternString(warpPatternString)} 
            weftYarnSequence={expandedWeftPattern} 
        />
        <CustomWeaveModal isOpen={showCustomModal} onClose={() => setShowCustomModal(false)} onSave={(w) => setCustomWeaves(prev => [...prev, w])} />
    </div>
  );
};

import { YarnDefinition } from '../types';

// Helper to convert hex to rgb
const hexToRgb = (hex: string) => {
    hex = hex.replace(/^#/, '');
    return {
        r: parseInt(hex.substring(0, 2), 16),
        g: parseInt(hex.substring(2, 4), 16),
        b: parseInt(hex.substring(4, 6), 16)
    };
};

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

// Robust Seamless Noise
const generateSeamlessNoise1D = (length: number, scale: number = 1.0): Float32Array => {
    const buffer = new Float32Array(length);
    const period = Math.max(1, Math.floor(length / scale));
    const rawNoise = new Float32Array(period);
    for(let i=0; i<period; i++) rawNoise[i] = Math.random();

    for(let i=0; i<length; i++) {
        const x = (i / length) * period;
        const i0 = Math.floor(x);
        const i1 = (i0 + 1) % period; 
        const t = x - i0;
        const smoothT = t * t * (3 - 2 * t);
        buffer[i] = rawNoise[i0] * (1 - smoothT) + rawNoise[i1] * smoothT;
    }
    return buffer;
};

// --- CACHING SYSTEM ---
const CACHE_SIZE_LIMIT = 200;
const textureCache = new Map<string, HTMLCanvasElement>();

const generateYarnHash = (yarn: YarnDefinition, dpi: number): string => {
    return `${yarn.color}-${yarn.colorB}-${yarn.colorC}-${yarn.model}-${yarn.construction}-${yarn.thickness}-${yarn.twist}-${yarn.tpi}-${yarn.sheen}-${yarn.roughness}-${yarn.shadowStrength}-${yarn.hairiness}-${yarn.hairLength}-${yarn.hairCurl}-${yarn.hairThickness}-${yarn.unevenness}-${yarn.slubMode}-${yarn.slubLength}-${yarn.slubDistance}-${yarn.slubAmplitude}-${yarn.spaceDyeLength}-${yarn.pileLength}-${yarn.coreColor}-${dpi}`;
};

const manageCache = () => {
    if (textureCache.size > CACHE_SIZE_LIMIT) {
        const keysToDelete = Array.from(textureCache.keys()).slice(0, 20);
        keysToDelete.forEach(k => {
            textureCache.delete(k);
        });
    }
};

/**
 * 2.5D Hyper-Realistic Yarn Renderer v12.1
 * Optimized for slub clearance and non-clipping.
 */
export const generateYarnTexture = (yarn: YarnDefinition, dpi: number = 144): HTMLCanvasElement => {
    const hash = generateYarnHash(yarn, dpi);
    if (textureCache.has(hash)) return textureCache.get(hash)!;

    const { 
        color, colorB, colorC, model, construction, fiberType, twist, tpi, 
        sheen, roughness, shadowStrength = 0.8,
        hairiness = 0, hairLength = 0.2, hairCurl = 0, hairThickness = 1.0,
        unevenness = 0, spaceDyeLength = 10,
        slubMode = 'periodic', slubLength = 0, slubDistance = 0, slubAmplitude = 0, slubColor,
        pileLength = 1.0, coreColor
    } = yarn;

    const pxPerMm = dpi / 25.4;
    const isChenille = construction === 'chenille';
    const isSlubActive = ((slubLength > 0.1 || (yarn.slubLength || 0) > 0) && (slubAmplitude > 10 || (yarn.slubAmplitude || 0) > 0));
    const isSpaceDye = model === 'space-dyed';
    const isGrindle = model === 'grindle';

    let cycleLenPx = 1; 
    let sLenPx = 0;
    let sDistPx = 0;
    let ampFactor = 0;

    if (isSlubActive) {
        if (slubLength > 0) {
            sLenPx = slubLength * (dpi / 2.54);
            sDistPx = slubDistance * (dpi / 2.54);
            ampFactor = slubAmplitude / 100;
            cycleLenPx = Math.max(1, sLenPx + sDistPx);
        } else {
            const dpiScale = dpi / 96;
            sLenPx = lerp(40, 300, yarn.slubLength || 0.5) * dpiScale;
            sDistPx = lerp(40, 800, yarn.slubDistance || 0.5) * dpiScale;
            ampFactor = yarn.slubAmplitude || 0;
            cycleLenPx = Math.max(1, sLenPx + sDistPx);
        }
    } else if (isSpaceDye) {
        cycleLenPx = Math.max(1, (spaceDyeLength || 10) * (dpi / 2.54));
    }

    const MIN_TEXTURE_WIDTH = 2048;
    const MAX_TEXTURE_WIDTH = 8192; 
    let width = MIN_TEXTURE_WIDTH;
    let cycles = 1;

    if ((isSlubActive || isSpaceDye) && cycleLenPx > 1) {
        let targetCycles = Math.ceil(MIN_TEXTURE_WIDTH / cycleLenPx);
        targetCycles = Math.max(2, targetCycles);
        let idealWidth = targetCycles * cycleLenPx;
        if (idealWidth > MAX_TEXTURE_WIDTH) {
            targetCycles = Math.floor(MAX_TEXTURE_WIDTH / cycleLenPx);
            idealWidth = targetCycles * cycleLenPx;
        }
        cycles = targetCycles;
        width = Math.ceil(idealWidth);
    } else {
        width = Math.min(4096, Math.max(2048, Math.ceil(50 * (dpi / 2.54)))); 
    }

    // --- GEOMETRY CALCULATION ---
    const coreHeight = Math.min(64, Math.max(16, Math.floor(dpi / 4))); 
    const pLenPx = (pileLength || 0.1) * pxPerMm;

    // V12.1 Fix: Increased clearance to coreHeight * 4.0 to ensure slubs/piles aren't cut
    const totalVisHeight = isChenille ? coreHeight + (pLenPx * 3.0) : coreHeight * 4.0;
    const height = Math.max(1, Math.floor(totalVisHeight));
    const centerY = height / 2;

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, width);
    canvas.height = Math.max(1, height);

    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return canvas;

    const colA = hexToRgb(color);
    const colB = colorB ? hexToRgb(colorB) : colA;
    const colC = colorC ? hexToRgb(colorC) : (colorB ? hexToRgb(colorB) : colA);
    const colSlub = slubColor ? hexToRgb(slubColor) : colA;
    const colCore = coreColor ? hexToRgb(coreColor) : { r: colA.r * 0.7, g: colA.g * 0.7, b: colA.b * 0.7 };

    const twistDirVal = twist === 'S' ? 1 : -1;
    const twistAngle = Math.atan((tpi || 15) * 0.15) * twistDirVal; 
    const twistSin = Math.sin(twistAngle);
    const twistCos = Math.cos(twistAngle);

    const L = { x: -0.2, y: -0.3, z: 1.0 };
    const lenL = Math.sqrt(L.x*L.x + L.y*L.y + L.z*L.z);
    L.x/=lenL; L.y/=lenL; L.z/=lenL;

    const V = { x: 0, y: 0, z: 1 };
    const H = { x: L.x + V.x, y: L.y + V.y, z: L.z + V.z };
    const lenH = Math.sqrt(H.x*H.x + H.y*H.y + H.z*H.z);
    H.x/=lenH; H.y/=lenH; H.z/=lenH;

    const imgData = ctx.createImageData(canvas.width, canvas.height);
    const data = imgData.data;

    const slubProfile = new Float32Array(width).fill(1.0);

    if (isSlubActive && cycles >= 1 && cycleLenPx > 1) {
        const fittedTotalPx = width / cycles;
        const totalFeaturePx = sLenPx + sDistPx;
        const lenRatio = sLenPx / Math.max(1, totalFeaturePx);
        const actualLenPx = fittedTotalPx * lenRatio;
        const intervals = [];
        for(let i=0; i<cycles; i++) {
            const start = (i * fittedTotalPx) + (fittedTotalPx - actualLenPx)/2;
            intervals.push({ start, len: actualLenPx });
        }
        const rampPx = Math.min(actualLenPx * 0.25, 40 * (dpi/96));
        for (let i=0; i<intervals.length; i++) {
            const { start, len } = intervals[i];
            for(let x = Math.floor(start - rampPx); x <= Math.ceil(start + len + rampPx); x++) {
                const wx = ((x % width) + width) % width;
                let dist = x < start ? start - x : (x > start + len ? x - (start + len) : 0);
                let val = dist <= 0 ? 1.0 + ampFactor : (dist < rampPx ? lerp(1.0 + ampFactor, 1.0, dist / rampPx) : 1.0);
                if (val > slubProfile[wx]) slubProfile[wx] = val;
            }
        }
    }

    if (unevenness > 0) {
        const lowFreq = generateSeamlessNoise1D(width, 200 * (dpi/96));
        for(let i=0; i<width; i++) slubProfile[i] += (lowFreq[i] - 0.5) * 0.3 * unevenness;
    }

    const isTweed = construction === 'tweed';
    const tweedNoise = isTweed ? generateSeamlessNoise1D(width, 2.0) : null;
    const fiberNoise = generateSeamlessNoise1D(width, 2.0); 

    // MAIN VOLUME PASS
    for (let x = 0; x < width; x++) {
        let thicknessMod = Math.max(0.1, slubProfile[x]);
        let isNep = false;
        if (isTweed && tweedNoise && tweedNoise[x] > 0.85) { thicknessMod += 0.4; isNep = true; }

        const currentRadius = (coreHeight / 2) * thicknessMod;
        const minY = Math.floor(centerY - currentRadius);
        const maxY = Math.ceil(centerY + currentRadius);

        let spaceDyeFactor = isSpaceDye ? (Math.sin(((x % cycleLenPx) / cycleLenPx) * Math.PI * 2) + 1) / 2 : 0;

        for (let y = minY; y <= maxY; y++) {
            if (y < 0 || y >= height || isChenille) continue; 
            const ny = (y - centerY) / Math.max(0.1, currentRadius);
            if (Math.abs(ny) > 1) continue;

            const idx = (y * width + x) * 4;
            const cylinderDepth = Math.sqrt(Math.max(0, 1.0 - ny*ny));
            const rotX = x * twistCos - (y - centerY) * twistSin;
            const twistPhase = rotX * (tpi || 15) * 0.15;
            const rawTwist = Math.sin(twistPhase);
            const twistNormal = Math.cos(twistPhase);
            const noiseX = Math.floor((rotX * 2) % width + width) % width;
            const micro = (fiberNoise[noiseX] - 0.5) * 2.0;

            let n_y = ny + (twistNormal * 0.6 + micro * (roughness * 0.5 + 0.2)) * 0.3; 
            let nz = cylinderDepth;
            const lenN = Math.sqrt(n_y*n_y + nz*nz);
            n_y /= Math.max(0.01, lenN); nz /= Math.max(0.01, lenN);

            const diffuse = Math.max(0, Math.min(1, (n_y*L.y + nz*L.z) * 0.6 + 0.4));
            const specular = Math.pow(Math.max(0, n_y*H.y + nz*H.z), fiberType === 'Lurex' ? 120 : (10 + sheen * 80)) * (fiberType === 'Lurex' ? 2.0 : sheen * 0.6);

            const totalAO = Math.max(0.5 + 0.5 * (1.0 - shadowStrength), Math.pow((rawTwist + 1) / 2, 0.15) * Math.pow(cylinderDepth, 0.1));

            let r, g, b;
            if (isNep) { r = colC.r; g = colC.g; b = colC.b; }
            else if (thicknessMod > 1.1 && slubColor) { const blend = Math.min(1, (thicknessMod - 1.0) * 2.0); r = lerp(colA.r, colSlub.r, blend); g = lerp(colA.g, colSlub.g, blend); b = lerp(colA.b, colSlub.b, blend); }
            else if (isSpaceDye) { r = lerp(colA.r, colB.r, spaceDyeFactor); g = lerp(colA.g, colB.g, spaceDyeFactor); b = lerp(colA.b, colB.b, spaceDyeFactor); }
            else if (isGrindle) {
                const grindlePhase = twistPhase * 1.0; 
                const useB = Math.sin(grindlePhase) > 0;
                const activeCol = useB ? colB : colA;
                r = activeCol.r; g = activeCol.g; b = activeCol.b;
            }
            else { const useB = model === 'mouline' ? Math.sin(rotX * 0.2) > 0 : (model === 'melange' ? fiberNoise[x] > 0.5 : false); const activeCol = useB ? colB : colA; r = activeCol.r; g = activeCol.g; b = activeCol.b; }

            const lightVal = diffuse * totalAO * 1.1;
            data[idx] = Math.min(255, r * lightVal + specular * 255);
            data[idx+1] = Math.min(255, g * lightVal + specular * 255);
            data[idx+2] = Math.min(255, b * lightVal + specular * 255);
            data[idx+3] = 255; // Solid core
        }
    }

    ctx.putImageData(imgData, 0, 0);

    if (isChenille) {
        const density = (hairiness * 40000 + 10000) * (width / 2048);
        ctx.lineWidth = hairThickness || 1.2;

        for(let i=0; i<density; i++) {
            const x = Math.random() * width;
            const angle = (Math.random() * Math.PI * 2);
            const baseLen = pLenPx * (0.8 + Math.random() * 0.4);

            ctx.strokeStyle = `rgba(${colA.r}, ${colA.g}, ${colA.b}, ${0.5 + Math.random() * 0.3})`;
            if (sheen > 0.5 && Math.random() > 0.9) ctx.strokeStyle = `rgba(255,255,255,0.4)`;

            ctx.beginPath();
            const startR = coreHeight * 0.2;
            const sx = x;
            const sy = centerY + Math.sin(angle) * startR;
            const ex = x + Math.cos(angle) * (baseLen * 0.1); 
            const ey = centerY + Math.sin(angle) * baseLen;

            ctx.moveTo(sx, sy);
            ctx.lineTo(ex, ey);
            ctx.stroke();
        }

        ctx.save();
        ctx.filter = 'blur(3px)';
        ctx.globalAlpha = 0.2 * (hairiness || 0);
        ctx.fillStyle = `rgb(${colA.r}, ${colA.g}, ${colA.b})`;
        ctx.fillRect(0, centerY - pLenPx, width, pLenPx * 2);
        ctx.restore();
    } else if (hairiness > 0 || roughness > 0) {
        const scHair = ((hairiness * 30000) + (roughness * 5000)) * (width / 2048);
        const maxL = (hairLength || 0.2) * coreHeight * 6;
        for(let i=0; i<scHair; i++) {
            let cx = Math.random() * width, cy = centerY + (Math.random()-0.5) * coreHeight * slubProfile[Math.floor(cx)] * 0.9;
            const dirY = Math.random() < 0.5 ? -1 : 1, len = Math.random() * maxL, steps = Math.max(2, len), alpha = 0.4 + Math.random() * 0.2;
            ctx.strokeStyle = `rgba(${colA.r * 1.2}, ${colA.g * 1.2}, ${colA.b * 1.2}, ${alpha})`;
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            for(let s=0; s<steps; s++) {
                cy += dirY * 0.8; cx += (hairCurl || 0) > 0 ? Math.sin(s * 0.3) * hairCurl * 2.0 : (Math.random()-0.5) * 0.5;
                ctx.lineTo(cx, cy);
                if (Math.random() < 0.05) break;
            }
            ctx.stroke();
        }
    }

    manageCache();
    textureCache.set(hash, canvas);
    return canvas;
};

import { YarnDefinition, DensityZone } from '../types';
import { generateYarnTexture } from './yarnRenderer';

interface RenderOptions {
    weavePattern: string[][];
    structure: boolean[][];
    epi: number;
    ppi: number;
    dentingPlan?: number[];
    weftZones?: DensityZone[];
    warpYarns: { [key: string]: YarnDefinition };
    weftYarns: { [key: string]: YarnDefinition };
    warpYarnSequence: string[];
    weftYarnSequence: string[];
    viewSide: 'face' | 'back';
    dpi: number;
    width: number; 
    height: number; 
    hideFloats?: boolean; 
    backgroundColor?: string; 
    smoothingQuality?: 'low' | 'medium' | 'high' | 'none';
}

const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = 128;
shadowCanvas.height = 128;
const sCtx = shadowCanvas.getContext('2d');
if (sCtx) {
    const grad = sCtx.createRadialGradient(64, 64, 0, 64, 64, 64);
    grad.addColorStop(0, 'rgba(0,0,0,0.8)'); 
    grad.addColorStop(0.6, 'rgba(0,0,0,0.2)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    sCtx.fillStyle = grad;
    sCtx.fillRect(0, 0, 128, 128);
}

export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern = [], structure = [], epi, ppi, dentingPlan, weftZones,
        warpYarns = {}, weftYarns = {}, warpYarnSequence = [], weftYarnSequence = [],
        viewSide, dpi, width: displayW, height: displayH,
        hideFloats = false,
        backgroundColor = '#020205',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    // --- STABLE DIMENSIONING ---
    const SS_FACTOR = 1.25; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const CANVAS_WIDTH = Math.round((displayW / 96) * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round((displayH / 96) * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    if (smoothingQuality === 'none') ctx.imageSmoothingEnabled = false;
    else ctx.imageSmoothingEnabled = true;

    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- GEOMETRY: WARP ---
    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = Math.max(1, safePlan.reduce((a, b) => a + b, 0) / safePlan.length);
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    while (currentX < CANVAS_WIDTH) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) currentX += dentWidthPx;
        else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.05) });
                currentX += w;
            }
        }
        dIdx++;
        if (dIdx > 10000) break; // Safety
    }
    const totalCols = warpPositions.length;

    // --- GEOMETRY: WEFT ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const nominalH = PX_PER_INCH / Math.max(1, ppi);
    let currentY = 0;

    for (let r = 0; r < rows; r++) {
        const yid = weftYarnSequence.length > 0 ? weftYarnSequence[r % weftYarnSequence.length] : 'A';
        const preferred = weftYarns[yid]?.preferredPPI;
        let h = preferred ? (PX_PER_INCH / Math.max(1, preferred)) : nominalH;
        rowY.push(currentY);
        rowHeights.push(h);
        currentY += h; 
        if (currentY > CANVAS_HEIGHT + 400) break;
    }

    // --- TEXTURE MAPPING ---
    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => {
        if (warpYarns[k]) textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR));
    });
    Object.keys(weftYarns).forEach(k => {
        if (weftYarns[k]) textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR));
    });

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);

    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, op: number, bloomVal: number, ao: number, taper: number) => {
        if (op <= 0 || !tex) return;

        // Physical geometry adjustment
        const effThick = thickness * (1.0 + bloomVal) * (1.0 - taper);
        const sFact = 1.0 - (spacing || 0);

        let dw, dh, dx, dy;
        if (isV) {
            // Tex scale for warp is lateral width. 
            // We multiply by 1.8 to ensure fiber-to-fiber contact in tight epi.
            dw = NOMINAL_WARP_W * effThick * sFact * 1.8; 
            dh = gh + 1.2;
            dx = gx + gw/2 - dw/2; dy = gy;
        } else {
            // Tex scale for weft is vertical height.
            dh = NOMINAL_WEFT_H * effThick * sFact * 1.8;
            dw = gw + 1.2;
            dx = gx; dy = gy + gh/2 - dh/2;
        }

        ctx.save();
        ctx.globalAlpha = op;
        // Randomize the texture phase to avoid visual repetitive patterns
        const phase = Math.floor((Math.abs(Math.sin((isV ? gx : gy) * 441.3)) * 1000) % tex.width);

        if (isV) {
            ctx.translate(dx + dw/2, dy + dh/2);
            ctx.rotate(Math.PI / 2);
            // Draw a slice of the yarn texture
            ctx.drawImage(tex, (gy + phase) % tex.width, 0, 1, tex.height, -dh/2, -dw/2, dh, dw);
        } else {
            ctx.drawImage(tex, (gx + phase) % tex.width, 0, 1, tex.height, dx, dy, dw, dh);
        }

        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(dx, dy, dw, dh); 
        }
        ctx.restore();
    };

    /**
     * GLOBAL 3-PASS RENDERER
     * Prevents thickness artifacts by separating foreground from background globally.
     */

    // PASS 1: BOTTOM LAYER (Yarns that are tucked under)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const weftIsOnTop = viewSide === 'face' ? !wTopR : wTopR;

            if (weftIsOnTop) {
                // Warp is on BOTTOM
                const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
                const waDef = warpYarns[waYId];
                const waTex = textureMap.get(`warp-${waYId}`);
                if (waTex && waDef) {
                    drawThread(waTex, warpPositions[c].x, rowY[r], warpPositions[c].w, rowHeights[r], waDef.thickness || 1, waDef.spacing || 0, true, 1.0, 0, 0, 0);
                }
            } else {
                // Weft is on BOTTOM
                const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
                const wDef = weftYarns[wYId];
                const wTex = textureMap.get(`weft-${wYId}`);
                if (wTex && wDef) {
                    let op = 1.0;
                    if (wDef.isExtraWeft) op = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);
                    drawThread(wTex, warpPositions[c].x, rowY[r], warpPositions[c].w, rowHeights[r], wDef.thickness || 1, wDef.spacing || 0, false, op, 0, 0, 0);
                }
            }
        }
    }

    // PASS 2: SHADOWS (Occlusion for top yarns)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const weftIsOnTop = viewSide === 'face' ? !wTopR : wTopR;

            const def = weftIsOnTop ? weftYarns[weftYarnSequence[pR % weftYarnSequence.length]] : warpYarns[warpYarnSequence[pC % warpYarnSequence.length]];
            const sTh = (def?.shadowThrow ?? 1.5) * SS_FACTOR;
            const sAn = (def?.shadowAngle ?? 135) * Math.PI/180;

            if (sTh > 0) {
                const gX = warpPositions[c].x, gW = warpPositions[c].w, gY = rowY[r], gH = rowHeights[r];
                ctx.globalAlpha = 0.4;
                ctx.drawImage(shadowCanvas, (gX + gW/2) + Math.cos(sAn)*sTh - gW*1.5, (gY + gH/2) + Math.sin(sAn)*sTh - gH*1.5, gW*3.5, gH*3.5);
            }
        }
    }

    // PASS 3: TOP LAYER (The visible interlaced surface)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const weftIsOnTop = viewSide === 'face' ? !wTopR : wTopR;

            if (weftIsOnTop) {
                // Weft is on TOP
                const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
                const wDef = weftYarns[wYId];
                const wTex = textureMap.get(`weft-${wYId}`);
                if (wTex && wDef) {
                    let wAO = 0, wT = 0;
                    const prevW = viewSide === 'face' ? (structure[pR]?.[(pC-1+cols)%cols] || false) : !(structure[pR]?.[(pC-1+cols)%cols] || false);
                    const nextW = viewSide === 'face' ? (structure[pR]?.[(pC+1)%cols] || false) : !(structure[pR]?.[(pC+1)%cols] || false);
                    if (prevW || nextW) { 
                        wAO = wDef.bindingDepth || 0.15; 
                        wT = wDef.floatTaper || 0; 
                    }
                    drawThread(wTex, warpPositions[c].x, rowY[r], warpPositions[c].w, rowHeights[r], wDef.thickness || 1, wDef.spacing || 0, false, 1.0, wDef.extraOverlap ?? 0, wAO, wT);
                }
            } else {
                // Warp is on TOP
                const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
                const waDef = warpYarns[waYId];
                const waTex = textureMap.get(`warp-${waYId}`);
                if (waTex && waDef) {
                    let waAO = 0, waT = 0;
                    const upW = viewSide === 'face' ? (structure[(pR-1+rows)%rows]?.[pC] || false) : !(structure[(pR-1+rows)%rows]?.[pC] || false);
                    const dnW = viewSide === 'face' ? (structure[(pR+1)%rows]?.[pC] || false) : !(structure[(pR+1)%rows]?.[pC] || false);
                    if (!upW || !dnW) { 
                        waAO = waDef.bindingDepth || 0.15; 
                        waT = waDef.floatTaper || 0; 
                    }
                    drawThread(waTex, warpPositions[c].x, rowY[r], warpPositions[c].w, rowHeights[r], waDef.thickness || 1, waDef.spacing || 0, true, 1.0, waDef.extraOverlap ?? 0, waAO, waT);
                }
            }
        }
    }

    return canvas;
};

