export const renderFabricToCanvas = (options: RenderOptions): HTMLCanvasElement => {
    const { 
        weavePattern = [], structure = [], epi, ppi, dentingPlan, weftZones,
        warpYarns = {}, weftYarns = {}, warpYarnSequence = [], weftYarnSequence = [],
        viewSide, dpi, width: displayW, height: displayH,
        hideFloats = false,
        backgroundColor = '#0a0a0c',
        smoothingQuality = 'high'
    } = options;

    const rows = weavePattern.length;
    const cols = weavePattern[0] ? weavePattern[0].length : 0;
    if (rows === 0 || cols === 0) return document.createElement('canvas');

    // --- STABLE DIMENSIONING ---
    const SS_FACTOR = 1.25; 
    const PX_PER_INCH = dpi * SS_FACTOR;
    const CANVAS_WIDTH = Math.round((displayW / 96) * PX_PER_INCH);
    const CANVAS_HEIGHT = Math.round((displayH / 96) * PX_PER_INCH);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, CANVAS_WIDTH);
    canvas.height = Math.max(1, CANVAS_HEIGHT);

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return canvas;

    ctx.imageSmoothingEnabled = smoothingQuality !== 'none';
    ctx.fillStyle = backgroundColor; 
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // --- GEOMETRY: WARP ---
    const safePlan = (dentingPlan && dentingPlan.length > 0) ? dentingPlan : [1];
    const avgThreadsPerDent = Math.max(1, safePlan.reduce((a, b) => a + b, 0) / safePlan.length);
    const dentWidthPx = (PX_PER_INCH * avgThreadsPerDent) / Math.max(1, epi);

    const warpPositions: {x: number, w: number, jitter: number}[] = [];
    let currentX = 0;
    let dIdx = 0;
    while (currentX < CANVAS_WIDTH) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) currentX += dentWidthPx;
        else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.02) });
                currentX += w;
            }
        }
        dIdx++;
        if (dIdx > 10000) break; 
    }
    const totalCols = warpPositions.length;

    // --- GEOMETRY: WEFT ---
    const rowY: number[] = [];
    const rowHeights: number[] = [];
    const nominalH = PX_PER_INCH / Math.max(1, ppi);
    let currentY = 0;

    for (let r = 0; r < rows; r++) {
        const yid = weftYarnSequence.length > 0 ? weftYarnSequence[r % weftYarnSequence.length] : 'A';
        const preferred = weftYarns[yid]?.preferredPPI;
        let h = preferred ? (PX_PER_INCH / Math.max(1, preferred)) : nominalH;
        rowY.push(currentY);
        rowHeights.push(h);
        currentY += h; 
        if (currentY > CANVAS_HEIGHT + 400) break;
    }

    // --- TEXTURE MAPPING ---
    const textureMap = new Map<string, HTMLCanvasElement>();
    Object.keys(warpYarns).forEach(k => {
        if (warpYarns[k]) textureMap.set(`warp-${k}`, generateYarnTexture(warpYarns[k], dpi * SS_FACTOR));
    });
    Object.keys(weftYarns).forEach(k => {
        if (weftYarns[k]) textureMap.set(`weft-${k}`, generateYarnTexture(weftYarns[k], dpi * SS_FACTOR));
    });

    const NOMINAL_WARP_W = PX_PER_INCH / Math.max(1, epi);
    const NOMINAL_WEFT_H = PX_PER_INCH / Math.max(1, ppi);

    const drawThread = (tex: HTMLCanvasElement, gx: number, gy: number, gw: number, gh: number, thickness: number, spacing: number, isV: boolean, op: number, bloomVal: number, ao: number, taper: number, isExtra: boolean = false) => {
        if (op <= 0 || !tex) return;

        /**
         * COVERAGE CALCULATION (High-Cover logic)
         * We bump the base expansion to 2.8x. 
         * This compensates for "round" yarn rendering in a 2D plane and eliminates black gaps.
         */
        const baseExpansion = 2.8;
        let effThick = thickness * baseExpansion;

        if (isExtra && bloomVal > 0.0) {
            // Aggressive bloom for Lancé to overlap neighbors vertically
            effThick *= (1.0 + bloomVal * 1.5);
        }

        const taperMod = 1.0 - (taper * 0.7); // Smoother tapering
        const sFact = 1.0 - (spacing || 0);

        let dw, dh, dx, dy;
        if (isV) {
            dw = NOMINAL_WARP_W * effThick * sFact * taperMod; 
            dh = gh + 1.8; // Small overlap to hide horizontal gaps
            dx = gx + gw/2 - dw/2; dy = gy - 0.9;
        } else {
            dh = NOMINAL_WEFT_H * effThick * sFact * taperMod;
            dw = gw + 1.8; // Small overlap to hide vertical gaps
            dx = gx - 0.9; dy = gy + gh/2 - dh/2;
        }

        ctx.save();
        ctx.globalAlpha = op;
        const phase = Math.floor((Math.abs(Math.sin((isV ? gx : gy) * 19.33)) * 5000) % tex.width);

        if (isV) {
            ctx.translate(dx + dw/2, dy + dh/2);
            ctx.rotate(Math.PI / 2);
            ctx.drawImage(tex, (gy + phase) % tex.width, 0, 1, tex.height, -dh/2, -dw/2, dh, dw);
        } else {
            ctx.drawImage(tex, (gx + phase) % tex.width, 0, 1, tex.height, dx, dy, dw, dh);
        }

        if (ao > 0) { 
            ctx.fillStyle = `rgba(0,0,0,${ao})`; 
            if(isV) ctx.fillRect(-dh/2, -dw/2, dh, dw); else ctx.fillRect(dx, dy, dw, dh); 
        }
        ctx.restore();
    };

    /**
     * GLOBAL 3-PASS RENDERER WITH GROUND SATURATION
     */

    // PASS 1: BOTTOM LAYER (The Base Bed)
    // We render background threads slightly extra thick here to ensure no black shows through.
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        const gY = rowY[r], gH = rowHeights[r];
        if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const weftIsOnTop = viewSide === 'face' ? !wTopR : wTopR;
            const gX = warpPositions[c].x, gW = warpPositions[c].w;

            if (weftIsOnTop) {
                // Warp is on BOTTOM
                const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
                const waDef = warpYarns[waYId];
                const waTex = textureMap.get(`warp-${waYId}`);
                if (waTex && waDef) {
                    drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, 1.0, 0, 0.05, 0);
                }
            } else {
                // Weft is on BOTTOM
                const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
                const wDef = weftYarns[wYId];
                const wTex = textureMap.get(`weft-${wYId}`);
                if (wTex && wDef) {
                    let op = 1.0;
                    if (wDef.isExtraWeft) op = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);
                    drawThread(wTex, gX, gY, gW, gH, wDef.thickness || 1, wDef.spacing || 0, false, op, 0, 0.05, 0, wDef.isExtraWeft);
                }
            }
        }
    }

    // PASS 2: SHADOWS (Occlusion Depth)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        const gY = rowY[r], gH = rowHeights[r];
        if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const weftIsOnTop = viewSide === 'face' ? !wTopR : wTopR;

            const def = weftIsOnTop ? weftYarns[weftYarnSequence[pR % weftYarnSequence.length]] : warpYarns[warpYarnSequence[pC % warpYarnSequence.length]];
            const sTh = (def?.shadowThrow ?? 1.5) * SS_FACTOR;
            const sAn = (def?.shadowAngle ?? 135) * Math.PI/180;

            if (sTh > 0 && def) {
                const gX = warpPositions[c].x, gW = warpPositions[c].w;
                ctx.globalAlpha = 0.3;
                ctx.drawImage(shadowCanvas, (gX + gW/2) + Math.cos(sAn)*sTh - gW*2, (gY + gH/2) + Math.sin(sAn)*sTh - gH*2, gW*5, gH*5);
            }
        }
    }

    // PASS 3: TOP LAYER (The Surface Interlacements)
    for (let r = 0; r < rowY.length; r++) {
        const pR = r % rows;
        const gY = rowY[r], gH = rowHeights[r];
        if (gY > CANVAS_HEIGHT || gY + gH < 0) continue;

        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols;
            const wTopR = structure[pR]?.[pC] || false;
            const weftIsOnTop = viewSide === 'face' ? !wTopR : wTopR;
            const gX = warpPositions[c].x, gW = warpPositions[c].w;

            if (weftIsOnTop) {
                // Weft is on TOP
                const wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A';
                const wDef = weftYarns[wYId];
                const wTex = textureMap.get(`weft-${wYId}`);
                if (wTex && wDef) {
                    let wAO = 0, wT = 0;
                    const prevW = viewSide === 'face' ? (structure[pR]?.[(pC-1+cols)%cols] || false) : !(structure[pR]?.[(pC-1+cols)%cols] || false);
                    const nextW = viewSide === 'face' ? (structure[pR]?.[(pC+1)%cols] || false) : !(structure[pR]?.[(pC+1)%cols] || false);
                    if (prevW || nextW) { 
                        wAO = (wDef.bindingDepth || 0.1) * 1.5; 
                        wT = wDef.floatTaper || 0; 
                    }
                    drawThread(wTex, gX, gY, gW, gH, wDef.thickness || 1, wDef.spacing || 0, false, 1.0, wDef.extraOverlap ?? 0, wAO, wT, wDef.isExtraWeft);
                }
            } else {
                // Warp is on TOP
                const waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A';
                const waDef = warpYarns[waYId];
                const waTex = textureMap.get(`warp-${waYId}`);
                if (waTex && waDef) {
                    let waAO = 0, waT = 0;
                    const upW = viewSide === 'face' ? (structure[(pR-1+rows)%rows]?.[pC] || false) : !(structure[(pR-1+rows)%rows]?.[pC] || false);
                    const dnW = viewSide === 'face' ? (structure[(pR+1)%rows]?.[pC] || false) : !(structure[(pR+1)%rows]?.[pC] || false);
                    if (!upW || !dnW) { 
                        waAO = (waDef.bindingDepth || 0.1) * 1.5; 
                        waT = waDef.floatTaper || 0; 
                    }
                    drawThread(waTex, gX, gY, gW, gH, waDef.thickness || 1, waDef.spacing || 0, true, 1.0, 0, waAO, waT);
                }
            }
        }
    }

    return canvas;
};

